\subsection{Extracting the order, $k$ of the boundary conditions, and the integral kernels $\kappa$}
\label{SubSec:Extrating k and kappa}

Taking an arbitrary electromagnetic field, the boundary conditions \eqref{Bdd_Gen_Bdd}, will not be satisfied.  To quantify this we define a set of distributions $R_1,\ldots,R_\dimXi$, which represent the remainder of the difference between the two sides of Eq. (\ref{Bdd_Gen_Bdd})
%[
\begin{align}
\begin{split}
\lefteqn{R_A(\uvec)[F^\I_{\mu\nu},H^\I_{\mu\nu},F^\II_{\mu\nu},H^\II_{\mu\nu}]} 
\hspace{3em}&
\\&=
\tfrac12\sum_{r=0}^k\int_{J^\Sigma(\uvec)} 
\Big(
\kappa^{\F\I }_{Ar}{}^{\mu\nu}(\uvec,\uvec')
\,
\frac{\partial^r }{\partial z^r}F^\I_{\mu\nu}
+
\kappa^{\H\I }_{Ar}{}^{\mu\nu}(\uvec,\uvec')
\,
\frac{\partial^r }{\partial z^r}H^\I_{\mu\nu}
\Big)
\,d^3\uvec'
\\&\quad
-
\tfrac12\sum_{r=0}^k\int_{J^\Sigma(\uvec)} 
\Big(
\kappa^{\F\II }_{Ar}{}^{\mu\nu}(\uvec,\uvec')
\,
\frac{\partial^r }{\partial z^r}F^\II_{\mu\nu}
+
\kappa^{\H\II }_{Ar}{}^{\mu\nu}(\uvec,\uvec')
\,
\frac{\partial^r }{\partial z^r}H^\II_{\mu\nu}
\Big)
\,d^3\uvec'
\end{split}
\label{Bdd_Gen_Def_R}
\end{align}
%]
where for brevity we have suppressed the arguments of the field tensors.  Clearly the BCs are satisfied if and only if all the $R_A(\uvec)=0$ for all $\uvec$.  

In order to calculate the order $k$ of the distributions, we replace the electromagnetic fields with $\{z^{k+1}F^\I_{\mu\nu},z^{k+1}H^\I_{\mu\nu},z^{k+1}F^\II_{\mu\nu},z^{k+1}H^\II_{\mu\nu}\}$ then
%[
\begin{align}
\begin{split}
\lefteqn{R_A(\uvec)[z^{k+1}F^\I_{\mu\nu},z^{k+1}H^\I_{\mu\nu},z^{k+1}F^\II_{\mu\nu},z^{k+1}H^\II_{\mu\nu}]} 
\hspace{3em} &
\\
&=
\tfrac12\sum_{r=0}^k\int_{J^\Sigma(\uvec)} 
\Big(
\kappa^{\F\I }_{Ar}{}^{\mu\nu}(\uvec,\uvec')
\,
\frac{\partial^r }{\partial z^r}\big(z^{k+1}F^\I_{\mu\nu}\big)
+
\kappa^{\H\I }_{Ar}{}^{\mu\nu}(\uvec,\uvec')
\,
\frac{\partial^r }{\partial z^r}\big(z^{k+1}H^\I_{\mu\nu}\big)
\Big)
\,d^3\uvec'
\\&\quad
-
\tfrac12\sum_{r=0}^k\int_{J^\Sigma(\uvec)} 
\Big(
\kappa^{\F\II }_{Ar}{}^{\mu\nu}(\uvec,\uvec')
\,
\frac{\partial^r }{\partial z^r}\big(z^{k+1}F^\II_{\mu\nu}\big)
+
\kappa^{\H\II }_{Ar}{}^{\mu\nu}(\uvec,\uvec')
\,
\frac{\partial^r }{\partial z^r}\big(z^{k+1}H^\II_{\mu\nu}\big)
\Big)
\,d^3\uvec'\\
&=0
\end{split}
\label{Bdd_Gen_R_order}
\end{align}
%]
since $z=0$ on $\Sigma$.  Hence we can define the order of the boundary conditions  as the smallest $k$ such that $R_A(\uvec)=0$ for all $A$ and $\uvec$ when applied to $\left\{z^{k+1}F^\I_{\mu\nu},z^{k+1}H^\I_{\mu\nu},z^{k+1}F^\II_{\mu\nu},z^{k+1}H^\II_{\mu\nu}\right\}$.  

We now illustrate how the $\kappa$ tensors appearing in the boundary conditions (\ref{Bdd_Gen_Bdd}) can be extracted from the remainder functions $R_{A}$. This method only works if the $\kappa$ are regular functions and not distributions. 
Let $\psi_0(\sigma)$ be a bump function, so that $\psi_0(0)=1$, $\partial_\sigma^r\psi_0(0)=0$ for all $r\ge1$ and $\int_{-\infty}^\infty\psi_0(\sigma) d\sigma=1$. 
This has the property that $\partial_z^s \big(z^r \psi_0(z)\big)=r!\delta^s_r$ and $\lim_{\epsilon\to 0} \epsilon^{-1} \psi_0(\epsilon^{-1}\sigma)=\delta(\sigma)$.

Now consider the field 
\begin{align}
   T_{\mu\nu}^{\sigma\rho}(r,\uvec,z,\vvec,\epsilon)
   &=
   \frac{1}{2\epsilon^3 r!} (\delta^\sigma_\mu \delta^\rho_\nu -\delta^\sigma_\nu \delta^\rho_\mu)
   \psi_0\Big(\frac{u^1-v^1}{\epsilon}\Big)
   \psi_0\Big(\frac{u^2-v^2}{\epsilon}\Big)
   \psi_0\Big(\frac{u^3-v^3}{\epsilon}\Big)
   z^r\psi_0(z)
\label{Bdd_Gen_Test}
\end{align}
for $\epsilon>0$. Then
\begin{align}
    \kappa^{\F\I }_{Ar}{}^{\sigma\rho}(\uvec,\vvec)
    = \lim_{\epsilon\to0} \Big(
    R_A(\uvec)[T^{\sigma\rho}_{\mu\nu}(r,\uvec,z,\vvec,\epsilon),0,0,0]
    \Big)\,,
    \label{Bdd_Gen_kappa_extact}
\end{align}
and likewise for the other $\kappa$'s.
This follows since
\begin{align}
\begin{split}
&
\lim_{\epsilon\to0}
    R_A(\uvec)[T^{\sigma\rho}_{\mu\nu}(r,\uvec,z,\vvec,\epsilon),0,0,0]
    \\&=
\tfrac12 \lim_{\epsilon\to0}\sum_{s=0}^k\int_{J^\Sigma(\uvec)} 
\kappa^{\F\I }_{As}{}^{\mu\nu}(\uvec,\uvec')
\,
\frac{\partial^s }{\partial z^s}\Big(
T_{\mu\nu}^{\sigma\rho}(r,\uvec',z,\vvec,\epsilon)
\Big)
\,d^3\uvec'
    \\&=
 \lim_{\epsilon\to0}
\frac1{4 r!\epsilon^3}\sum_{s=0}^k\int_{J^\Sigma(\uvec)} 
\kappa^{\F\I }_{As}{}^{\mu\nu}(\uvec,\uvec')
\,
\frac{\partial^s }{\partial z^s}\Big(
(\delta^\sigma_\mu \delta^\rho_\nu -\delta^\sigma_\nu \delta^\rho_\mu)
   \psi_0\Big(\frac{u^1{-}v^1}{\epsilon}\Big)
   \psi_0\Big(\frac{u^2{-}v^2}{\epsilon}\Big)
\\&\hspace{10em}
   \psi_0\Big(\frac{u^3{-}v^3}{\epsilon}\Big)
   z^r\psi_0(z)
\Big)
\,d^3\uvec'
   \\&=
 \lim_{\epsilon\to0}
\frac1{2 r!\epsilon^3}\sum_{s=0}^k\int_{J^\Sigma(\uvec)} 
\kappa^{\F\I }_{As}{}^{\sigma\rho}(\uvec,\uvec')
\,
\frac{\partial^s }{\partial z^s}\Big(
   \psi_0\Big(\frac{u^1{-}v^1}{\epsilon}\Big)
   \psi_0\Big(\frac{u^2{-}v^2}{\epsilon}\Big)
   \psi_0\Big(\frac{u^3{-}v^3}{\epsilon}\Big)
   z^r\psi_0(z)
\Big)
\,d^3\uvec'
   \\&=
 \lim_{\epsilon\to0}
\frac1{2 \epsilon^3}\int_{J^\Sigma(\uvec)} 
\kappa^{\F\I }_{Ar}{}^{\sigma\rho}(\uvec,\uvec')
\,
   \psi_0\Big(\frac{u^1{-}v^1}{\epsilon}\Big)
   \psi_0\Big(\frac{u^2{-}v^2}{\epsilon}\Big)
   \psi_0\Big(\frac{u^3{-}v^3}{\epsilon}\Big)
\,d^3\uvec'
\\&=
\kappa^{\F\I }_{Ar}{}^{\sigma\rho}(\uvec,\vvec)
\end{split}
\end{align}
As stated this assumes the $\kappa$'s are regular functions. For distributional $\kappa$'s the technique will depend on the nature and support of the distibutions.





