        \caption{Optimal Hub Selection}\label{alg:optimal_hub}
        \begin{algorithmic}[1]
        \State $DistanceMatrix \gets \text{Input}$ \Comment{Matrix of distances between hubs and delivery points}
        \State $ExistingHubs \gets \text{Input}$ \Comment{List of indices of existing hubs}
        \State $MinimumCost \gets \infty$ \Comment{Initialize the minimum cost to infinity}
        \State $BestHubIndex \gets \text{Null}$ \Comment{Index of the optimal hub to be determined}

        \For{$CandidateHubIndex$ in $DistanceMatrix$} \Comment{Iterate over potential hub locations}
            \If {$CandidateHubIndex$ in $ExistingHubs$} \Comment{Skip existing hubs}
                \State \textbf{continue}
            \EndIf

            \State $RelevantDistances \gets DistanceMatrix_{CandidateHubIndex, m}$ \Comment{Extract distances between candidate hub and delivery points}
            \State $CurrentCost \gets 0$ \Comment{Initialize cost for the current candidate hub}

            \For{$i = 0$ to $N-1$} \Comment{Assuming N is the number of existing hubs}
                \State $CurrentCost \mathrel{\gets} CurrentCost + \min\left(RelevantDistances_{i}\right)$ \Comment{Add the minimum distance for this hub}
            \EndFor

            \If{$CurrentCost < MinimumCost$} \Comment{Check if current cost is less than the minimum cost found so far}
                \State $MinimumCost \gets CurrentCost$ \Comment{Update the minimum cost}
                \State $BestHubIndex \gets CandidateHubIndex$ \Comment{Update the best hub index}
            \EndIf
        \EndFor
        \end{algorithmic}
        \end{algorithm}
