\subsection{Recursive Return Derivatives}
%%%%%%%%%%%
{\color{black}
        {\color{black}
        \begin{table}[h!t!b!]
        \centering
        \begin{tabular}{lll}
        \toprule
        \textbf{Contract Type} & $A_M$ & $G(A_M)$ \\
        \midrule
        Realized Variance Swaps & $\displaystyle  \frac{1}{T}\sum_{m=1}^{M}\left( R_m \right)^2$ & $A_M-K$ \\
        Realized Variance Options & $\displaystyle  \frac{1}{T}\sum_{m=1}^{M}\left(e^{R_m} - 1 \right)^2$ & $(A_M-K)^+$ \\
        Cliquet & $\displaystyle \sum_{m=1}^M \max\left(F,\min\left(C,\exp(R_m) - 1\right) \right)$ &  $K \cdot\min\left(C_g, \max\left(F_g, A_M \right) \right)$ \\
        Asian Options & {\scriptsize $\displaystyle\frac{S_0}{M+1}\left(w_0 + \e^{R_1}\left(\dots\left(w_{M-1} + w_{M}\e^{R_M} \right)\right)\right)$} & $(A_M-K)^+$ \\
        \bottomrule
        \end{tabular}
