Let \(X'_S\) be the set of projection cycle-vectors \((p,\lambda) \in X_{S}\), such that the propositions \((a)-(e)\) of the \textbf{Theorem 2.2} holds for \((p,\lambda)\) and let \(X'_{S,min}\) denote the set of all minimal projection cycle-vectors \((p,\lambda) \in X'_{S}\).

The following lemmas hold.
\begin{lemma}
    The vector assigned to a minimal projection cycle is unique up to multiplication by a constant. Moreover, if it is orthonormal, then it has rational components.
    Thus, any minimal projection cycle uniquely (up to a sign) defines an orthonormal projection cycle-vector.
\end{lemma}
\begin{proof}
    (See: Lemma 4 and Lemma 5 in \cite{Navada} or Lemma 3.32 in \cite{Ismailov_2021}).
\end{proof}
\begin{lemma}
    For any projection cycle \((p,\lambda) \in X_{S}\) and for any function \(f\in C(\Omega)\), there exist a projection cycle \((p^0,\lambda^0) \in X_{S,min}\) such that \(p^0 \subset p\) and the following relations hold
    \begin{enumerate}
        \item \[\lambda^0(x)\lambda(x)>0, \forall x \in p^0 \]
        \item \[\frac{\sum_{x_j \in p^0}\lambda^0_jf(x_j)}{\sum|\lambda^0_j|} \ge \frac{\sum_{x_i \in p}\lambda_if(x_i)}{\sum|\lambda_i|}\]
    \end{enumerate}
\end{lemma}
\begin{proof}
    See \cite[Theorem 2]{Navada}.
\end{proof}
The \textbf{Lemma 2.3} implies that, for any function \(f\),
\[
\max_{(p,\lambda)\in X_{S}} \frac{\sum_{}\lambda_if(x_i)}{\sum|\lambda_i|}=\max_{(p,\lambda)\in X_{S,min}} \frac{\sum_{}\lambda_if(x_i)}{\sum|\lambda_i|}
\]
and
\[
\max_{(p,\lambda)\in X'_{S}} \frac{\sum_{}\lambda_if(x_i)}{\sum|\lambda_i|}=\max_{(p,\lambda)\in X'_{S,min}} \frac{\sum_{}\lambda_if(x_i)}{\sum|\lambda_i|}
\]
\begin{lemma} 
    For any set \(S=S_x\times S_y\times S_z\) where, \(S_x,S_y,S_z \subset [0,1]\) are some finite sets with \(\{0,1\}\subset S_x \cap S_y \cap S_z\) and for any function \(f \in C(\Omega)\) satisfying the inequalities \eqref{e: delta class definition}, the intersection \(X'_S \cap X_{S,f}\) is non-empty. 
\end{lemma}
\begin{proof}
Let's define 
\[
f_n(x,y,z)=f(x,y,z)+\frac{1}{n}(xy+xz+yz), \forall n \in \mathbb{N}
\]
Clearly, the function \(f_n\) satisfies the inequalities \eqref{e:strict-class-definition} and therefore it follows from \textbf{Theorem 2.2} and \textbf{Lemma 2.4} that,
\[
 \max_{(p,\lambda)\in X_{S}} \frac{\sum_{}\lambda_if(x_i)}{\sum|\lambda_i|} =\max_{(p,\lambda)\in X_{S,min}} \frac{\sum_{}\lambda_if(x_i)}{\sum|\lambda_i|} = \max_{(p,\lambda)\in X_{S,min}} \frac{\sum_{}\lambda_i(\lim_{n \rightarrow  \infty}f_{n}(x_i))}{\sum|\lambda_i|}
\]
%And since there are only finitely many terms on the numerator, we can take the limit out:
Here, we can change the order of the limit and the maximum as \(X_{S,min}\) is a finite set by the \textbf{Lemma 2.3} (considering vectors up to multiplication by a constant) and hence,
%The \textbf{Theorem 2.2 } applied to \(f_n\) gives
\[
\max_{(p,\lambda)\in X_{S,min}} \frac{\sum_{}\lambda_i(\lim_{n \rightarrow  \infty}f_{n}(x_i))}{\sum|\lambda_i|}=\lim_{n \rightarrow \infty}\max_{(p,\lambda)\in X_{S,min}} \frac{\sum_{}\lambda_if_{n}(x_i)}{\sum|\lambda_i|}=\lim_{n \rightarrow  \infty}\max_{(p,\lambda) \in X_{S}}\frac{\sum_{}\lambda_if_{n}(x_i)}{\sum|\lambda_i|}
\]

By the \textbf{Theorem 2.2} and \textbf{Lemma 2.4},
\[
\lim_{n \rightarrow  \infty}\max_{(p,\lambda) \in X_{S}}\frac{\sum_{}\lambda_if_{n}(x_i)}{\sum|\lambda_i|}=\lim_{n \to  \infty}\max_{(p,\lambda) \in X'_{S}}\frac{\sum_{}\lambda_if_{n}(x_i)}{\sum|\lambda_i|}=\lim_{n \to  \infty}\max_{(p,\lambda) \in X'_{S,min}}\frac{\sum_{}\lambda_if_{n}(x_i)}{\sum|\lambda_i|}
\]
Changing the order of the limit and maximum once more and using the \textbf{Lemma 2.3}  gives the desired result:
\[
\lim_{n \rightarrow  \infty}\max_{(p,\lambda) \in X'_{S,min}}\frac{\sum_{}\lambda_if_{n}(x_i)}{\sum|\lambda_i|}=\max_{(p,\lambda) \in X'_{S,min}}\frac{\sum_{}\lambda_i(\lim_{n \rightarrow  \infty}f_{n}(x_i))}{\sum|\lambda_i|}=\max_{(p,\lambda) \in X'_{S}}\frac{\sum_{}\lambda_i(f(x_i))}{\sum|\lambda_i|}
\]
Now let's choose \((p^0,\lambda^0) \in X'_{S}\) such that,
\[
\frac{\sum_{}\lambda^0_i(f(x_i))}{\sum|\lambda^0_i|}=\max_{(p,\lambda) \in X'_{S}}\frac{\sum_{}\lambda_i(f(x_i))}{\sum|\lambda_i|}.
\]
Then, 
\[
\frac{\sum_{}\lambda^0_i(f(x_i))}{\sum|\lambda^0_i|}=\max_{(p,\lambda) \in X_{S}}\frac{\sum_{}\lambda_i(f(x_i))}{\sum|\lambda_i|}
\]
and thus, \((p^0,\lambda^0) \in X_{S,f}\) by the definition of \(X_{S,f}\). Hence, \((p^0,\lambda^0) \in X'_{S} \cap X_{S,f}\)
\end{proof}

\subsection{Construction of a finite set containing an extremal projection cycle-vector}
\vspace{15pt}

Above we study some structural properties of optimal projection cycles on certain finite sets. Below, we will use this properties to prove that there is a projection cycle on an explicitly given finite set that gives the supremum \eqref{e:Golomb-applied}. 

We start by defining the desired set.
Let's name the corners of the unit cube from \(T_1\) to \(T_8\) as 
\[T_1=(0,0,0),T_2=(0,0,1),T_3=(1,0,1),T_4=(1,0,0), \]
\[ T_5=(1,1,0),T_6=(0,1,0),T_7=(0,1,1),T_8=(1,1,1).\]
Define the functions,
\begin{align*}
    g_1(x,y,z)=f(x,y,z)-f(x,0,1)-f(1,y,0)-f(0,1,z), \\
    g_2(x,y,z)=f(x,y,z)-f(1,0,z)-f(x,1,0)-f(0,y,1), \\
    g_3(x,y,z)=f(x,y,z)-f(x,0,1)-f(1,0,z)-f(1,y,0), \\
    g_4(x,y,z)=f(x,y,z)-f(1,0,z)-f(1,y,0)-f(x,1,0), \\
    g_5(x,y,z)=f(x,y,z)-f(1,y,0)-f(x,1,0)-f(0,1,z), \\
    g_6(x,y,z)=f(x,y,z)-f(x,1,0)-f(0,1,z)-f(0,y,1), \\
    g_7(x,y,z)=f(x,y,z)-f(0,1,z)-f(0,y,1)-f(x,0,1), \\
    g_8(x,y,z)=f(x,y,z)-f(0,y,1)-f(x,0,1)-f(1,0,z),
\end{align*}
on the unit cube and
\begin{align*}
    h_1(x,y,0)=f(x,y,0)-f(0,y,1)-f(x,0,1),\\
    h_2(x,y,1)=f(x,y,1)-f(1,y,0)-f(x,1,0),\\
    h_3(x,0,z)=f(x,0,z)-f(0,1,z)-f(x,1,0),\\
    h_4(x,1,z)=f(x,1,z)-f(1,0,z)-f(x,0,1),\\
    h_5(0,y,z)=f(0,y,z)-f(1,0,z)-f(1,y,0),\\
    h_6(1,y,z)=f(1,y,z)-f(0,1,z)-f(0,y,1).
\end{align*}
on the faces of the unit cube lying on the planes \(z=0,z=1,y=0,y=1,x=0\) and \(x=1\) correspondingly.

Let \(M_i,1\le i \le 8\) be a maximum point of the function \(g_i\) on the domain \(\Omega=[0,1]^3\).
And \(F_i,1\le i \le 6\) be a maximum point of the function \(h_i\) on the face it's defined.

Let \[U=\{T_i, 1 \le i \le 8\} \cup\{M_i, 1 \le i \le 8\} \cup \{F_i, 1 \le i \le 6\}\]
and let \(U_x,U_y,U_z\) be the set of projections of elements of \(U\) to the coordinate lines \(Ox,Oy,Oz\) respectively. 
%We will call \(U\) the set of maximal efficient points. 
We will see that, the choice of \(M_i\) and \(F_i\) among the maximum points of \(g_i\) and \(h_i\) will not change the correctness of the following theorem.

\begin{remark}
    Some of the points $T_i, \ 1 \le i \le 8$, $M_j, \ 1 \le j \le 8$, $F_k,\ 1 \le k \le 6$ may coincide. In this case, the set $U$ will narrow.
\end{remark}

\begin{theorem} \label{t:Theorem 1}
    Let \(f \in C(\Omega) \) be a function satisfying the inequalities \eqref{e: delta class definition} and  \(S =S_x \times S_y \times S_z \subset \Omega \) be any arbitrary finite set with \(U \subset S\), then we have:
    \begin{equation} \label{e:maximum-clarified}
        \max_{(p,\lambda)\in X_{S} }\frac{\sum_{}\lambda_if(x_i)}{\sum|\lambda_i|} =\max_{(p,\lambda) \in X_{U_x\times U_y \times U_z}}\frac{\sum_{} \lambda_if(x_i)}{\sum|\lambda_i|}
    \end{equation}
\end{theorem}
\begin{proof}
Let, \(X''_{S}\) be the set of projection cycle-vectors \((p,\lambda) \in X_{S}\) that satisfies the propositions \((b),(c),(d)\) of the \textbf{Theorem 2.2}.

It is clear that, \(X'_{S} \subset X''_{S}\) and hence from the \textbf{Lemma 2.5} we have,
\[
\max_{(p,\lambda)\in X_{S} }\frac{\sum_{}\lambda_if(x_i)}{\sum|\lambda_i|}=\max_{(p,\lambda)\in X''_{S} }\frac{\sum_{}\lambda_if(x_i)}{\sum|\lambda_i|}.
\]
Thus, it is enough to prove that
\[
\max_{(p,\lambda)\in X''_{S} }\frac{\sum_{}\lambda_if(x_i)}{\sum|\lambda_i|}=\max_{(p,\lambda) \in X_{U_x\times U_y \times U_z}}\frac{\sum_{} \lambda_if(x_i)}{\sum|\lambda_i|}
\]
Assume the contrary.
Since, \(U \subset S\) and \(S=S_x \times S_y \times S_z\) we have \(U_x \subset S_x\), \(U_y \subset S_y\) and \(U_z \subset S_z\) which imply \(U_x\times U_y \times U_z \subset S\) and therefore we can write the inequality
\[
\max_{(p,\lambda)\in X''_{S} }\frac{\sum_{}\lambda_if(x_i)}{\sum|\lambda_i|} \ge \max_{(p,\lambda) \in X_{U_x\times U_y \times U_z}}\frac{\sum_{} \lambda_if(x_i)}{\sum|\lambda_i|}.
\]
Hence, there exist a projection cycle \((p^0,\lambda^0) \in X''_{S}\) such that
\begin{equation} \label{e: contrary assumption}
    \frac{\sum_{}\lambda^0_if(x^0_i)}{\sum|\lambda^0_i|} > \max_{(p,\lambda) \in X_{U_x\times U_y \times U_z}}\frac{\sum_{} \lambda_if(x_i)}{\sum|\lambda_i|}. 
\end{equation}

Clearly, \((p^0,\lambda^0) \not \in X_{U_x \times U_y \times U_z}\). 

If all points in \(p^0\) with positive weight belong to \(U\), then the set of the projections of them into the edges of the unit cube (which are all the possible locations of points of \(p^0\) with negative weights)  would belong to the set \(U_x \times U_y \times U_z\) and hence we would have \(p^0 \subset U_x \times U_y \times U_z\).

Thus, there exist a point \(x \in p^0\) with positive weight(\(\lambda^0(x)>0\)) such that, \(x \not \in U\). Moreover, let \((p^0,\lambda^0)\) be chosen to minimise the number of positive weighted points not belonging to the set \(U\) among all projection cycle-vectors \((p,\lambda)\in X''_{S}\) satisfying \eqref{e: contrary assumption}.

By and \textbf{Lemma 2.5} and \textbf{Theorem 2.2} part \((d)\), we have that \(x\) cannot be on the edges of the unit cube. Thus, we have the following cases:

    \item[\textbf{Case 1:}] \(x\) is an interior point of one of the faces of the unit cube \(\Omega\).

    Without loss of generality, we can assume that \(x\) belongs to the face lying on the \(xOy\) plane. Then we can write \(x=(\xi,\gamma,0)\) for some \(\xi,\gamma \in (0,1)\). 

    Consider the planes \(x=\xi\) and \(y=\gamma \). In each of these planes, at least one point of \((p^0,\lambda^0)\) with negative weight should exist. By \textbf{Theorem 2.2}, part \((c)\), these negative weighted points could only be on the edges, not adjacent to any of the vertices \((0,0,0)\) and \((1,1,1)\). The intersections of the planes \(x=\xi\) and \(y=\gamma \) and the edges are the points \((\xi,1,0),(\xi,0,1)\) and \((1,\gamma,0),(0,\gamma,1)\) respectively. 

     Since both of \((\xi,1,0)\) and \((1,\gamma,0)\) are well-ordered with \(x\) and lying on an interior plane, by the \textbf{Theorem 2.2}, part \((b)\), none of \((\xi,1,0)\) and \((1,\gamma,0)\) can have a negative weight. Thus, both \((\xi,0,1)\) and \((0,\gamma,1)\) have negative weights. Moreover, since no other negative weighted points can exist on the planes \(x=\xi\) and \(y=\gamma \), we have:
     \begin{equation*} \label{e:inequalities for weights}
     |\lambda^0(\xi,0,1)|\ge \lambda^0(x)\text{ and } |\lambda^0(0,\gamma,1)| \ge \lambda^0(x)
     \end{equation*}
     and thus, \(\min(|\lambda^0(\xi,0,1)|,|\lambda^0(0,\gamma,1)|,|\lambda^0(x)|)=\lambda^0(x)\).

    Let's move the weights on the points \(x\),\((\xi,0,1)\) and \((0,\gamma,1)\) to the points \(F_1=(\xi_1,\gamma_1,0)\) and its two corresponding projections, namely \((\xi_1,0,1)\) and \((0,\gamma_1,1)\). Or in other words, we define \[p'=(x,(\xi,0,1)\,(0,\gamma,1),(\xi_1,\gamma_1,0),(\xi_1,0,1),(0,\gamma_1,1))\]
    and vector 
    \[ \lambda_{\varepsilon}=(-\varepsilon,\varepsilon,\varepsilon,\varepsilon,-\varepsilon,-\varepsilon) \]
    where, \(\varepsilon=\lambda^0(x)\).
    Let \((p^1,\lambda^1)=(p^0,\lambda^0)+(p',\lambda_{\varepsilon})\). Since, at each of the first three points of \(p'\), the weights defined in \((p',\lambda_{\varepsilon})\) and \((p^0,\lambda^0)\) have opposite signs and
    \[ \varepsilon=\min(|\lambda^0(\xi,0,1)|,|\lambda^0(0,\gamma,1)|,|\lambda^0(x))|, \]
    by the \textbf{Lemma 2.2} we have
    %for arbitrarily small \(\varepsilon>0\) we get
    \[
    \sum|\lambda^1_i| \le \sum|\lambda^0_i|
    \]
    On the other hand, 
    \[
    \sum\lambda^1_if(x_i)-\sum\lambda^0_if(x_i)=
    \]
    \[
    =f(\xi_1,\gamma_1,0)-f(\xi_1,1,0)-f(1,\gamma_1,0)-f(\xi,\gamma,0)+f(\xi,1,0)+f(1,\gamma,0)=h(\xi_1,\gamma_1,0)-h(\xi,\gamma,0) \ge 0
    \]
    where the inequality follows from the choice of \(F_1=(\xi_1,\gamma_1,0)\) as maximum of the function \(h_1\).
    Thus, we get
    \[
    \frac{\sum\lambda^1_if(x_i)}{\sum|\lambda^1_i|} \ge \frac{\sum\lambda^0_if(x_i)}{\sum|\lambda^0_i|} >\max_{(p,\lambda) \in X_{U_x\times U_y \times U_z}}\frac{\sum_{} \lambda_if(x_i)}{\sum|\lambda_i|} 
    \]
    Clearly, \((p^1,\lambda^1) \in X''_{S}\) as no negative weighted point became positive weighted and vice versa. Moreover, \(\lambda^1(x)=\lambda^0(x)-\lambda_\varepsilon(x)=0\) and hence, \((p^1,\lambda^1)\) has less number of positive weighted points not belonging \(U\) than \((p^0,\lambda^0)\) has.
    Thus, we get a contradiction to the choice of \((p_0,\lambda_0)\).
    \\
    \\
    \textbf{Case 2:} \(x\) is an interior point of the unit cube \(\Omega\).

    Let \(x=(\xi, \gamma, \zeta)\). Consider the planes \(x=\xi\), \(y=\gamma\), \(z=\zeta\). Their intersections with the edges of the unit cube that are not adjacent to the vertices not adjacent to any of the vertices \((0,0,0)\) and \((1,1,1)\) will be the points \((\xi,1,0),(\xi,0,1)\) and \((1, \gamma, 0),(0, \gamma, 1)\) and \((1, 0, \zeta),(0, 1, \zeta)\) respectively. To make the sum over the corresponding plane zero, at least one (maybe both) of two points in each plane should belong to \((p^0,\lambda^0)\) with a negative weight.

    Hence, all points of at least one of the eight sets 
    \begin{align*}
    G_1(x)=\{(\xi,0,1),(1,\gamma,0),(0,1,\zeta)\}, \\
    G_2(x)=\{(1,0,\zeta),(\xi,1,0),(0,\gamma,1)\}, \\
    G_3(x)=\{(\xi,0,1),(1,0,\zeta),(1,\gamma,0)\}, \\
    G_4(x)=\{(1,0,\zeta),(1,\gamma,0),(\xi,1,0)\}, \\
    G_5(x)=\{(1,\gamma,0),(\xi,1,0),(0,1,\zeta)\}, \\
    G_6(x)=\{(\xi,1,0),(0,1,\zeta),(0,\gamma,1)\}, \\
    G_7(x)=\{(0,1,\zeta),(0,\gamma,1),(\xi,0,1)\},\\
    G_8(x)=\{(0,\gamma,1),(\xi,0,1),(1,0,\zeta)\}
    \end{align*}
    belong to \((p^0,\lambda^0)\) and have negative weights.

For each \(G_i\) we proceed by moving the weights at point \(x\) and elements of \(G_i\) to \(M_i\) and its corresponding projections on the edges. For example, if all elements of \(G_1\) belong to \(p^0\), then we construct
\(p'=(x,(\xi,0,1),(1,\gamma,0),(0,1,\zeta),(\xi_1,\gamma_1,\zeta_1),(\xi_1,0,1),(1,\gamma_!,0),(0,1,\zeta_1))\)
and vector
\(
\lambda_\varepsilon=(-\varepsilon,\varepsilon,\varepsilon,\varepsilon,\varepsilon,-\varepsilon,-\varepsilon,-\varepsilon)
\)
where \(M_1=(\xi_1,\gamma_1,\zeta_1)\) is the maximum point of \(g_1\) defined above and \(\varepsilon>0\). \\ As in \textbf{Case 1}, let \((p^1,\lambda^1)=(p^0,\lambda^0)+(p',\lambda_\varepsilon).\) Since, at each of the first four points of \((p',\lambda_\varepsilon)\), the weights defined in \((p',\lambda_\varepsilon)\) and \((p^0,\lambda^0)\) have opposite signs, by the \textbf{Lemma \textbf{2.2}} for \(\varepsilon=\min(\lambda)\) we have 
\[
\sum|\lambda_i^1| \le \sum |\lambda_j^0|.
\]
Moreover, \[
\sum \lambda^1_if(x^1_i)-\lambda^0_if(x^0_i)=g_1(M_1)-g_1(x) \ge 0.\]\\
Thus, we have
\[
\frac{\sum\lambda^1_if(x_i)}{\sum|\lambda^1_i|} \ge \frac{\sum\lambda^0_if(x_i)}{\sum|\lambda^0_i|}
\]
As in the first case the last inequality contradicts our assumption of \((p^0,\lambda^0)\).
Similarly for all other sets we will get a contradiction.

Since all cases lead to the contradiction, the theorem is proved.

\end{proof}

The proof implies that, the choice of \(M_i\) and \(F_i\) among the maximum points of \(g_i\) and \(h_i\) does not affect to the correctness of the theorem.

Now we are ready to prove the \textbf{Theorem \(2.1\)}.
\begin{proof}[Proof (\textbf{Theorem 2.1})]
Applying the \textbf{Theorem 2.3} in the relation \eqref{e: supremum-maximum} we get
\begin{equation*} \label{e: main result}
   E(f,\Omega)=\sup_{A,B,C}  \left({\max_{(p,\lambda)\in X_{A\times B\times C}} \frac{\sum_{}\lambda_if(x_i)}{\sum|\lambda_i|}}\right)=\sup_{ A,B,C}  \left({\max_{(p,\lambda)\in X_{(U_x \cup A)\times (U_y \cup B) \times (U_z \cup C)}} \frac{\sum_{}\lambda_if(x_i)}{\sum|\lambda_i|}}\right) = 
\end{equation*}
\begin{equation*}
   \sup_{A,B,C}  \left(\max_{(p,\lambda) \in X_{U_x\times U_y \times U_z}}\frac{\sum_{} \lambda_if(x_i)}{\sum|\lambda_i|}\right)=
   \max_{(p,\lambda) \in X_{U_x\times U_y \times U_z}}\frac{\sum_{} \lambda_if(x_i)}{\sum|\lambda_i|}.
\end{equation*}
\end{proof}
\begin{remark}
    The proofs of the \textbf{Theorem 2.3} and the \textbf{Theorem 2.1} shows that, there exists a projection cycle-vector \((p,\lambda) \in X_{U_x\times U_y \times U_z}\) such that \((p,\lambda)\) satisfies all the propositions of the \textbf{Theorem 2.2} and 
    \[
    E(f,\Omega)=\frac{\sum_{x_i \in p} \lambda(x_i)f(x_i)}{\sum_{x_i \in p}|\lambda(x_i)|}.
    \]
    Moreover, it can be reconstructed by only knowing the weights in the vertices and all positive weighted points.
\end{remark}


\section{Minimal Projection Cycles on a Finite Set}
\vspace{15pt}

The relation \eqref{e: main result} implies that, the error can be found by calculating a maximum over a finite set of the form \(V=U_x \times U_y \times U_z\). In this section we will search for \(X'_{V,min}\).

Let \(p=(x_1,x_2,...,x_k)\) be an ordered finite subset of \(\Omega\) with \(k\) points. In order to find all vectors \(\lambda=(\lambda_1,\lambda_2,\dots, \lambda_k)\), such that \((p,\lambda)\) is a projection cycle-vector, we have to solve the system of linear equations \eqref{e: weak projection}. Let this system be represented as 
\begin{equation} \label{e: matrix form}
    A\lambda=0
\end{equation}
for a matrix \(A\).
Below, we will prove some necessary conditions for an ordered subset \(p'\) of \(p\) to be an optimal projection cycle.

We start with a well-known algebraic definition and a lemma (See: Definition 1 and Proposition 7 in \cite{Szalkai_Dosa}). 
\begin{definition}
    Let for any vector \(v=(v_1,...,v_n) \in \mathbb{R}^n\) we define,
    \[
    \operatorname{supp}(v):=\left\{i \leq m: v_i \neq 0\right\}
    \] and call it the support of \(v\). A solution \(v_0\) of the homogeneous linear equation 
    \(
    Mv=0
    \)
    is called a minimal solution if the set \(\operatorname{supp}(v_0)\) is minimal, that is, there exist no other solution \(v\) of the equation satisfying \[\operatorname{supp}(v)\varsubsetneqq \operatorname{supp}(v_0)\]
\end{definition}
\begin{lemma} Let \(M\) be a matrix then a solution \(v_0\) of the equation \(
    Mv=0
    \)
    which \(i_1,i_2,...,i_t\)-th components are nonzero and all other components are zero, is minimal, then the column system consisting \(i_1,i_2,...,i_k\)-th columns of the matrix \(M\) is a minimal linearly dependent column system.
\end{lemma}
\begin{lemma}
Let \(p'=(x_{i_1},x_{i_2},\dots x_{i_t}) \subset p\) be a minimal projection cycle and \(\lambda'=(\lambda'_{i_1},\lambda'_{i_2},\dots \lambda'_{i_t})\) be a vector assigned to \(p'\). Then the vector, \(\lambda=(\lambda_1,...,\lambda_k)\) is a minimal solution of the equation \eqref{e: matrix form}, where, 
\begin{equation} \label{e: vector-g}
    \lambda_i=
    \begin{cases}
        \lambda'_i, \hspace{13pt} \text{ if } i \in \{i_1,i_2,\dots, i_t\} \\
        0, \hspace{17pt}\text{ otherwise }
    \end{cases}
\end{equation}

\end{lemma}
\begin{proof}
    Assume the contrary, suppose \(\lambda\) is not a minimal solution of \eqref{e: matrix form}. Then, there exist a solution \(\lambda^0\) of \eqref{e: matrix form} such that,
    \[
    \operatorname{supp}(\lambda^0)\varsubsetneqq \operatorname{supp}(\lambda).
    \]
    Thus, there exist a nonempty set \(\{j_1,j_2,...,j_s\} \varsubsetneqq \{1,2,...,t\}\) such that the  \(i_{j_1},i_{j_2},...,i_{j_s}\)-th components of \(\lambda^0\) are nonzero and all other components are zero. And, this implies that \[p''=(x_{i_{j_1}},x_{i_{j_2}},...,x_{i_{j_s}}) \varsubsetneqq p' \] is a projection cycle with vector \(\lambda''=(\lambda^0_{i_{j_1}},\lambda^0_{i_{j_2}},...,\lambda^0_{i_{j_s}})\), which contradicts the minimality of \(p'\).
\end{proof}
The next theorem gives a necessary condition on minimality of a projection cycle.

\begin{theorem}
    Let, \(a_i\) denote the \(i\)-th column of the matrix \(A\) and \(p'=(x_{i_1},x_{i_2},\dots x_{i_t}) \subset p\) be a minimal projection cycle, then the set of columns \(\{a_{i_1},a_{i_2},\dots a_{i_t}\}\) is a minimal linearly dependent set of columns.
\end{theorem}
\begin{proof}
    Let \(\lambda'=(\lambda'_{i_1},\lambda'_{i_2},\dots \lambda'_{i_t})\) be a vector assigned to \(p'\) and the vector \(\lambda\) be defined as in \eqref{e: vector-g}. Then, by the\textbf{ Lemma 3.2}, \(\lambda\) is a minimal solution of \eqref{e: matrix form}. Thus, by the\textbf{ Lemma 3.1} the proof follows.
\end{proof}

