%EndExpansion
\overline{3}$ are simple submodules while it is not a simple module. We
investigate the stability of pseudo simple modules under homomorphism, in
factor modules, in direct products and direct sums, in quotient modules, in the
trivial extension $R\ltimes M$ of an $R$-module $M\ $(See, Theorem \ref{homo},
Corollary \ref{cfac}, Theorem \ref{tdir}, Theorem \ref{tdir2}, Theorem
\ref{tquotient} and Theorem \ref{ttri}). Furthermore, we give a complete
classification for finitely generated pseudo simple ${\mathbb{Z}}$-modules
(See, Theorem \ref{fgPS}).

Section 4 is dedicated to the study of compactness, countability axioms, and
connectivity of $D(M)$. We note that the authors in \cite[Proposition
11]{YiKo} showed that $D(R)\ $can not be compact. Unlike $D(R),\ $it is possible that
$D(M)$ is a compact space (See, Example \ref{excom1}, Example \ref{excom2}
and Example \ref{excom3}). We prove that $D(M)\ $is a compact space if and
only if $M\ $has only finitely many simple submodules (See, Theorem
\ref{tcom}). Thanks to this result, we show that if $D(M)$ is a compact space,
then $M$ is a finitely cogenerated module (See, Theorem \ref{tfinitelycog}).
Also, we examine the first and second countability axioms for $D(M)\ $(See,
Proposition \ref{countable}). Moreover, we study the connectivity of the
divisor topology $D(M)\ $(See, Proposition \ref{ultraconnected} and Corollary
\ref{cconnected}).

Consequently, in Section 5, we study the further topological properties of
$D(M)$ such as Hausdorff, $T_{3}$-axiom, $T_{5}$-axiom, discrete and
(completely) normal properties (See, Theorem \ref{Hausdorff*condition},
Theorem \ref{tdiscrete}, Theorem \ref{main}, Proposition \ref{T5}, Corollary
\ref{ccompletely} and Remark \ref{rcompletely}).

\section{Fundamental Properties of Divisor Topology $D(M)$}

Let $M\ $be an $R$-module and $m,n\in M$. We say that an element $m^{\prime
}\in M$ is the greatest common divisor of $m$ and $n$, denoted by $m^{\prime
}=\gcd(m,n),$ if $m^{\prime}\mid m$ and $m^{\prime}\mid n$ with the property
that for any $m^{\prime\prime}\in M$ dividing both $n$ and $m$ implies
$m^{\prime\prime}\mid m^{\prime}$. In a similar fashion, one can define
$\operatorname{lcm}(m,n)$ for any $m,n\in M$. In the following, our first
result indicates that the family $\{U_{m}\}_{m\in M^{\#}}$ is a basis for a
topology on $\operatorname{EC}(M^{\#})$ which is called the divisor topology
of $M$, denoted by $D(M)$. We omit the proof since the proof is analogous to \cite[Proposition
$1$]{YiKo}.

\begin{proposition}
\label{Prop1} Let $M$ be an $R$-module. Then the following statements hold.

(i) $[m]\in U_{m}$ for any $m\in M^{\#}$.

(ii)$\ m\mid n$ if and only if $U_{m}\subseteq U_{n}$ for all $n,m\in M^{\#}$.

(iii) $\bigcup_{m\in M^{\#}}U_{m}=\operatorname{EC}(M^{\#})$

(iv)\ If $[x]\in U_{m}\cap U_{n}$ for some $m,n\in M^{\#},$ then $[x]\in
U_{x}\subseteq U_{m}\cap U_{n}$.

(v) If $\gcd(m,n)\in M^{\#}$ for some $n,m\in M^{\#},$ then $U_{m}\cap
U_{n}=U_{\operatorname{gcd}(n,m)}$.

(vi) Let $U_{m}\subseteq U_{n}$ and $U_{m^{\prime}}\subseteq U_{n}$ for some
$m,m^{\prime},n\in M^{\#}$.$\ $If $\operatorname{lcm}(m,m^{\prime})$ exists,
then $U_{\operatorname{lcm}(m,m^{\prime})}\subseteq U_{n}$.
\end{proposition}

\begin{remark}
We remark that if $M$ is chosen to be a simple module, then $\operatorname{EC}%
(M^{\#})=\emptyset$ and so $D(M)$ is an empty space. Therefore, we will assume
that $M$ is not a simple module unless otherwise specified.
\end{remark}

\begin{example}
Consider the ${\mathbb{Z}}$-module $M={\mathbb{Z}}$, it is clear that
${\mathbb{Z}}^{\#}=\{n\in{\mathbb{Z}}:n\neq0,\pm1\}$ and $U_{m}=\{[n]:m\text{
is integer multiple of $n$}\}$. In this case, $D(M)$ is actually the divisor
topology on the integers in the sense of Steen \cite{Steen}.
\end{example}

\begin{lemma}
\label{smallU_m} Let $M$ be an $R$-module and $m\in M^{\#}$. Then $U_{m}$ is
the smallest open set containing $[m]$.
\end{lemma}

\begin{proof}
The lemma holds in view of Proposition \ref{Prop1}.
\end{proof}

Given a topology, it is sensible to investigate that which separation axioms satisfies. A topological space $X$ is called a $T_{0}$\textit{-space} if, for
every two distinct points, there is an open set that contains exactly one of
them, not the other. $X$ is called a $T_{1}$\textit{-space} if, for every two
distinct points, there are open sets for each containing exactly one of them.
Also, $X$ is said to be a \textit{Hausdorff space} (or $T_{2}$\textit{-space})
if for every two distinct points there exist two disjoint open sets containing
them \cite{Munkres}. The authors in \cite[Proposition 4 and Proposition
5]{YiKo} showed that $D(R)\ $is always a $T_{0}$-space but not a $T_{1}$-space
and Hausdorff. One of the differences between $D(R)$ and $D(M)$ is that $D(M)$
may, in some cases, be a $T_{1}$ space or Hausdorff even discrete space. More
precisely, we give two examples; the first example shows that $D(M)$ is a
$T_{1}$-space and Hausdorff (indeed, $D(M)\ $is discrete), and the latter
example shows that it is not a $T_{1}$-space.

\begin{proposition}
\label{pT0}$D(M)$ is a $T_{0}$-space.
\end{proposition}

\begin{proof}
Choose two distinct points $[m]$ and $[n]$ in $\operatorname{EC}(M^{\#}),$
then $m\nmid n$ or $n\nmid m$. One may assume that $m\nmid n$, leading to
$[m]\not \in U_{n}$ and $[n]\in U_{n}$.
\end{proof}

\begin{example}
\label{ex1}Consider ${\mathbb{Z}}$-module $M={\mathbb{Z}}_{6}.$ Then
$\operatorname{EC}(M^{\#})=\{[\overline{2}],[\overline{3}]\}$ with the basis
$U_{\overline{2}}=\{[\overline{2}]\}$ and $U_{\overline{3}}=\{[\overline
{3}]\}$. In view of Proposition \ref{Prop1}, $D(M)$ is a discrete topology.
\end{example}

\begin{example}
\label{ex2}Consider ${\mathbb{Z}}$-module $M={\mathbb{Z}}_{12}.\ $Then
$\operatorname{EC}(M^{\#})=\{[\overline{2}]=[\overline{10}],[\overline
{3}]=[\overline{9}],[\overline{4}]=[\overline{8}],[\overline{6}]\}$ with the
basis $U_{\overline{2}}=\{[\overline{2}]\}$, $U_{\overline{3}}=\{[\overline
{3}]\}$, $U_{\overline{4}}=\{[\overline{2}],[\overline{4}]\}$ and
$U_{\overline{6}}=\{[\overline{2}],[\overline{3}],[\overline{6}]\}$. One can
see that $D(M)$ is not a $T_{1}$ space since $[\overline{2}]$ and
$[\overline{4}]$ can not be separated by two open sets.
\end{example}

Let $M$ be an $R$-module and $S$ be a subset of $M$. We say that an element
$m\in S$ an \textit{irreducible on }$S$ if whenever $m_{1}\mid m$ for some
$m_{1}\in S$ then $m\mid m_{1}$. It is easy to see that if we take
$S=M,\ $then irreducibles on $S$ are exactly irreducible elements of $M\ $in
the sense \cite{Lu}. For instance, consider ${\mathbb{Z}}$-module
${\mathbb{Z}}_{6}$ then the irreducibles of ${\mathbb{Z}}_{6}$ are
$\{\overline{1},\overline{5}\}$ and irreducibles on $S={\mathbb{Z}}_{6}^{\#}$
are $\{\overline{2},\overline{3},\overline{4}\}$.\ One can easily show that
irreducibles of a noncyclic $R$-module $M$ and irreducibles on $M^{\#}$
coincide. A torsion free $R$-module $M\ $is said to be a \textit{factorial
module} if $M\ $satisfies following two conditions: $(i)\ $every nonzero $m\in
M$ has irreducible factorization, that is,\ $m=q_{1}q_{2}\cdots q_{n}%
m^{\prime}$ for some irreducibles $q_{1},q_{2},\ldots,q_{n}\in R$ and some
irreducible $m^{\prime}\in M\ $and $(ii)$\ if $m=q_{1}q_{2}\cdots
q_{n}m^{\prime}=p_{1}p_{2}\cdots p_{t}m^{\prime\prime}$ has two irreducible
factorizations, then $n=t,\ q_{i}\sim p_{j}$ and $m^{\prime}\sim
m^{\prime\prime}$, that is, every irreducible factorization is unique up to
order and associated elements \cite{Lu}. A nonzero element $m\in M$ is said to
be a \textit{primitive} if $m\ |\ am^{\prime}$ for some $0\neq a\in R$ and
$m^{\prime}\in M,\ $then $m\ |\ m^{\prime}.\ $Every primitive element of a
torsion free module is irreducible, and the converse holds in factorial
modules (See, \cite[Theorem 2.1]{Lu}).

Recall that an element $x$ in the topological space $X$ is called an
\textit{isolated point} if the singleton $\{x\}$ is an open set in
$X\ $\cite{Munkres}. Now, we are ready to determine all isolated points of
$D(M)$ in terms of irreducibles on $M^{\#}.$

\begin{proposition}
\label{isolated} Let $M$ be an $R$-module (not necessarily a torsion free
module). Then $[m]\in\operatorname{EC}(M^{\#})$ is an isolated point if and
only if $m$ is an irreducible element on $M^{\#}$. In particular, if $M\ $is a
noncyclic module, then $[m]\in\operatorname{EC}(M^{\#})$ is an isolated point
if and only if $m$ is an irreducible element of $M.$ Furthermore, if $M\ $is a
factorial module, then $[m]\in\operatorname{EC}(M^{\#})$ is an isolated point
if and only if $m$ is a primitive element of $M.$
\end{proposition}

\begin{proof}
Suppose $[m]$ is an isolated point in $D(M),$ then there exists an open set
$O$ such that $\{[m]\}=O=\bigcup_{x\in\Lambda}U_{x}$ for some indexed set
$\Lambda\subseteq M^{\#}$. Since $U_{m}$ is the smallest open set containing
$[m]$, one must have $\{[m]\}=U_{m}$. Let $m^{\prime}\in M^{\#}$ be a divisor
of $m$ then $[m^{\prime}]\in U_{m}=\{[m]\}$ which implies that
$m\ |\ m^{\prime}.\ $Hence $m$ is irreducible on $M^{\#}$. Conversely, assume
that $m\ $is irreducible on $M^{\#}.\ $Let $[n]\in U_{m}$ then $n\mid m$ but
$m$ is an irreducible, so $m\ |\ n$ and hence $Rm=Rn$ if and only if
$[m]=[n]$. The rest follows from \cite[Theorem 2.1]{Lu}.
\end{proof}

Recall that a topological space $(X,\tau)$ is called a \textit{nested space} if $\tau$ is
linearly ordered by inclusion, or equivalently, every open set $O_{1},O_{2}$
in $X$ are comparable i.e. $O_{1}\subseteq O_{2}$ or $O_{2}\subseteq O_{1}%
\ $\cite{Richmand}. In \cite[Lemma $1$]{YiKo} the authors showed that a
topological space $(X,\tau)$ with a basis $\mathcal{B}$ is a nested space if
and only if any two elements of basis $\mathcal{B}$ is comparable. Now, we
will determine the conditions under which $D(M)$ is a nested topology. Before
this, we need the following result.

\begin{lemma}
\label{divide} Let $M$ be an $R$-module. Then, $M$ is an uniserial module if
and only if $m\mid n$ or $n\mid m$ for every $m,n\in M^{\#}$.
\end{lemma}

\begin{proof}
The first direction of the statement is straightforward. Conversely, suppose
that $m\mid n$ or $n\mid m$ for every $m,n\in M^{\#}$. Now, we will show that
$M\ $is uniserial. Assume that there are submodules $N$ and $L$ of $M$ such
that $N\not \subseteq L$ and $L\not \subseteq N$. It follows that there exist
elements $n\in N\setminus L$ and $l\in L\setminus N$. Then we have $n,l\in
M^{\#}$.\ By the assumption, $n\mid l$ or $l\mid n$, and thus we have
$Rn\subseteq Rl\subseteq L$ or $Rl\subseteq Rn\subseteq N,$ which both of them
are contradictions. Hence, $M$ is an uniserial module.
\end{proof}

\begin{theorem}\label{tnested}
Let $M$ be an $R$-module. Then, $M$ is an uniserial module if and only if $D(M)$ is a nested topology.
\end{theorem}

\begin{proof}
The proof holds in view of Lemma \ref{divide}. Suppose that $m\mid n$ or
$n\mid m$ for all $m,n\in M^{\#}$. It follows that either $U_{m}\subseteq
U_{n}$ or $U_{n}\subseteq U_{m}$, which leads to the result. Conversely, choose $m,n\in
M-\{0\}.$ It is clear that if at least one of them is a generator, then the
proof is done. Now, assume that they are not generators, that is, $m,n\in
M^{\#}$. Then, $U_{m}\subseteq U_{n}$ or $U_{n}\subseteq U_{m}$ by the
assumption. This implies that $m\ |\ n\ $or $n\ |\ m,\ $and so $M$ is a
uniserial module.
\end{proof}

A topological space is called an \textit{Alexandrov space} if the intersection
of an arbitrary family of open sets is also open \cite{Arenas}. This is
equivalent to the existence of a minimal neighborhood for every point $x$ of
$X$.

\begin{proposition}
\label{pAlex}$D(M)$ is an Alexandrov space.
\end{proposition}

\begin{proof}
The proof follows directly from Lemma \ref{smallU_m}.
\end{proof}

\begin{proposition}
\label{closure} Let $M$ be an $R$-module with $[m]\in\operatorname{EC}%
(M^{\#})$. Then,
\[
\overline{\{[m]\}}=\{[n]\in\operatorname{EC}(M^{\#}):m\mid n\}.
\]

\end{proposition}

\begin{proof}
Let $[n]\in\overline{\{[m]\}}$ for some $n\in M^{\#}$. It follows that any
open set containing $[n]$ necessarily contains $[m]$. Since $\left[  n\right]
\in U_{n}$, we have $\left[  m\right]  \in U_{n},\ $that is, $m\ |\ n.\ $%
Conversely, suppose $m\mid n$ for some $n\in M^{\#}$ and choose an open set
$O$ such that $O\cap\{[n]\}\neq\emptyset$. It is obvious that $[m]\in
U_{m}\subseteq U_{n}\subseteq O$ by Lemma \ref{smallU_m}. Thus, $\left[
n\right]  \in\overline{\{[m]\}}$.
\end{proof}

Let $M$ be an $R$-module. The set of all irreducible elements of $M$ is
denoted by $\operatorname{Irr}(M).\ $It is clear that if $M\ $is a cyclic
module, then $\operatorname{Irr}(M)=u(M).\ $ where $u(M)$ is the set of all generators of $M$. If $M\ $is a noncyclic module,
then $\operatorname{Irr}(M)\cap u(M)=\emptyset.$ Recall from \cite{Munkres}
that a topological space $X\ $is said to be a \textit{Baire space} if for
every countable family $\left\{  F_{n}\right\}  _{n\in%
%TCIMACRO{\U{2115} }%
%BeginExpansion
\mathbb{N}
%EndExpansion
}$ of closed sets having an empty interior, then $%
%TCIMACRO{\dbigcup \limits_{n\in\mathbb{N}}}%
%BeginExpansion
{\displaystyle\bigcup\limits_{n\in\mathbb{N}}}
%EndExpansion
F_{n}\ $also has an empty interior, or equivalently, for every countable family
$\left\{  O_{n}\right\}  _{n\in%
%TCIMACRO{\U{2115} }%
%BeginExpansion
\mathbb{N}
%EndExpansion
}$ of open dense sets, their intersection $%
%TCIMACRO{\dbigcap \limits_{n\in\mathbb{N}}}%
%BeginExpansion
{\displaystyle\bigcap\limits_{n\in\mathbb{N}}}
%EndExpansion
O_{n}\ $is dense in $X\ $(See, \cite[Lemma 48.1]{Munkres}). In the following
result, we investigate the open dense set in $D(M)$ for any factorial module
$M,$ and use this fact to prove $D(M)$ is a Baire space for factorial modules.

\begin{theorem}
\label{dense}Let $M$ be a factorial $R$-module with the property that
$\operatorname{Irr}(M)\cap u(M)=\emptyset$. Then, $\operatorname{EC}%
(\operatorname{Irr}(M))$ is dense in $D(M)$. Furthermore, each open dense set
in $D(M)$ contains $\operatorname{EC}(\operatorname{Irr}(M))$.
\end{theorem}

\begin{proof}
We only need to show that $\operatorname{EC}(M^{\#})\subseteq\overline
{\operatorname{EC}(\operatorname{Irr}(M))}$. Any nonzero element $m$ of $M$
has an irreducible factorization $m=r_{1}r_{2}\dots r_{n}m^{\prime}$ where
$r_{1},\dots,r_{n}$ are irreducibles in $R$ and $m^{\prime}$ is irreducible in
$M$. Then, $[m]\in\{\overline{[m^{\prime}]}\}\subseteq\overline
{\operatorname{EC}(\operatorname{Irr}(M))}$ by Proposition \ref{closure} which
implies that $\operatorname{EC}(M^{\#})=\overline{\operatorname{EC}%
(\operatorname{Irr}(M))}$. In addition, take an open dense set $O$ in $D(M)$
then $\overline{O}=\operatorname{EC}(M^{\#})$. Now, let $m\in
\operatorname{Irr}(M)$ then $\left[  m\right]  \in\overline{\operatorname{EC}%
(\operatorname{Irr}(M))}=\operatorname{EC}(M^{\#})=\overline{O}$. It follows
that for any open set $O^{\prime}$ containing $[m]$ intersects with $O$. In
particular, one may choose $O^{\prime}=U_{m}$, and in this case $O^{\prime
}=U_{m}=\{[m]\}$ by Proposition \ref{isolated}. Since $U_{m}\cap
O\neq\emptyset$ we get $[m]\in O$. Therefore, $\operatorname{EC}%
(\operatorname{Irr}(M))\subseteq O$.
\end{proof}

\begin{theorem}
\label{tBaire}Let $M$ be a factorial $R$-module with the property that
$\operatorname{Irr}(M)\cap u(M)=\emptyset$. Then $D(M)$ is a Baire space.
\end{theorem}

\begin{proof}
Follows from Theorem \ref{dense} and \cite[Lemma 48.1]{Munkres}.
\end{proof}

\bigskip The concept of Noetherian rings has a distinguished place in
commutative algebra and algebraic geometry. A ring $R$ is said to be a
\textit{Noetherian ring} if the ascending chain condition holds for an
arbitrary family of its ideals, or equivalently, each ideal of $R$ is finitely
generated \cite{Sharp}. Similarly, recall from \cite{Hars} that a topological
space $X$ is called a \textit{Noetherian space} if the descending chain
condition holds for closed subsets of $X$, alternatively, an ascending chain
condition holds for open subsets of $X$. In the literature, there is a strong
connection between Noetherian rings and Noetherian space in terms of Zariski
topology on $Spec(R):$ if $R\ $is a Noetherian ring, then the Zariski topology
on $Spec(R)$ is a Noetherian space, but the converse is not true in general
\cite{Ohm}. The reader may consult \cite{Hamed}, \cite{Ohm} and
\cite{OzNaTeKo} for more details on rings satisfying the converse of the statement.

Let $X$ be a topological space with the basis $\mathfrak{B}$.\ The authors in
\cite[Theorem 6]{YiKo} showed that $X$ is a Noetherian space if and only if
$X$ satisfies the minimum condition on closed sets if and only if $X\ $satisfies
the maximum condition on open sets if and only if any subfamily $\mathfrak{B}%
^{\prime}$ of $\mathfrak{B}$ has a maximal element. Now, we are ready to
determine the conditions under which $D(M)$ is a Noetherian space.

\begin{theorem}
\label{tNoetherian}Let $M$ be a torsion free $R$-module. Then $D(M)$ is a
Noetherian space if and only if either $M\ $is a simple module or $M$ is a
vector space over the field $R.\ $
\end{theorem}

\begin{proof}
$\left(  \Rightarrow\right)  :\ $Suppose that $D(M)$ is a Noetherian space.
Then, every subfamily $\mathfrak{B}^{\prime}$ of the basis $\mathfrak{B}%
=\left\{  U_{m}\right\}  _{m\in M^{\#}}$ has a maximal element by \cite[Theorem
6]{YiKo}. If there is no element $m\in M^{\#},\ $then $M$ is simple. Now,
assume that $M\ $is not simple so one may choose $m\in M^{\#}.\ $Now, we will
show that $R\ $is a field. Take an element $0\neq a\in R.\ $Since $M\ $is
torsion free, we have $0\neq a^{k}m\in M^{\#}$ and $a^{k}m\ |\ a^{k+1}m$ for
all $k\in%
%TCIMACRO{\U{2115} }%
%BeginExpansion
\mathbb{N}
%EndExpansion
.\ $Now, put $\mathfrak{B}^{\prime}=\left\{  U_{a^{k}m}\right\}  _{k\in%
%TCIMACRO{\U{2115} }%
%BeginExpansion
\mathbb{N}
%EndExpansion
}$ and then $\mathfrak{B}^{\prime}$ has a maximal element, say $U_{a^{t}m}%
.\ $Since $U_{a^{t}m}\subseteq U_{a^{t+1}m},\ $we conclude that $U_{a^{t}%
m}=U_{a^{t+1}m}$ which yields that $a^{t}m=ra^{t+1}m$ for some $r\in R.\ $As
$M\ $is a torsion free module, we have $ra=1$, that is, $a$ is a unit. Hence,
$R\ $is a field.

$\left(  \Leftarrow\right)  :$\ Suppose first $M\ $is a simple module then
$D(M)$ is an empty space, so it is trivially a Noetherian space. Now, assume that
$M$ is a vector space over the field $R.\ $Let $\mathfrak{B}^{\prime}$ be a
subfamily of the basis $\mathfrak{B}=\left\{  U_{m}\right\}  _{m\in M^{\#}}%
.$\ Let $U_{m_{1}}\subseteq U_{m_{2}}$ for some $U_{m_{1}},U_{m_{2}}%
\in\mathfrak{B}^{\prime}.$\ Then $m_{1}\ |\ m_{2}$ so $m_{2}=am_{1}$ for some
$0\neq a\in R.\ $Since $R$ is a field, $m_{1}=a^{-1}m_{2}$ which implies that
$m_{2}\ |\ m_{1}.\ $Thus, we have $U_{m_{1}}=U_{m_{2}}$ which means that every
nonempty subcollection $\mathfrak{B}^{\prime}$ of $\mathfrak{B}$ has a maximal element. Then by
\cite[Theorem 6 (iv)]{YiKo}, $D(M)$ is a Noetherian space.
\end{proof}

\section{Pseudo simple modules vs $T_1$-space}

\bigskip From Example \ref{ex1} and Example \ref{ex2}, one may ask when
$D(M)\ $is a $T_{1}$-space? In this section, we introduce pseudo simple
modules, which are a new generalization of simple modules. We answer the
aforementioned question in the language of algebra by means of pseudo simple
modules. In this section, $R\ $is assumed to be a commutative ring with a
nonzero identity (not necessarily a domain).

\begin{definition}
An $R$-module $M$ is called a pseudo simple if $Rm$ is simple for each $0\neq
m\in M$ with $Rm\neq M$.\ In particular, a ring $R\ $is said to be a pseudo
simple ring if it is a pseudo simple module over itself.
\end{definition}

\begin{lemma}
\label{LemmaPseu} An $R$-module $M$ is a pseudo simple if and only if
$\operatorname{ann}(m)$ is a maximal ideal for every $0\neq m\in M$ with
$Rm\neq M$.
\end{lemma}

\begin{proof}
Suppose that $M\ $is a pseudo simple module and choose $0\neq m\in M$ with
$Rm\neq M$. Let $a\not \in \operatorname{ann}(m)$ then $Ram$ is a nonzero
submodule of $Rm$. It follows that $Ram=Rm$ and then $m=ram$ for some $r\in
R$. Hence, $1-ra\in\operatorname{ann}(m)$, that is, $\operatorname{ann}(m)$ is
a maximal ideal of $R$. Conversely, suppose that $\operatorname{ann}(m)$ is a
maximal ideal for each $0\neq m\in M$ with $Rm\neq M$. Now, take a nonzero
cyclic submodule of $Rm$, namely $Ram=N\subseteq Rm$. Since $N$ is a nonzero
submodule then $a\not \in \operatorname{ann}(m)$. We can now conclude that
$1-ra\in\operatorname{ann}(m)$ by the maximality of $\operatorname{ann}(m)$.
This gives $N=Ram=Rm,\ $and thus $Rm\ $is simple.
\end{proof}

We will list down examples with a non-example of pseudo simple modules.

\begin{example}
(i) Every vector space $V$ is a pseudo simple module

(ii)\ Every simple module is trivially a pseudo simple module.

(iii)$\ {\mathbb{Z}}_{2}\times{\mathbb{Z}}_{2}$ is a pseudo simple as
${\mathbb{Z}}$-module.

(iv) ${\mathbb{Z}}$-module ${\mathbb{Z}}_{6}$ is pseudo simple module apart
from the examples $i)$ and $ii)$. Let $\overline{0}\neq\overline{m}%
\in{\mathbb{Z}}_{6}$ be a nonzero element such that ${\mathbb{Z}}\overline
{m}\neq{\mathbb{Z}}_{6}$. Then, $\overline{m}$ must be in the set
$\{\overline{2},\overline{3},\overline{4}\}$. Observing that
$\operatorname{ann}(\overline{2})=\operatorname{ann}(\overline{4}%
)=3{\mathbb{Z}}$ and $\operatorname{ann}(\overline{3})=2{\mathbb{Z}}$ are both
maximal ideals of ${\mathbb{Z}}$. Therefore, ${\mathbb{Z}}$-module
${\mathbb{Z}}_{6}$ is a pseudo simple ${\mathbb{Z}}$-module.

(v)$\ {\mathbb{Z}}$-module ${\mathbb{Z}}_{12}$ is not a pseudo simple module
since $\operatorname{ann}(\overline{3})=4{\mathbb{Z}}$ is not a maximal ideal.
\end{example}

In the following discussion, we are interested in the following problem. Given
a finitely generated abelian group $G$, is there a way to decide whether $G$
is a pseudo simple ${\mathbb{Z}}$-module or not? The following theorem
provides an affirmative answer.

\begin{theorem}
\label{fgPS} A finitely generated abelian group $G$ is a pseudo simple
${\mathbb{Z}}$-module if and only if $G\cong{\mathbb{Z}}_{p}\oplus{\mathbb{Z}%
}_{q}$ for some distinct primes $p$ and $q$ or $({\mathbb{Z}}_{p})^{n}$ where
$n\geq1$.
\end{theorem}

\begin{proof}
The fundamental theorem of finitely generated abelian groups asserts that any
finitely generated abelian group $G$ can be expressed as
\[
G\cong{\mathbb{Z}}^{n}\oplus{\mathbb{Z}}_{q_{1}}\oplus{\mathbb{Z}}_{q_{2}%
}\oplus\dots\oplus{\mathbb{Z}}_{q_{r}},\quad n\geq0
\]
where $q_{1},\dots,q_{t}$ are prime powers i.e., $q_{r}=p_{r}^{m_{r}}$ for
some prime numbers $p_{r}$ and $m_{r}\geq1$.

Assume $n\geq1$ and let $m=(1,1,\dots,1,\overline{0},\dots,\overline{0})\in G$
then $\operatorname{ann}(m)=0$ which is not maximal, so $G$ is not a pseudo
simple module by Lemma \ref{LemmaPseu}. Therefore, $n=0$ if $G$ is a finitely
generated abelian pseudo simple ${\mathbb{Z}}$-module.

Now, assume that $G\cong{\mathbb{Z}}_{p_{1}^{m_{1}}}\oplus{\mathbb{Z}}%
_{p_{2}^{m_{2}}}\oplus\dots\oplus{\mathbb{Z}}_{p_{r}^{m_{r}}}$ for some prime
numbers $p_{i}$ and $m_{i}\geq1$. Moreover, assume that $m_{1}\geq2$ and set
$m=(\overline{1},\overline{0},\dots,\overline{0})\in G$. This gives
$\operatorname{ann}(m)=p_{1}^{m_{1}}{\mathbb{Z}}$ which is not maximal since
$m_{1}\geq2$. Thus, $m_{i}=1$ for each $i$ if $G$ is pseudo simple.

Now assume that $G\cong{\mathbb{Z}}_{p_{1}}\oplus{\mathbb{Z}}_{p_{2}}%
\oplus\dots\oplus{\mathbb{Z}}_{p_{r}}$ for some prime numbers $p_{1}%
,\dots,p_{r}$. It is obvious that if $r=1$ then $G$ is simple and so pseudo
simple. If $r=2$ then $G\cong{\mathbb{Z}}_{p_{1}}\oplus{\mathbb{Z}}_{p_{2}}$.
In case of $p_{1}=p_{2}$, $\operatorname{ann}(m)=p_{1}{\mathbb{Z}}$ is maximal
for every $0\neq m\in G$. Thus, $G$ is a pseudo simple ${\mathbb{Z}}$-module.
If $p_{1}\neq p_{2}$, consider the nonzero non-generator element
$(\overline{0},\overline{0})\neq(\overline{x},\overline{y})=m^{\prime}\in G$
i.e., $\overline{x}=0$ and $\overline{y}\neq\overline{0}$ or $\overline{x}%
\neq0$ and $\overline{y}=\overline{0}$. It follows that $\operatorname{ann}%
(m^{\prime})=p_{2}{\mathbb{Z}}$ or $\operatorname{ann}(m^{\prime}%
)=p_{1}{\mathbb{Z}}$ which both of them are maximal. Therefore $G$ is a pseudo simple.

Lastly, assume $r\geq3$ and we will show that $\{p_{1},\dots,p_{r}\}$ contains
exactly one prime, that is, $p_{1}=\dots=p_{r}$. Assume $p_{1}\neq p_{2}$ and
set $m=(\overline{1},\overline{1},\overline{0},\dots,\overline{0})\in G$ then
$\operatorname{ann}(m)=p_{1}p_{2}{\mathbb{Z}}$ which is not maximal which
completes the proof.
\end{proof}

\begin{corollary}
\label{pseudoZn}${\mathbb{Z}}$-module ${\mathbb{Z}}_{n}$ is pseudo simple if
and only if $n=p,p^{2}$ or $pq$ where $p$ and $q$ are distinct primes.
\end{corollary}

\begin{proof}
The statement holds in view of Theorem \ref{fgPS}. Let $n=p_{1}^{\alpha_{1}%
}\dots p_{r}^{\alpha_{r}}$ for some distinct primes and $\alpha_{i}\geq1$.
Remark that $r\leq2$ by Theorem \ref{fgPS}. If $r=2$ then $\alpha_{1}%
=\alpha_{2}=1$, i.e., $n=p_{1}p_{2}$ for some distinct primes. Now, assume
that $n=p^{\alpha}$ for some $\alpha\geq1$. It is clear that, ${\mathbb{Z}}%
$-module ${\mathbb{Z}}_{n}$ is pseudo simple if $\alpha=1$. In case of
$\alpha=2$, choose $\overline{0}\neq\overline{m}\in{\mathbb{Z}}_{p^{2}}$ which
is not a generator then $m=pk$ for some $k\in{\mathbb{Z}}$ with $\gcd(k,p)=1$.
It follows that $\operatorname{ann}(\overline{m})=\operatorname{ann}%
(\overline{pk})=\operatorname{ann}(\overline{p})=p{\mathbb{Z}}$. Therefore,
${\mathbb{Z}}$-module ${\mathbb{Z}}_{p^{2}}$ is a pseudo simple.

Now, assume $\alpha\geq3$ then $\operatorname{ann}(\overline{p})=p^{\alpha
-1}{\mathbb{Z}}$ is not maximal since $\alpha\geq3$. Thus, ${\mathbb{Z}}%
$-module ${\mathbb{Z}}_{p^{\alpha}}$ is not pseudo simple if $\alpha\geq3$.
\end{proof}

\begin{theorem}
\label{homo} Let $\phi:M\rightarrow N$ be an $R$-module homomorphism. Then the
following statements hold.

(i) If $M$ is a pseudo simple $R$-module and $\phi$ is a surjective, then $N$
is a pseudo simple $R$-module.

(ii)\ If $N$ is a pseudo simple $R$-module and $\phi$ is an injective, then
$M$ is a pseudo simple $R$-module.
\end{theorem}

\begin{proof}
$(i):$\ Let $0\neq n\in N$ be a nongenerator element such that $\phi(m)=n$ for
some $0\neq m\in M$. Note that $m$ cannot be a generator and
$\operatorname{ann}(m)\subseteq\operatorname{ann}(\phi(m))=\operatorname{ann}%
(n)$. Hence, $\operatorname{ann}(n)$ is a maximal ideal.

$(ii):$\ Let $0\neq m\in M$ be a nongenerator element then $\phi(m)$ can not
be a generator as well. It follows that $\operatorname{ann}%
(m)=\operatorname{ann}(\phi(m))$. Thus, $M$ is a pseudo simple module.
\end{proof}

The following results are immediate consequences of Theorem \ref{homo}.

\begin{corollary}
\label{cfac}(i)\ If $M$ is a pseudo simple $R$-module then each submodule of
$M$ is a pseudo simple $R$-module.

(ii)\ If $M$ is a pseudo simple module then each factor module of $M$ by a
submodule is a pseudo simple $R$-module.

(iii)\ Let $\{M_{i}\}_{i\in I}$ be a set of all $R$-modules $M_{i}$ such that
$\bigoplus_{i}M_{i}$ or $\prod_{i}M_{i}$ is a pseudo simple module. Then, each
$M_{i}$ is a pseudo simple module $R$-module.
\end{corollary}

\begin{theorem}
Let $M$ be an $R$-module with a submodule $N$. Then, $M/N$ is a pseudo simple
$R$-module if and only if $(N:m)$ is a maximal ideal for each $0\neq m\in M$
with $R(m+N)\neq M/N$.
\end{theorem}

\begin{proof}
The first direction follows from the fact that $\operatorname{ann}%
(m+N)=(N:m)$. Conversely, let $\operatorname{ann}(m+N)$ be a maximal ideal for
each $0\neq m\in M$ with $R(m+N)\neq M/N$. Take a nonzero cyclic submodule of
$R(m+N)$, say $M^{\prime}=R(am+N)\subseteq R(m+N)$. Since $M^{\prime}$ is
nonzero then $am\not \in N$ so $a\not \in (N:m)$. Hence, $1-ra\in(N:m)$ for
some $r\in R$. Moreover, $m-ram\in N$. Thus, $M^{\prime}=R(am+N)=R(m+N)$. That
is, $R(m+N)$ is simple.
\end{proof}

\begin{theorem}
\label{tquotient}Suppose $M$ is an $R$-module with a multiplicatively closed
subset $S$ of $R$. If $M$ is a pseudo simple $R$-module with
$\operatorname{ann}(m)\cap S=\emptyset$ for all $m\in M^{\#}$ then $S^{-1}M$
is a pseudo simple $S^{-1}R$ module.
\end{theorem}

\begin{proof}
Let $\frac{m}{s}$ be a nonzero and nongenerator element of $S^{-1}M$. Note
that $\operatorname{ann}(m)\cap S=\emptyset$ and $0\neq m\in M$ is
nongenerator as well. Since $M$ is a pseudo simple then $\operatorname{ann}%
(m)$ is a maximal ideal for each nonzero nongenerator element $m$ of $M$.
Moreover, $S^{-1}(\operatorname{ann}_{R}(m))=\operatorname{ann}_{S^{-1}%
R}(\frac{m}{s})$ is a maximal ideal. Hence, $S^{-1}M$ is a pseudo simple.
\end{proof}

\begin{theorem}
\label{tdir}Let $M_{1}$ and $M_{2}$ be $R$-modules such that at least one of
them is a noncyclic module. Then $M=M_{1}\oplus M_{2}$ is a pseudo simple
$R$-module if and only if $M_{1}$ and $M_{2}$ are pseudo simple $R$-modules
and $\operatorname{ann}(M_{1})=\operatorname{ann}(M_{2})$ is a maximal ideal
of $R$.
\end{theorem}

\begin{proof}
$\Rightarrow:$ It remains to show that $\operatorname{ann}(M_{1}%
)=\operatorname{ann}(M_{2})$ is a maximal ideal of $R$ by Corollary \ref{cfac} (iii).
Let $0\neq m\in M_{1}$ be a fixed element and choose an arbitrary element
$0\neq m^{\prime}\in M_{2}$, then $(0,0)\neq(m,m^{\prime})$ is not a generator
of $M$. It follows that $\operatorname{ann}((m,m^{\prime}))=\operatorname{ann}%
(m)\cap\operatorname{ann}(m^{\prime})$ is a maximal ideal of $R$. Hence we
have $\operatorname{ann}(m)=\operatorname{ann}(m)\cap\operatorname{ann}%
(m^{\prime})$ as $\operatorname{ann}(m)\cap\operatorname{ann}(m^{\prime
})\subseteq\operatorname{ann}(m)$, and this shows that $\operatorname{ann}%
(m)=\operatorname{ann}(m^{\prime})$ is a maximal ideal of $R$. Moreover, we
conclude that $\operatorname{ann}(m)=\cap_{m^{\prime}\in M_{2}}%
\operatorname{ann}(m^{\prime})=\operatorname{ann}(M_{2})$ since $m^{\prime}\in
M_{2}$ is arbitrary. By replacing $m\in M_{1}$ with arbitrary element
$m^{\star}\in M_{1},\ $we obtain $\operatorname{ann}(M_{1})=\operatorname{ann}%
(M_{2}).\ $

$\Leftarrow:$ Suppose that $\ann(M_1)=\ann(M_2)$ is a maximal ideal. Then $\operatorname{ann}(M)=\operatorname{ann}%
(M_{1})\cap\operatorname{ann}(M_{2})=\operatorname{ann}(M_{1})$ is a maximal
ideal. This gives $M=M_{1}\oplus M_{2}$ is a pseudo simple module.
\end{proof}

\begin{theorem}
\label{tdir2}Let $M_{1}$ and $M_{2}$ be two cyclic $R$-modules and
$M=M_{1}\oplus M_{2}$. Then $M$ is pseudo simple $R$-module if and only if
$M_{1}$ and $M_{2}$ are simple modules and one of the following conditions hold:

(i)$\ \operatorname{ann}(M_{1})\neq\operatorname{ann}(M_{2})$ are maximal
ideals of $R$ and $(m_{1},m_{2})$ is a generator of $M$ for all nonzero
$m_{1}$ and $m_{2}$.

(ii)$\ \operatorname{ann}(M_{1})=\operatorname{ann}(M_{2})$ is a maximal ideal
of $R$.
\end{theorem}

\begin{proof}
Suppose $M$ is a pseudo simple $R$-module with $M_{1}=Rx$ and $M_{2}=Ry$ for
some $x\in M_{1}$ and $y\in M_{2}$. We will show that $M_{1}$ is a simple
$R$-module. Since $(x,0)$ is non-generator of $M$ and $M$ is a pseudo simple,
we have $\operatorname{ann}(x,0)=\operatorname{ann}(x)=\operatorname{ann}%
(M_{1})$ is a maximal ideal. This gives $M_{1}$ is a simple module as
$M_{1}\cong R/\operatorname{ann}(x)$. Similarly, one can show that $M_{2}$ is
a simple module. Assume that $\operatorname{ann}(M_{1})\neq\operatorname{ann}%
(M_{2})$. Now, we need to show that $(m_{1},m_{2})$ is a generator of $M$ for
all nonzero $m_{1}$ and $m_{2}$. Suppose to the contrary that $(m_{1},m_{2})$
is not a generator of $M$ for some nonzero $m_{1}$ and $m_{2}$. Since $M$ is a
pseudo simple, $\operatorname{ann}((m_{1},m_{2}))=\operatorname{ann}%
(m_{1})\cap\operatorname{ann}(m_{2})=\operatorname{ann}(M_{1})\cap
\operatorname{ann}(M_{2})$ is a maximal ideal. Then, $\operatorname{ann}%
(M_{1})\cap\operatorname{ann}(M_{2})\subseteq\operatorname{ann}(M_{1}%
),\operatorname{ann}(M_{2})$. Hence, $\operatorname{ann}(M_{1}%
)=\operatorname{ann}(M_{2})$ as $\operatorname{ann}(M_{1})$ is maximal ideal
which completes the proof.

For the only if part, if $(ii)$ holds, then note that $\operatorname{ann}%
(M)=\operatorname{ann}(M_{1})\cap\operatorname{ann}(M_{2})=\operatorname{ann}%
(M_{1})$ is a maximal ideal of $R$. This ensures that $M$ is a pseudo simple
module. Now, assume that $M_{1}$ and $M_{2}$ are two simple modules with
different maximal ideals $\operatorname{ann}(M_{1})$ and $\operatorname{ann}%
(M_{2})$ and also $(m_{1},m_{2})$ is a generator of $M$ for all nonzero
$m_{1}$ and $m_{2}$. Assume moreover that $(m,m^{\prime})\in M$ is a nonzero
nongenerator then by assumption we have either $m=0$ or $m^{\prime}=0$. One
may assume that $m^{\prime}=0$. It follows that $\operatorname{ann}%
((m,m^{\prime}))=\operatorname{ann}(m)=\operatorname{ann}(M_{1})$ is a maximal
ideal. Hence $M$ is a pseudo simple $R$-module since $M_{1}$ is a simple
module and $m\neq0$.
\end{proof}

Let $M$ be an $R$-module. The trivial extesion $R\ltimes M=R\oplus M=\left\{
(r,m):r\in R,m\in M\right\}  $ is a commutative ring with componentwise
addition and the multiplication defined by $(a,m)(b,n)=(ab,an+bm)$ for every
$a,b\in R$ and $m,n\in M$\ \cite{Anderson}.

\begin{theorem}
\label{ttri}Let $M$ be an $R$-module. Then $R\ltimes M$ is a pseudo simple ring
if and only if $R$ is a local ring with a unique maximal ideal
$\operatorname{ann}(M)$ and $\operatorname{ann}(r)=\operatorname{ann}(M)$ for
all nonzero nonunit elements $r$ of $R$.
\end{theorem}

\begin{proof}
$\Rightarrow:$ Let $R\ltimes M$ be a pseudo simple ring. We may assume that
$R$ is not a field. Now, take a nonzero nonunit element $a$ of $R$, then
$(0,0)\neq(a,0)$ is a nongenerator of $R\ltimes M$. Since $R\ltimes M$ is a
pseudo simple ring, we have $\operatorname{ann}((a,0))=\operatorname{ann}%
_{R}(a)\ltimes\operatorname{ann}_{M}(a)$ is a maximal ideal of $R\ltimes M$.
Then by \cite[Theorem 3.2]{Anderson}, $\operatorname{ann}_{M}(a)=M$ and
$\operatorname{ann}_{R}(a)$ is a maximal ideal of $R$. This gives
$a\in\operatorname{ann}(M)$ which implies that $\operatorname{ann}(M)$ is the
unique maximal ideal of $R$. Also note that $\operatorname{ann}%
(a)=\operatorname{ann}(M)$.

$\Leftarrow:$ Let $(0,0)\neq(a,m)$ be a nongenerator of $R\ltimes M$. Assume
that $a=0$ then this gives $\operatorname{ann}((0,m))=\operatorname{ann}%
(m)\ltimes M=\operatorname{ann}(M)\ltimes M$ since $\operatorname{ann}(M)$ is
the unique maximal ideal and $\operatorname{ann}(M)\subseteq\operatorname{ann}%
(m)$. Then by \cite[Theorem 3.2]{Anderson}, $\operatorname{ann}%
((0,m))=\operatorname{ann}(M)\ltimes M$ is a maximal ideal. Now, we assume
that $a\neq0$ then this gives $a$ is a nonunit since $(a,m)$ is a nongenerator
element of $R\ltimes M$. Then, $a\in\operatorname{ann}(M)$ which implies that
$\operatorname{ann}_{M}(a)=M$. It follows from the assumption that
$\operatorname{ann}((a,m))=\operatorname{ann}(a)\cap\operatorname{ann}%
(m)\ltimes\operatorname{ann}_{M}(a)=\operatorname{ann}(M)\ltimes M$. Thus,
$\operatorname{ann}((a,m))=\operatorname{ann}(M)\ltimes M$ is a maximal ideal
of $R\ltimes M$.
\end{proof}

\begin{theorem}
\label{T_1-p.simple} Let $M\ $be a module over an integral domain $R.\ $Then
$D(M)$ is a $T_{1}$-space if and only if $M$ is a pseudo simple $R$-module.
\end{theorem}

\begin{proof}
$\Leftarrow:$ Suppose $M$ is a pseudo simple module and choose $[m]\in
\operatorname{EC}(M^{\#})$. It follows that $Rm$ is a simple module. Now,
choose $[m_{1}]\in\overline{\{[m]\}}$ then $m_{1}\neq0$ and $m\mid m_{1}$ by
Proposition \ref{closure}. Hence, $Rm_{1}=Rm$ as $Rm$ is a simple module.
Therefore, $[m]=[m_{1}]$ so $D(M)$ is a $T_{1}$ space.

$\Rightarrow:$ Suppose $D(M)$ is a $T_{1}$-space then $\overline{\{[m]\}}%
=[m]$. Now, choose $a\not \in \operatorname{ann}(m)$ then note that $am\neq0$
and not a generator. Moreover, $[am]\in\overline{\{[m]\}}=\{[m]\}$ then
$Ram=Rm$. Hence, $1-xa\in\operatorname{ann}(m)$ for some $x\in R$ implying
that $\operatorname{ann}(m)$ is a maximal, which completes the proof.
\end{proof}

\section{Compactness, Connectivity and countability axioms of $D(M)$}

\bigskip In this section, we examine compactness, connectivities, and
countability axioms of $D(M).\ $A topological space $X$ is said to be a
\textit{compact space} if every open covering of $X$ has a finite subcover
\cite{Munkres}. In \cite[Proposition 11]{YiKo}, the authors proved that $D(R)$
is never a compact space. In the following, we show that it is possible for $D(M)$ to be a compact space depending on cases.

