\begin{theorem}
\label{tcom}Let $M\ $be an $R$-module. Then $D(M)$ is a compact space if and
only if the family $\left\{  Rm\right\}  _{m\in M^{\#}}$ has only finitely
many minimal elements with respect to inclusion $\subseteq$ if and only if $M$
has only finitely many simple submodules.
\end{theorem}

