\subsection{Derivation of NV Axes Parameterization}
\label{sec:appendix_axes_derivation}

Equation \eqref{eq:axes-exp} parameterizes the four NV axes $\{\hat{n}_{j}\}$ using the spherical coordinates $(\theta_1, \phi_1)$ of $\hat{n}_1$ and an auxiliary angle $\alpha$, satisfying the tetrahedral constraint $\hat{n}_{k} \cdot \hat{n}_l = -1/3$ ($k \neq l$).

The derivation involves:
\begin{enumerate}
    \item Defining $\hat{n}_1 = (\cos\theta_1\cos\phi_1, \cos\theta_1\sin\phi_1, \sin\theta_1)$.
    \item Defining an orthonormal basis $(\hat{u}, \hat{v}, \hat{n}_1)$ relative to $\hat{n}_1$:
    \begin{align*}
        \hat{u} &= (-\sin\phi_1, \cos\phi_1, 0) \\
        \hat{v} &= (-\sin\theta_1\cos\phi_1, -\sin\theta_1\sin\phi_1, \cos\theta_1)
    \end{align*}
    \item Expressing $\hat{n}_{i}$ ($i=2,3,4$) as $\hat{n}_{j} = c_1 \hat{n}_1 + c_{u,j} \hat{u} + c_{v,j} \hat{v}$.
    \item Applying constraints: $\hat{n}_{j} \cdot \hat{n}_1 = -1/3 \implies c_1 = -1/3$. And $\hat{n}_{j} \cdot \hat{n}_{j} = 1 \implies c_{u,j}^2 + c_{v,j}^2 = 8/9$. Also $\hat{n}_{k} \cdot \hat{n}_l = -1/3 \implies c_{uk}c_{ul} + c_{vk}c_{vl} = -4/9$ for $i \neq j$.
    \item Parameterizing the $(c_{u,j}, c_{v,j})$ components using the angle $\alpha$ and $2\pi/3$ rotations to satisfy the above conditions:
    \begin{align*}
        c_{u,j} &= \frac{2\sqrt{2}}{3} \sin\left(\alpha + \frac{2\pi}{3}(j-2)\right) \\
        c_{v,j} &= \frac{2\sqrt{2}}{3} \cos\left(\alpha + \frac{2\pi}{3}(j-2)\right)
    \end{align*}
    \item Substituting back into $\hat{n}_{j} = c_1 \hat{n}_1 + c_{u,j} \hat{u} + c_{v,j} \hat{v}$ yields the expression in Eq.\eqref{eq:axes-exp}.
\end{enumerate}

\begin{widetext}
    \begin{equation}
    \hat{n}_{j} =
        \begin{cases}
            (\cos\theta_1\cos\phi_1,\, \cos\theta_1\sin\phi_1,\, \sin\theta_1), & j=1, \\[1mm]\\
            -\dfrac{1}{3}(\cos\theta_1\cos\phi_1,\, \cos\theta_1\sin\phi_1,\, \sin\theta_1) \\ \quad
            -\dfrac{2\sqrt{2}}{3}\,\sin\!\Bigl(\alpha+\dfrac{2\pi}{3}(j-2)\Bigr)(-\sin\phi_1,\, -\cos\phi_1,\, 0) \\[1mm]
            \quad -\dfrac{2\sqrt{2}}{3}\,\cos\!\Bigl(\alpha+\dfrac{2\pi}{3}(j-2)\Bigr)(-\sin\theta_1\cos\phi_1,\, -\sin\theta_1\sin\phi_1,\, \cos\theta_1), & j=2,3,4,
        \end{cases}
        \label{eq:axes-exp}
    \end{equation}

\end{widetext}




