\section{The Method of Gallagher and Mueller}
\label{sec3}

We use the same method as \cite{GLSS1}, following Gallagher and Mueller \cite{GaMu78}. Both propositions below come from \cite[Section 2]{GLSS1}, and the proofs are given in Section 4 of \cite{GLSS1}.
The key idea lies in the estimate of the summation over pairs of zeros
\begin{equation}\label{Dsec2a} \Ss(T,\lambda) := \sum_{\substack{\rho,\rho' \\ 0<\gamma, \gamma'\le T \\ |(\gamma-\gamma')L|\le \lambda }} \left(\frac\lambda{L}-|\gamma-\gamma'|\right),
\end{equation}
for a real number $\lambda >0$, which is closely related to the second moment for zeros in short intervals.
\begin{prop}[Gallagher and Mueller {\cite{GaMu78}}] \label{prop1} For $\lambda>0$, we have, as $T\to\infty$,
\[ \int_0^T \left(N\left(t+\tfrac\lambda{L}\right)-N(t)\right)^2 \, dt
= \Ss(T,\lambda) + O(L^2). \]
\end{prop}
On the other hand, we also have the following unconditional estimate for the above second moment of zeros. %the left-hand side of Proposition \ref{lem3}.
Recall for $T\ge 2$, the Riemann-von Mangoldt formula
\[
S(T)
:=
\frac1{\pi}{\rm arg }\, \zeta(\tfrac12+iT)
=
N(T)
-
\frac{T}{2\pi} \log \frac{T}{2\pi e}
-
\frac78
+ O\left(\frac{1}{T}\right),
\]
where the term $O(T^{-1})$ is continuous, see Titchmarsh \cite[Theorem 9.3]{Titchmarsh2} or \cite[Corollary 14.2]{MontgomeryVaughan2007}. Here we assume $T\neq \gamma$ for any zero $\rho=\beta+i\gamma$, and we set $N(T)= N(T^+)$ otherwise.
%\footnote{The choice $N(T)= \frac12(N(T^+)+N(T^-))$ if $T$ is the ordinate of a zero is also commonly made. Our choice is in agreement with \eqref{N(T)}.}.
%Then unconditionally, we have the following estimates due to Gallagher and Mueller {\cite[Section 1]{GaMu78}}, Fujii \cite{Fu74,Fu81} and Tsang \cite[Theorem 13.2]{Tsang84}, which follows from an idea of Selberg.
\begin{prop}[Gallagher and Mueller {\cite{GaMu78}}, Fujii {\cite{Fu74,Fu81}}, Tsang {\cite{Tsang84}}]\label{prop2} For $\lambda>0$, we have, as $T\to\infty$,
\begin{equation*}%\label{lem1_eq}
\int_0^T \left(N\left(t+\tfrac\lambda{L}\right)-N(t)\right)^2 \, dt = \lambda^2T + O\left(\frac{\lambda^2T}L\right) + \int_0^T \left(S\left(t+\tfrac\lambda{L}\right)-S(t)\right)^2 \, dt + O(L^2),
\end{equation*}
and
\begin{equation*}%\label{lem2_eq}
\int_0^T \left(S\left(t+\tfrac\lambda{L}\right) - S(t)\right)^2\, dt = \frac{T}{\pi^2} \log(2+\lambda) + O\left(T\sqrt{\log(2+\lambda)}\right).
\end{equation*}
\end{prop}

Combining the two results, we have for any $\lambda>0$, as $T\to\infty$,
\begin{equation} \begin{split} \label{Dsec2b}
\Ss(T,\lambda)-\lambda^2T &= \int_0^T \left(S\left(t+\tfrac\lambda{L}\right) - S(t)\right)^2\, dt + O\left(\frac{\lambda^2T}L\right) + O(L^2) \\
&= \frac{T}{\pi^2} \log(2+\lambda) + O\left(T\sqrt{\log(2+\lambda)}\right) + O\left(\lambda^2T/L\right).
\end{split}\end{equation}


\section{Proof of Theorem \ref{thm2} and Corollary \ref{cor2}}
\label{sec4}

\begin{proof}[Proof of Theorem \ref{thm2}]
We first evaluate $\Ss(T,M)$ using \hyperref[AH_GLSS]{\bf AH-Pairs}.
Letting $M$ be a positive even integer and taking $\lambda=M$ in \eqref{Dsec2a}, we have on using \eqref{switch} and then \hyperref[AH_GLSS]{\bf AH-Pairs} that 
\[ \begin{split} \Ss(T,M) &= \sum_{\substack{\rho,\rho' \\ 0<\gamma, \gamma'\le T \\ |(\gamma-\gamma')L|\le M }} \left(\frac{M}{L}-|\gamma-\gamma'|\right) = \sum_{\substack{\rho,\rho' \\ (\gamma,\gamma')\in \mathcal{P}(T,M) \\ |(\gamma-\gamma')L|\le M }} \left(\frac{M}{L}-|\gamma-\gamma'|\right) +O\left( \frac{M}{L}\frac{(1+M)T}{L}\right) \\&
= \sum_{|k|\le 2M} \sum_{\substack{\rho, \rho' \\ (\gamma, \gamma') \in \mathcal{B}_{k/2}(T)}} \left(\frac{M}{L}-|\gamma-\gamma'|\right)+O\left( \frac{M^2T}{L^2}\right)\\
%+ O\left(\left(1+\frac{M}L\right)\frac{M^2T}{L^2}\log{\frac{MT}L}\right) \\
% &= TL\sum_{|k|\le 2M} \left(\frac{M}{L}-\frac{|k|}{2L} + O\left(\frac{(|k|+1)}{L} R(T)\right)\right) P_{k/2}(T).
&= T\sum_{|k|\le 2M} \bigl(M-{|k|}/{2} + O\left((|k|+1) R(T)\right)\bigr) P_{k/2}(T) + O\left( \frac{M^2T}{L^2}\right).
\end{split}\]

Writing $k=2j$ if $k$ is even, and $k=2j-1$ otherwise,  we have by \eqref{P_k/2sumbound} as $T\to\infty$,
\begin{equation} \begin{split}\label{D(T,M)1}
\Ss(T,M) &= T\big(M+O(R(T)\big)P_0(T)+ 2T\sum_{k=1}^{2M}\left(M- k/2 + O\left(k R(T)\right)\right) P_{k/2}(T)  +O\left( \frac{M^2T}{L^2}\right) \\
&= \left(MP_0(T) + 2\sum_{k=1}^{2M} \left(M-k/2\right) P_{k/2}(T) + O\left(MR(T)\sum_{k=0}^{2M}P_{k/2}(T) +\frac{M^2}{L^2}\right) \right)T \\
&= \Biggl(MP_0(T) + 2\sum_{j=1}^{M}\left( (M-j+1/2)P_{j-1/2} + (M-j)P_j(T) \right) \\
&\qquad+ O\left(M^2\left(R(T) + \frac1{L^2}\right)\right)\Biggr)T \\
&= \Biggl(MP_0(T) + 2\sum_{j=1}^{M} (M-j)(P_{j-1/2}(T) + P_j(T)) + \sum_{j=1}^{M}P_{j-1/2}(T) \\
&\qquad+ O\left(M^2\left(R(T)+ \frac1{L^2}\right)\right)\Biggr)T.
\end{split}\end{equation}

Next, taking $\lambda=M$ in \eqref{Dsec2b}, we have as $T\to \infty$
\begin{equation}\label{D(T,M)2}
\begin{aligned}
\Ss(T,M) &= \left(M^2 + \frac{\log M}{\pi^2} + O\left(\sqrt{\log M}\right)\right)T \\
&= \left(\frac32 M + 2\sum_{j=1}^{M}(M-j)\left(1-\frac{2}{\pi^2(2j-1)^2} \right)  + O\left(\sqrt{\log M}\right) \right)T,
\end{aligned}
\end{equation}
where the second equality is obtained by noting that
\begin{equation*}%\label{D(T,M)3}
\begin{aligned}
2\sum_{j=1}^{M} (M-j)\left(1-\frac{2}{\pi^2(2j-1)^2} \right)
&= 2\sum_{j=1}^{M}(M-j) - \frac{4}{\pi^2}\sum_{j=1}^{M}\frac{M-j}{(2j-1)^2} \\
&=
\left( 
    M^2 - M \right) - \left(
    \frac{M}2 - \frac{\log M}{\pi^2} + O(1)
\right) \\
&= M^2 -\frac32M + \frac{\log M}{\pi^2} + O(1).
\end{aligned}
\end{equation*}
Combining \eqref{D(T,M)1} and \eqref{D(T,M)2} and dividing by $T$, we obtain \eqref{mainthm}.
\end{proof}

\begin{proof}[Proof of Corollary \ref{cor2}] Assuming \hyperref[AH_GLSS]{\bf AH-Pairs} and \eqref{SumtwoPs}, by \eqref{thm3a} and  $P_{k/2}(T)\ge 0$ we have 
\[ P_0(T)\le P_0(T) +\frac1{M}\sum_{j=1}^M P_{j-1/2}(T) = \frac32 + O\left(\frac{\sqrt{\log M}}{M}\right) + O\left(M\left(R(T)+R_P(T)+ \frac{1}{L^2}\right)\right).\]
Thus, as $T\to \infty$,
% \[ \limsup_{T\to \infty}P_0(T) \le \frac32 + O\left(\frac{\sqrt{\log M}}{M}\right), \]
% and since $M$ can be taken as large as we wish,
% we have $\limsup_{T\to \infty}P_0(T)\le 3/2$.
% and since $M$ can be taken as large as we wish,
\begin{equation}
\limsup_{T\to \infty}P_0(T) \le \frac32 + O\left(\frac{\sqrt{\log M}}{M}\right),
\qquad \text{and thus}
\qquad
P_0(T) \le \frac32 + o(1)
\end{equation}
because $M$ can be taken as large as we wish.
Next, by \eqref{eq:cor1:eq1} we have as $T\to \infty$
\begin{align*}
N^\circledast(T)\le N^\circledast(T) + 2N(T,C_0R(T))
&= \sum_{\substack{\rho,\rho' \\ 0<\gamma, \gamma'\le T \\ |(\gamma-\gamma')L|\le C_0R(T) }} 1 =  \sum_{\substack{\rho,\rho' \\ \frac{T}{\log^2\!T}<\gamma,\gamma'\le T \\ |(\gamma-\gamma')L| \le C_0R(T)}} 1 + O\left(\frac{T}{L}\right)\\
&= |\mathcal{B}_0(T)| +O\left(\frac{T}{L}\right)
= P_0(T)\, TL  + o(TL)
\le \left(\frac32+o(1)\right) TL.
\end{align*}
From \cite[Equation (1.10)]{GLSS1}
we have
\begin{equation}\label{cor2proof} N^*(T) \le
N^*(T) + N_{\beta\neq \frac12}^*(T) \le N^\circledast(T) \le 
\left(\frac32+o(1)\right) TL,
\end{equation}
where 
\[ N_{\beta\neq \frac12}^*(T) := \sum_{\substack{\rho\\ 0<\gamma \le T\\ \beta \neq \frac12}}m_\rho . \]
Thus, by the same argument as in \cite[Equation (1.11) and below]{GLSS1}, we have, letting
\begin{equation}\label{Thm1eq} N_0(T) := \sum_{\substack{\rho\\0<\gamma \le T\\ \beta=\frac12}} 1 \qquad \text{and}\qquad N_s(T) := \sum_{\substack{\rho\ \text{simple} \\ 0<\gamma\le T}} 1,\end{equation} that, by \eqref{cor2proof},
% \[ N_s(T) \ge \sum_{\substack{\rho \\ 0<\gamma\le T}} (2-m_\rho)
% = 2N(T)-N^*(T) \ge 2TL - \frac32 TL + o(TL) = \frac12 N(T) + o(TL) ,\] 
\[ N_s(T) \ge \sum_{\substack{\rho \\ 0<\gamma\le T}} (2-m_\rho)
= 2N(T)- N^*(T) \ge 2N(T) - \left(\frac32+o(1)\right)TL = \left(\frac12+o(1)\right)N(T). \]
% and therefore $N_s(T) \ge \left(\frac12 +o(1)\right) N(T)$.
Similarly, since $N^*(T) \ge N(T)$, we have by \eqref{cor2proof}
% \[
% N_{\beta\neq \frac12}^*(T)\le \left(\frac32+o(1)\right) TL -N^*(T) \le \left(\frac12+o(1)\right) TL, \]
\[
 N_{\beta\neq \frac12}^*(T)\le 
\left(\frac32+o(1)\right)TL
- N^*(T)
\le 
\left(\frac12+o(1)\right)N(T) , \]
which implies since $N_0(T) + N_{\beta\neq \frac12}^*(T)\ge N(T)$ that 
% $N_0(T) \ge\left(\frac12+o(1)\right) TL .$
$N_0(T) \ge (\frac12+o(1)) N(T)$.
\end{proof}
