		u\left( t,x,y \right) =0,  on\,\,\partial \varOmega \times \left( 0,T \right) ,\\
		u\left( 0,x,y \right) =\sin \left( x \right) \sin \left( y \right) ,    \left( x,y \right) \in \varOmega ,\\
		u_t\left( 0,x,y \right) =-2\sin \left( x \right) \sin \left( y \right) ,  \left( x,y \right) \in \varOmega ,\\
		u_{tt}\left( 0,x,y \right) =4\sin \left( x \right) \sin \left( y \right) ,  \left( x,y \right) \in \varOmega ,\\
	\end{cases},
	\label{eq5.6:energy}
\end{equation}
