\section{Reconciliation via conditioning of multivariate t}
\label{app: rec via cond t}

Similarly to the Gaussian case \citep{zambon2024properties}, if the joint base forecast distribution is a multivariate t, then the reconciled distribution and the parameters can be computed in closed-form. 
Theorem~\ref{theorem: t reconc via conditioning} is proved by applying the following result to Eq.~\eqref{eq: posterior predictive mt}.

\begin{proposition} \label{prop: t reconc via conditioning}
Let $\Abf \in \rr^{(n-n_b) \times n_b}$ be the aggregation matrix of a hierarchy with $n$ time series, and let the joint forecast distribution be a multivariate t:
$\YH \sim \mt\big(\yH, \PsiH, \nuhat\big)$.
Then, the reconciled distribution via conditioning of the $n_b$ bottom series is still a multivariate t:
\begin{equation}
\BT
\,\sim\, \mt\big(\bT, \SigmaT_B, \nutil_B\big),
\end{equation}
where
\begin{align}
\bT &= \bH + \left(\PsiH_{UB}^T - \PsiH_B \Abf^T\right) \Qbf^{-1} (\Abf \bH - \uH), \\
\SigmaT_B &= 
C
\left[\PsiH_B - \left(\PsiH_{UB}^T - \PsiH_B \Abf^T\right) \Qbf^{-1} \left(\PsiH_{UB}^T - \PsiH_B \Abf^T\right)^T \right], \\
\nutil_B &= \nuhat + n - n_b,
\end{align}
%
and 
\begin{align}
C &=  \frac{\nuhat +  (\Abf \bH - \uH)^T \Qbf^{-1} (\Abf \bH - \uH)}{\nuhat + (n-n_b)}, \nonumber \\  
\Qbf &= \PsiH_U - \PsiH_{UB} \Abf^T - \Abf \PsiH_{UB}^T + \Abf \PsiH_B \Abf^T.
\end{align}
\end{proposition}
%

To prove Proposition~\ref{prop: t reconc via conditioning}, we first state two technical lemmas about key properties of the multivariate t distribution.
For a proof of these lemmas, we refer to \cite{Kotz_Nadarajah_2004}.

\begin{lemma} \label{lemma: affine transform of multiv t}
Let $\Xbf$ be a $n$-dimensional random vector distributed as a multivariate t:
\[\Xbf \sim \mt\big(\mubf, \Sigmabf, \nu\big),\]
and let $\Vbf \in \rr^{n \times n}$ be full-rank.
Then, the random vector $\Vbf \Xbf$ is distributed as a multivariate t:
\[\Vbf \Xbf \sim \mt\big(\Vbf \mubf, \Vbf \Sigmabf \Vbf^T, \nu\big).\]
\end{lemma}

\begin{lemma} \label{lemma: condit of multiv t}
Let $\Xbf = \begin{bmatrix} \Xbf_1 \\ \Xbf_2 \end{bmatrix} \sim 
\mt\left(\begin{bmatrix} \mubf_1 \\ \mubf_2 \end{bmatrix} , 
\begin{bmatrix} \Sigmabf_{11} & \Sigmabf_{12} \\ \Sigmabf_{21} & \Sigmabf_{22} \end{bmatrix}, \nu\right)$.
Then, the conditional  distribution of $\Xbf_1$ given $\Xbf_2$ is still a multivariate t:
\begin{equation}
\Xbf_1\,|\,\Xbf_2 \sim \mt\big(\mubf_{1|2},\, \Sigmabf_{1|2},\, \nu_{1|2}\big),    
\end{equation}
where
\begin{align}
\mubf_{1|2} &= \mubf_1 + \Sigmabf_{12} \Sigmabf_{22}^{-1} (\xbf_2 - \mubf_2), \\
\Sigmabf_{1|2} &= \frac{\nu + (\xbf_2 - \mubf_2)^T \Sigmabf_{22}^{-1} (\xbf_2 - \mubf_2)}{\nu + n_2} 
\left[ \Sigmabf_{11} - \Sigmabf_{12} \Sigmabf_{22}^{-1} \Sigmabf_{21} \right], \\
\nu_{1|2} &= \nu + n_2.
\end{align}
\end{lemma}

\begin{proof}[Proof of Proposition~\ref{prop: t reconc via conditioning}]

Let us define $\Tbf \in \rr^{n \times n}$ as
\begin{equation*}
\Tbf = \begin{bmatrix} \textbf{0} & \Ibf_{n_b} \\
\Ibf_{n-n_b} & -\Abf \end{bmatrix},
\end{equation*}
%
and let $\Zbf := \Tbf\YH$.
Since $\Tbf$ is full-rank, from Lemma~\ref{lemma: affine transform of multiv t}, $\Zbf$ is a multivariate t:
\begin{equation}
\Zbf \sim \mt\left( \Tbf \yH, \, \Tbf\PsiH\Tbf^T,\, \nuhat \right),
\end{equation}
where
\begin{align}\label{eq: T Sigma T}
\Tbf \yH &= \begin{bmatrix} \bH \\ \uH - \Abf \bH \end{bmatrix}, \nonumber \\
\Tbf \PsiH \Tbf^T &= \begin{bmatrix} \PsiH_B & \PsiH_{UB}^T - \PsiH_B \Abf^T \\
\PsiH_{UB} - \Abf \PsiH_B & \Qbf \end{bmatrix}, \end{align}
and $\Qbf= \PsiH_U - \PsiH_{UB} \Abf^T - \Abf \PsiH_{UB}^T + \Abf \PsiH_B \Abf^T$.
%
Since 
\[\Zbf = \begin{bmatrix} \BH \\ \UH - \Abf\BH \end{bmatrix} =: \begin{bmatrix} \Zbf_1 \\ \Zbf_2 \end{bmatrix},\]
the reconciled bottom distribution is given by the conditional distribution of $\Zbf_1$ given $\Zbf_2=0$.
%
From Lemma~\ref{lemma: condit of multiv t}, we have that 
\begin{equation*}
\Zbf_1 \,|\, \Zbf_2 = 0 \sim \mt\left(\mubf_{1|2}, \,\Sigmabf_{1|2}, \nutil_{1|2}\right), 
\end{equation*}
where
\begin{align*}
\mubf_{1|2} &= \bH + \left(\PsiH_{UB}^T - \PsiH_B \Abf^T\right) \Qbf^{-1} (\Abf \bH - \uH) = \bT, \\
\nutil_{1|2} &= \nuhat + (n-n_b) = \nutil_B, \\
\Sigmabf_{1|2} &= \frac{\nuhat + (\Abf \bH - \uH)^T \Qbf^{-1} (\Abf \bH - \uH)}{\nuhat + (n-n_b)} \; \left[\PsiH_B - \left(\PsiH_{UB}^T - \PsiH_B \Abf^T\right) \Qbf^{-1} \left(\PsiH_{UB}^T - \PsiH_B \Abf^T\right)^T \right]  \\
&= C \; \left[\PsiH_B - \left(\PsiH_{UB}^T - \PsiH_B \Abf^T\right) \Qbf^{-1} \left(\PsiH_{UB}^T - \PsiH_B \Abf^T\right)^T \right] 
= \SigmaT_B.
\end{align*}
\end{proof}

