\title{Toric reduction of singularities for Newton non-degenerate $p$-forms}
\author{Bilal Balo}
\date{}
\maketitle


\begin{abstract}
    \no We study a class of holomorphic $p$-forms satisfying non-degeneracy conditions expressed through their Newton polyhedron. We show that a regular refinement of their dual fan defines a toric reduction of singularities to a log-smooth $p$-form.
\end{abstract}
