\section{Newton non-degeneracy condition}

In this paper we adopt the convention that the set $\nnn$ contains $0$:
$\nnn=\{0,1,2,3,\ldots\}$. Let $n$ and $p$ be fixed integers such that $n\ge 2$ and $1\le p<n$. 

\subsection{Newton polyhedron of a $p$-form.} We denote by $X=(x_1,\dots,x_n)$ the standard coordinate system on $\ccc^n$.  We identify $n$-tuples in $\ccc^n$ with lign matrices. The notation $\langle \cdot | \cdot \rangle$ stands for the usual dot product on $\ccc^n$. Let $N$ be an $n$-dimensional smooth complex analytic space and $P\in N$, for any local coordinates $Z=(z_1,\dots,z_n)$ centered at $P$ and any $n\times n$ matrix $M=(v_{ij})$ with entries $v_{ij}$ in $\nnn$, we set $Z^M = (z_1^{v_{11}}\cdots z_n^{v_{1n}}, \dots,z_1^{v_{n1}}\cdots z_n^{v_{nn}})$. If $I=(i_1,\dots,i_n)\in \nnn^n$ is a line matrix, we will identify $Z^I$ with the monomial $z_1^{i_1}\dots z_n^{i_n}$. We will also use these notations for points $c=(c_1,\dots,c_n)\in \ccc^n$, namely: $c^M=(c_1^{v_{11}}\cdots c_n^{v_{1n}}, \dots,c_1^{v_{n1}}\cdots c_n^{v_{nn}})$ and $c^I =c_1^{i_1}\dots c_n^{i_n} $. For any finite set $J$, the number of elements of $J$ is denoted by $|J|$. When $J\subset\{1,\dots,n\}$ has $q$ elements $j_1<\dots<j_q$, we set $Z_J=z_{j_1}\dots z_{j_q}$ and $dZ_J = dz_{j_1}\wedge \dots \wedge dz_{j_q}$. If $q=p$, the logarithmic $p$-differentials are:

\begin{equation*}
    \frac{dZ_J}{Z_J} = \frac{dz_{j_1}}{z_{j_1}}\wedge \dots \wedge \frac{dz_{j_p}}{z_{j_p}}.
\end{equation*}

\medskip

\noindent Let $\eta$ be a holomorphic $p$-form defined on $\ccc^n$. Taking $N=\ccc^n$ and $Z=X$ allows us to express $\eta$ in a logarithmic way in the standard coordinate system:

\begin{equation}\label{logway}
\eta(X) = \sum_{|J|=p}f_J(X)\frac{dX_J}{X_J}.
\end{equation}

\smallskip

\no In the above expression, the subscript $|J| = p$ means that the sum is indexed by all the subsets $J\subset \{1,\dots,n\}$ with $|J| = p$. The coefficients $f_J(X)$ are holomorphic functions on $\ccc^n$ such that $\frac{f_J(X)}{X_J}$ is holomorphic. Expanding the functions $f_J(X)$ into power series, we obtain
\begin{equation}\label{powseries}
\eta(X) = \sum_{|J| = p} \left(\sum_{I\in \nnn^n} a_{I,J}X^{I}\right)\frac{dX_J}{X_J}, 
\end{equation}
where the coefficients $a_{I,J}$ are complex numbers and $X_J$ appears in every non-zero monomial $a_{I,J}X^{I}$. This means that if a coordinate of $I$ indexed by $J$ is zero, then $a_{I,J}=0$.  

\medskip

\noindent For any subset $A\subset \nnn^n$, we define $\eta_{A}$ by restricting the exponents in the expression of $\eta$ to $A$ :
\begin{equation*}
\eta_A(X) = \sum_{|J| = p} \left(f_J\right)_{|A}(X)\frac{dX_J}{X_J},
\end{equation*}

\noindent where 
\begin{equation*}
    \left(f_J\right)_{|A}(X)=\sum_{I\in A} a_{I,J}X^{I}.
\end{equation*}

\medskip

\noindent We then define the \emph{support} $\supp \eta$ of $\eta$: 
\begin{equation*}
    \supp \eta = \left\{I\in\nnn^n \mid \exists J\subset\{1,\dots,n\}, |J|=p \text{  and  }  a_{I,J}\ne 0\right\}.
\end{equation*}


\noindent \cref{Newtonpolyhedron} and \cref{nnd} below draw both from \cite{brunella1990topological}  and \cite{esterov2005indices}.

\begin{defn} \label{Newtonpolyhedron}
Let $A\subset \rrr_{\ge 0}^n$ The \emph{Newton polyhedron} of $A$, denoted by $\Gamma = \Gamma(A)$ is the convex envelope of 
\[\bigcup_{I\in A}\left(I+\rrr_{+}^n\right).\]
Its boundary is called the \emph{Newton boundary}. The dimension $1$ faces of $\Gamma$ are called \emph{edges} and the codimension $1$ one are \emph{facets}. The Newton polyhedron of $\eta$ is, by definition, the Newton polyhedron of its support.
\end{defn}

\nocite{fernandez2022characterization} \nocite{loray:hal-00016434}


