\subsection{Newton non-degeneracy.}

\begin{defn}
    Let $\eta$ be a holomorphic $p$-form on $\ccc^n$ written as $\eta =\sum_{|J|=p} g_J(X)dX_J$, where $g_J(X)$ are holomorphic functions. The \emph{singular locus} of $\eta$ is defined as the common zeroes of the coefficients $g_J$:
\begin{equation*}
    \sing \eta  = \left\{c\in \ccc^n \mid \forall J\subset\ \{1,\dots,n \}, |J| = p, \; g_J(c) =0  \right\}.
\end{equation*}

\no Its elements are called \emph{singularities} or \emph{singular points} of $\eta$.

\end{defn}

\begin{defn} \label{nnd}
Let $\eta$ be a holomorphic $p$-form on $\ccc^n$, denote by $\Gamma$ its Newton polyhedron. We say that $\eta$ is \emph{Newton non-degenerate} (NND) if for any non-empty face $F$ of $\Gamma$, the so called \emph{initial form} $\eta_F$ has no singularities in $\left(\ccc^{*}\right)^n$. 

\begin{rke}
    Suppose $\eta $ is expressed logarithmically as in \cref{logway}:
    \begin{equation*}
        \eta(X) =\sum_{|J|=p} \frac{f_J(X)}{X_J} dX_J.
    \end{equation*}
    \no Let $F$ be a non-empty face of $\Gamma$ and $J\subset\{1,\dots,n\}$ with $|J|=p$. As $\left(\frac{f_J}{X_J}\right)_{|F} = \frac{\left({f_J}\right)_{|F}}{X_J}$, for any $c\in\left(\ccc^{*}\right)^n$, $\left(\frac{f_J}{X_J}\right)_{|F}(c) =0$ if and only if $\left(f_J\right)_{|F}(c) = 0$. Thus, \cref{nnd} is equivalent to the following: for any non-empty face $F\subset \Gamma$ and $J\subset\{1,\dots,n\}$ with $|J|=p$, the functions $(f_J)_{|F}$ have no common zeroes in $\left(\ccc^{*}\right)^n$.
\end{rke}

\end{defn}

\begin{ex}
    We examine \cref{ex1.2} and \cref{ex1.3}, starting by $\eta(x,y) = (2x^3+x^2y)\frac{dx}{x}+(x^2y+y^3+xy)\frac{dy}{y}$.  

    \medskip

     \no A practical observation is that the NND condition is automatically verified for vertices, so they don't play a role in the definition. Nevertheless, let's check it this time by computing the initial forms: $\eta_{\{(0,3)\}}(x,y) = y^2 dy$, $\eta_{\{(1,1)\}}(x,y) = xdy$ and $\eta_{\{(3,0)\}}(x,y) = 2x^2dx$. As expected, they only have singularities in the coordinate hyperplanes. For the facets, the initial forms are $\eta_{F_1}(x,y) = y^2 dy$, $\eta_{F_2}(x,y) =(y^2+x)dy$, $\eta_{F_3}(x,y) = 2x^2dx+xdy$ and $\eta_{F_4}(x,y) = 2x^2dx$. We notice that $\eta_{F_2}$ has a curve of singularities intersecting $\left(\ccc^{*}\right)^2$. Let's look at the full face $F = \Gamma$, the associated initial form $\eta_\Gamma$ is $\eta$ itself. It has two singularities: $(0,0)$ and $(-\frac 15,\frac{2}{5})\in \left(\ccc^{*}\right)^2$. We conclude that the faces $F_2$ and $\Gamma$ prevent $\eta$ from being NND.


    \bigskip

    \noindent We can find the initial forms for $\omega$ with \cref{boundary}. Notice that the support point $(4,2,2)$ given by the monomial $x^4yzdy\wedge dz$ does not belong to the Newton boundary, it is in the interior of the Newton polyhedron. 

    \smallskip

    \no To begin, we consider the edges of $\Gamma$. For instance, $\omega_{F_1\cap F_2}(x,y,z) = xz dx\wedge dz$ is a monomial. This is also true for the initial forms defined by the remaining five non-compact edges. Let's look at the compact ones, for example: $\omega_{F_4 \cap F_5}(x,y,z) = xy dx \wedge dy + xzdx \wedge dz$. Here again the NND condition is fullfilled and this will also be the case for the $2$ other segments of $F_5$. Now, considering facets: $F_1$, $F_3$ and $F_7$ define monomials. The point $(4,2,2)$ associated to the monomial $x^4yzdy\wedge dz$ may be in the support of $\eta$, but it is outside of the face $F_4$, so $\omega_{F_4}(x,y,z) = xydx \wedge dy+ xz dx\wedge dz + x^6 dy\wedge dz$, whose singular locus is the hyperplane $\{x=0\}$. We can make the same type of verifications for $F_2$, $F_5$ and $F_6$. The initial form associated to the full face $\Gamma$ is $\omega$. Its singular locus is defined by a polynomial system whose set of solutions is the $y$-axis $\{x=z=0\}$. We conclude that $\omega$ is NND.
\end{ex}


\section{Toric background} In this section, we collect some results on normal toric varieties. We follow closely the introduction found in \cite{aroca2013torical}. A general reference on toric geometry is \cite{cox2024toric}. One can also consult the second chapter in \cite{oka1997non} for an introduction to toric morphisms.

\subsection{Cones and fans} 


    Let $v_1,\dots,v_q\in \rrr^n$. The \emph{convex polyhedral cone} generated by $v_1,\dots,v_q$ is the subset
\begin{equation*}
    \sigma = \left\{\lambda_1 v_1 +\dots +\lambda_q v_q, \lambda_k\in \rrr_{\ge 0}, k=1,\dots, q\right \}\subset \rrr^n.
\end{equation*}

\no We will often shortly refer to these objects as ‘cones’. The vectors $v_k$ are called \emph{generators} of the cone. A convex polyhedral cone is said to be \emph{rational} if it has a set of generators in $\zzz^n$. A rational polyhedral cone is said to be \emph{strongly convex} if it does not contain any non-trivial linear subspace.

\medskip

\no Let $\sigma \subset \rrr^n$ a strongly convex rational polyhedral cone. The $1$-dimensional faces of $\sigma$ are half-lines called \emph{rays} and each of them has a unique generator in $\zzz^n$ whose coordinates have greatest common divisor 1. Considering all the $1$-dimensional faces of $\sigma$, we thus define a set of vectors in $\zzz^n$ which generates $\sigma$ (see Lemma 1.2.15. in \cite{cox2024toric} for more details). We call it the set of \emph{minimal generators} of the strongly convex rational polyhedral cone $\sigma$.

\medskip

\no A strongly convex rational polyhedral cone $\sigma \subset \rrr^n$ is \emph{smooth} if its minimal generators form part of a $\zzz$-basis of $\zzz^n$.

\medskip

\no A fan $\Sigma$ in $\rrr^n$ is a finite collection of cones $\sigma \subset \rrr^n$ such that:

\begin{enumerate}
    \item[$a)$] Each $\sigma\in \Sigma$ is a strongly convex rational polyhedral cone;
    \item[$b)$] For all $\sigma \in \Sigma$, each face of $\sigma$ is also in $\Sigma$;
    \item[$c)$] For all $\sigma_1,\sigma_2 \in \Sigma$, the intersection $\sigma_1 \cap \sigma_2$ is a face of each (hence, also in $\Sigma$).
\end{enumerate}

\no Given a fan $\Sigma$ in $\rrr^n$, we will say that $\sigma\in \Sigma$ is a \emph{maximal cone} of $\Sigma$ if it is maximal for the inclusion among the cones of $\Sigma$. The fan $\Sigma$ is \emph{regular} when each of its cones are smooth (in practice, it is sufficient to check that the maximal cones are smooth). Let $\Sigma$ and $\Sigma'$ be fans in $\rrr^n$, we say that $\Sigma'$ is a refinement of $\Sigma$ if every $\sigma \in \Sigma$ is a union of cones in $\Sigma'$. We refer to \cite{cox2024toric} for the proof of the existence of regular refinements.

\begin{thm}
    Any fan in $\rrr^n$ has a regular refinement.
\end{thm}

\begin{defn}
    Let $\eta$ be a non identically zero holomorphic $p$-form on $\ccc^n$ and $\Gamma$ its Newton polyhedron. For any non-empty face $F\subset \Gamma$, the normal vectors to the facets of $\Gamma$ containing $F$ which are in the orthant $\rrr_{\ge 0}^n$ generate a cone denoted by $C_F$. The set of all the such cones
\begin{equation*}
    \Sigma(\eta) = \{C_F, \; F \text{ is a non-empty face of } \Gamma\}
\end{equation*}

\no is a fan called the \emph{dual fan} of $\eta$.
\end{defn}


\subsection{Varieties and morphisms} \label{varsandmorphs}  We refer to \cite{cox2024toric} and \cite{oka1997non} for the proofs of the following results. For our purposes, we will only need the expression of a toric morphism in affine charts. 

\begin{defn}
    A \emph{toric variety} of dimension $n$ is an irreducible complex algebraic variety $V$ containing a torus $T_N\cong \left(\ccc^{*}\right)^n$ as a Zariski open subset such that the action of $T_N$ on itself extends to an action $T_N\times V \longrightarrow V$ given by a morphism of algebraic varieties.
\end{defn}

\no To any fan $\Sigma$ in $\rrr^n$, we can associate a normal separated toric variety $X_{\Sigma}$ (Theorem 3.1.5 in \cite{cox2024toric}). Moreover, if the fan $\Sigma$ is regular, then $X_{\Sigma}$ is a smooth variety.

\begin{defn}
    Let $\Sigma$ and $\Sigma'$ be fans in $\rrr^n$. A morphism $\pi : X_{\Sigma} \longrightarrow X_{\Sigma'}$ is \emph{toric} if $\pi$ maps the torus $T\subset X_{\Sigma}$ into $T'\subset X_{\Sigma'}$ and $\pi_{|T}$ is a group morphism.
\end{defn}

\begin{thm} \label{refinement}
    Let $\Sigma$ and $\Sigma'$ be fans in $\rrr^n$. If $\Sigma$ is a refinement of $\Sigma'$, then it induces a proper birational toric morphism $\pi : X_{\Sigma} \longrightarrow X_{\Sigma'}$.
\end{thm}

\no Suppose that in the previous theorem, $\Sigma'$ is the fan whose only maximal cone is the orthant $\rrr_{\ge 0}^n$, then $X_{\Sigma'} = \ccc^n$. Let $\mathcal{U}_{\sigma}$ be an affine chart of $X_{\Sigma}$ defined by a maximal cone $\sigma$ with minimal generators $v_1,\dots,v_n$. For any $k\in\{1,\dots,n\}$, we can write $v_k = (v_{1k},\dots,v_{nk})\in \nnn^n$. Let $M$ be the matrix whose columns are given by the coordinates of the generators:
    \begin{equation*}
          M  = \bordermatrix{
           & v_{1} & v_{2} & \dots & v_{n} \cr
     & v_{11} & v_{12} & \dots & v_{1n} \cr
     & v_{21} & v_{22} &  \dots & v_{2n} \cr
     & \vdots & \ddots & \vdots & \vdots \cr
     & v_{n1} & v_{n2} & \dots & v_{nn} \cr
  }
      \end{equation*}

\smallskip

\no Let $Y=(y_1,\dots,y_n)$ be coordinates on $\mathcal{U}_\sigma$, then the morphism $\pi_{|\mathcal{U}_\sigma}$ is given by $X=Y^M$.

\section{Reduction of singularities}

\subsection{Log-smooth $p$-forms} We first precise what we mean by an adapted or log-smooth $p$-form with respect to a divisor, as these notions appear in \cref{Reduction theorem}. 

\nocite{cano2013theorie}  \nocite{duqueelim} \nocite{cano2022truncated} \nocite{camacho1984topological}


\begin{defn}
    Let $\eta$ be holomorphic $p$-form defined on $\ccc^n$ and $A\subset\{1,\dots,n\}$. We consider the divisor $E = \left(\prod_{k\in A } x_k = 0\right)$, suppose that $\eta$ can be written

    \begin{equation} \label{adapt}
        \eta = \prod_{k\in A}x_k^{t_k} \sum_{|J|=p}  g_J(X)\frac{dX_J}{X_J},
    \end{equation}

    \no where the coefficients $g_J(X)$ are holomorphic functions and $t_k \in \nnn^{*}$ for $k\in A$. We will say that

    \begin{enumerate}
        \item[$a)$] $\eta$ is \emph{adapted} to the divisor $E$ if each coefficient $g_J(X)$ is divisible by the monomial $X_{J\setminus A} = \prod_{k\in J\setminus A} x_k$;
        \item[$b)$] $\eta$ is \emph{log-smooth} with respect to the divisor $E$ if the functions $g_J(X)$ have no common zeroes in $\ccc^n$.
    \end{enumerate}

\end{defn}



\begin{rke}
  One should note that even with $p=1$, these definitions differ from the standard ones for codimension 1 foliations found in \cite{cano1998reduction} and \cite{molina2020newton}: 
  \begin{enumerate}
      \item[-] both definitions are formulated globally;
      \item[-] in $a)$, the coefficients $g_J(X)$ of the $p$-form may have common factors;
      \item[-] definition $b)$ is not equivalent to the notion of logarithmical regularity studied in \cite{molina2020newton} since we ask for the coefficients $g_J(X)$ to share no common zeroes instead of $\frac{g_J(X)}{X_{J\setminus A}}$.
  \end{enumerate}  

  \smallskip
  \no Definitions $a)$ and $b)$ apply to a form $\eta$ defined on a smooth variety by taking local coordinates.
\end{rke}


\subsection{Reduction theorem}

\begin{thm}\label{Reduction theorem}
     Let $\eta$ be a non identically zero holomorphic $p$-form defined on $\ccc^n$. We denote by $\Gamma$ its Newton polyhedron and by $\Sigma$ a regular refinement of the dual fan of $\eta$. Let $\pi : X_\Sigma \longrightarrow \ccc^n$ be the associated proper birational toric morphism. Consider an affine chart $\mathcal{U}_\sigma$ of $X_\Sigma$ defined by a maximal cone $\sigma\in \Sigma$ with minimal generators $v_1,\dots,v_n$. Set $t_k=\min_{I\in \Gamma}\langle v_k,I \rangle$, where $k\in\{1,\dots,n\}$. Denote by $Y=(y_1,\dots,y_n)$  coordinates on $\mathcal{U}_\sigma$. The equation $y_1^{t_1}\dots y_n^{t_n} = 0$ defines a normal crossings divisor $E$ on $X_\Sigma$. 
    \begin{enumerate}
        \item[$1)$] The pull-back $\pi^{*}\eta$ is adapted to the divisor $E$.
        \item[$2)$] Suppose that $\eta$ is Newton non-degenerate, then $\pi^{*}\eta$ is log-smooth with respect to $E$.
    \end{enumerate}
\end{thm}

\begin{proof}


     \no  We will keep the same notations as in \cref{varsandmorphs}. We want to compute the pull-back of $\eta$ by $\pi$ in the chart $\mathcal{U}_{\sigma}$. Let $Y=(y_1,\dots,y_n)$ be coordinates on $\mathcal{U}_\sigma$. The toric morphism $\pi$ is expressed in this chart by the change of variables $X = Y^{M}$ :
    \begin{equation}\label{chvar}
      \begin{cases}
  x_1 = y_1^{v_{11}}\cdots y_n^{v_{1n}}\\      
 x_2 = y_1^{v_{21}}\cdots y_n^{v_{2n}}\\
 \;\;\;\;\;\vdots \\
  x_n = y_1^{v_{n1}}\cdots y_n^{v_{nn}}
\end{cases}
\end{equation}

    \smallskip

   \no   For all $j\in\{1,\dots,n\}$, taking logarithmic differentials in \cref{chvar}, we obtain a change of base formula:
\begin{equation}\label{chbase1}
    \frac{dx_j}{x_j} = \sum_{k=1}^n v_{jk} \frac{dy_k}{y_k}.
\end{equation}




\noindent Let $J$ be a subset of $\{1,\dots,n\}$ with $p$ elements $j_1<\dots<j_p$, using \cref{chbase1}, we find

\begin{equation*}
    \frac{dX_J}{X_J} = \bigwedge_{s=1}^{p} \left(\sum_{k=1}^n v_{j_sk} \frac{dy_k}{y_k}\right),
\end{equation*}

\smallskip

\noindent from which we derive a change of base formula for $p$-logarithmic differentials:

\begin{equation}\label{chbase2}
    \frac{dX_J}{X_J}=\sum_{|K| =  p} |M_{J,K}| \frac{dY_K}{Y_K},
\end{equation}


\smallskip

\noindent where $|M_{J,K}|$ is the determinant of the submatrix of $M$ whose lines and columns are indexed respectively by $J$ and $K$. Recall that $\eta$ is expressed in the standard coordinate system $X$ as in \cref{logway}:

\begin{equation*}
\eta(X) = \sum_{|J|=p}f_J(X)\frac{dX_J}{X_J}.
\end{equation*}


\smallskip

\noindent Combining \cref{chbase2} with the previous one, we start to compute the total transform of $\eta$ by $\pi$:

\begin{equation*}
    \begin{gathered}
        \pi^{*}\eta(Y) = \sum_{|J|=p}f_J(Y^M)\sum_{|K| =  p} |M_{J,K}| \frac{dY_K}{Y_K} \\
        \pi^{*}\eta(Y) = \sum_{|K|=p}\left(\sum_{|J| =  p} |M_{J,K}| f_J(Y^M)\right) \frac{dY_K}{Y_K}.
    \end{gathered}
\end{equation*}

\smallskip

\noindent Let us expand the coefficients $f_J$ into power series, keeping the same notations as in \cref{powseries}:

\begin{equation*}
    \pi^{*}\eta(Y) = \sum_{|K|=p}\left(\sum_{|J| =  p} |M_{J,K}| \left(\sum_{I\in \nnn^n\cap \Gamma} a_{I,J}Y^{I\cdot M}\right)\right) \frac{dY_K}{Y_K},
\end{equation*}

\smallskip

\noindent where the dot $\cdot$ denotes the matrix product. 

\begin{equation*}
    \pi^{*}\eta(Y) = \sum_{I\in \nnn^n\cap \Gamma}\left(\sum_{|K|=  p}\sum_{|J|=p}  a_{I,J} |M_{J,K}| \frac{dY_K}{Y_K}\right) Y^{ I\cdot M}.
\end{equation*}

\medskip

\noindent For any $I\in \nnn^n\cap \Gamma$ recall that $Y^{ I\cdot M} = y_1^{\langle v_1,I \rangle}\dots y_n^{\langle v_n,I \rangle}$. For any $k\in\{1,\dots,n\}$, we have $t_k = \min_{I\in \Gamma} \langle v_k,I \rangle$ and we denote by $F_k$ the face of $\Gamma$ defined by $v_k$, namely $F_k = \{I\in \Gamma, \langle v_k, I \rangle = t_k\}$. Let $A = \{k\in\{1,\dots,n\}, t_k > 0\}$. We consider the divisor $\left(\prod_{k\in A}y_k= 0\right)$. This leads us to factor the previous expression by $Y^T$, where $T=(t_1,\dots,t_n)$:


\begin{equation*}
    \pi^{*}\eta(Y) = Y^T\Biggl(\sum_{|K|=p}
\Bigl(
\underbrace{
\sum_{I\in \N^n\cap \Gamma}\sum_{|J| =  p} a_{I,J} |M_{J,K}| Y^{I\cdot M - T}
}_{\overline{f}_K(Y)}
\Bigr)
\frac{dY_K}{Y_K}
\Biggr).
\end{equation*}





\medskip



\no For any $K\subset \{1,\dots,n\}$ such that $|K|=p$, we can rewrite $\overline{f}_K(Y)$ with dot products:

\begin{equation} \label{dotprod}
    \overline{f}_K(Y)=\sum_{I\in \nnn^n\cap \Gamma}\sum_{|J| =  p}  a_{I,J} |M_{J,K}| y_1^{ \langle v_1,I\rangle -t_1}\dots y_n^{ \langle v_n,I \rangle -t_n}.
\end{equation}

\smallskip

\no \textbullet \; \textbf{Proof of statement $1)$.}

\medskip

\no Let $K\subset \{1,\dots,n\}$ such that $|K|=p$ and $k\in K\setminus A$, we will show that $y_k$ divides $\overline{f}_K(Y)$. To do so, we substitute $y_k = 0$ in \cref{dotprod}:


\begin{equation*} 
    \overline{f}_K(Y)_{|y_k=0}=\sum_{I\in F_k}\sum_{|J| =  p}  a_{I,J} |M_{J,K}| \prod_{s\ne k} y_s^{ \langle v_s,I\rangle -t_s}.
\end{equation*}

\smallskip

\no Let $I\in F_k$ and $J\subset \{1,\dots,n\}$ with $|J|=p$. We will justify that the product $a_{I,J}|M_{J,K}|$ is equal to zero. This will show that the sum above is also zero and that $y_k$ divides $\overline{f}_K(Y)$. Recall that  $a_{I,J} = 0$ whenever a coordinate of $I$ indexed by $J$ is zero (this has been stated after \cref{powseries}). Suppose now that all coordinates of $I$ indexed by $J$ are non-zero and let us prove that $|M_{J,K}|=0$.

\medskip

\no As $k\notin A$, we have $t_k=\min_{I\in\Gamma} \langle v_k,I\rangle = 0$. This implies that $v_k$ has at least one coordinate which is $0$. Let $T=\{j\in\{1,\dots,n\}, v_{jk} >0\}$. The face $F_k=\{I\in \Gamma, \langle v_k,I \rangle = 0\}$ is the intersection of $\Gamma$ with coordinate hyperplanes, namely: $F_k=\{I=(i_1,\dots,i_n)\in \Gamma, \forall s\in T, i_s = 0\}$. The matrix $M$ can be written as:

\newenvironment{mypmatrix}{\def\mathstrut{\vphantom{\big(}}\pmatrix}{\endpmatrix}

\begin{equation*}
    M = \bordermatrix{     
            & v_{1}     & \cdots    & v_k   & \cdots & v_n \cr
         & v_{11}     & \ldots    & *  & \ldots  & v_{1n}  \cr
         & \vdots     & \ldots     & *  &  \ldots  & \vdots \cr
         & \vdots  & \ldots       & \vdots     & \ldots  & \vdots \cr
         & \vdots     & \ldots      & \vdots   & \ldots  & \vdots \cr
         & v_{n1}     & \ldots      & *   & \ldots  & v_{nn} \cr
}.
\end{equation*}


\medskip

\no The coefficient $|M_{J,K}|$ is the determinant of the matrix whose lines are indexed by $J$ and columns are indexed by $K$. As $k\in K$, the $k$-th column of $M$ will be part of this extracted matrix. The elements of $T$ do not belong to $J$. Indeed, if there was an element $s\in T\cap J$, as $F_k=\{I=(i_1,\dots,i_n)\in \Gamma, \forall s\in T, i_s = 0\}$ and $I\in F_k$, the $s$-th coordinate of $I$ would be indexed by an element of $J$ and equal to zero. This contradicts our hypothesis. In the end, we get that all non-zero elements of the $k$-th column are placed in lines indexed by $\{1,\dots, n\}\setminus J$. Thus, the submatrix that we consider has a column of zeroes and its determinant $|M_{J,K}|$ is zero.

\medskip

\no For any $k\in K\setminus A$, $y_k$ divides $\overline{f}_K(Y)$, so $Y_{K\setminus A}$ divides $\overline{f}_K(Y)$. We conclude that $\pi^{*}\eta $ is adapted to the divisor $E$.

\medskip

\no \textbullet \; \textbf{Proof of statement $2)$.} 

\medskip

\no Suppose that $\pi^{*}\eta$ is not log-smooth with respect to $E$. There exists a point $c=(c_1,\dots,c_n)\in \ccc^n$ which is a common zero for the coefficients $\overline{f}_K(Y)$. Let $S =\{k\in\{1,\dots,n\}, c_k\ = 0\}$. 

\medskip

\nocite{brondsted2012introduction}


\no Consider the non-empty face $F$ of $\Gamma$ defined by $F=\cap_{k\in S}F_k$. Since $c$ is a common zero of the coefficients $\overline{f}_K(Y)$, for each subset $K\subset \{1,\dots,n\}$, using \cref{dotprod}, we get:

\begin{equation*}
    \sum_{I\in F} \sum_{|J|=p}a_{I,J}|M_{J,K}| \prod_{k\notin S} c_k^{ \langle v_k,I\rangle -t_k} = 0 
\end{equation*}
\begin{equation} \label{cancellation}
    \sum_{|J|=p} \left(\sum_{I\in F} a_{I,J} \prod_{k\notin S} c_k^{ \langle v_k,I\rangle}\right)|M_{J,K}|  = 0.
\end{equation}

\medskip

\no We observe that for any $I\in\Gamma \cap\nnn^n$,

\begin{equation*}
    \prod_{k\notin S} c_k^{ \langle v_k,I\rangle}  = \prod_{k\notin S}c_k^{i_1 v_{1k}+\dots+i_nv_{nk}} = \prod_{j=1}^n\prod_{k\notin S} (c_k^{v_{1k}})^{i_j} = C^I.
\end{equation*}

\medskip

\no where $C=(\prod_{k\notin S}c_k^{v_{1k}},\dots,\prod_{k\notin S}c_k^{v_{nk}}) \in (\ccc^{*})^n$. This helps us further simplify \cref{cancellation}:

\begin{equation*}
    \forall K, \; \sum_{|J|=p} \left(\sum_{I\in F} a_{I,J} C^I\right)|M_{J,K}|  = 0
\end{equation*} 
\begin{equation} \label{eqzerobis}
    \sum_{|J|=p} (f_J)_{|F}(C)|M_{J,K}|  = 0
\end{equation}

\no Let $J_1 \prec \dots \prec J_{r}$ be an ordering of the subsets of $\{1,\dots,n\}$ with $p$ elements, where $r=\binom{n}{p}$.


\no We introduce the following matrix: 
\begin{equation*}
    M'=\begin{pmatrix}
    |M_{J_1,J_1}| & |M_{J_1,J_2}| & \dots & |M_{J_1,J_r}| \\
    |M_{J_2,J_1}| & |M_{J_2,J_2}| & \dots & |M_{J_2,J_r}| \\
    \vdots & \vdots & \ddots & \vdots \\
    |M_{J_r,J_1}| & |M_{J_r,J_2}| & \dots & |M_{J_r,J_r}|
 \end{pmatrix}.
\end{equation*}

\smallskip

\no We proceed to reformulate the $r=\binom{n}{p}$ equalities in \cref{eqzerobis} as a matrix equation:
\begin{equation} \label{matrix}
    \left((f_{J_1})_{|F}(C),\dots, (f_{J_r})_{|F}(C)\right) M' = 0.
\end{equation}

\no Since $\sigma$ is a smooth cone, $M$ is invertible. Let us prove that $M'$ is also invertible. Denote by $(e_1, \dots, e_n)$ the canonical basis of $\ccc^n$ and $u : \ccc^n \longrightarrow \ccc^n$ the $\ccc$-linear map represented by the matrix $M$ in this basis. For any subset $J\subset\{1,\dots,n\}$ such that $J = \{j_1,\dots, j_p\}$ and $j_1<\dots < j_p$, set $e_J = e_{j_1}\wedge \dots \wedge e_{j_p}$. The $p$-th exterior power $\wedge^{p}u$ of the map $u$ is defined by $\wedge^p u(e_J) = u(e_{j_1})\wedge \dots \wedge u(e_{j_p})$. For any subset $K\subset \{1,\dots,n\}$ with $p$ elements $k_1<\dots<k_p$,

\begin{equation*}
    \wedge^p u(e_{K}) = \bigwedge_{\ell = 1}^pu(e_{k_\ell}) = \bigwedge_{\ell = 1}^p\left(\sum_{i=1}^nv_{ik_{\ell}}e_i\right) = \sum_{|J|= p }|M_{J,K}| e_J.
\end{equation*}


\medskip

\no The family of vectors $(e_{J_1},\dots,e_{J_r})$ is a basis of $\wedge^p \ccc^n$. For any $\ell \in\{1,\dots, r\}$,

\begin{equation*}
    \wedge^p u(e_{J_\ell}) = \sum_{s=1}^r|M_{J_s,J_\ell}| e_{J_s}.
\end{equation*}

\medskip

\no This proves that $M'$ is the matrix of $\wedge^p u$ in the basis $(e_{J_1},\dots,e_{J_r})$. The exterior power of an invertible linear endomorphism is invertible. Thus, $\wedge^p u$ is invertible and so is the matrix $M'$.

\medskip

\no This implies that the unique solution of \cref{matrix} is
\begin{equation*}
    \left((f_{J_1})_{|F}(C),\dots, (f_{J_r})_{|F}(C)\right)=(0,\dots,0)
\end{equation*}

\smallskip

\no and that $C\in \left(\ccc^{*}\right)^n$ is a common zero for the initial forms $(f_{J_k})_{|F}$. This is impossible because $\eta$ is NND, so the coefficients $\overline{f}_K(Y)$ have no common zeroes. We conclude that $\pi^{*}\eta$ is log-smooth with respect to $E$.


\medskip


\end{proof}




