\includegraphics[width=0.47\linewidth]{plots/genome_structure/nbchr_nb_segments.png}\hfill\includegraphics[width=0.47\linewidth]{plots/genome_structure/nbchr_chr_anc_density.png}    \caption{Number of ancestral segments (left) and proportion of chromosomes that are genetic ancestors (right) for different genome structure (with $c \times L_c = 200,000$ , $r = 1/L_c$ and $N=20,000$). Temporal data are presented in Supp \autoref{fig:temp_nbch}.} 
