\underline{\emph{Case 2:}}\ If $\Lambda_F(x)$ is continuous at $x_\alpha$, we have $p_0 := F\(x_\alpha-\) = \alpha$. Next, we need to consider two subcases:
\begin{itemize}
  \item Subcase 2.1: Suppose that $-\ln(1-\alpha) \geq x_\alpha$. In this subcase, we choose the ${\rm Exp}(1)$ distribution $E \in {\cal F}^\ast$. By the convexity of $\Lambda_F$, we have
	$$
          \Lambda_F(x) \geq - \frac{\ln(1-\alpha)}{x_\alpha} x \geq x = \Lambda_E(x),\quad \forall x \in \[x_\alpha, x_\beta\].
	$$
    Then $x_p \leq \VaR_p(E)$ for $p \in [\alpha, \beta]$. Therefore, we have ${\rm RVaR}_{\alpha, \beta}(E) \geq {\rm RVaR}_{\alpha, \beta}(F)$.

\item Subcase 2.2: Suppose that $-\ln(1-\alpha) < x_\alpha$, i.e., $w:=-x_\alpha^{-1} \ln (1-p_0)\in (0,1]$; see Figure \ref{Fig3-2}. In this subcase, we have $\int_0^\oo \exp\{-w x\} \d x > 1$. 			Note that
	\begin{equation}\label{constraint2}
			1 = \mu(F) > \int_0^{x_\alpha} \Fbar(x) \d x \geq \int_0^{x_\alpha} \exp\{- w x \} \d x.
	\end{equation}
    In view of \eqref{constraint2}, there exists some $t\in (x_\alpha, \oo)$ such that $\int_0^t \exp\{-w x\} \d x = 1$. Thus, $G_{t,w} \in {\cal F}^\ast$, where $G_{t,w}$ is defined in \eqref{eq-20250622}.

	\begin{enumerate}[{\rm (1)}]
       \item If $t \geq x_\beta$, by the convexity of $\Lambda_F$, we have $\Lambda_F(x) \ge w x = \Lambda_{G_{t,w}}(x)$ for all $x \in \[x_\alpha, x_\beta\]$, which implies $x_p \leq \VaR_p(G_{t,w})$ for $p \in [\alpha, \beta]$. Therefore, we have ${\rm RVaR}_{\alpha, \beta}(G_{t,w}) \geq {\rm RVaR}_{\alpha, \beta}(F)$.

       \item If $t < x_\beta$, then $q_0 := F(t-) < \beta$. For any $q > \beta$, we have $\VaR_q(G_{t,w}) = t < x_\beta < x_q$. Therefore,
		   \begin{equation}\label{mean-right}
					\int_\beta^1 \VaR_q(G_{t,w}) \d q < \int_\beta^1 x_q \d q.
		   \end{equation}
          Moreover, by the convexity of $\Lambda_F$, we have $\Lambda_F(x) \leq w x = \Lambda_{G_{t,w}}(x)$ for all $x \in \[0, x_\alpha\)$, implying $\VaR_q(G_{t,w}) \leq x_q$ for any $q < \alpha$. Then
		  \begin{equation}\label{mean-left}
				\int_0^\alpha \VaR_q(G_{t,w}) \d q \leq \int_0^\alpha x_q \d q.
		  \end{equation}
         Since $\mu(F) = \mu(G_{t,w})=1$, it follows from \eqref{mean-right} and \eqref{mean-left} that
		 \begin{equation*}
				\int_\alpha^\beta \VaR_q(G_{t,w}) \d q \geq \int_\alpha^\beta x_q(F) \d q.
		\end{equation*}
		That is, ${\rm RVaR}_{\alpha, \beta}(G_{t,w}) \geq {\rm RVaR}_{\alpha, \beta}(F)$.
	\end{enumerate}
\end{itemize}
This completes the proof of the theorem.
\end{proof}

Theorem \ref{thm3-4} shows that an infinite dimensional optimization problem can be transformed into a finite dimensional optimization problem through the method of construction. Subsequently, we can use simulation software to perform numerical simulations on it. This construction method will run through this article. The next proposition \ref{pro3-5} provides a simple expression of the worst-case RVaR on uncertainty set ${\cal F}^\ast$.

\begin{proposition}  \label{pro3-5}
For $0 \leq \alpha < \beta \leq 1$, we have
\begin{equation}  \label{eq-250627}
     \sup_{F \in {\cal F}} {\rm RVaR}_{\alpha, \beta}(F) = \max_{w \in [\alpha, \beta]} \frac{(1-\beta)\ln(1-w) - (1-\alpha)\ln(1-\alpha) + w - \alpha}{w (\beta - \alpha)}.
\end{equation}
In particular, for $\alpha\in [0,1]$,
\begin{equation}   \label{eq-250628}
     \sup_{F \in {\cal F}} {\rm TVaR}_{\alpha}(F) = 1-\ln (1-\alpha).
\end{equation}
\end{proposition}

\begin{proof}
For any $G_{t,w} \in {\cal F}_w$, we have $1 - w = \exp\{-wt\}$. Thus, $t:=t_w = -w^{-1} \ln(1-w)$, where $t_0 = 1$ is the limit of $t_w$ when $w$ goes to $0$. It is easy to see that
$$
	\VaR_p(G_{t,w}) = \left\{\begin{array}{ll}
			-\dfrac {1}{w} \ln(1-p), & {\rm for}\ 0 \leq p \leq w, \\[8pt]
			-\dfrac{1}{w} \ln(1-w), & {\rm for}\ w < p \leq 1. \end{array} \right.
$$
Then
\begin{align*}
  g(w) := {\rm RVaR}_{\alpha, \beta}(G_{t,w}) &= \left\{\begin{array}{ll}
		-\dfrac{1}{w} \ln(1-w), & {\rm for}\ w \in [0, \alpha), \\[8pt]
		\dfrac{1}{\beta -\alpha} \[\int_\alpha^w \frac{-\ln(1-p)}{w}\d p -\frac {\beta - w}{w} \ln(1-w)\],
				& {\rm for}\ w \in [\alpha, \beta], \\[8pt]
		\dfrac{1}{\beta - \alpha} \int_\alpha^\beta \frac{-\ln(1-p)}{w} \d p, & {\rm for}\ w \in (\beta, 1],
			\end{array} \right.   \\[8pt]
	&= \left\{\begin{array}{ll}
		-\dfrac{1}{w} \ln(1-w), & {\rm for}\ w \in [0, \alpha), \\[8pt]
		\dfrac{(1-\beta)\ln(1-w) - (1-\alpha)\ln(1-\alpha) + w - \alpha}{w (\beta - \alpha)},
				& {\rm for}\ w \in [\alpha, \beta], \\[8pt]
		\dfrac{(1-\beta)\ln(1-\beta) - (1-\alpha)\ln(1-\alpha) + \beta - \alpha}{w (\beta - \alpha)},
			& {\rm for}\ w \in (\beta, 1]. \end{array} \right.
\end{align*}
It is easy to verify that $g(w)$ is increasing in $w \in [0, \alpha)$ and decreasing in $w \in (\beta, 1]$. Moreover, $g(w)$ is continuous in $w \in [0, 1]$. Therefore, we only consider $g(w)$ on $[\alpha, \beta]$. We first calculate its first-order derivative:
$$
     g'(w) = \frac{1}{w^2(1-w)(\beta-\alpha)} \[(1-w) \(\alpha + (1-\alpha) \ln(1-\alpha)\) - (1-\beta) \(w + (1-w)\ln(1-w)\)\].
$$
Denote $k(w) := (1-w) \(\alpha + (1-\alpha) \ln(1-\alpha)\) - (1-\beta) \(w + (1-w)\ln(1-w)\)$. Then $k'(w) = (1-\beta)\ln(1-w) - \(\alpha + (1-\alpha) \ln(1-\alpha)\) < 0$. Thus, $k(w)$ is non-increasing on $[\alpha, \beta]$. Combining $g'(\alpha) > 0$ and $g'(\beta) < 0$, we know that there exists $w^* \in [\alpha, \beta]$ such that $g'(w) \geq 0$ for $w \in [\alpha, w^*]$ and $g'(w) \leq 0$ for $w \in [w^*, \beta]$. This means that $g(w)$ achieves its maximum value at $w^* \in [\alpha, \beta]$. Therefore, \eqref{eq-250627} follows from Theorem \ref{thm3-4}.
It is trivial to check that \eqref{eq-250628} follows from \eqref{eq-250627} with $\beta=1$ by observing $\alpha+(1-\alpha)\ln (1-\alpha)\geq 0$ for $\alpha\in [0,1]$. This completes the proof of the proposition.
\end{proof}


\begin{remark}{\rm
\cite{CHLW23} recently derived the tight bounds for RVaR under mean or variance ambiguity set with support information. They showed that
\begin{equation*}
	\sup_{F \in \widetilde{{\cal F}}} {\rm RVaR}_{\alpha, \beta}(F) = \frac{1}{1-\alpha},
\end{equation*}
where $\widetilde{{\cal F}} := \left\{F: \mu(F) = 1 \right\}$. Since ${\cal F} \subseteq \widetilde{{\cal F}}$, it follows from Theorem \ref{thm3-4} that
$$
  	\sup_{F \in {\cal F}} {\rm RVaR}_{\alpha, \beta}(F) \leq \frac {1}{1-\alpha},\quad 0\le \alpha<\beta\le 1.
$$		}
\end{remark}

The next theorem characterizes the best-case RVaR on $\cal F$. Notably, it is uniquely attained by exponential or degenerate distributions depending on the parameters $\alpha$ and $\beta$.

\begin{theorem}\label{thm3-7}
For $0 \leq \alpha < \beta < 1$, we have
\begin{align}
	\inf_{F \in {\cal F}} {\rm RVaR}_{\alpha, \beta}(F)
		&= \min \{{\rm RVaR}_{\alpha, \beta}(E), \RVaR_{\alpha, \beta}(\delta_1)\} \label{eq-2024-315}  \\
		&= \min\left\{1+\frac{(1-\beta)\log(1-\beta) -(1-\alpha)\log(1-\alpha)}{\beta-\alpha}, 1\right\},
 		\label{eq-2024-316}
\end{align}
where $E(x) = 1-\exp\{-x\}$ for $x\ge 0$.
\end{theorem}

\begin{proof}
Eq. \eqref{eq-2024-316} can be calculated directly. Below, we only prove \eqref{eq-2024-315}. Note that $\inf_{F \in {\cal F}} {\rm RVaR}_{\alpha, \beta}(F) \leq \min \{{\rm RVaR}_{\alpha, \beta}(E), \RVaR_{\alpha, \beta}(\delta_1)\}$. Below, we need to show the reverse inequality. It suffices to show that for any given $F \in {\cal F}$ with $F \neq E$ and $F \neq \delta_1$, we have
\begin{equation}\label{eq-2024-317}
      \min \{{\rm RVaR}_{\alpha, \beta}(E),\RVaR_{\alpha, \beta}(\delta_1)\}\leq {\rm RVaR}_{\alpha, \beta}(F).
\end{equation}
Denote by $x_p=\VaR_p(F)$ for $p\in [0,1]$. Below, we consider two cases.

\underline{\it Case 1}:\ Suppose $-\ln(1-\beta) \leq x_\beta$. In this case, whether $F$ is continuous at $x_\beta$ (see Figure \ref{Fig3-3}) or discontinuous at $x_\beta$ (see Figure  \ref{Fig3-4}), we always have $F(x) \leq E(x)$ for any $x \in [0, x_\beta]$ by the convexity of $\Lambda_F$ and $E(x_\beta) \geq \beta$. Thus, $x_p \geq \VaR_p(E)$ for $p \in [\alpha, \beta]$. Finally,
\begin{equation*}
	\RVaR_{\alpha, \beta}(F) \geq \RVaR_{\alpha, \beta}(E) \geq \min \{{\rm RVaR}_{\alpha, \beta}(E),
		\RVaR_{\alpha, \beta}(\delta_1)\}.
\end{equation*}
Therefore, \eqref{eq-2024-317} holds.

