        \item Assume that $F$ is continuous at $x_\beta$; see Figure \ref{Fig3-6}. We obtain $F(x) \geq H_t(x)$ for $x \geq x_\beta$. Then, $x_p \leq \VaR_p(H_t)$ holds for $p \geq \beta$. Thus, $\TVaR_\beta(F) \leq \TVaR_\beta(H_t)$ holds.
	  \end{itemize}
