\section{Extreme-cases via mean and variance}\label{sec4}


In this section, we consider the mean-variance ambiguity set of IFR distribution $F \in {\cal M}$ with its dispersion information specified by the second moment of the distribution:
\begin{equation*}
		{\cal G} := \left\{F \in {\cal M}: F {\rm\ is\ IFR},\ \mu(F) = 1,\ \mu_2(F) = \mu_2\right\}.
\end{equation*}
Let's recall two facts \citep{BMP63}. The first one is that $F \in {\cal G}$ implies $1 \leq \mu_2(F) \leq 2$. The another one is that $F \in {\cal G}$ contains only one distribution when $\mu_2(F) = 1$ or $\mu_2(F) = 2$. Specifically, ${\cal G}$ degenerates to (i) the Dirac delta at $1$, $\delta_1$, when $\mu_2(F) = 1$, and (ii) ${\rm Exp}(1)$ distribution when $\mu_2(F) = 2$. Thus, from now on, we assume that $1 < \mu_2(F) < 2$ to avoid trivial discussions when $F \in {\cal G}$. We consider the following questions:
\begin{equation}   \label{eq-2024-1}
		\sup_{F \in {\cal G}} \rho(F), {\rm\ and}\ \inf_{F \in {\cal G}} \rho(F),
\end{equation}
where $\rho$ is a risk measure.

In order to solve \eqref{eq-2024-1}, we need to review some notations and lemmas \citep{BM64}. Denote $T_0 = 1 - \sqrt{\mu_2 - 1}$, and define
\begin{eqnarray}\label{eq-2024-42}
	\Gbar_{T_1}(x) &=& \left\{\begin{array}{ll}  1, & {\rm for}\ x < 0, \\
			\exp\{-ax\}, & {\rm for}\ 0 \leq x < T_1, \\
			0, & {\rm for}\ x \geq T_1, \end{array} \right.
\end{eqnarray}
where $a$ and $T_1$ are chosen such that $\mu(G_{T_1}) = 1$ and $\mu_2(G_{T_1}) = \mu_2$. The first two moment conditions uniquely identify $a \in [0, 1]$ and $T_1 \geq 1$. Note that $T_0 < T_1$. For $T \geq T_1$, define
\begin{eqnarray}   \label{eq-2024-43}
	\Gbar_T^{(1)}(x) &=& \left\{\begin{array}{ll} 	1, & {\rm for}\ x < \Delta, \\
			\exp\{-k(x-\Delta)\}, & {\rm for}\ \Delta \leq x < T, \\
			0, & {\rm for}\ x \geq T, \end{array} \right.
\end{eqnarray}
and for $T_0 \leq T < T_1$, define
\begin{eqnarray}   \label{eq-2024-44}
	\Gbar_T^{(2)}(x) &=& \left\{\begin{array}{ll}  	1, & {\rm for}\ x < 0, \\
			\exp\{-k_1 x\}, & {\rm for}\ 0 \leq x < T, \\
			\exp\{-k_1 T - k_2(x-T)\}, & {\rm for}\ x \geq T, \end{array} \right.
\end{eqnarray}
where $(k, \Delta)$ and $(k_1, k_2)$ are respectively determined by the moment conditions, i.e.,
\begin{equation}   \label{eq-2024-45}
	1=\int_0^\oo \Gbar^{(i)}_T(x) \d x\ \ {\rm and}\ \ \mu_2=2\int_0^\oo x \Gbar^{(i)}_T(x)\d x,\quad i=1, 2.
\end{equation}
According to \cite{BM64}, for any fixed $T$, Eq. \eqref{eq-2024-45} has uniquely determined solution pairs $(k(T), \Delta(T))$ and $(k_1(T), k_2(T))$, both of which are continuous in $T\in [T_0, \oo)$. Denote
\begin{equation}\label{distributions}
      {\cal G}_1 := \left\{G_T^{(1)}: T \geq T_1\right\}\ \ {\rm and}\ \ {\cal G}_2 := \left \{G_T^{(2)}: T_0 \leq T < T_1\right \}.
\end{equation}
We now state a useful lemma.

\begin{lemma}{\rm \citep[][Theorem 3.1]{BM64}}\label{lem-4-1}
For any given $1 < \mu_2 < 2$ and $x \geq 0$, we have
$$
   	\left\{(x, F(x)): F\in {\cal G}\right\} = \left\{(x, G(x)): G\in {\cal G}_1\cup {\cal G}_2\right\}.
$$
\end{lemma}

Our analysis commences with the derivation of extreme VaR cases, illustrating the power of Lemma \ref{lem-4-1}.

\begin{proposition}
For any $\alpha \in (0, 1)$, we have
\begin{equation}\label{eq-2024-6}
      \sup_{F \in {\cal G}} \VaR_\alpha(F) = \sup_{F \in {\cal G}_1 \cup {\cal G}_2} \VaR_\alpha(F),\qquad
			\inf_{F \in {\cal G}} \VaR_\alpha(F) = \inf_{F \in {\cal G}_1 \cup {\cal G}_2} \VaR_\alpha(F),
\end{equation}
and
\begin{equation}\label{eq-2024-7}
	\sup_{F \in {\cal G}} \VaR_\alpha^+(F) = \sup_{F \in {\cal G}_1 \cup {\cal G}_2} \VaR_\alpha^+(F),\qquad
			\inf_{F \in {\cal G}} \VaR_\alpha^+(F) = \inf_{F \in {\cal G}_1 \cup {\cal G}_2} \VaR_\alpha^+(F).
\end{equation}
\end{proposition}

\begin{proof}
We give the proof of \eqref{eq-2024-6} only; the proof of \eqref{eq-2024-7} is similar. Since ${\cal G}_1 \subseteq {\cal G}$ and ${\cal G}_2 \subseteq {\cal G}$, it follows that
$$
     \sup_{F \in {\cal G}} \VaR_\alpha(F) \geq \sup_{F \in {\cal G}_1 \cup {\cal G}_2} \VaR_\alpha(F)\ \ {\rm and}\ \ \inf_{F\in {\cal G}} \VaR_\alpha(F)\leq \inf_{F\in {\cal G}_1\cup {\cal G}_2} \VaR_\alpha(F).
$$
For the reverse inequality of \eqref{eq-2024-6}, note that for any given $F \in {\cal G}$, we have $F(\VaR_\alpha(F) - \ep) < \alpha$ for any $\ep > 0$ and $F(\VaR_\alpha(F)) \geq \alpha$. By Lemma \ref{lem-4-1}, there exist two distribution functions $G_1, G_2 \in {\cal G}_1 \cup {\cal G}_2$ such that $G_1(\VaR_\alpha(F) - \ep) = F(\VaR_\alpha(F) - \ep) < \alpha$ and $G_2(\VaR_\alpha(F)) \geq \alpha$. Then $\VaR_\alpha(G_1) > \VaR_\alpha(F) - \ep$ and $\VaR_\alpha(G_2) \leq \VaR_\alpha(F)$. Thus,
$$
	\sup_{G \in {\cal G}_1 \cup {\cal G}_2} \VaR_\alpha(G) \geq \VaR_\alpha(G_1) > \VaR_\alpha(F) - \ep,
$$
and
$$
	\inf_{G\in {\cal G}_1 \cup {\cal G}_2} \VaR_\alpha(F) \leq \VaR_\alpha(G_2) \leq \VaR_\alpha(F).
$$
Therefore, the desired result is obtained by taking the limit as $\ep \downarrow 0$ and computing the supremum of $F$ over the set ${\cal G}$.
\end{proof}

We now examine the extreme-case RVaR. Building upon the cut criterion established in \cite{KN63} (which plays a pivotal role in our proof), we first establish the simple extreme-case TVaR result. This preliminary result will serve to clarify our subsequent RVaR analysis.


\begin{lemma}\label{cut}
For any two distribution functions $F, G \in {\cal M}$ with $\mu(F) = \mu(G)$, if $F$ up-crosses $G$ with only one time, then $\mu_2(F) < \mu_2(G)$.
\end{lemma}


\begin{theorem}\label{thm-4-4}
For any $\alpha \in (0,1)$, we have
\begin{equation}\label{eq-2024-8}
	\sup_{F \in {\cal G}} \TVaR_\alpha(F) = \sup_{F \in {\cal G}_1} \TVaR_\alpha(F).
\end{equation}
\end{theorem}

\begin{proof}
Since $\sup_{F \in {\cal G}} \TVaR_\alpha(F) \geq \sup_{F \in {\cal G}_1} \TVaR_\alpha(F)$, it suffices to prove that for any $\alpha \in (0, 1)$ and given $F \in {\cal G}$, there exists another distribution function $G \in {\cal G}_1$ such that
\begin{equation}\label{eq-2024-9}
	\TVaR_\alpha(F) \leq \TVaR_\alpha(G).
\end{equation}

For any given $F \in {\cal G}$, let's first examine the relationship between $F$ and $G_{T_1}$, where $G_{T_1}$ is given by \eqref{eq-2024-42}. If $F = G_{T_1}$, then \eqref{eq-2024-9} holds since $G_{T_1} \in {\cal G}_1$. If $F \neq G_{T_1}$, note that $F \in {\cal G}$ implies that $\Lambda_F(x)$ is a convex function and $\Lambda_{G_{T_1}}(x)$ is a linear function in $x \in (0, T_1)$. Thus, by Proposition \eqref{pro-2-1} (iii), there exists some point $t_1 \in (0, T_1)$ such that $F$ up-crosses $G_{T_1}$ at $t_1$ under the conditions of the first two moments are equal and $F(0) = G_{T_1}(0) = 0$. Denote $F(t_1) = G_{T_1}(t_1) =: \alpha_1$. Let $G^{(1)}_\oo \in {\cal G}_1$ be defined by
\begin{eqnarray}\label{eq-2024-10}
	\Gbar^{(1)}_\oo(x) &=& \left\{\begin{array}{ll}  1, & {\rm for}\ x < \Delta_0, \\
		\exp\{-b(x-\Delta_0)\}, & {\rm for}\ x \geq \Delta_0, \end{array} \right.
\end{eqnarray}
where $b > 0$ such that $\mu(G^{(1)}_\oo) = 1$ and $\mu_2(G^{(1)}_\oo) = \mu_2(F)$. Now, we consider the link between $F \in {\cal G}$ and $G^{(1)}_\oo \in {\cal G}_1$.  If $F = G^{(1)}_\oo$, then \eqref{eq-2024-9} holds since $G^{(1)}_\oo \in {\cal G}_1$. If $F \neq G^{(1)}_\oo$ and $F(\Delta_0) = 0 = G_\oo(\Delta_0)$, it follows from Proposition \eqref{pro-2-1} (iii) that $F$ up-crosses $G^{(1)}_\oo$ on $(\Delta_0, \oo)$ at most once. Thus, the condition of the first two moments being equal doesn't hold by Lemma \ref{cut}. Thus, $F(\Delta_0) > 0$. In this case, $F$ down-crosses first and then up-crosses $G^{(1)}_\oo$ on $(\Delta_0, \oo)$ under the condition that the first two moments are equal. Denote by $t_0 \in (\Delta_0, \oo)$ the point at which $F$ up-crosses $G^{(1)}_\oo$, and set $\alpha_0 := G^{(1)}_\oo(t_0)$. For the graphical explanation of $\alpha_0$ and $\alpha_1$, see Figure \ref{Fig1}, where $t_0=r(\oo)$ and $t_1=r(T_1)$. It is worth pointing out that the two numbers $\alpha_0$ and $\alpha_1$ play important roles in the remaining proof of the theorem.

Below, we show how to construct $G \in {\cal G}_1$ such that \eqref{eq-2024-9} holds for any given $F \in {\cal G}$ with $F \neq G_{T_1}$ and $F \neq G^{(1)}_\oo$. We consider three cases.

\underline{\emph{Case 1:}}\ Suppose $\alpha \geq \alpha_0$. In this case, we have $F(x) > G^{(1)}_\oo(x)$ for $x > t_0$ by the convexity of $\Lambda_F$, see Figure \ref{Fig1}. It is obvious to see that $\VaR_p(F) \leq \VaR_p\big (G^{(1)}_\oo\big )$ for any $p > \alpha_0$. Thus, we have
\begin{equation*}
	\TVaR_\alpha(F) \leq \TVaR_\alpha\big (G^{(1)}_\oo\big ).
\end{equation*}

\underline{\emph{Case 2:}}\ Suppose $\alpha \leq \alpha_1$. In this case, we have $F(x) < G_{T_1}(x)$ for any $x \in (0, t_1)$ by the convexity of $\Lambda_F$, see Figure \ref{Fig1}. Thus, $\VaR_p(F) \geq \VaR_p(G_{T_1})$ for any $p < \alpha_1$, which implies
\begin{equation*}
	\int_0^\alpha \VaR_p(F)\d p \geq \int_0^\alpha \VaR_p(G_{T_1}) \d p.
\end{equation*}
Therefore,
\begin{align*}
	\TVaR_\alpha(F) &= \frac{1}{1-\alpha} \(1 - \int_0^\alpha \VaR_p(F)\d p\) \\
		&\leq \frac{1}{1-\alpha} \(1 - \int_0^\alpha \VaR_p(G_{T_1}) \d p\) = \TVaR_\alpha (G_{T_1}).
\end{align*}

\underline{\emph{Case 3:}}\ Suppose $\alpha_0 \wedge \alpha_1 < \alpha < \alpha_0 \vee \alpha_1$. For any given $F \in {\cal G}$, we give some analysis on $F$ and $G^{(1)}_T$, where $G^{(1)}_T \in {\cal G}_1$ is given by \eqref{eq-2024-43} with $T \geq T_1$. If $F(\Delta) = 0 = G_T^{(1)} (\Delta)$, then $F$ up-crosses $G^{(1)}_T$ on $(\Delta, T)$ only once by Proposition \eqref{pro-2-1} (iii). If $F(\Delta) > 0 = G^{(1)}_T(\Delta)$, we know that $F$ down-crosses first and then up-crosses $G_T^{(1)}$ on $(\Delta, T)$ under the condition that the first two moments are equal. Thus, whether $F(\Delta) = 0$ or $F(\Delta) > 0$, $F$ up-crosses $G^{(1)}_T$ on $(\Delta, T)$ only once. Assume $F$ up-crosses $G^{(1)}_T$ at $r(T) \in (\Delta, T)$ and denote
$$
          g(T) := G_T^{(1)}(r(T)).
$$
The intersection point $(r(T), -\ln(1-g(T)))$ has been graphically represented in in Figure \ref{Fig2}. Note that $g(T_1) = G_{T_1}(r(T_1)) = G_{T_1}(t_1) = \alpha_1$ and $g(\oo) = G^{(1)}_\oo(r(\oo)) = G^{(1)}_\oo(t_0) = \alpha_0$. We will establish \eqref{eq-2024-9} by verifying the following two claims.

