\begin{itemize}
  \item Claim 1: The function $g(T)$ is continuous on $T \in [T_1, \oo]$.

      \emph{Proof}: It is well known that $k(T) := k$ and $\Delta(T) := \Delta$ are continuous functions on $T \in [T_1, \oo]$, see Lemma 3.4 in \cite{BM64}. Below, we show that $k(T)$ and $\Delta(T)$ are increasing on $T \in [T_1, \oo]$. Taking $T_1 \leq T < T' \leq \oo$. If $\Delta(T) > \Delta(T')$, then $\Lambda_{G^{(1)}_T}$ and $\Lambda_{G^{(1)}_{T'}}$ have at most one intersection point. If there is no intersection point, then $\Lambda_{G^{(1)}_T}(x) \leq \Lambda_{G^{(1)}_{T'}}(x)$ on $x \in (0, \Delta(T))$ and $\Lambda_{G^{(1)}_T}(x) < \Lambda_{G^{(1)}_{T'}}(x)$ on $x \in (\Delta(T), T)$, which contracts $\mu(G^{(1)}_T) = \mu(G^{(1)}_{T'})$. If there is one intersection point between $\Lambda_{G^{(1)}_T}$ and $\Lambda_{G^{(1)}_{T'}}$, then this contracts $\mu_2(G^{(1)}_T) = \mu_2(G^{(1)}_{T'})$ by Lemma \ref{lem-4-1}. Thus, we have $\Delta(T) \leq \Delta(T')$. On the other hand, if $k(T) \geq k(T')$, then $G^{(1)}_T(x) \geq G^{(1)}_{T'}(x)$ on $x \in (0, T)$ and $G^{(1)}_T(x) > G^{(1)}_{T'}(x)$ on $x \in (T, T')$. This contracts $\mu(G^{(1)}_T) = \mu(G^{(1)}_{T'})$. Thus, $k(T) < k(T')$.

      Moreover, $r(T)$ is also continuous in $T \in [T_1, \oo]$ from the proof of Theorem 3.1 and Lemma 3.4 in \cite{BM64}. By the definition of $G^{(1)}_T \in {\cal G}_1$ given by \eqref{eq-2024-43}, $G^{(1)}_T(x)$ is continuous in $T \in [T_1, \oo]$ for any given fixed $x \geq 0$. Thus, taking any point $T' \in (T-\ep, T+\ep)$ for any $\ep > 0$ (if $T = T_1$, let $T' \in (T, T+\ep)$), we have
	  \begin{align*}
		\left|g(T)- g(T')\right | &= \left |G^{(1)}_T(r(T)) - G^{(1)}_{T'}(r(T'))\right| \\[2pt]
			&\leq \left|G^{(1)}_T(r(T)) - G^{(1)}_{T'}(r(T))\right| + \left|G^{(1)}_{T'}(r(T))
			- G^{(1)}_{T'}(r(T'))\right| \\[3pt]
    		&\leq \left|G^{(1)}_T(r(T)) - G^{(1)}_{T'}(r(T))\right |+k(T')\left |r(T)-r(T')\right| \\[3pt]
			&\leq  \left|G^{(1)}_T(r(T)) - G^{(1)}_{T'}(r(T))\right| + k(\oo) \left|r(T) - r(T')\right|,
	  \end{align*}
      where the second inequality follows from the Lipschitz continuity of $G_{T'}$ with Lipschitz constant $k(T')$, and the last one follows from the monotonicity $k(T)$ with $k(\oo) \in \R$. Letting $T' \to T$ yields that $\left|g(T) - g(T')\right| \to 0$. Thus, $g(T)$ is continuous in $T \in [T_1, \oo]$.

   \item Claim 2: For any $F \in {\cal G}$ and $\alpha_0 \wedge \alpha_1 < \alpha < \alpha_0 \vee \alpha_1$, we have
	   \begin{equation}\label{eq-2024-11}
		  \TVaR_\alpha(F) \leq \TVaR_\alpha \big (G^{(1)}_T\big ),
	   \end{equation}
      where $G^{(1)}_T \in {\cal G}_1$, given by \eqref{eq-2024-43}, such that $g(T) = \alpha$ for $T \in [T_1, \oo]$.

      \emph{proof}: For any given $\alpha_0 \wedge \alpha_1 < \alpha < \alpha_0 \vee \alpha_1$, we know that there exists $T \in [T_1, \oo]$ such that $g(T) = \alpha$ by Claim 1, see Figure \ref{Fig2}. If $F(x)$ is discontinuous at $x^\ast = r(T)$, then $F(t^\ast)-) < 1$ and $F(t^\ast)) = 1$. For any $p \geq \alpha$, we have $\VaR_p(F) = t^\ast \leq \VaR_p\big (G^{(1)}_T\big )$. Then \eqref{eq-2024-11} holds. If $F(x)$ is continuous at $t^\ast= r(T)$, then, in view of $\VaR_\alpha\big (G^{(1)}_T\big ) = \VaR_\alpha(F) =t^\ast$, we have
	  \begin{eqnarray}\label{eq-2024-12}
		& & \TVaR_\alpha\big (G^{(1)}_T\big ) - \TVaR_\alpha(F) \nonumber \\[3pt]
           & & \qquad = \VaR_\alpha\big (G^{(1)}_T\big ) + \frac{1}{1-\alpha} \int_{\VaR_\alpha(G^{(1)}_T)}^\oo \Gbar^{(1)}_T(x) \d x - \VaR_\alpha(F) - \frac{1}{1-\alpha}  \int_{\VaR_\alpha(F)}^\oo \Fbar(x) \d x \nonumber \\[3pt]
               & &\qquad = \frac{1}{1-\alpha} \(\int_{t^\ast}^\oo \Gbar^{(1)}_T(x) \d x - \int_{t^\ast}^\oo \Fbar(x) \d x\) \nonumber \\[3pt]
                     & &\qquad=\frac{1}{1-\alpha}\(\int_0^{F^{-1}(\alpha)}\Fbar(x)\d x-\int_0^{\(G^{(1)}_T\)^{-1}(\alpha)} \Gbar^{(1)}_T(x) \d x\),
      \end{eqnarray}
     where the last equality follows from $\mu(F) = \mu(G^{(1)}_T) = 1$. To show $\TVaR_\alpha\big (G^{(1)}_T\big ) \geq \TVaR_\alpha(F)$, combining \eqref{eq-2024-12} and Proposition \ref{pro-2-1} (iv), it suffices to consider
	 \begin{equation}\label{eq-2024-13}
			\phi_F(\alpha) \geq \phi_{G^{(1)}_T}(\alpha),
	\end{equation}
    where $\phi_F$ and $\phi_{G^{(1)}_T}$ are the TTTs of $F$ and $G^{(1)}_T$, respectively. By Proposition \ref{pro-2-1} (i), $F$ is absolutely continuous and strictly increasing in $x \in \{z \geq 0, F(z) <1\}$. Then $F^{-1}(p)$ is also absolute continuous in $p \in (\alpha_o\wedge\alpha_1, \alpha_0\vee \alpha_1)$. Combining $F(t^\ast) = G^{(1)}_T(t^\ast) = \alpha$, we calculate the derivatives of TTTs for $F$ and $G^{(1)}_T$ at $\alpha$, i.e.,
	\begin{equation*}
           \phi_F'(\alpha) = \frac{1}{\lm_F(t^\ast)}\ \ {\rm and}\ \ \phi_{G^{(1)}_T}'(\alpha) = \frac{1}{\lm_{G^{(1)}_T}(t^\ast)},
	\end{equation*}
    where $\lm_F$ and $\lm_{G^{(1)}_T}$ are the corresponding failure rates of $F$ and $G^{(1)}_T$. Since $F$ up-crosses $G^{(1)}_T$ at $t^\ast$, then $\lambda_{G^{(1)}_T}(t^\ast) < \lambda_F(t^\ast)$, implying  $\phi_F'(\alpha) < \phi_{G^{(1)}_T}'(\alpha)$. If $\phi_F(\alpha) < \phi_{G^{(1)}_T}(\alpha)$, by the concavity of $\phi_F$ (see Proposition \ref{eq-2024-1} (iv)) and linearity of $\phi_{G^{(1)}_T}$, we obtain
	$$
		\phi_F(1)\leq \phi_F(\alpha) + \phi_F'(\alpha)(1 -\alpha)
			< \phi_{G^{(1)}_T}(\alpha) + \phi_{G^{(1)}_T}'(\alpha)(1 - \alpha) = \phi_{G^{(1)}_T}(1),
   $$
   which contradicts $\phi_F(1) = 1 = \phi_{G^{(1)}_T}(1)$. Thus, \eqref{eq-2024-13} holds and we complete the proof of Claim 2.
\end{itemize}
Thus, for any $\alpha \in (0, 1)$, \eqref{eq-2024-9} holds. This completes the proof of the theorem.
\end{proof}

Based on Theorem \ref{thm-4-4}, we now establish the worst-case RVaR bound. The subsequent analysis requires greater sophistication than that in the proof of Theorem \ref{thm-4-4}, as the parameter $\beta$ introduces significant analytical complexity -- especially in the small $\beta$ regime where its uncertainty dominates.

\begin{theorem}\label{thm-4-5}
For any $0\leq\alpha < \beta \le 1$, we have
\begin{equation}\label{eq-2024-14}
   \sup_{F\in {\cal G}} \RVaR_{\alpha, \beta}(F) =\sup_{F\in {\cal G}_1\cup {\cal G}_2}\RVaR_{\alpha, \beta}(F).
\end{equation}
\end{theorem}

\begin{proof}
It suffices to establish that for any $0<\alpha<\beta< 1$ and given $F \in {\cal G}$, there exists another $G \in {\cal G}_1 \cup {\cal G}_2$ such that
\begin{equation}\label{eq-2024-15}
	\RVaR_{\alpha, \beta}(F) \leq \RVaR_{\alpha, \beta}(G).
\end{equation}

For any given $F \in {\cal G}$, define $G_{T_1} \in {\cal G}_1$ as \eqref{eq-2024-42} and $G^{(1)}_\oo \in {\cal G}_1$ as \eqref{eq-2024-10}. Recall the definitions of $\alpha_1$ and $\alpha_0$ from the proof of Theorem \ref{thm-4-4}. That is, $\alpha_1 = F(t_1) = G_{T_1}(t_1)$, where $t_1 \in (0, T_1)$ such that $F$ up-crosses $G_{T_1}$, and $\alpha_0 = G^{(1)}_\oo(t_0)$, where $F$ up-crosses $G^{(1)}_\oo$ at $t_0 \in (\Delta_0, \oo)$, see also Figure \ref{Fig1}. Moreover, we have $F(T_1) < 1$. Otherwise $F$ up-crosses $G_{T_1}$ only once. This contradicts the equality of the first two moments by Lemma \ref{cut}. Furthermore, we also have $G_\oo \in {\cal G}_2$, since $\Gbar^{(1)}_\oo = \Gbar^{(2)}_{\Delta_0} \in {\cal G}_2$. To see this, when substituting $\Gbar_{\Delta_0}^{(2)}$ into \eqref{eq-2024-45}, we get $k_1 = 0$ and $k_2 = (\mu_2 - 1)^{-1/2}$. We can assert that $\Delta_0 = T_0$ and $b = k_2$ by the equally first two moments. In order to better reflect our proof, we always denote $G^{(2)}_{T_0} = G^{(1)}_\oo$ below and $\alpha_0 = G^{(2)}_{T_0}(t_0)$.

Below, we show how to construct $G \in {\cal G}_1 \cup {\cal G}_2$ such that \eqref{eq-2024-15} holds for any given $F \in {\cal G}$ with $F \neq G_{T_1}$ and $F \neq G^{(2)}_{T_0}$. We consider three cases:

\underline{\emph{Case 1:}}\ Suppose $\alpha \geq \alpha_0$. In this case, we have $F(x) > G^{(2)}_{T_0}(x)$ for $x > t_0$ by the convexity of $\Lambda_F$, see Figure \ref{Fig1}. It is obviously to see that, $\VaR_p(F) \leq \VaR_p(G^{(2)}_{T_0})$ for any $p > \alpha_0$. Finally, we have
\begin{equation*}
	\RVaR_{\alpha, \beta}(F) \leq \RVaR_{\alpha, \beta}(G^{(2)}_{T_0}).
\end{equation*}

\underline{\emph{Case 2:}}\ Suppose $\alpha \leq \alpha_1$. In this case, denote $h_1 := F(T_1) < 1$ by the previous analysis. Moreover, $F$ down-crosses first and then up-crosses $G^{(2)}_{T_0}$. Denote $F$ down-crosses $G^{(2)}_{T_0}$ at $u(T_0) \in (T_0, \oo)$ and $G^{(2)}_{T_0}(u(T_0)) = F(u(T_0)) =: h_0$. For any $T_0 < T < T_1$. Let's consider the case where $F$ intersects with $G^{(2)}_T$ defined in \eqref{eq-2024-44}. If $F$ is greater than or equal to $G^{(2)}_T$ on $(0, T)$, then $F$ will down-cross first and then up-cross $G^{(2)}_T$ on $(T, \oo)$. If $F$ up-crosses $G^{(2)}_T$ on $(0, T)$, then $F$ will down-cross $G^{(2)}_T$ or $F$ will down-cross first then up-cross $G^{(2)}_T$ on $(T, \oo)$. Anyway, we can always ensure that $F$ down-crosses $G^{(2)}_T$ at $(T, \oo)$, and denote this point as $u(T) \in (T, \oo)$. Denote
$$
   h(T):= G^{(2)}_T(u(T)) = F(u(T)).
$$
Note that, $h(T_0) = h_0$. Moreover, by the proof process of Theorem 3.1 in \cite{BM64}, then $u(T)$ is continuous in $T \in (T_0, T_1)$ and $\lim_{T \to T_1} u(T) = T_1$. Thus, $h(T_1) = h_1$. For graphic interpretation, see Figure \ref{Fig3}.

Below, we show that $F$ must be continuous at $u(T)$ for $T \in [T_0, T_1]$. Assume that $F$ is not continuous at $u(T)$, then $F(u(T)) = 1$ and $F(u(T)-) < 1$. After $u(T)$, $F$ cannot up-crosses $G^{(2)}_T$ again, this contradicts the equally first two moments. Thus, $h(T)$ is continuous for $T \in [T_0, T_1]$. Below, we consider three subcases:
\begin{itemize}
  \item Assume $\beta \geq h_1$. In this subcase, by Theorem \ref{thm-4-4}, we have
	\begin{equation*}
		\TVaR_{\alpha}(F) \leq \TVaR_{\alpha}(G_{T_1}).
	\end{equation*}
	Moreover, we have $\VaR_p(F) \geq \VaR_{h_1}(F) = T_1 = \VaR_p(G_{T_1})$ for all $p \geq \beta$. Thus,
	\begin{align*}
         \RVaR_{\alpha, \beta}(G_{T_1}) &= \frac{1}{\beta - \alpha} \[(1-\alpha)\TVaR_{\alpha}(G_{T_1}) - (1-\beta)\TVaR_{\beta}(G_{T_1})\] \\
             & \geq \frac{1}{\beta - \alpha} \[(1-\alpha)\TVaR_{\alpha}(F) - (1-\beta)\TVaR_{\beta}(F)\]
				= \RVaR_{\alpha, \beta}(F).
	\end{align*}

  \item Assume $\beta \leq h_0$. In this subcase, we have $G^{(2)}_{T_0}(x) \leq F(x)$ for any $x \in (0, u(T_0))$. Then, $\VaR_p(F) \leq \VaR_p(G^{(2)}_{T_0})$ for $p \in (0, h_0)$. Thus,
	  $$	\RVaR_{\alpha, \beta}(G^{(2)}_{T_0}) \geq \RVaR_{\alpha, \beta}(F).   $$

  \item Assume $h_0 \wedge h_1 < \beta < h_0 \vee h_1$. In this subcase, there exists $G^{(2)}_T \in {\cal G}_2$  such that $F$ down-crosses $G^{(2)}_T$ at $u(T)$ and $F(u(T)) = G^{(2)}_T(u(T)) = \beta$, where $G^{(2)}_T$ is given by \eqref{eq-2024-44}. If $G^{(2)}_T(x) \leq F(x)$ for any $x \in (0, u(T))$, then we have $\VaR_p(F) \leq \VaR_p(G^{(2)}_T)$ for any $p \in (\alpha, \beta)$. Thus, $\RVaR_{\alpha, \beta}(G^{(2)}_T) \geq \RVaR_{\alpha, \beta}(F)$. Otherwise, there exists $v_1(T)$ and $v_2(T)$ with $v_1(T) < u(T) < v_2(T)$ such that $F$ first up-crosses, then down-cross and up-crosses $G_T$ at $v_1(T)$, $u(T)$, and $v_2(T)$, respectively. For graphic interpretation, see Figure \ref{Fig4}. Note that, $v_2(T)$ may be infinity. Denote
      \begin{equation} \label{eq-20250625}
	   	\psi(t) := \int_0^t \[\Fbar(x) - \Gbar^{(2)}_T(x)\] \d x.
     \end{equation}
     Note that $\psi(t)$ is increasing on $(0, v_1(T))$ first, and then decreasing, increasing and decreasing on  $(v_1(T), u(T))$, $(u(T), v_2(T))$ and $(v_2(T), \oo)$, respectively. Note that, $\psi(\oo) = 0$ and $\psi(0) = 0$. If $\psi(u(T)) \geq 0$, then $\psi(t) \geq 0$ for any $t > 0$. Thus,
	 \begin{align*}
            \int_0^\oo 2x\[\Fbar(x)-\Gbar^{(2)}_T(x)\] \d x &= 2\int_0^\oo \int_0^x \[\Fbar(x)-\Gbar^{(2)}_T(x)\]\d y\d x\\[3pt]
				& = 2 \int_0^\oo \int_y^\oo \[\Fbar(x) - \Gbar^{(2)}_T(x)\] \d x \d y\\[3pt]
       	& = -2 \int_0^\oo \int_0^y \[\Fbar(x) - \Gbar^{(2)}_T(x)\] \d x \d y < 0.
	\end{align*}
    This contradicts $\mu_2(F) = \mu_2(G^{(2)}_T)$. Thus, $\psi(u(T)) < 0$, i.e.,
    \begin{equation} \label{eq-250626}
        \RVaR_{0, \beta}(G^{(2)}_T) > \RVaR_{0, \beta}(F).
    \end{equation}
    Denote $\alpha' := F(v_1(T))$. If $\alpha \geq \alpha'$, then $\VaR_p(F) \leq \VaR_p(G^{(2)}_T)$ for $p \in (\alpha, \beta)$ since $G^{(2)}_T(x) \leq F(x)$ for $x \in (v_1(T), u(T))$. Thus $\RVaR_{\alpha, \beta}(G^{(2)}_T) > \RVaR_{\alpha, \beta}(F)$. If $\alpha < \alpha'$, then $\VaR_p(F) >\VaR_p(G^{(2)}_T)$ for $p \in (0, \alpha')$. Thus, in view of \eqref{eq-250626}, we have
	\begin{align*}
	  \RVaR_{\alpha, \beta}(G^{(2)}_T) &= \frac{1}{\beta - \alpha} \[\beta\, \RVaR_{0, \beta}(G^{(2)}_T)
				- \alpha\, \RVaR_{0, \alpha}(G^{(2)}_T)\] \\
			&  \geq \frac{1}{\beta - \alpha} \[\beta\RVaR_{0, \beta}(F) - \alpha\RVaR_{0, \alpha}(F)\]
				= \RVaR_{\alpha, \beta}(F).
	\end{align*}
\end{itemize}

