\underline{\emph{Case 3:}}\ Suppose $\alpha_0 \wedge \alpha_1 < \alpha < \alpha_0 \vee \alpha_1$. In this case, for given $\alpha$, it is easy to see that there exists some point $T \in [T_1, \oo]$ such that  $g(T) = \alpha$ by Claim 1 in Theorem \ref{thm-4-4}; see Figure \ref{Fig2}. If $F(x)$ is not continuous at $r(T)$, then $F(r(T)-) < 1$ and $F(r(T)) = 1$. For any $p \geq \alpha$, we have $\VaR_p(F) = r(T) \leq \VaR_p(G^{(1)}_T)$. Then \eqref{eq-2024-15} holds. If $F(x)$ is continuous at $r(T)$, then by $\VaR_\alpha(G^{(1)}_T) = \VaR_\alpha(F) = r(T)$. Below, we consider two subcases:
\begin{itemize}
    \item Suppose $\VaR_\beta(F) \leq T$. We have $F(x) \geq G^{(1)}_T(x)$ for any $x \in [r(T), \VaR_\beta(F)]$. Then $\VaR_p(F) \leq \VaR_p (G^{(1)}_T)$ for any $p \in [\alpha, \beta]$. Then \eqref{eq-2024-15} holds.

   \item Suppose $\VaR_\beta(F) > T$. In this case, we have $\beta > F(T) \geq F(T-) \geq G^{(1)}_T(T-)$.			 Then, it is easy to see that $\VaR_p(F) \geq \VaR_\beta(F) > T = \VaR_p(G^{(1)}_T)$. Thus,
       $$
              \TVaR_\beta(F) = \frac{1}{1-\beta} \int^1_{\beta} \VaR_p(F) \d p > \frac{1}{1-\beta}  \int^1_{\beta} \VaR_p(G^{(1)}_T) \d p = \TVaR_\beta(G^{(1)}_T).
	   $$
       Note that by the proof of Theorem \ref{thm-4-4}, we have $\TVaR_\alpha(G^{(1)}_T) \geq \TVaR_\alpha(F)$. Thus,
	  \begin{align*}
          \RVaR_{\alpha, \beta}(G^{(1)}_T) &= \frac{1}{\beta - \alpha} \[(1-\alpha)\TVaR_{\alpha}(G^{(1)}_T) - (1-\beta)\TVaR_{\beta}(G^{(1)}_T)\] \\
              & \geq \frac{1}{\beta - \alpha} \[(1-\alpha)\TVaR_{\alpha}(F) - (1-\beta)\TVaR_{\beta}(F)\]  =\RVaR_{\alpha, \beta}(F)
  	  \end{align*}
\end{itemize}
Thus, for any $\alpha \in (0, 1)$, \eqref{eq-2024-14} holds.
\end{proof}

A comparison of Theorems \ref{thm-4-4} and \ref{thm-4-5} indicates that, within the context of worst-case TVaR, the analysis of the worst-case distribution must be in ${\cal G}_1$ exclusively. Conversely, within the framework of worst-case RVAR, the worst-case distribution may be observed not only in ${\cal G}_1$, but also in ${\cal G}_2$. This phenomenon can be attributed to the observation that, in scenarios where the parameters $\alpha$ and $\beta$ are small, i.e. $\alpha \leq \alpha_1$ and $\beta \leq h_0$ (see Case 2 in the proof of Theorem \ref{thm-4-5}), the worst-case distribution is attained in ${\cal G}_2$.

Finally, we examine the best-case RVaR scenario. Analogous to Theorem \ref{thm-4-5}, our analysis demonstrates that the optimal RVaR under the first two moments and IFR distribution constraints is likewise attained within the sets ${\cal G}_1$ and ${\cal G}_2$.

\begin{theorem}\label{thm-4-6}
For any $0<\alpha< \beta\le 1$, we have
\begin{equation}  \label{eq-2024-16}
      \inf_{F \in {\cal G}} \RVaR_{\alpha, \beta}(F) = \inf_{F \in {\cal G}_1 \cup {\cal G}_2} \RVaR_{\alpha, \beta}(F).
\end{equation}
\end{theorem}

\begin{proof}
It suffices to show that for given $F \in {\cal G}$, there exists $G \in {\cal G}_1 \cup {\cal G}_2$ such that
\begin{equation}\label{eq-2024-17}
		\RVaR_{\alpha, \beta}(G) \leq \RVaR_{\alpha, \beta}(F).
\end{equation}

From Theorems \ref{thm-4-4} and \ref{thm-4-5}, $F$ up-crosses $G^{(1)}_T \in {\cal G}_1$ at $r(T) \in (\Delta, T)$ when $T \geq T_1$, where $G^{(1)}_T$ is given by \eqref{eq-2024-43}. Besides, $g(T) = G^{(1)}_T(r(T)) = F(r(T))$, $\alpha_1 = g(T_1)$ and $\alpha_0 = g(\oo)$. Moreover, $F$ down-crosses $G^{(2)}_T \in {\cal G}_2$ at $u(T) \in (T, \oo)$ when $T \in (T_0, T_1)$. In addition, $h(T) = G^{(2)}_T(u(T)) = F(u(T))$, $h_1 = h(T_1) < 1$ and $h_0 = h(T_0)$.	Below, we show how to construct $G \in {\cal G}_1 \cup {\cal G}_2$ such that \eqref{eq-2024-17} holds for any given $F \in {\cal G}$ with $F \neq G_{T_1}$ and $F \neq G^{(2)}_{T_0}$. We consider three cases:

\underline{\emph{Case 1:}}\ Suppose $\beta \leq \alpha_1$. In this case, we have $G_{T_1}(x) \geq F(x)$ for $x \in [0, r(T_1)]$ by the convexity of $\Lambda_F$, see Figure \ref{Fig1}. It is obviously to see that, $\VaR_p(F) \geq \VaR_p(G_{T_1})$ for any $p \in [\alpha, \beta]$, implying
\begin{equation*}
	\RVaR_{\alpha, \beta}(F) \geq \RVaR_{\alpha, \beta}(G_{T_1}).
\end{equation*}

\underline{\emph{Case 2:}}\ Suppose $\beta \geq \alpha_0$. In this case, we need to consider the following three subcases, see Figure \ref{Fig3}.
\begin{itemize}
   \item Assume $\alpha \leq h_0$. In this subcase, we have $G^{(2)}_{T_0}(x) \leq F(x)$ on $x \in [0, u(T_0)]$. Then $\VaR_p(F) \leq \VaR_p(G^{(2)}_{T_0})$ on $p \in [0, \alpha]$. Therefore, $\TVaR_\alpha(F) \geq \TVaR_\alpha(G^{(2)}_{T_0})$ since $\mu(F) = \mu(G_{T_0})$. Moreover, we also have $\TVaR_\beta(F) \leq \TVaR_\beta(G^{(2)}_{T_0})$ by Case 1 in Theorem 4.4 and $G^{(2)}_{T_0} = G_\oo$. Note that
       $$
             \RVaR_{\alpha, \beta}(F) = \frac{1}{\beta-\alpha} \int_\alpha^\beta \VaR_p(F) \d p = \frac{1}{\beta-\alpha} \[(1-\alpha) \TVaR_\alpha(F) - (1-\beta) \TVaR_\beta(F)\]
	   $$
	   Thus, \eqref{eq-2024-17} holds.

   \item Assume $\alpha \geq h_1$. In this subcase, we have $h_1 = F(T_1) > \lim_{t \uparrow T_1} G_{T_1}(t)$. 		 Then, $\VaR_p(G_{T_1}) = T_1 = \VaR_{h_1}(F) \leq \VaR_p(F)$ for $p \geq \alpha$. Thus,
	  $$	\RVaR_{\alpha, \beta}(G_{T_1}) \leq \RVaR_{\alpha, \beta}(F).   $$

  \item Assume $h_0 \wedge h_1 < \alpha < h_0 \vee h_1$. In this subcase, there exists $G^{(2)}_T \in {\cal G}_2$  such that $F$ down-crosses $G^{(2)}_T$ at $u(T)$ and $F(u(T)) = G^{(2)}_T(u(T)) = \alpha$, where $T \in (T_0, T_1)$ and $G^{(2)}_T$ is given by \eqref{eq-2024-44}. Following the similar analysis of Case 2 in the proof of Theorem \ref{thm-4-5}, we know that either $G^{(2)}_T(x) \geq F(x)$ for any $x \in (u(T), \oo)$, or $F$ up-cross only once $G^{(2)}_T$ at $v_2(T) \in (u(T), \oo)$. For graphic interpretation, see Figure \ref{Fig4}. In the former type, we have $\VaR_p(F) \geq \VaR_p(G^{(2)}_T)$ for any $p \in [\alpha, \beta]$, so \eqref{eq-2024-17} holds. In the later type, denote
      $$
           \beta' := G^{(2)}_T(v_2(T)) = F(v_2(T)).
      $$
      If $\beta \leq \beta'$, then $G^{(2)}_T(x) \geq F(x)$ for any $x \in (u(T), v_2(T))$, and $\VaR_p(F) \geq \VaR_p(G^{(2)}_T)$ for any $p \in [\alpha, \beta]$, so \eqref{eq-2024-17} holds. If $\beta > \beta'$, then $G^{(2)}_T(x) \leq F(x)$ for any $x \in (v_2(T), \oo)$, and $\VaR_p(F) \leq \VaR_p(G^{(2)}_T)$ for any $p \in [\beta, 1]$. Therefore, $\TVaR_\beta(F) \leq \TVaR_\beta(G^{(2)}_T)$. Moreover, we also have $\RVaR_{0, \alpha}(F) \leq \RVaR_{0, \alpha}(G^{(2)}_T)$ by the similar Case 2 in Theorem \ref{thm-4-5}. Thus, \eqref{eq-2024-17} holds.
\end{itemize}

\underline{\emph{Case 3:}}\ Suppose $\alpha_0 \wedge \alpha_1 < \beta < \alpha_0 \vee \alpha_1$. In this case, it is easy to see that there exists some point $T \in (T_1, \oo)$ such that $g(T) = \beta$ by Claim 1 in Theorem \ref{thm-4-4}. Following the similar analysis of Case 3 in Theorem \ref{thm-4-4}, we know that either $G^{(1)}_T(x) \geq F(x)$ for any $x \in (0, r(T))$, or $F$ down-cross $G^{(1)}_T$ at $t' \in (0, r(T))$, see Figure \ref{Fig2}. In the former type, we have $\VaR_p(F) \geq \VaR_p(G^{(1)}_T)$ for any $p \in [\alpha, \beta]$, so \eqref{eq-2024-17} holds. In the later type, denote
$$
      \alpha' := G^{(1)}_T(t') = F(t').
$$
If $\alpha \geq \alpha'$, then $G^{(1)}_T(x) \geq F(x)$ for any $x \in (t', r(T))$, and $\VaR_p(F) \geq \VaR_p(G^{(1)}_T)$ for any $p \in [\alpha, \beta]$, so \eqref{eq-2024-17} holds. If $\alpha < \alpha'$, then $G^{(1)}_T(x) \leq F(x)$ for any $x \in (0, t')$, and $\VaR_p(F) \leq \VaR_p(G^{(1)}_T)$ for any $p \in [0, \alpha]$. Therefore, $\TVaR_\alpha(F) \geq \TVaR_\alpha(G^{(1)}_T)$ since $\mu(F) = \mu(G^{(1)}_T)$. Moreover, we also have $\TVaR_\beta(F) \leq \TVaR_\beta(G^{(1)}_T)$ by Claim 2 in Theorem \ref{thm-4-4}. Thus, \eqref{eq-2024-17} holds.

Therefore, by considering the above three cases, we have \eqref{eq-2024-14}. This completes the proof of the theorem.
\end{proof}


\section{Applications to stop-loss and limited loss transforms}\label{sec5}


In this section, we are going to apply the previous results to the extreme-case stop-loss transform and extreme-case limited loss transform. For any $t \in \R_+$ and a loss random variable $X_F$ with distribution $F\in {\cal M}$, the stop-loss transformation $(X_F-t)_+$ and the limited loss random variable $X_F \wedge t$ are two of the most commonly used transformations in insurance and finance. Note that
$$
     \sup_{F\in {\cal P}} \E\[\(X_F-t\)_+\] = \E\[X_F\]- \inf_{F\in {\cal P}} \E\[X_F \wedge t\],
$$
and
$$
     \inf_{F \in {\cal P}} \E\[\(X_F-t\)_+\] = \E\[X_F\] - \sup_{F \in {\cal P}} \E\[X_F \wedge t\],
$$
where $\cal P$ is some ambiguity set of distributions. We only need to consider the extreme-case stop-loss transform based on the above observation. In this section, we consider the following questions to illustrate our previously established results: for any given $t \in \R_+$,
\begin{equation}\label{eq5-1}
	\sup_{F \in {\cal P}} \E\[\(X_F - t\)_+\],\ {\rm and}\ \inf_{F \in {\cal P}} \E\[(X_F - t)_+\],
\end{equation}
where ${\cal P}$ is ${\cal F} = \left\{F \in {\cal M}: F {\rm\ is\ IFR},\ \mu(F) = 1 \right\}$ or ${\cal G} = \left\{F \in {\cal M}: F {\rm\ is\ IFR},\ \mu(F) = 1,\ \mu_2(F) = \mu_2\right\}$. We first derive the result for the worst-case scenario by applying the reverse TVaR optimization formula, originally proposed by \cite{GJZ24} and later generalized by \cite{GZGH24}.

\begin{proposition}\label{pro5-1}
For $t \in \R_+$, we have
\begin{eqnarray*}
	& & \sup_{F \in {\cal F}} \E\[\(X_F-t\)_+\]  =  \exp\{-t\},\\
    & & \sup_{F \in {\cal G}} \E\[\(X_F-t\)_+\]  = \sup_{\alpha \in [0,1]} \left\{(1-\alpha) \left(\sup_{F \in {\cal G}_1} \TVaR_\alpha(F) - t\right)\right\},
\end{eqnarray*}
where ${\cal G}_1$ is defined by \eqref{distributions}.
\end{proposition}

\begin{proof}
It is well known that
\begin{eqnarray*}
	\E\[\(X_F - t\)_+\] = \sup_{\alpha \in [0,1]} \left\{(1-\alpha) \[\TVaR_\alpha(F) - t\]\right\}.
\end{eqnarray*}
Thus,
\begin{align}\label{eq5-2}
   \sup_{F \in {\cal P}} \E\[\(X_F-t\)_+\] &= \sup_{F \in {\cal P}} \sup_{\alpha \in [0,1]} \left\{(1-\alpha) \(\TVaR_\alpha(F) - t\)\right\} \nonumber \\
        &= \sup_{\alpha\in [0,1]}\sup_{F \in {\cal P}}\left\{(1-\alpha) (\TVaR_\alpha(F)-t)\right\}\nonumber \\
       &=\sup_{\alpha \in [0,1]} \left\{(1-\alpha) \(\sup_{F\in {\cal P}} \TVaR_\alpha(F)- t\)\right\}.
\end{align}
When ${\cal P} = {\cal F}$, we have
\begin{align*}
    \sup_{F \in {\cal F}} \E\[\(X_F-t\)_+\] &= \sup_{\alpha \in [0,1]} \left\{(1-\alpha) \left(\sup_{F \in {\cal F}} \TVaR_\alpha(F) - t\right)\right\} \\
	 &=\sup_{\alpha \in [0,1]} \left\{(1-\alpha) (1 - \ln(1-\alpha) - t)\right\}= \exp\{-t\},
\end{align*}
where the second equality follows \eqref{eq-250628}. When ${\cal P} = {\cal G}$, we have
\begin{align*}
    \sup_{F\in {\cal G}} \E\[\(X_F-t\)_+\] &= \sup_{\alpha \in [0,1]} \left\{(1-\alpha) \left(\sup_{F \in {\cal G}} \TVaR_\alpha(F) - t\right)\right\} \\
           &= \sup_{\alpha \in [0,1]} \left\{(1-\alpha) \(\sup_{F \in {\cal G}_1} \TVaR_\alpha(F) -t\)\right\},
\end{align*}
where the second equality follows from Theorem \ref{thm-4-4}.
\end{proof}


\begin{proposition}\label{pro5-2}
For $t \in \R_+$, we have
\begin{eqnarray*}
      \inf_{F \in {\cal F}} \E\[\(X_F-t\)_+\]  =  (1-t)_+,\ \  {\rm\ and\ } \ \
      \inf_{F \in {\cal G}} \E\[\(X_F-t\)_+\]  = \inf_{F\in {\cal G}_1 \cup {\cal G}_2} \E\[\(X_F-t\)_+\],
\end{eqnarray*}
where ${\cal G}_1$ and ${\cal G}_2$ are defined by \eqref{distributions}.
\end{proposition}

\begin{proof}
When ${\cal P} = {\cal F}$, we have $\delta_1 \leq_{\rm cx} F$. Thus
$$
		\inf_{F \in {\cal F}} \E\[\(X_F - t\)_+\] =(1 - t)_+.
$$
When ${\cal P} = {\cal G}$, we need to establish that for any given $F \in {\cal G}$, there exists $G \in {\cal G}_1 \cup {\cal G}_2$ such that
\begin{equation}\label{eq-2024-53}
		\E\[\(X_G - t\)_+\] \leq \E\[\(X_F - t\)_+\].
\end{equation}
Following the same notations as those in the proof of Theorem \ref{thm-4-5}, we know that $F$ down-crosses $G^{(2)}_T \in {\cal G}_2$ at $u(T) \in (T, \oo)$ when $T \in (T_0, T_1)$. Moreover, $u(T)$ is continuous over $T \in (T_0, T_1)$ and $\lim_{T \to T_1} u(T) = T_1$. Below, we consider three cases:

\underline{\emph{Case 1:}}\ Suppose that $t \leq u(T_0)$. We know that $F(x) \leq G^{(2)}_{T_0}(x)$ for $x \in (0, u(T_0))$ by the convexity $\Lambda_F$. Then
\begin{equation*}
	\int_0^t \overline{G}_{T_0}^{(2)}(x) \d x \leq \int_0^t \Fbar(x) \d x.
\end{equation*}
Combining $\mu(F) = \mu(G_{T_0}) = 1$, we have
\begin{equation*}
   \E\[\(X_F - t\)_+\] = \int_t^\oo \Fbar (x) \d x \geq \int_t^\oo \overline{G}_{T_0}^{(2)}(x) \d x = \E\[\(X_{G_{T_0}} - t\)_+\].
\end{equation*}

\underline{\emph{Case 2:}}\ Suppose that $t \geq u(T_1) = T_1$. Note that $\essinf\(G_{T_1}\) = T_1$ for $G_{T_1} \in {\cal G}_1$. Then
\begin{equation*}
	\E\[\(X_F - t\)_+\] \geq 0 = \E\[\(X_{G_{T_1}} - t\)_+\].
\end{equation*}

\underline{\emph{Case 3:}}\ Suppose that $u(T_0) \wedge u(T_1) < t < u(T_0) \vee u(T_1)$. From the proof of Theorem \ref{thm-4-5}, we know that there exists $G_T^{(2)} \in {\cal G}_2$ such that $F$ down-crosses $G_T^{(2)}$ at $u(T) = t$ and
\begin{equation*}
	\psi(u(T)) = \int_0^t \[\Fbar(x) - \Gbar_T^{(2)}(x)\] \d x<0,
\end{equation*}
where $\psi(x)$ is defined by \eqref{eq-20250625}. Then
\begin{align*}
       \E\[\(X_F - t\)_+\] - \E\[\(X_{G_T^{(2)}} - t\)_+\] &= \int_t^\oo \[\Fbar(x) -\Gbar_T^{(2)}(x)\]\d x\\
        & = -\int_0^t \[\Fbar(x) - \Gbar_T^{(2)}(x)\] \d x > 0.
\end{align*}
Thus, we complete the proof of the proposition.
\end{proof}



\section{Conclusions}\label{sec6}


This paper develops a constructive methodology to determine the extreme-case RVaR for IFR distributions under mean and/or variance ambiguity sets. Our approach characterizes the extremal distributions through parametric families of IFR distributions, which enables efficient computation of extreme-case RVaR bounds. While the proposed framework naturally lends itself to numerical implementation (as demonstrated by our theoretical construction), we emphasize that the current analysis focuses primarily on the theoretical development rather than numerical simulation.

We conclude with some open questions that are the focus of our ongoing research.
\begin{itemize}
 \item How to find the extreme-case RVaR under the mean/variance ambiguity sets of distributions with DFR property or other ageing notions? A promising direction to solve extreme-case RVaR under DFR ambiguity set may refer to \cite{BM64}, in which they derived the bounds for distribution functions with IFR/DFR property and given mean and/or variance.

 \item The existing literature has developed various ambiguity sets beyond mean/variance uncertainty sets, notably those constructed by using probability distances like the likelihood ratio \citep{LMWW22} and Wasserstein distance \citep{BPV24}. This raises an important research question. Can we develop computational method to determine the worst-case or best-case RVaR by employing probability distances between distributions while incorporating IFR or DFR constraint?

 \item Since RVaR constitutes a special case of distortion risk measure, we propose extending this analysis to general distortion risk measures or distortion riskmetrics \citep{PWW24} while incorporating uncertainty information about the underlying distribution's failure rate characteristics (IFR/DFR).
\end{itemize}

