\noindent \textbf{Proof of Theorem \ref{main_thm}: }

\begin{proof}
    Let $x^{\mathtt{i}}, y^{\mathtt{i}}$ be the concentration vectors of species in $\mathcal{X}^{\mathtt{i}},\mathcal{Y}^{\mathtt{i}}$, respectively, where $\mathtt{i}=1,2$. Then the dynamics of $\mathscr{C}^{\mathtt{i}}$ is given by
    $$\begin{cases}
        \dot{x}^{\mathtt{i}}=f^{\mathtt{i}}(x^{\mathtt{i}},y^{\mathtt{i}}), \\
        \dot{y}^{\mathtt{i}}=g^{\mathtt{i}}(x^{\mathtt{i}},y^{\mathtt{i}}), 
    \end{cases} x^{\mathtt{i}}(0)=x_0^{\mathtt{i}},~y^{\mathtt{i}}(0)=y_0^{\mathtt{i}},$$ 
    and its solutions satisfy $\bar{y}^\mathtt{i}=\lim_{t \to \infty} y^\mathtt{i}(t)=\sigma_i(x_0^{\mathtt{i}})$, where $\mathtt{i}=1,2$. Since $\mathscr{C}^{\mathtt{1}}$ and $\mathscr{C}^{\mathtt{2}}$ are dynamically composable, it takes $f^\mathtt{2}=0$, and the dynamics of $\mathscr{C}_{2 \circ 1}$ is given by
    $$\begin{cases}
        \dot{x}^{\mathtt{1}}=f^{\mathtt{1}}(x^{\mathtt{1}},y^{\mathtt{1}}),  \\
        \dot{y}^{\mathtt{1}}=g^{\mathtt{1}}(x^{\mathtt{1}},y^{\mathtt{1}}),  \\
        \dot{y}^{\mathtt{2}}=g^{\mathtt{2}}(y^{\mathtt{1}},y^\mathtt{2}), 
    \end{cases} \begin{array}{l}
         x^{\mathtt{1}}(0)=x_0^{\mathtt{1}},~y^{\mathtt{1}}(0)=y_0^{\mathtt{1}}, \\
         y^{\mathtt{2}}(0)=y_0^{\mathtt{2}}.
    \end{array}$$
    Due to Definition \ref{Def_dynamic_composable}, it holds 
    $$\lim_{t\to \infty}y^{\mathtt{2}}(t)=\sigma_2(\bar{y}^{\mathtt{1}})=\sigma_2(\sigma_1(x_0^{\mathtt{1}})),$$
    which means $\mathscr{C}_{2\circ 1}$ is a dynamic computation of $\sigma_2 \circ \sigma_1$.
\end{proof}



\noindent \textbf{Proof of Corollary \ref{coro_thm1}: }

\begin{proof}
    The proof proceeds by induction on $p$. The result for $p=2$ is described as \textit{Theorem} \ref{main_thm} before. Suppose that the result holds for $p=r (r \ge 2)$. Then the dynamics of $\mathscr{C}_{r\circ \cdots \circ 1}$ is given by
    $$\begin{cases}
        \dot{x}=f(x,y^{\mathtt{r}}),  \\
        \dot{y}^{\mathtt{r}}=g^{\mathtt{r}}(x,y^{\mathtt{r}}), & 
    \end{cases},x(0)=x_0,~y^{\mathtt{r}}(0)=y_0^{\mathtt{r}}.$$
    where $x$ denotes the concentrations of all the species in $\mathscr{C}_{r\circ \cdots \circ 1}$, and its solutions satisfy $\bar{y}^{\mathtt{r}}=\lim_{t \to \infty} y^{\mathtt{r}}(t)=(\sigma_{r} \circ \cdots \circ \sigma_1)(x_0^{\mathtt{1}})$. Applying Theorem \ref{main_thm} by taking $\mathscr{C}_{r\circ \cdots \circ 1}$ as the first msCRC and $\mathscr{C}_{r+1}$ as the second msCRC, we can conclude that $\mathscr{C}_{(r+1)\circ r \circ \cdots \circ 1}$ is a dynamic computation of $\sigma_{r+1} \circ \sigma_r \circ \cdots \circ \sigma_1$, and the proof is complete.
\end{proof}



\noindent \textbf{Proof of Proposition \ref{prop_simple_structure}: }

\begin{proof}
    For system (\ref{dy=p-qy}) with initial values $x(0)=\bar{x},~y(0)=y_0$, it leads to
    \begin{equation*}
        y(t)=\frac{p(\bar{x})}{q(\bar{x})}+\left(y_0-\frac{p(\bar{x})}{q(\bar{x})}\right)e^{-q(\bar{x})t}
    \end{equation*}
    and $\lim_{t \to \infty}y(t)=\frac{p(\bar{x})}{q(\bar{x})}$. Now for any system (\ref{dx=f}) with $\lim_{t \to \infty}y^{\mathtt{1}}(t)=\bar{y}^{\mathtt{1}}$, the coupled system
    \begin{equation*}
        \begin{cases}
            \dot{x}^{\mathtt{1}}=f^{\mathtt{1}}(x^{\mathtt{1}},x) \\
            \dot{x}=g^{\mathtt{1}}(x^\mathtt{1},x) \\
            \dot{y}=p(x)-q(x)y
        \end{cases}\begin{array}{l}
        x^{\mathtt{1}}(0)=x^{\mathtt{1}}_0,~x(0)=y^{\mathtt{1}}_0,\\
        y(0)=y_0.
        \end{array}
    \end{equation*}
    supports $\lim_{t \to \infty}x(t)=\bar{x}$, and has the solution
    $$y(t)=e^{-\int_0^tq(s)\mathrm{d}s}\left(y_0+\int_0^{t}p(s)e^{\int_0^sq(u)\mathrm{d}u}\mathrm{d}s\right),$$ which satisfies
    \begin{align*}
        \lim_{t \to \infty}y(t)&=\lim_{t \to \infty}\frac{\int_{0}^tp(x(s))e^{\int_{0}^sq(x(u))\mathrm{d}u}\mathrm{d}s}{e^{\int_{0}^tq(x(s))\mathrm{d}s}} \\
        &=\lim_{t \to \infty}\frac{p(x(t))e^{\int_{0}^tq(x(u))\mathrm{d}u}}{q(x(t))e^{\int_{0}^tq(x(s))\mathrm{d}s}} \\
        &=\lim_{t \to \infty}\frac{p(x(t))}{q(x(t))} \\
        &=\frac{p(\bar{x})}{q(\bar{x})}
    \end{align*}
    with the second equality guaranteed by the L'Hopital's Rule. By definition \ref{Def_dynamic_composable}, the proof is complete.
\end{proof}


\noindent \textbf{Proof of Theorem \ref{Thm_ISS_net}: }

\begin{proof}
    For the coupled system (\ref{coupled_system}), since $\lim_{t \to \infty}y^{\mathtt{1}}(t)=\bar{y}^{\mathtt{1}}$, we just need to prove that $\lim_{t \to \infty}y^{\mathtt{2}}(t)=\bar{y}^{\mathtt{2}}$. Since (\ref{g2_y}) is ISS regarding $(\bar{y}^{\mathtt{1}},\bar{y}^{\mathtt{2}})$, it satisfies
    \begin{equation}\label{ISS_s_to_t}
    \begin{split}
        \left \| y^{\mathtt{2}} \left( t \right) -\bar{y}^{\mathtt{2}} \right \| \le& \beta \left( \left\| y^{\mathtt{2}}(s) - \bar{y}^{\mathtt{2}} \right\| , t-s \right) \\
        +& \gamma ( \sup \limits_{s\le \tau \le t}\left\| x^{\mathtt{2}} \left( \tau \right) -\bar{y}^{\mathtt{1}} \right\| ),
    \end{split}
    \end{equation}
    where $0\le s\le t$, $\beta$ is a class $\mathcal{KL}$ function and $\gamma$ is a class $\mathcal{K}$ function. Substituting $s=\frac{t}{2}$ into (\ref{ISS_s_to_t}) yields
    \begin{equation}\label{ISS_t_2}
    \begin{split}
        \left \| y^{\mathtt{2}} \left( t \right) -\bar{y}^{\mathtt{2}} \right \| \le& \beta \left( \left\| y^{\mathtt{2}}\left(\frac{t}{2}\right) - \bar{y}^{\mathtt{2}} \right\| , \frac{t}{2} \right) \\
        +& \gamma \left( \sup \limits_{\frac{t}{2}\le \tau \le t}\left\| x^{\mathtt{2}} \left( \tau \right) -\bar{y}^{\mathtt{1}} \right\| \right),
    \end{split}
    \end{equation}
    To estimate $\left\| y^{\mathtt{2}}\left(\frac{t}{2}\right) - \bar{y}^{\mathtt{2}} \right\|$, apply (\ref{ISS_s_to_t}) with $s=0$ and $t$ replaced by $\frac{t}{2}$ to obtain
    \begin{equation*}
        \begin{split}
        \left \| y^{\mathtt{2}} \left( \frac{t}{2} \right) -\bar{y}^{\mathtt{2}} \right \| \le& \beta \left( \left\| y^{\mathtt{2}}_0 - \bar{y}^{\mathtt{2}} \right\| , \frac{t}{2} \right) \\
        +& \gamma \left( \sup \limits_{0\le \tau \le \frac{t}{2}}\left\| x^{\mathtt{2}} \left( \tau \right) -\bar{y}^{\mathtt{1}} \right\| \right),
        \end{split}
    \end{equation*}
    Since $\lim_{t\rightarrow \infty} x^{\mathtt{2}}\left( t \right) =\bar{y}^{\mathtt{1}}$, $x^{\mathtt{2}}(t)-\bar{y}^{\mathtt{1}}$ is bounded, then there exists a $M>0$ satisfying $\gamma(\left \| x^{\mathtt{2}}(t)-\bar{y}^{\mathtt{1}} \right \|) \le M$. And for sufficiently large $t$, it holds $\beta \left (\left \| y^{\mathtt{2}}_0-\bar{y}^{\mathtt{2}} \right \|,\frac{t}{2} \right ) \le M$. Substitute all above results into (\ref{ISS_t_2}) to obtain
    \begin{align*}
    \left \| y^{\mathtt{2}} \left( t \right) -\bar{y}^{\mathtt{2}} \right \| \le &\beta \left(  2M , \frac{t}{2} \right) + \gamma \left( \sup_{\frac{t}{2} \le \tau \le t}\left\| x^{\mathtt{2}} \left( \tau \right) -\bar{y}^{\mathtt{1}} \right\| \right) \\
     \rightarrow & ~0 \quad \left( t \rightarrow \infty \right)
    \end{align*}
    It means $y^{\mathtt{2}}(t)\rightarrow \bar{y}^{\mathtt{2}}~ (t \rightarrow \infty)$, the proof is complete.
\end{proof}


\noindent \textbf{Proof of Corollary \ref{coro_thmISS}: }

\begin{proof}
    The proof proceeds by induction on $p$. The result for $p=2$ is described as \textit{Theorem} \ref{Thm_ISS_net} before. Suppose that the result holds for $p=r (r \ge 2)$. Consider $\mathscr{C}^{\mathtt{r}\circ \cdots \circ \mathtt{1}}$ and $\mathscr{C}^{\mathtt{r+1}}$, which satisfy the condition in \textit{Theorem} \ref{Thm_ISS_net}. Then they are dynamically composable, and the proof is complete.
\end{proof}



\noindent \textbf{Proof of Proposition \ref{iss_condition}: }

\begin{proof}
We introduce the following two lemmas for convenience of the subsequent proof: 
\begin{lemma}\label{lem1}(Khalil \cite{Khalil_2002_nonlinear})
    The system (\ref{general_system}) is ISS regarding $(\bar{u},\bar{s})$ if it admits an ISS-Lyapunov function $V: \mathbb{R}^{n-m} \to \mathbb{R}_{\ge 0}$, which is smooth, positive definite, and radially unbounded, and also satisfies that
    \begin{itemize}
        \item [] for bounded input $u$, there exist a positive definite function $W:\mathbb{R}^{n-m} \to \mathbb{R}_{\ge 0}$ and a class $\mathcal{K}$ function $\rho:\mathbb{R}_{\ge 0} \to \mathbb{R}_{\ge 0}$ to support
         \begin{equation*}
            \nabla V^{\top} (s-\bar{s})f(u,s) \le -W(s-\bar{s})
    \end{equation*}
    under the condition of $\left \|s-\bar{s} \right  \| \ge \rho (\left\|u-\bar{u} \right \|)$.
    \end{itemize}
\end{lemma}

\begin{lemma}\label{lem2}(Khalil \cite{Khalil_2002_nonlinear})
    Suppose $f(u,s)$ in (\ref{general_system}) is continuously differentiable and globally Lipschitz in $(u,s)$, and $\bar{s}$ is a globally exponentially stable equilibrium point in (\ref{general_system}) evaluated at $u=\bar{u}$. Then system (\ref{general_system}) is ISS regarding $(\bar{u},\bar{s})$.
\end{lemma}

The proof is obtained by applying \textit{Theorem} \ref{Thm_ISS_net}, \textit{Lemma} \ref{lem1} and \textit{Lemma} \ref{lem2}.
\end{proof}


\noindent \textbf{Proof of Theorem \ref{thm_error_n2}: }

\begin{proof}
    (1) Note that
    \begin{align}\label{esti_0}
        \left| z\left( T \right) -\frac{1}{1+e^{-x_0}} \right|&\le \left| z\left( T \right) -\frac{1}{1+y(\frac{T}{2})} \right| \nonumber\\
        & + \left| \frac{1}{1+y(\frac{T}{2})}- \frac{1}{1+e^{-x_0}} \right|
    \end{align}
    For the first phase of (\ref{sigmoid_2_CRC}), where $0 < t < \frac{T}{2}$, it holds $y(\frac{T}{2})=e^{-x_0\left(1-e^{-\frac{T}{2}}\right)}$ and $z(\frac{T}{2})=z(0)=z_0$. For the second phase of (\ref{sigmoid_2_CRC}), where $\frac{T}{2}< t < T$, it holds $z(T)=\frac{1}{1+y(\frac{T}{2})}+\left( z(\frac{T}{2})-\frac{1}{1+y(\frac{T}{2})} \right)e^{-(1+y(\frac{T}{2}))\frac{T}{2}}$. Then we have
    \begin{flalign}\label{esti_1}
        \left| z\left( T \right) -\frac{1}{1+ y\left( \frac{T}{2} \right)} \right| \nonumber&= \left| z_0-\frac{1}{1+ y\left( \frac{T}{2} \right)} \right|e^{-\left(1+y(\frac{T}{2})\right)\frac{T}{2}}  \nonumber \\
        &\le \left(z_0+1 \right)e^{-\frac{T}{2}}
    \end{flalign}
    and 
    \begin{flalign}
    &\left| \frac{1}{1+y(\frac{T}{2})}- \frac{1}{1+e^{-x_0}} \right| \nonumber \\
    =& \frac{1}{\left (1+y(\frac{T}{2}) \right )(1+e^{-x_0})} \left|y\left(\frac{T}{2}\right)-e^{-x_0} \right| \nonumber \\
    \le& \frac{1}{1+e^{-x_0}} \left|e^{-x_0\left(1-e^{-\frac{T}{2}}\right)}-e^{-x_0} \right| \nonumber \\
    \le& \frac{e^{-x_0}}{1+e^{-x_0}} \left|e^{x_0e^{-\frac{T}{2}}}-1 \right| \nonumber \\
    \le& 2x_0e^{-\frac{T}{2}} \nonumber 
    \end{flalign}
    with the last inequality satisfied for sufficiently large $T\ge T_0>0$. Defining 
    $$C=2x_0+\max_{0\le t\le T_0}\left| \frac{1}{1+y(\frac{t}{2})}- \frac{1}{1+e^{-x_0}} \right|e^{\frac{T_0}{2}},$$
    we have
    \begin{equation}\label{esti_2}
    \left| \frac{1}{1+y(\frac{T}{2})}- \frac{1}{1+e^{-x_0}} \right| \le Ce^{-\frac{T}{2}} 
    \end{equation}
    for all $T>0$. Substitute (\ref{esti_1}) and (\ref{esti_2}) into  (\ref{esti_0}), we can get (\ref{2_step_esti}) with $C_1=z_0+1+C$.

    (2) The composition of msCRC (\ref{exp_CRC}) and (\ref{laycom_sigmoid}) has dynamics of
    \begin{equation*}
        \begin{cases}
        \dot{x}=-x \\
        \dot{y}=-xy \\
        \dot{z}=1-(1+y)z \\
        \end{cases}
    \end{equation*}
    where $y(0)=1$. It is obvious that $y(t)=e^{-x_0 \left(1-e^{-t}\right)}$. Let $u(t)=z(t)-\frac{1}{1+e^{-x_0}}$, and it takes to
    \begin{equation*}
        \dot{u}=-p(t)u+g(t), \quad u(0)=z_0-\frac{1}{1+e^{-x_0}}
    \end{equation*}
    which have solutions
    \begin{align}\label{esti_00}
    u\left( T \right) = & u\left( 0 \right) e^{-\int_0^{T}{p\left( s \right)}\mathrm{d}s} \nonumber\\
    +&e^{-\int_0^{T}{p\left( s \right)}\mathrm{d}s}\int_0^{T}{g\left( s \right) e}^{\int_0^s{p\left( u \right)}\mathrm{d}u}\mathrm{d}s
    \end{align}
    where
    \begin{align*}
    p(t) &=1+y(t)=1+e^{-x_0 \left(1-e^{-t}\right)}, \\
    g(t) &=1-\frac{1}{1+e^{-x_0}}(1+y(t)) \\
    &=\frac{1}{e^{x_0}+1}\left(1-e^{x_0e^{-t}} \right).
    \end{align*}
    Then it holds that
    \begin{align}\label{esti_4}
        \left| u(0)e^{-\int_0^{T}{p(s)\mathrm{d}s}} \right|&=\left| u(0)e^{-\int_0^{T}{\left( 1+e^{-x_0 \left(1-e^{-s}\right)}\right )\mathrm{d}s}} \right| \nonumber \\
    &\le \left| u\left( 0 \right) \right|e^{-T}=C_3e^{-T}
    \end{align}
    Besides, defining $F(t)=\left| e^{-\int_0^{t}{p\left( s \right) \mathrm{d}s}}\int_0^{t}{g\left( s \right) e^{\int_0^s{p\left( u \right) \mathrm{d}u}}\mathrm{d}s} \right|$ and using L'Hopital's Rule, we have
    \begin{align*}
    \lambda&=-\lim_{t \to \infty} \frac{\ln F(t)}{t}   \\ 
    &=-\lim_{t\rightarrow \infty}\frac{\ln \left( e^{-\int_0^{t}{p\left( s \right) \mathrm{d}s}}\int_0^{t}{(-g\left( s \right) )e^{\int_0^s{p\left( u \right) \mathrm{d}u}}\mathrm{d}s} \right)}{t}\\
    &=-\lim_{t\rightarrow \infty}\left( \frac{-\int_0^{t}{p\left( s \right) \mathrm{d}s}}{t}+\frac{\ln \left( -\int_0^{t}{g\left( s \right) e^{\int_0^s{p\left( u \right) \mathrm{d}u}}\mathrm{d}s} \right)}{t} \right) \\
    &=-\lim_{t\rightarrow \infty}\left( -p\left( t \right) +\frac{g\left( t \right) e^{\int_0^{t}{p\left( u \right) \mathrm{d}u}}}{\int_0^{t}{g\left( s \right) e^{\int_0^s{p\left( u \right) \mathrm{d}u}}\mathrm{d}s}} \right) \\
    &=1+e^{-x_0}-\lim_{t\rightarrow \infty}\left( \frac{g^{\prime}(t)}{g( t )}+p(t) \right) \\
    &=-\lim_{t\rightarrow \infty}\frac{x_0e^{x_0e^{-t}-t}}{1-e^{x_0e^{-t}}}\\
    &=-\lim_{t\rightarrow \infty}\frac{-x_0e^{-t}}{x_0e^{x_0e^{-t}}e^{-t}}\\
    &=1.\\
\end{align*}
Then for any $\varepsilon >0$, there is a $T_0>0$ such that for any $T\ge T_0$, it holds 
\begin{equation*}
    -\frac{\ln F(T)}{T}\ge  \lambda-\varepsilon.
\end{equation*}
Hence we have $F(T) \le e^{-(1-\varepsilon)T},~ T\ge T_0$. Defining 
$$C_2=1+\max_{0\le t\le T_0}F(t)e^{(1-\varepsilon)T_0},$$
we have
\begin{equation}\label{esti_6}
    \left |e^{-\int_0^{T}{p\left( s \right)}\mathrm{d}s}\int_0^{T}{g\left( s \right) e}^{\int_0^s{p\left( u \right)}\mathrm{d}u}\mathrm{d}s \right |=F(T) \le C_2 e^{-(1-\varepsilon)T}
\end{equation}
for all $T\ge 0$. Substitute (\ref{esti_4}) and (\ref{esti_6}) into (\ref{esti_00}), we can get (\ref{1_step_esti}).
\end{proof}



\subsection{Another example of composite function computed}\label{appendixB}
\setcounter{equation}{0}
\renewcommand\theequation{B.\arabic{equation}}

Consider the frequently-used quadratic formula (positive root) 
\begin{equation}\label{root}
    z=\frac{1}{2}\left (b+\sqrt{b^2+4c}\right )
\end{equation}
for the quadratic equation $z^2-bz-c=0$ with $b,c>0$. This composition function may be viewed as a composition of three functions $x=b^2+4c$, $y=\sqrt{x}$ and $z=\frac{1}{2}(b+y)$. We thus introduce the following three msCRCs
\begin{equation*}
    \begin{split}
        \mathscr{C}^{\mathtt{1}}:&~C \overset{4}{\longrightarrow}C+X, \quad X \overset{1}{\longrightarrow} \varnothing, \quad 2B \overset{1}{\longrightarrow}2B+X;    \\
        \mathscr{C}^{\mathtt{2}}:&~X \overset{1}{\longrightarrow} X+Y,\quad  2Y \overset{1}{\longrightarrow} \varnothing; \\
        \mathscr{C}^{\mathtt{3}}:&~ B \overset{1}{\longrightarrow}B+Z,\quad Y \overset{1}{\longrightarrow} Y +Z,\quad  Z \overset{2}{\longrightarrow} \varnothing.
    \end{split}
\end{equation*}
Then the dynamics of the composition $\mathscr{C}^{\mathtt{3}\circ \mathtt{2}\circ \mathtt{1}}$ is
\begin{equation*}
    \begin{cases}
        \dot{b}=\dot{c}=0, \\
        \dot{x}=b^2+4c-x, \\
        \dot{y}=x-y^2, \\
        \dot{z}=b+y-2z.
    \end{cases}\begin{array}{ll}
         b(0)=b_0,&c(0)=c_0, \\
         x(0)=x_0,&y(0)=y_{0}, \\
         z(0)=z_0.
    \end{array}
\end{equation*}
It is easy to observe that $\bar{x}=b_0^2+4c_0,~\bar{y}=\sqrt{b_0^2+4c_0}, ~\bar{z}=\frac{1}{2}\left(b_0+\sqrt{b_0^2+4c_0}\right)$. Next, construct $V(y-\bar{y})=\frac{1}{2}(y-\bar{y})^2$, which suggests
\begin{equation*}
    \begin{split}
        &\frac{\mathrm{d}V}{\mathrm{d}t} =(y-\bar{y})\left(x-y^2 \right) \\
        =&-(y+\bar{y})(y-\bar{y})^2+(x-\bar{x})(y-\bar{y}) \\
        \le &-2\bar{y}V+|y-\bar{y}||x-\bar{x}|. \\
    \end{split}
\end{equation*}
Since $y(t)$ is uniformly bounded in time when $x(t)$ are bounded (suggested by $\mathscr{C}^{\mathtt{1}}$), there is a $C>0$ such that $|y-\bar{y}|<C$. We can thus get $\frac{\mathrm{d}V}{\mathrm{d}t}\le -2\bar{y}V+C|x-\bar{x}|$. Similar to the proof in \textit{Example} \ref{ex_sqrt}, we can conclude that $\dot{y}=x-y^2$ is ISS regarding $\bar{x}$. Further, $\dot{z}=b+y-z$ is ISS regarding $(\bar{b},\bar{y})$ by \textit{Proposition} \ref{prop_simple_structure}. Then by \textit{Corollary} \ref{coro_thm1} and \textit{Corollary} \ref{coro_thmISS}, $\mathscr{C}^{\mathtt{1}}$ and $\mathscr{C}^{\mathtt{2}}$, $\mathscr{C}^{\mathtt{2}\circ \mathtt{1}}$ and $\mathscr{C}^{\mathtt{3}}$ are both dynamically composable, and $\mathscr{C}^{\mathtt{3} \circ \mathtt{2}\circ \mathtt{1}}$ serves to dynamically compute (\ref{root}).






