\section{Proofs of the Results in Section \ref{Characterization of the Value Function}}
\label{appendix_caracterization}
\subsection{Continuity Modulus}
\begin{proof}[Proof of Lemma \ref{unifcont_phi}]
Let $0\leq t\leq s\leq T$, $x\in[0,\midbar X] $, $y\geq 0$ and $X\in\mathcal{A}_t(x)$. Suppose $\xi$ is a nonnegative random variable with finite moments. We have 
\begin{equation*}
    \begin{split}
\Delta & :=  
\E\Big[\Phi_{I_s}\left(Y^{t,y,X}_s+\xi\right)-\Phi_{I_s}\left(Y^{t,y,X}_s\right)\Big]  =   \E\Big[\int_0^\xi\psi_{I_s}\left(Y^{t,y,X}_s+\zeta\right)\ud\, \zeta\Big].
\end{split}
\end{equation*}
Note that under Assumption \ref{carnetinfini}, we have that $\psi_{I_s}(y)\leq b^{\frac{1}{\beta}}y^{\frac{1}{\beta}},$ for all $y\geq F_{I_s}(a).$ As $y\mapsto\psi_{I_s}(y)$ is non-decreasing on $\RR_+$, we have
\begin{align*}
\Delta & :=  \E\Big[\int_0^{\xi}\psi_{I_s}\left(Y^{t,y,X}_s+\zeta\right)\ud\, \zeta \Big]\\
 & \leq \E\Big[\int_0^{\xi}b^{\frac{1}{\beta}}\left(F_{I_s}(a)+\zeta\right)^{\frac{1}{\beta}}\1_{\{Y^{t,y,X}_s\leq F_{I_s}(a)\}}\ud\, \zeta +\int_0^{\xi}b^{\frac{1}{\beta}}\left(Y^{t,y,X}_s+\zeta\right)^{\frac{1}{\beta}}\1_{\{Y^{t,y,X}_s> F_{I_s}(a)\}}\ud\, \zeta\Big]\\ & = \sum_{i=1}^m\frac{\beta}{1+\beta}b^{\frac{1}{\beta}}\E\Big[\1_{\{I_s = i\}}\left(F_i(a)\right)^{\frac{\beta+1}{\beta}}\1_{\{Y^{t,y,X}_s\leq F_i(a)\}}\Big(\big(1+\frac{\xi}{F_i(a)}\big)^{\frac{\beta+1}{\beta}}-1\Big)\Big]\\ 
  &\quad\quad +\sum_{i=1}^m\frac{\beta}{1+\beta}b^{\frac{1}{\beta}}\E\Big[\1_{\{I_s = i\}}\left(Y^{t,y,X}_s\right)^{\frac{\beta+1}{\beta}}\1_{\{Y^{t,y,X}_s> F_i(a)\}}\Big(\big(1+\frac{\xi}{Y^{t,y,X}_s}\big)^{\frac{\beta+1}{\beta}}-1\Big)\Big]\\
   & \leq  \sum_{i=1}^m \frac{\beta}{1+\beta}b^{\frac{1}{\beta}}\E\Big[\Big(F_i(a)^{\frac{\beta+1}{\beta}}+\underset{0\leq u\leq T}{\sup}|Y^{t,y,X}_u|^{\frac{\beta+1}{\beta}}\Big)\Big(\big(1+\frac{\xi}{F_i(a)}\big)^{\frac{\beta+1}{\beta}}-1\Big)\Big].
\end{align*}
Using Cauchy-Schwarz inequality,
\begin{equation*}
\begin{split}
\Delta & \leq  \sum_{i=1}^m \frac{\beta}{1+\beta}b^{\frac{1}{\beta}}\E\Big[\Big(F_i(a)^{\frac{\beta+1}{\beta}}+\underset{0\leq u\leq T}{\sup}|Y^{t,y,X}_u|^{\frac{\beta+1}{\beta}}\Big)^2\Big]^{\frac{1}{2}}\E\Big[\Big(\big(1+\frac{\xi}{F_i(a)}\big)^{\frac{\beta+1}{\beta}}-1\Big)^2\Big]^{\frac{1}{2}}.
\end{split}
\end{equation*}
Finally, based on Proposition \ref{existence_uniqueness_SDE}, we get that
\begin{equation*}
\begin{split}
\Delta &\leq  \sum_{i=1}^m C^y_i\E\Big[\Big(\big(1+\frac{\xi}{F_i(a)}\big)^{\frac{\beta+1}{\beta}}-1\Big)^2\Big]^{\frac{1}{2}}\\&=\rho_y(\xi),
\end{split}
\end{equation*}
where $C^y_i:= \frac{2\beta}{1+\beta}b^{\frac{1}{\beta}}\left(F_i(a)^{\frac{2(\beta+1)}{\beta}}+ C_T\big(1+|y|^{\frac{2(\beta+1)}{\beta}}\big)\right)^{\frac{1}{2}}$. This completes the proof.
\end{proof}
\section{Proofs of the Results in Section \ref{viscosity_section}}
\label{appendix_viscosity}
\subsection{Viscosity Subsolution Property}
\begin{proof}[Proof of Theorem \ref{viscosity_sub}]
\label{proof_subsolution}
     Let $z_0:=(t_0,x_0,y_0) \in\mathcal{S}$ and $i\in \I_m$. Consider a test function $\varphi \in
C^{1,2}(\mathcal{S})$ such that $z_0$ achieves a local maximum of $v_i-\varphi$ and $v_i(z_0) = \varphi(z_0)$. In other words, there exists $r_0>0$ such that 
$$v_i(z) \leq \varphi(z), \quad \forall z \in \midbar B_{r_0}(z_0).
$$
Define, for all $(j,z) \in \I_m\times\cS$,
\begin{equation*}
\Psi(z,j)=\left\{\begin{array}{ll}
\varphi(z), & \text { if } j=i, \\
v_j(z), & \text { if } j \neq i.
\end{array} \right.\end{equation*}
Observe that $v_j(t,x,y) \leq \Psi(z,j)$ holds within the neighborhood $\midbar B_{r_0}(z_0)$. Define $Z^{z_0,X}_u$ as the tuple $\big(u, X_u, Y^{t_0,y_0,X}_u\big)$ for all $u \in [0,T]$. Next, define $\tau_{r_0}$ as the first exit time of $Z^{z_0,X}$ from $\midbar B_{r_0}(z_0)$, i.e.,  
$$\tau_{r_0} = \inf \big\{ u \geq t_0 : Z^{z_0,X}_u \notin \midbar B_{r_0}(z_0) \big\}.$$ Similarly, let $\tau^I_1$ denote the first jump time of the $I$ after time $t_0$, given by  
$$\tau^I_1 = \inf \big\{ u \geq t_0 : I_u \neq i \big\}.$$ 
Furthermore, we introduce the $\cF$-stopping time $\tau_0$ such that $\tau_0 \in\big]t_0, (\tau^I_1\wedge\tau_{r_0}) \wedge T\big[$. Note that $\tau^I_1>t_0$ and that $I_{u} = i$, for all $u\in[t_0,\tau^I_1[$. Consider an admissible control $X \in \mathcal{A}_{t_0}(x_0)$ in which the agent buys $0 \leq \eta < (\bar{X} - x_0)\wedge r_0$ assets at time $t_0$ and then remains inactive until time $(t_0 + \varepsilon) \wedge \tau_0$, where $\varepsilon>0$. Using the DPP introduced in Proposition \ref{prog_dyn}, we have
\begin{equation} \begin{split}
  \Psi(z_0,i) &= \varphi(z_0)\\ &\leq
  \E
  \Big[\Phi_{I_{(t_0+\eps)\wedge \tau_0}}(y_0+\eta)-\Phi_{I_{(t_0+\eps)\wedge \tau_0^-}}(y_0)+ v((t_0+\eps)\wedge \tau_0, x_0+\eta,{Y}^{t_0,y_0,X}_{(t_0+\eps)\wedge \tau_0},I_{(t_0+\eps)\wedge \tau_0}) \Big]\\
  &\leq \E
\Big[\Phi_{i}(y_0+\eta)-\Phi_{i}(y_0)+ \Psi((t_0+\eps)\wedge \tau_0, x_0+\eta, {Y}^{t_0,y_0,X}_{(t_0+\eps)\wedge \tau_0}, i) \Big].
\label{proofvis2}
\end{split} \end{equation}
 Applying It\^o's formula and taking the expectation over the interval 
$[t_0, (t_0+\varepsilon) \wedge \tau_0]$, while noting that 
$\mathbb{E} \big[\Psi(Z^{z_0,X}_{t_0}, I_{t_0})\big] = \mathbb{E} \big[\varphi(Z^{z_0,X}_{t_0})\big]$, we obtain
 \begin{equation} \begin{split}
  \E \Big[\Psi(Z^{z_0,X}_{(t_0+\eps)\wedge \tau_0}, I_{(t_0+\eps)\wedge \tau_0})\Big] &=
  \varphi(t_0,x_0+\eta,y_0+\eta) \\
  &\quad + \E \Big[\int_{t_0}^{(t_0+\eps)\wedge \tau_0} \big(
  \frac{\partial \varphi}{\partial t}+\Lc
  \varphi\big)(u,x_0+\eta,Y_{u}^{t_0,y_0,X}) \ud u \Big]\\
  &\quad + \E \Big[\int_{t_0}^{(t_0+\eps)\wedge \tau_0} \sum_{j\neq i}Q_{ij}(u)\big(v_j-\varphi\big)(u, x_0+\eta,Y_{u}^{t_0,y_0,X}) \ud u \Big].
  \label{proofvis3}
\end{split} \end{equation}
In the last equality, the martingale expectation vanishes since 
$\varphi(Z^{z_0,X}_u)$ and $D\varphi(Z^{z_0,X}_u)$ are bounded, given that $Z^{z_0,X}_u \in \midbar B_{r_0}(z_0)$ for all $u \in [t_0, (t_0+\varepsilon) \wedge \tau_0]$. For all $u \in [t_0, (t_0+\varepsilon) \wedge \tau_0]$, since $Z^{z_0,X}_u$ remains in $\midbar B_{r_0}(z_0)$, we obtain that 
$v_i(Z^{z_0,X}_u) \leq \varphi(Z^{z_0,X}_u)$. Combining this with relations \eqref{proofvis2} and
\eqref{proofvis3} yields
\begin{equation} \begin{split}
  \E \Big[\int_{t_0}^{(t_0+\eps)\wedge \tau_0}
  \big(\frac{\partial \varphi}{\partial t}+\Lc
  \varphi\big)(u,x_0+&\eta,Y_{u^-}^{t_0,y_0,X})+\sum_{j\neq i}Q_{ij}(u)\big(v_j-\varphi\big)(u,x_0+\eta,Y_{u^-}^{t_0,y_0,X}) \ud u \Big] \\& \geq
  \varphi(z_0)-\varphi(t_0,x_0+\eta,y_0+\eta) - \Phi_i(y_0+\eta)+\Phi_i(y_0).  \label{proofvis4}
\end{split} \end{equation}
Assume that the agent decides to do nothing, meaning $\eta = 0$. We know from Theorem \ref{continuous_v} that $v_j$ is continuous on $\midbar \cS$, for all $j\in \I_m$. Additionally, $Q$ is continuous on $\R_+$. Dividing inequality \eqref{proofvis4} by $\eps$ and letting $\eps$ going to $0$ and recalling that $\varphi(z_0) = v_i(z_0)$, we get that
\begin{equation*}
 \big(\frac{\partial \varphi}{\partial t}+\Lc \varphi+\sum_{j\neq i}Q_{ij}(v_j-v_i)\big) (z_0)\geq 0.
\end{equation*}
Assume now that the agent executes a part $\eta > 0$ of the position at time $t_0$. By sending $\varepsilon$ to $0$, we get
$$
0\geq-\varphi(t_0,x_0+\eta,y_0+\eta)+\varphi(t_0,x_0,y_0)- \Phi_i(y_0+\eta)+\Phi_i(y_0).$$
It follows from equation \eqref{definitionPhi} that
\begin{equation*}
 \int_0^\eta \frac{\partial \varphi}{\partial x}(t_0,x_0+v,y_0+\eta)\ud v+\int_0^\eta\frac{\partial
\varphi}{\partial y}(t_0,x_0,y_0+v)\, \ud v+\int_{y_0}^{y_0+\eta}\psi_i(\xi)\,
\ud \xi\geq 0.
\end{equation*}
The function $\psi_i$ is left-continuous and non-decreasing on $\R_+$. Dividing by $\eta$ and letting $\eta
\rightarrow 0$, we obtain
\begin{equation*}
\big(\frac{\partial \varphi}{\partial x}+\frac{\partial \varphi}{\partial
y}+\psi_i\big)(z_0)\geq 0.
\end{equation*}
This proves the required subsolution property
\begin{equation*}
 \max\Big(-\big(\frac{\partial
  \varphi}{\partial t}+\mathcal{L}\varphi+\sum_{j\neq i}Q_{ij}(v_j-v_i)\big)(z_0) ,\ -\big(\frac{\partial
  \varphi}{\partial x}+\frac{\partial \varphi}{\partial y}+\psi_i\big)(z_0)\Big)\leq 0.
\end{equation*}
\end{proof}
\subsection{Viscosity Supersolution Property}
\begin{proof}[Proof of Theorem \ref{viscosity_super}] 
\label{proof_supersolution}
Suppose that $v$ does not satisfy the supersolution property. Then, there exists $i_0\in \I_m$, $z_0:=(t_0,x_0,y_0) \in\mathcal{S}$, a test function $\bar\varphi \in
C^{1,2}(\mathcal{S})$ such that $z_0$ achieves a local minimum of $v_{i_0}-\bar\varphi$ and $v_{i_0}(z_0) = \bar\varphi(z_0)$, and $\eta>0$ such that
\begin{equation*}
-\big(\frac{\partial \bar\varphi}{\partial t}+\mathcal{L} \bar\varphi+\sum_{j\neq {i_0}}(v_j-v_{i_0})Q_{i_0j}\big)(z_0) < -\eta,~~\text{and}~~
-\big(\frac{\partial \bar\varphi}{\partial x}+\frac{\partial \bar\varphi}{\partial
y}+\psi_{i_0}\big)(z_0)<-\eta.
\end{equation*}
Since $z_0$ achieves a local minimum of $v_{i_0}-\bar\varphi$, there exists $r_0>0$ such that 
$$v_{i_0}(z) \geq \bar\varphi(z), \quad \forall z \in\midbar B_{r_0}(z_0).
$$
By Theorem \ref{continuous_v}, the value functions $(v_j)_{j\in \I_m}$ are continuous on $\bar{\cS}$. Moreover, the test function $\bar\varphi$ belongs to $C^{1,2}(\mathcal{S})$, and each $\psi_{i_0}$ is non-decreasing and left-continuous. Consequently, there exists $r_1>0$ such that $t_0+r_1<T$ and for all $z:=(t,x,y)\in\midbar{B}_{r_1}(z_0)$, 
\begin{equation}
  \label{proofvis5} - \big(\frac{\partial \bar\varphi}{\partial t}+\Lc\bar\varphi+\sum_{j\neq i_0}(v_j-v_{i_0})Q_{i_0j}\big)(z) < -\eta,~~\text{and}~~
-\big(\frac{\partial \bar\varphi}{\partial x}+\frac{\partial \bar\varphi}{\partial
y}+\psi_{i_0}\big)(z) < -\eta,
\end{equation}
where
$\midbar B_{r_1}(z_0):= \{ z \in \cS : \|z - z_0\| \leq r_1 \}$. Define, for all $(j,z) \in \I_m\times \cS$,
\begin{equation*}
\Psi(z,j)=\left\{\begin{array}{ll}
\bar\varphi(z), & \text { if } j=i_0, \\
v_j(z), & \text { if } j \neq i_0.
\end{array} \right.\end{equation*}
Let $X$ and admissible strategy in $\cA_{t_0}(x_0)$ and $Z^{z,X}_u$ represent the tuple $\big(u, X_u, Y^{t,y,X}_u\big)$ for all $(u,z)\in[0,T]\times \cS$. Additionally, set the radius $\eps_0$ as $\eps_0:=r_0\wedge r_1$. Define $\tau_B$ as the first exit time of $Z^{z_0,X}$ from $\midbar{B}_{\eps_0}(z_0)$, i.e.,  
$$\tau_{B} = \inf \big\{u \geq t_0:
Z^{z,X}_u \notin \midbar{B}_{r_0}(z_0)\cap \midbar B_{r_1}(z_0)\big\}$$ for any admissible control $X\in\mathcal{A}_{t_0}(x_0)$. Let $\tau^I_1$ be the first jump time after time $t_0$ of the Markov chain $I$ such that $$\tau^I_1=\inf \big\{u \geq t_0: I_u \neq i_0\big\}.$$ Next, we introduce the $\cF$-stopping time $\tau_1$ such that $\tau_1:=\tau^I_1\wedge\tau_B$. Note that $\tau_B<T$, $t_0<\tau^I_1$ and that $I_{u} = i_0$, for all $u\in[0,\tau^I_1[$. Applying  It{\^o}'s formula between $t_0$ and
$\tau_1^-$, we obtain \begin{equation}
\begin{split}
\E\Big[\Psi(Z^{z_0,X}_{\tau_1^-},I_{\tau_1^-}) \Big] &=
\bar\varphi(z_0)
+ \E \Big[\int_0^{\tau_1^-}\big(\frac{\partial
  \bar\varphi}{\partial x}+\frac{\partial \bar\varphi}{\partial
  y}\big)(Z^{z_0,X}_{u^-})\, \ud X^c_u \Big] \\
    & \quad+ \E \Big[\int_{t_0}^{\tau_1^-} \big(\frac{\partial \bar\varphi}{\partial t} +\Lc
\bar\varphi+\sum_{j\neq i}(v_j-\bar\varphi)Q_{i_0j}\big) (Z^{z_0,X}_{u^-}) \ud u \Big]\\
  &\quad + \E \Big[ \sum_{t_0\leq u < \tau_1}
  \bar\varphi(u,X_u,Y_u^{t_0,y_0,X}) -\bar\varphi(u,X_{u^-},\check{Y}_{u^-}^{t_0,y_0,X})\Big]. \label{proofvis8}
  \end{split}
  \end{equation}  
In the last equality, the martingale expectation vanishes since 
$\varphi(Z^{z_0,X}_u)$ and $D\varphi(Z^{z_0,X}_u)$ are bounded, given that $Z^{z_0,X}_u \in \midbar B_{\eps_0}(z_0)$ for all $u \in [t_0,\tau_1[$. From \eqref{proofvis5} the fact that 
$\Delta X_u := X_u - X_{u^-} = Y_{u}^{t_0,y_0,X} - \check{Y}_{u^-}^{t_0,y_0,X}$ 
for all $t_0 \leq u < \tau_1$, we deduce that
\begin{equation}
\label{proofvis55}
\begin{split}
\bar\varphi(u,X_u,Y_u^{t_0,y_0,X}) -
\bar\varphi(u,X_{u^-},\check{Y}_{u^-}^{t_0,y_0,X}) & =  \int_0^{\Delta X_u} \big(\frac{\partial \bar\varphi}{\partial x}+\frac{\partial
\bar\varphi}{\partial y}\big)(u,X_{u^-}+v,\check{Y}_{u^-}^{t_0,y_0,X}+v)\, \ud v\\
& \geq \eta\Delta X_u-\int_0^{\Delta X_u}\psi_{i_0}(\check{Y}_{u^-}^{t_0,y_0,X}+\zeta)\,
\ud\zeta\\ & = \eta\Delta
X_u-\Phi_{i_0}(Y^{t_0,y_0,X}_u)+\Phi_{i_0}(\check{Y}_{u^-}^{t_0,y_0,X}).
    \end{split}
  \end{equation}
Note that $\E\Big[\Psi(Z^{z_0,X}_{\tau_1^-},I_{\tau_1^-}) \Big] = \E\Big[\bar\varphi(Z_{\tau_1^-}^{z_0,X}) \Big]$. Plugging \eqref{proofvis5} and \eqref{proofvis55} in equation
\eqref{proofvis8}, we obtain
\begin{equation*}
\begin{split}
\E\Big[\bar\varphi(Z_{\tau_1^-}^{z_0,X}) \Big]
& \geq  \bar\varphi(z_0)
  + \eta\E \Big[\tau_1-t_0 +  \int_{t_0}^{\tau_1^-}\ud X_u\Big] -\E\Big[\int_{t_0}^{\tau_1^-}\psi_{i_0}(\check{Y}_{u^-}^{t_0,y_0,X})\ud X^c_u\Big]\\ & \quad-\E \Big[\sum_{t_0\leq u < \tau_1}
  \Phi_{i_0}(Y_u^{t_0,y_0,X}) -
  \Phi_{i_0}(\check{Y}_{u^-}^{t_0,y_0,X}) \Big].
\end{split}
  \end{equation*}
Therefore, we obtain
\begin{equation}
\begin{split}
  v_{i_0}(z_0) = \bar\varphi(z_0) &\leq \E\Big[\int_{t_0}^{\tau_1^-} \psi_{i_0}(\check{Y}_{u^-}^{t_0,y_0,X}) \ud X^c_u
+\bar\varphi(Z_{\tau_1^-}^{z_0,X}) \Big]
 \\& \quad+\E\Big[ \sum_{t_0\leq u < \tau_1}
  \Phi_{i_0}(Y_u^{t_0,y_0,X}) -
  \Phi_{i_0}(\check{Y}_{u^-}^{t_0,y_0,X}) - \eta \big( \int_{t_0}^{\tau_1^-}\ud u + \int_{t_0}^{\tau_1^-}\ud X_u\big)\Big].
    \label{proofvis11}
 \end{split}
  \end{equation}
Define the set $$\cD^{\eps_0} := \Big\{\omega\in \Omega:\tau_B(\omega)<\tau^I_1(\omega)~\text{and}~\check{Y}_{\tau_1^-}^{t_0,y_0,X}(\omega)\in[y_0-\varepsilon_0,
y_0+\varepsilon_0] \Big\},$$ 
and the $\cF_{\tau_1}$-random variable,
$$Z^{(\gamma)}_{\tau_1} :=
\big(\tau_1,\check{Y}_{\tau_1^-}^{t_0,y_0,X}+\gamma\Delta
X_{\tau_1},X_{\tau_1^-}+\gamma\Delta
X_{\tau_1}\big).$$
We know that if $\tau_1=\tau_B$ and $\check{Y}_{\tau_1^-}^{t_0,y_0,X} \in [y_0-\varepsilon_0,y_0+\varepsilon_0]$, then $Z^{z_0,X}_{\tau_1}$ either lies on the boundary $\partial\bar{B}_{\eps_0}(z_0)$ or has exited $\bar{B}_{\eps_0}(z_0)$ at time $\tau_1$. Since $\check{Y}_{\tau_1^-}^{t_0,y_0,X}$ accounts for the jumps of $M$, only the jumps in the inventory process $X$ can cause $Z^{z_0,X}$ to cross the boundary at $\tau_1$. Consequently, there exists an $\cF_{\tau_1}$-measurable random variable $\gamma \in [0,1]$ such that
$$
\check{Y}_{\tau_1^-}^{t_0,y_0,X} +\gamma\Delta
X_{\tau_1}\in\big\{y_0-\varepsilon_0,y_0+\varepsilon_0\big\},~~\text{and}~~Z^{(\gamma)}_{\tau_1} \in\midbar{B}_{\eps_0}(z_0),$$
on the set $\cD^{\eps_0}$. It follows from the DPP (see Lemma \ref{prog_dyn}), that
$$
v_{i_0}({Z}^{(\gamma)}_{\tau_1}(\omega)) \leq v_{i_0}(Z^{z_0,X}_{\tau^-_1}(\omega))
+\Phi_{i_0}({Y}^{t_0,y_0,X}_{\tau_1}(\omega))-\Phi_{i_0}(\check{Y}^{t_0,y_0,X}_{\tau_1^-}(\omega)+\gamma \Delta
X_{\tau_1}(\omega)),\quad \forall \omega\in\cD^{\eps_0}.$$
Additionally, given that $Z^{(\gamma)}_{\tau_1}\in\midbar{B}_{\eps_0}(z_0)$, it follows that, for all $\omega\in\cD^{\epsilon_0}$,
\begin{equation*}
\resizebox{\textwidth}{!}{$
\begin{aligned}
\bar\varphi(Z^{z_0,X}_{\tau_1^-}(\omega)) & =
\bar\varphi(Z^{(\gamma)}_{\tau_1}(\omega))-\int_0^{\gamma(\omega)\Delta X_{\tau_1}(\omega)}\big(\frac{\partial
  \bar\varphi}{\partial x}+\frac{\partial \bar\varphi}{\partial
  y}\big)(t,X_{\tau_1^-}(\omega) + v ,\check{Y}_{\tau_1^-}^{t_0,y_0,X}(\omega)+v)\, \ud v\\
& \leq \bar\varphi(Z^{(\gamma)}_{\tau_1}(\omega))-\eta\gamma(\omega)\Delta
X_{\tau_1}(\omega)+\Phi_{i_0}(\check{Y}^{t_0,y_0,X}_{\tau_1^-}(\omega)+\gamma(\omega) \Delta
X_{\tau_1}(\omega))-\Phi_{i_0}(\check{Y}^{t_0,y_0,X}_{\tau_1^-}(\omega))\\
& \leq v_{i_0}(Z^{z_0,X}_{\tau_1^-}(\omega))-\eta\gamma(\omega)\Delta
X_{\tau_1}(\omega)+\Phi_{i_0}({Y}^{t_0,y_0,X}_{\tau_1}(\omega))-\Phi_{i_0}(\check{Y}^{t_0,y_0,X}_{\tau_1^-}(\omega)).
\end{aligned}
$}
\end{equation*}
Plugging the last inequality in \eqref{proofvis11}, we obtain
\begin{equation*} \begin{split}
v_{i_0}(z_0) & \leq \E \Big[ \sum_{t_0\leq u \leq \tau_1}
  \Phi_{i_0}(Y_u^{t_0,y_0,X}) -
  \Phi_{i_0}(Y_{u^-}^{t_0,y_0,X}) +\int_{t_0}^{\tau_1 } \psi_{i_0}(\check{Y}_{u^-}^{t_0,y_0,X})
\ud X^c_u +
   v_{i_0}(Z^{z_0,X}_{\tau_1}) \Big]  \\
& \quad - \eta \E \Big[ \int_{t_0}^{\tau_1 ^-}\ud u + \int_{t_0}^{\tau_1
^-}\ud X_u+\gamma\Delta X_{\tau_1}\1_{\{\check{Y}_{\tau_1^-}^{t_0,y_0,X}\in[ 
y_0-\varepsilon_0, y_0+\varepsilon_0] \}}\1_{\{\tau_B<\tau^I_1\}}\Big].
 \end{split} \end{equation*}
From the DPP, it follows that
$$
0 \leq -\inf_{X\in\mathcal{A}_{t_0}(x_0)}\E \Big[\tau_1 -t_0 + X_{\tau_1
^-} - x_0+\gamma\Delta
X_{\tau_1}\1_{\{\check{Y}_{\tau_1^-}^{t_0,y_0,X}\in[  y_0-\varepsilon_0,
y_0+\varepsilon_0] \}}\1_{\{\tau_B<\tau^I_1\}}\Big].$$
Using the sequential characterization of the supremum, we can find a sequence of admissible controls $X^n = (X^n)_{n\geq 0}$ such that
$$\E \Big[ \tau^n_1 -t_0+ X^n_{\tau^{n^-}_1}-x_0+\gamma\Delta
X^n_{\tau^n_1}\1_{\{\check{Y}_{{\tau_1^n}^-}^{t_0,y_0,X^n}\in[ 
y_0-\varepsilon, y_0+\varepsilon] \}}\1_{\{\tau^n_B<\tau^I_1\}}\Big]\leq \frac{1}{n},$$
where $\tau^n_B:=\inf \big\{t \geq t_0:
(t,X^n_t,Y_t^{t_0,y_0,X^n}) \notin \midbar{B}_{\eps_0}(z_0) \big\}$ and $\tau_1^n:=\tau_B^n\wedge \tau^I_1$. As $\tau^n_1-t_0\geq
0$ and $X^n_{\tau^{n^-}_1}-x_0\geq 0$, we have that
$$\max\Big\{\E\big[ \tau^n_1 -t_0\big],\ \E \big[X^n_{\tau^{n^-}_1}-x_0\big],\ \E \Big[\gamma\Delta
X^n_{\tau^n_1}\1_{\{\check{Y}_{{\tau_1^n}^-}^{t_0,y_0,X^n}\in[ 
y_0-\varepsilon, y_0+\varepsilon] \}}\1_{\{\tau^n_B<\tau^I_1\}}\Big]\Big\}\leq \frac{1}{n}.$$
Moreover, $\gamma\Delta X^n_{\tau^n_1} = y_0 + \eps_0 - \check{Y}_{{\tau_1^n}^-}^{t_0,y_0,X^n} \geq y_0 + \eps_0-y_0 = \eps_0$. Therefore,
\begin{equation}
\label{proofsuper1}
\begin{split}
\frac{1}{n}&\geq\eps_0\P\big(y_0-\varepsilon_0\leq \check{Y}_{{\tau_1^n}^-}^{t_0,y_0,X^n}\leq y_0+\eps_0\ ,\ \tau^n_B<\tau^I_1\big)\\&\geq \eps_0\Big(\P\big(y_0-\varepsilon_0\leq \check{Y}_{{\tau_1^n}^-}^{t_0,y_0,X^n}\leq y_0+\eps_0\big) +\P\big(\tau^n_B<\tau^I_1\big)-1\Big).
\end{split}
\end{equation}
On the other hand, we have
$$\lim_{n\to +\infty}\P(\tau^{n}_1=t_0) = 1,~~\textrm{and}~~\lim_{n\to
+\infty}\P(X^n_{\tau^{n^-}_1}=x_0) = 1.$$
Therefore, \begin{equation*}
\resizebox{\textwidth}{!}{$
\begin{aligned}\lim_{n\to +\infty}\P(\tau^{n}_B=t_0) = 1, ~~\lim_{n\to +\infty}\P\big(\check{Y}_{{\tau_1^n}^-}^{t_0,y_0,X^n}=y_0\big)=1~~ \text{and}~~
\lim_{n\to +\infty}\P\big(y_0-\varepsilon_0\leq\check{Y}_{{\tau_1^n}^-}^{t_0,y_0,X^n}\leq y_0+\eps_0\big)=1.\end{aligned}
$}
\end{equation*} Since $\lim_{n\to +\infty}\P\big(\tau_B^n<\tau^I_1\big) = \P\big(t_0<\tau^I_1\big) = \exp \big(-\int_{t_0}^{t_0} Q_{ii}(u) \, \ud u \big) = 1,$ we get from inequality \eqref{proofsuper1} when $n$ goes to $+\infty$ that
\begin{equation*}
\begin{split}
0 \geq \eps_0\Big(1+\lim_{n\rightarrow\+\infty}\P\big(\tau_B^n<\tau^I_1\big)-1\Big)=\eps_0>0.
\end{split}
\end{equation*}
This leads to a contradiction. Therefore, we obtain the required
viscosity supersolution property.
\end{proof}

