\begin{equation} \label{eq:nw functional}
\begin{split}
    \hat{I}_{S}[\epsilon] = \text{Re} \int_S \left\{ \lambda_1 \Big[\bar{\ethmmbar} \bar{\lambda}_{0^{'}} + \rho \bar{\lambda}_{1^{'}} + (K + \sqrt{2}\bar{\phi}_{0^{'}1^{'}})\mu_0\Big] - \lambda_0 \Big[\bar{\ethmm}\bar{\lambda}_{1^{'}} + \rho{'} \bar{\lambda}_{0^{'}} + (-K + \sqrt{2}\bar{\phi}_{0^{'}1^{'}})\mu_1\Big] \right. + \\ \left.
    \mu_1 \Big[\ethmm \bar{\mu}_{0^{'}} + \rho \bar{\mu}_{1^{'}} + (K - \sqrt{2}\bar{\phi}_{0^{'}1^{'}})\lambda_0 \Big] - \mu_0 \Big[\ethmmbar\bar{\mu}_{1^{'}} + \rho{'} \bar{\mu}_{0^{'}} + (-K - \sqrt{2}\bar{\phi}_{0^{'}1^{'}})\lambda_1 \Big] \right\}.
\end{split}
\end{equation}
Following \cite{reall2025lawblackholemechanics}, we now state and prove a series of simple lemmas regarding the Nester-Witten functional.
\begin{lemma}\label{lemma:zero on susy surface}
    If $S$ is supersymmetric with spinor field $\epsilon$ then $\hat{I}_{S}[\epsilon] =0$.
\end{lemma}
\begin{proof}
    If $S$ is supersymmetric with spinor $\epsilon$, then the pull-back of $\hat{\Lambda}(\epsilon)$ to $S$ is zero by the definition of supersymmetry of $S$.
\end{proof}
\begin{lemma}\label{lemma:equiv to 2.3}
    If $\epsilon$ satisfies (\ref{eq:holomorph a}) on $S$ then 
    \begin{equation}\label{eq:nw functional when m-bar susy condition holds}
        \hat{I}_S[\epsilon] = \int_S \left[ \rho{'}\left(|\lambda_0|^2 + |\mu_0|^2 \right) + \rho \left(|\lambda_1|^2 + |\mu_1|^2 \right)\right]. 
    \end{equation}
\end{lemma}
\begin{proof}
    Given equation (\ref{eq:holomorph a}) is satisfied by $\epsilon$, both the second and fourth terms on the RHS of equation \eqref{eq:nw functional} are set to zero. 
    Then, integrating by parts using the identity (\ref{eq:integration by parts for gauge covariant eth}), one can again use equation (\ref{eq:holomorph a}) to eliminate the remaining terms involving gauge covariant derivatives. 
    All terms involving $\bar{\phi}_{0^{'}1^{'}}$ and $K$ are imaginary and so drop out when we take the real part, resulting in the above equation.
\end{proof}
\begin{lemma} \label{lemma:equiv to 2.4}
    A supersymmetric surface is not trapped.
\end{lemma}
\begin{proof}
    By definition, a trapped surface has $\rho>0$ and $\rho{'}>0$.
    Assume that $S$ is both supersymmetric and trapped.
    By supersymmetry of $S$ (of which equation (\ref{eq:holomorph a}) is a condition), Lemma \ref{lemma:zero on susy surface} tells us that the LHS of equation (\ref{eq:nw functional when m-bar susy condition holds}) is zero. 
    Since the RHS is non-negative for $S$ trapped, we see that $\epsilon$ must be identically zero on $S$ for equality.
    However, by the definition of $S$ being supersymmetric, $\epsilon$ cannot be identically zero and therefore we have a contradiction.
\end{proof}

If $S$ is marginally outer trapped and the ingoing null geodesics normal to $S$ are strictly converging then we have
\begin{lemma} \label{lemma: equiv to 2.5}
    If $S$ is supersymmetric with $\rho{'}>0$ and $\rho \equiv 0$, then $V \equiv 0$ on $S$ and $X^a$ is an outgoing null normal to $S$.
\end{lemma}
\begin{proof}
    Lemmas \ref{lemma:zero on susy surface} and \ref{lemma:equiv to 2.3} imply $\mu_0 = \lambda_ 0 \equiv 0$ on $S$, i.e., $\mu_A,\lambda_A \propto o_A$ on $S$, hence $V \equiv 0$ and $X^a \propto l^a$.
\end{proof}

\subsection{Non-negativity of the Nester-Witten functional}

Following \cite{reall2025lawblackholemechanics}, we prove the following rigidity result for a compact surface $\Sigma$ whose boundary is supersymmetric:
\begin{theorem} \label{thm:equiv to 2.6}
    Let $\Sigma$ be any smooth, compact, connected, spacelike 3-surface such that matter satisfies the local mass-charge inequality (\ref{eq:local mass-charge inequality}) on $\Sigma$.
    Assume that $\Sigma$ has boundary $\partial \Sigma = S$, where $S$ is a compact, connected 2-surface.
    Assume that the future-directed ingoing null geodesics normal to $S$ are strictly converging on $S$ - i.e. $\rho{'}>0$ on $S$. Let $\epsilon$ be a non-zero solution to (\ref{eq:holomorph a}) on $S$. 
    Then, $\hat{I}_S [\epsilon] \geq 0$ with equality if, and only if, (i) $S$ is supersymmetric with spinor $\epsilon$, (ii) $\epsilon$ extends to a spinor on $\Sigma$ satisfying $h^{b}{_a}\hat{\nabla}_b \epsilon = 0$ where $h^{b}{_a}$ is the projection onto $\Sigma$ and (iii) on $\Sigma$ the charged matter satisfies
    \begin{equation}\label{eq:equiv to eqn 19 in 1.5}
        N^a\Big( T_{ab}^{(m)} X^b - \text{Re}(V)J_a\Big) = 0,
    \end{equation}
    where $N^a$ is a normal to $\Sigma$.
\end{theorem}
\begin{proof}
    We begin by considering a spinor field, $\tilde{\epsilon}$, on $\Sigma$ satisfying the following boundary conditions:
        \begin{equation} \label{eq: boundary conditions on S in 1.5}
            \bar{\tilde{\lambda}}_{1^{'}} = \bar{\lambda}_{1^{'}} \text{ and } \bar{\tilde{\mu}}_{1^{'}} = \bar{\mu}_{1^{'}} \text{ on }\; S.
        \end{equation}
    As in \cite{douganquasi,reall2025lawblackholemechanics} (see also \cite{Rogatko_2002}), after imposing equation (\ref{eq:holomorph a}) on $\epsilon$, we can relate the integrals of the Nester-Witten two-forms of $\epsilon$ and $\tilde{\epsilon}$:
    \begin{equation} \label{eq: equiv to 21 in 1.5}
        \hat{I}_S[\epsilon] = \hat{I}_S[\tilde{\epsilon}] + \int_S \rho{'}\Big(|\tilde{\lambda}_0 - \lambda_0|^2 + |\tilde{\mu}_0 - \mu_0|^2 \Big).
    \end{equation}
    The ingoing null geodesics on $S$ are strictly converging so $\rho{'}>0$ on $S$, hence the non-negativity of $\hat{I}_{S}[\epsilon]$ follows from non-negativity of $\hat{I}_{S}[\tilde{\epsilon}]$.
    To establish the latter, we use Stokes' theorem to obtain $\hat{I}_{S}[\tilde{\epsilon}] = \int_\Sigma d\hat{\Lambda}(\tilde{\epsilon})$. In Appendix \ref{appendix:supercovariant sparling-like identity}, we show, by methods similar to that of \cite{gibbons1982bogomolny, ghhp,witten1981new}, that the RHS can be rearranged as follows:
    \begin{equation}
    \label{eq:sw_id}
    \hat{I}_S[\tilde\epsilon] = \int_\Sigma d\hat\Lambda(\tilde\epsilon) = \int_\Sigma  \Big\{ 8\pi N^a\big(T^{(m)}_{ab}X^b + J_a \text{Re}(V) \big) - 2 h^{ij}(\hat{\nabla}_i\tilde\epsilon)^{\dagger}(\hat{\nabla}_j\tilde\epsilon) - (\gamma^i\hat{\nabla}_i\tilde\epsilon)^{\dagger}(\gamma^j\hat{\nabla}_j\tilde\epsilon)\Big\}.
    \end{equation}
    Here indices $i,j$ refer to spatial basis vectors tangent to $\Sigma$.
    If the local mass-charge inequality holds on $\Sigma$, then all terms but the final term are non-negative (the induced metric $h_{ij}$ is negative-definite).
    The final term is non-positive.
    We now impose the gauge-supercovariant Sen-Witten equation on $\tilde\epsilon$ on $\Sigma$, i.e.
    \begin{equation}\label{eq:gauge-supercovariant sw}
        \gamma^i \hat{\nabla}_i \tilde\epsilon = \gamma^a h{_a}{^b}\hat{\nabla}_b \tilde\epsilon = 0,
    \end{equation}
    subject to boundary conditions (\ref{eq: boundary conditions on S in 1.5}), to obtain
    \begin{equation}\label{eq:non-negativity of nw functional on sw spinors}
        \hat{I}_S[\tilde\epsilon] = \int_\Sigma  \Big\{ 8\pi N^a\big(T^{(m)}_{ab}X^b + J_a \text{Re}(V) \big) - 2 h^{ij}(\hat{\nabla}_i\tilde\epsilon)^{\dagger}(\hat{\nabla}_j\tilde\epsilon)\Big\},
    \end{equation}
    This, therefore, proves the statement $\hat{I}_{S}[\epsilon] \geq 0$. Justification for the existence of a solution to \eqref{eq:gauge-supercovariant sw} with boundary conditions \eqref{eq: boundary conditions on S in 1.5} is given in Appendix A of \cite{reall2025lawblackholemechanics} for the case $\Lambda = 0$ and generalised in Appendix \ref{sec:existence} of this paper.

    If $\hat{I}_{S}[\epsilon] =0$ then from equation (\ref{eq: equiv to 21 in 1.5}) we see that as both terms are individually non-negative, they must individually be zero.
    The second term implies that $\epsilon = \tilde{\epsilon}$ on $S$ and hence $\tilde{\epsilon}$ is an extension of $\epsilon$ and we drop the tilde.
    The vanishing of the first term implies the vanishing of \eqref{eq:non-negativity of nw functional on sw spinors}, which is a sum of non-negative terms and therefore each vanishes individually.
    The second term vanishes iff $h^a{_b} \hat{\nabla}_a\epsilon = 0$ on $\Sigma$ (which implies that $S$ is supersymmetric), while the first vanishes iff equation (\ref{eq:equiv to eqn 19 in 1.5}) holds in $\Sigma$. 
    This shows that $\hat{I}_{S}[\epsilon] = 0$ implies (i), (ii) and (iii).
    Conversely, if (i), (ii) and (iii) hold then the above implies that $\hat{I}_S[\epsilon] = 0$.
\end{proof}

An immediate corollary of this result is \cite{reall2025lawblackholemechanics}
\begin{corollary}\label{corollary:equiv to 2.6.1}
    If $\Sigma$ and $S$ satisfy the assumptions of Theorem \ref{thm:equiv to 2.6} and $S$ is supersymmetric, then every smooth 2-surface contained in $\Sigma$ is also supersymmetric and hence, by Lemma \ref{lemma:equiv to 2.4}, not trapped.
\end{corollary}
\begin{proof}
    Since $S$ is supersymmetric (with spinor $\epsilon)$, this implies (by lemma \ref{lemma:zero on susy surface}) that $\hat{I}_S[\epsilon] = 0$.
    Therefore, by the above theorem, $\epsilon$ extends to a spinor such that $h^a{_b}\hat{\nabla}_a \epsilon = 0$ on $\Sigma$ and so $\epsilon$ is supercovariantly constant on any spacelike 2-surface within $\Sigma$.
    Since, $\epsilon$ is nowhere zero on $\Sigma$ (as if it were then $\epsilon$ would have to vanish everywhere on $\Sigma$) and is supercovariantly constant on any spacelike 2-surface in $\Sigma$, every spacelike 2-surface within $\Sigma$ is supersymmetric with spinor $\epsilon$.
\end{proof}

