We recall that we say that an o.s. $X$ locally embeds in another one $C$ if for any $\vp>0$ and any f.d. subspace $E\subset X$
there is a subspace $F\subset C$ and an isomorphism 
$w: E \to F$ such that $\|w\|_{cb}\|w^{-1}\|_{cb} \le 1+\vp$. Moreover
we set
$$d_{cb}(E,F)=\inf \{\|w\|_{cb}\|w^{-1}\|_{cb} \}$$
where the infimum runs over all possible such $w$.\\
More generally, we say that $X$ locally embeds in a sequence $\{C_n\}$ of $C^*$-algebras
if for any $\vp>0$ and for any $E$  there is for  some $n$  a subspace $F\subset C_n$ 
such that $d_{cb}(E,F)\le 1+\vp$.

We will   need to discuss some additional properties:
\begin{equation}\label{ech50}   \| {T_n  
}     \|_{cb} \le  1+\vp_n.
\end{equation}
and hence
\begin{equation}\label{ech50'}   \| {T_{[k,n]} } 
     \|_{cb} \le  \prod\nl_{n\le j\le k} (1+\vp_j) \le 1+\eta_n.
\end{equation}
We will also need 
\begin{equation}\label{ech5}   \| {T_n^{-1}}_{| {T_n(E_{n-1} )}
}     \|_{cb} \le  1+\vp_n.
\end{equation}
and hence
\begin{equation}\label{ech5'}   \| {T_{[k,n]}^{-1}}_{| { T_{[k,n]}(E_{n-1} ) }
}     \|_{cb} \le  \prod\nl_{n\le j\le k} (1+\vp_j) \le 1+\eta_n.
\end{equation}

   \begin{pro}\label{pch10}
  Assume  
that the   inductive system satisfies \eqref{ech50} and \eqref{ech5},
 then $A$ locally embeds in $\{C_n\}$. In fact for all $n\ge 0$
 \begin{equation}\label{echy5}
 d_{cb} (E_n,A_n)\le (1+\eta_{n+1})^2.
 \end{equation}
\end{pro}
\begin{proof}
By perturbation it clearly suffices to show that
$A_n$ locally embeds in $C$ for all $n$. Fix $n$.
Recall that $Q: L \to \cl L$ denotes the quotient map.
Consider the map $\t_n : E_n \to L$
and let $\alpha_n = Q\t_n : E_n \to A_n$.
We have
$\|  \alpha_n\|_{cb} \le \| \t_n\|_{cb} \le \max\{ 1,  \sup\nl_{k> n}\|T_{[k,n+1]}\|_{cb}\}
$ and hence by  \eqref{ech50}
$\|  \alpha_n\|_{cb}  \le 1+\eta_{n+1}$.
 To estimate $\|  \alpha_n^{-1}\|_{cb} $ we will use \eqref{ech5}.
Let $x\in E_n$. We have $\|T_{[k,n+1]} (x)\| \ge (1+\eta_{n+1} )^{-1} \|x\|$ by
\eqref{ech5'} and hence
$$\|x\|=\limsup \|T_{[k,n+1]} (x)\| \ge (1+\eta_{n+1} )^{-1} \|x\| .$$
The latter remains true for any $x\in M_N(E_n)\simeq M_N \otimes E_n$ and any fixed $N$
when $T_{[k,n+1]} $ is replaced by $Id_{M_N} \otimes T_{[k,n+1]} $.
Thus we obtain
 \begin{equation}\label{cho4}
 \|  \alpha_n^{-1}\|_{cb} \le 1+\eta_{n+1} .
 \end{equation}
This implies $d_{cb}(A_n, E_n)\to 1$ when $n \to \infty$, and since
$\cup A_n$ is dense in $A$, this is enough to show that
$A$ locally embeds in $\{C_n\}$.
\end{proof}
