   \end{proof}

\section{Approximately multiplicative self-adjoint liftings of $F$}\label{am}

                Consider a separable $C^*$-algebra $C$ with LP and
                a $*$-homomorphism $$F : C \to \cl L(C)=
                \ell_\infty(C)/c_0(C).$$
                We know that $F$ admits
                a c.p. c.c. lifting $(f_n): C \to \ell_\infty(C)$
                that is (automatically) asymptotically
               multiplicative and self-adjoint, meaning that
                          \begin{equation}\label{ju2}
                \forall x,y\in C\qquad \limsup\|f_n(xy)-f_n(x)f_n(y)\|=0  \text{   and    } f_n(x^*)=f_n(x)^*. \end{equation}
                Let $(\d_n)$ be a given positive sequence.
                We will construct a system
                of f.d. subspaces $E_n \subset  C$  ($n\ge 0$),  maps
                $$T_{n } : E_{n-1} \to E_{n},$$ a  sequence of integers $(m(n))$     and   a sequence $\vp_n>0$,  
                such that $\sum \vp_n\le 1$, satisfying the following properties:


                (i) Each $T_n$ is the restriction of   $f_{m(n)}$ to $E_{n-1}$ and $T_n$ is an $\vp_n$-morphism.


                (ii) $T_{n }(E_{n-1}) + T_{n }(E_{n-1})T_{n }(E_{n-1}) \subset E_{n } $.

                (iii)    For any $n> k$ we have $e^2 \sum_{k+1}^n  \vp_j< \vp_k.$       


                (iv) For any $C^*$-algebra $D$ and any $\vp_n$ -morphism $\t : E_{n} \to D$
                we have $$\| [ Id_\C \otimes \t T_n] (t^{E_{n-1}} )  \|_{\max} \le 1+ \d_n .$$ 
                See Proposition \ref{ppchy} for the definition of $t^{E_{n-1}}$.
                By \eqref{tE},  (iv)  is equivalent to:

                (iv)' For any $C^*$-algebra $D$ and any $ \vp_n$-morphism $\t : E_{n} \to D$
                we have $$\|   \t T_n  \|_{MB(E_{n-1},D)} \le 1+ \d_n. $$ 


More explicitly by \eqref{tE'} (iv)' is equivalent to :

 (iv)'' For any $C^*$-algebra $D$ and any $  \vp_n$-morphism $\t : E_{n } \to D$
we have for any $C^*$-algebra $B$
         $$\| Id\otimes   \t T_n : B\otimes_{\max}  E_{n-1}  \to B\otimes_{\max} D  \|  \le 1+ \d_n. $$ 

Since $(f_n)$ is c.c. we have 
\begin{equation}\label{ech4} \| T_n\|_{cb} \le 1.  \end{equation}





\begin{rem}\label{r1} Note that (iv) applied to the identity map from $E_n$ to $C$
implies $\| [ Id \otimes  T_n] (t^{E_{n-1}} )  \|_{\max} \le 1+ \d_n .$
\end{rem}

The construction of our system is by induction: once we have $E_n,T_n, \vp_n$ we must produce $E_{n+1}, \vp_{n+1}$,  
and $T_{n+1} : E_n \to E_{n+1}$. Compared with \cite{155} the novelty is the use of  conditions (iii) and
(iv).



\begin{lem} \label{ch1} Let $C$ be a  $C^*$-algebra  with LP. Let $E\subset C$ be a f.d. subspace.\\
Then for any
           linear map $\psi:   E \to D$ ($D$ any other $C^*$-algebra) we have
           $$ \|\psi  \|_{mb} \le     \|( Id_\C \otimes \psi)( t^E)   \|_{\C\otimes_{\max} D} .$$
           In other words if we set $\hat \psi=Id_\C \otimes \psi : \C\otimes_{\max} E \to \C\otimes_{\max} D$
           we have $\|\hat\psi\| =\|\hat\psi( t^E)   \|$.
\end{lem}
 \begin{proof}  
            Since $C$ has the LP   (by Th. 10.5 in \cite{157}) $E$ is ``$\max$-controlable" in the sense of \cite{160}, i.e. there is
            $t^E$ in the unit ball of $\C\otimes_{\max} E$ such that  
            for any   $t \in B_{\C\otimes_{\max} E}$  there is a unital $*$-homomorphism
            $\pi: \C \to \C$ such that $t=(\pi \otimes Id_E) (t^E)$. Then $\|( Id_\C \otimes \psi)( t)\|_{\max}=  \|( \pi \otimes Id) (Id \otimes  \psi)( t^E) \|_{\max} \le  \|\hat\psi( t^E)   \|_{\max}$ whence the announced inequality.
             \end{proof}


           \begin{lem}\label{ch2} Let $C,{C_1}$ be $C^*$-algebras. 
           Let $E\subset C$, $F \subset {{C_1}}$ be  f.d.  subspaces. 
           For any $\d>0$ there is $\vp>0$ and 
             a f.d.s.a. superspace  $\cl E$ with  $E\subset \cl E\subset C$ 
           such that for any 
           $\vp$-morphism $\psi: \cl E \to {D}$ (${D}$ any other $C^*$-algebra) we have
           $$\forall x\in F \otimes E\quad \|(Id_{C_1} \otimes \psi)(x)   \|_{ {C_1}\otimes_{\max} {D} }\le (1+\d) \|x\|_{{C_1} \otimes_{\max} C}.$$
           \end{lem}
           \begin{proof} Let $I=\{ (\cl E,\vp)\}$ be the directed set of pairs with $E\subset \cl E$, $\vp>0$. Fix $\d>0$.
           It suffices to show  that there is $(\cl E,\vp)\in I$ such that 
           for all ${D}$, all
           $\vp$-morphisms $\psi: \cl E \to {D}$   and all   $x\in F \otimes E$ we have
           $ \|(  Id_{C_1} \otimes \psi)(x)   \|_{{C_1} \otimes_{\max} {D} }\le (1+\d) \|x\|_{{C_1} \otimes_{\max} C}$.\\
           Let us first fix $x\in F\otimes E$.
           For each $\alpha\in I$ with $E\subset \cl E_\alpha$,
           there is a ${D}_\alpha$ and
           an $\vp_\alpha$-morphism $\psi_\alpha: \cl E_\alpha \to {D}_\alpha$,
           such that
           $$\|(Id_{{C_1}}  \otimes \psi_\alpha)(x)\|_{{{C_1}}  \otimes_{\max} {D}_\alpha} \ge (1+\d)^{-1} \sup \|(
           Id_{{C_1}}  \otimes \psi )(x)\|_{ {{C_1}}  \otimes_{\max} {D}}$$ 
           where the last supremum runs over all ${D}$ and all
           $\vp_\alpha$-morphism $\psi: \cl E_\alpha \to {D} $.
           Note that this last supremum is finite since the nuclear norm
           of each $\psi:\cl E_\alpha \to {D} $ is at most
           $(1+\vp_\a) \dim(\cl E_\alpha) $.
         Let  $\psi'_\alpha : C \to {D}_\alpha$ be the map that extends $\psi_\alpha$   by $0$ outside $\cl E_\alpha$ (we could use a linear map but this is not needed at this point).
         Consider $\psi'=(\psi'_\alpha): C \to  \ell_\infty (I; \{{D}_\alpha\})$ and 
         let $Q: \ell_\infty (I; \{{D}_\alpha\})\to \ell_\infty (I; \{{D}_\alpha\})/c_0(I; \{{D}_\alpha\})$ be the quotient map.
         Then $\pi=Q \psi': C \to \ell_\infty (I; \{{D}_\alpha\})/c_0(I; \{{D}_\alpha\})$ is clearly an isometric $*$-homomorphism.
         We have a contractive morphism $Id_{{C_1}}   \otimes \pi : $ 
         $$ {{C_1}} \otimes_{\max} C  \to {{C_1}} \otimes_{\max} [\ell_\infty (I; \{{D}_\alpha\})/c_0(I; \{{D}_\alpha\})]  = [  {{C_1}} \otimes_{\max} \ell_\infty (I; \{{D}_\alpha\})]/
         [   {{C_1}}\otimes_{\max} c_0(I; \{{D}_\alpha\}) ]$$
         where the last $=$ holds by the ``exactness" of the max-tensor product (see e.g. \cite[p. 285]{P4}).
         Moreover, we have clearly a contractive morphism 
         $$  [  {{C_1}} \otimes_{\max} \ell_\infty (I; \{{D}_\alpha\})]/[{{C_1}}  \otimes_{\max} c_0(I; \{{D}_\alpha\})]
         \to  [\ell_\infty (I; \{ {{C_1}}  \otimes_{\max}  {D}_\alpha\}) ]/[c_0(I; \{ {{C_1}} \otimes_{\max} {D}_\alpha\}) ]. $$
         Since   $\pi(e)= Q ( (\psi_\alpha(e))_\a )$ for all $e\in E$ and since $x\in {{C_1}}  \otimes E$, it follows that 
         $$\limsup\nl_\alpha  \|(Id_{{C_1}}   \otimes \psi_\alpha)(x)\|_{{{C_1}}  \otimes_{\max} {D}_\alpha } \le \|x\|_{{{C_1}} \otimes_{\max} C},$$
         which proves the desired result for each fixed given $x\in F\otimes E\subset  {{C_1}}  \otimes E$.
         But since $F \otimes E$ is a finite dimensional subspace of ${{{C_1}}  \otimes_{\max} C } $
         we may replace the unit ball by a finite $\d$-net in it 
         (or invoke Ascoli's theorem). We can deal with the latter case by
        enlarging $\cl E$ finitely many times. We obtain the announced result (possibly with $2\d$ instead of $\d$).\\
         A different proof can be obtained using the Blecher-Paulsen factorization, as   in \cite[Th. 26.8]{P4}.
             \end{proof}

 \begin{lem}\label{ch3} In the situation of the preceding Lemma \ref{ch1},   
           for any $\d>0$ there is $\vp>0$ and 
             a f.d.s.a. superspace  $\cl E$ with  $E\subset \cl E\subset C$ 
           such that for any  other $C^*$-algebra $D$ and any
           $\vp$-morphism $\psi: \cl E \to D$   we have
           $$\forall x\in \C \otimes  E \quad \|( Id_\C \otimes \psi)(x)   \|_{\C\otimes_{\max} D}\le (1+\d) \|x\|_{\C\otimes_{\max} E},$$
           or equivalently for any $D$
           $$ \|\psi_{|   E} \|_{MB(E,D)} \le 1+\d.$$
           \end{lem}

            \begin{proof}  
            By Lemma \ref{ch2} (actually just by the first part of the proof of it)  applied with $x=t^E \in \C \otimes E$ 
            we find $\cl E$ such that for any $\vp$-morphism $\psi: \cl E \to D$ we have
            $ \|( Id_{\C} \otimes  \psi)(t^E) \| _{ \C\otimes_{\max} D} \le 1+\d.$ Therefore by Lemma \ref{ch1}
            $ \| \psi_E\|_{mb} \le 1+\d $.
                         \end{proof}

\begin{lem}\label{ch4} In the situation of the preceding Lemma \ref{ch1},   
           for any $\d>0$ there are $\vp'>0$,  a f.d.s.a. subspace $E_1\subset C$ and an integer $m$
           such that if we set $T={f_m}_{| E}$ then
         $T: E \to E_1$ is  an $\vp'$-morphism  
           such that $T(E)T(E)  \subset E_1$ and
           for any  other $C^*$-algebra $D$ and any
           $\vp'$-morphism $\psi: E_1 \to D$   we have
           \begin{equation}  \label{ju1}  \|\psi T \|_{MB(E,D)} \le 1+\d.\end{equation}
           In particular for $\psi$ equal to the inclusion $E_1\to C$ we have
           $ \| T \|_{MB(E,C)} \le 1+\d.$
           \end{lem}

           It will be convenient to set for $T: E \to E_1$
          \begin{equation}  \label{ju10} \|T\|_{mb,\vp} =\sup \|\psi T \|_{MB(E,D)} \end{equation}
           where the sup runs over all $C^*$-algebras $D$ and all $\vp$-morphisms $\psi: E_1 \to D$, so that  \eqref{ju1} could be written as $ \|T\|_{mb,\vp'} \le 1+\d $. Note   that  the case when 
           $\psi : E_1\to C$ acts as the identity yields $ \| T \|_{MB(E,C)} \le \|T\|_{mb,\vp'}$ for any $\vp'>0$.



            \begin{proof}  Let $\cl E$ and $\vp$ be as in Lemma \ref{ch3}. Fix $0<\vp'<\vp$ to be specified.
            Since $(f_m)$ satisfies \eqref{ju2},
            if $m$ is chosen large enough
            ${f_m}_{|\cl E}: \cl E \to C$ is an $\vp'$-morphism. 
            We set $T={f_m}_{|\cl E} $ and  $E_1= T(\cl E) + T(\cl E)T(\cl E)$.
            A fortiori $T(E)   \subset E_1$ and  $T(E)T(E)  \subset E_1$.
            For any $D$ and any
           $\vp'$-morphism $\psi: E_1 \to D$,  by
           Remark   \ref{rch1}
           the composition $\psi'=\psi {f_m} _{|\cl E}$ is
           an $\vp''$-morphism on $\cl E$ where 
           $\vp'' =(1+\vp') \vp' +\vp'(1+\vp')^2$. 
           Thus we can clearly select and fix
           $\vp'\approx \vp/2$ so that $\vp'' \le \vp$ or even, say, $\vp'' =\vp$. Then  Lemma \ref{ch3}
           tells us that $ \|\psi T \|_{MB(E,D)}=\|\psi'_{|   E} \|_{MB(E,D)} \le 1+\d.$
             \end{proof}

Let $(\vp_n)$ and $(\d_n)$ be positive sequences such that
 \begin{equation}  \label{ech0} 
 \sum \vp_n<\infty \text{   and   } \d_n \to 0.
 \end{equation}
From what precedes we see that
to any embedding $C \to \cl L(C)$ we can associate (at least if $C$ has LP)
an inductive system and a resulting $A$ :

\begin{pro}\label{pch2} Consider a separable $C^*$-algebra $C$ 
with LP
 and a $*$-homomorphism $$F : C \to \cl L(C)=
                \ell_\infty(C)/c_0(C)$$
                together with   a 
                 c.c. lifting $(f_n): C \to \ell_\infty(C)$,
                which  is (automatically) asymptotically
                $*$-multiplicative. For each positive sequence $(\d_n)$
                there is a summable positive sequence  $(\vp_n)$  
               and   an admissible inductive system $(E_n,T_n)$ with a sequence
                $(m(n))$  as before
                satisfying (i)-(iv)'.\\
 Moreover, if $(f_n)$ satisfies \eqref{cond}
then we can find $(E_n)$ and $m(n)$ satisfying
\eqref{ech5} in addition to (i)-(iv)'. 
\end{pro}

\begin{proof} By induction, suppose we have obtained the system up to
$ T_n : E_{n-1} \to E_n$ and $\vp_n$ with $T_n=f_{m(n)} $ restricted to $E_{n-1}$.
We then apply Lemma \ref{ch4} to $E=E_n$ with $\d=\d_{n+1}$ to produce
a number $\vp'$ so that we may  set $\vp_{n+1}=\vp'$, $m(n+1)=m$,
$E_{n+1}=E_1$ and $T_{n+1}=  { f_{m(n+1)} }_{|E_n}$. Lemma \ref{ch4}
then implies
$$\|  T_{n+1}  \|_{mb,\vp_{n+1}} \le 1+\d_{n+1}.$$
As for condition (iii) since the inequality is strict we can clearly adjust further
$\vp_{n+1}<\vp'$ so that the condition remains valid.
Thus we obtain (i)-(iv)' for the next level $n+1$, which proves the
first part. 
If in addition $(f_n)$ satisfies \eqref{cond}, 
we can choose $m(n+1)$ large enough so that
 $\|{ f^{-1}_{m(n+1)} }_{|f_{m(n+1)}( E_n)} \|_{cb} <1+ \vp_{n+1}$,
 and this gives us \eqref{ech5} at the next induction step.
\end{proof}

\begin{rem}\label{rpch2'} 
We will use (iii) and (iv)' together as follows.
Consider $\t_n : E_n \to Z$. By Lemma \ref{rch1'} we know that  $\t_n$ is a $\d$-morphism
for $\d =e^2 \sum_{j>n} \vp_j$, and hence by (iii) an $\vp_n$-morphism.
By (iv)'   we have
$\|   \t_n T_n  \|_{MB(E_{n-1},Z)} \le 1+ \d_n. $
We claim that this implies
\begin{equation}  \label{ju6-} \forall n\ge 1 \quad \|\t_{n-1}\|_{MB(E_{n-1},Z)} \le 1+\d_n 
\end{equation} 
and hence also 
\begin{equation}  \label{ju6} \forall n\ge 0\quad \|\t_n\|_{MB(E_{n},Z)} \le 1+\d_{n+1} .\end{equation} 
Indeed, since $\forall x\in E_{n-1}$ 
$$\t_{n-1}(x)=(0,\cdots,0, x, w_n(T_n(x)) )=(0,\cdots,0, x, 0,\cdots)+\t_n(T_n(x)) ) $$ (recall \eqref{ju3} and \eqref{ju4})
we have
\begin{equation}  \label{ju5}
\Phi_n \t_{n-1} =(0,\cdots,0,p_{n-1}) \oplus p_{[n,\infty]} \t_n T_n p_{n-1}\end{equation} 
and hence
by Lemma \ref{deco}

$$\|\t_{n-1}\|_{MB(E_{n-1},Z)} \le \max\{ 1, \| \t_n T_n \|_{MB(E_{n-1},   Z)} \}.$$
and hence our claim $\|\t_{n-1}\|_{MB(E_{n-1},Z)} \le 1+\d_n$ for all $n\ge 1$
follows.
\end{rem}

Following the terminology of \cite{154} we say
that the inclusion of a subalgebra $Z$  in a larger one $ \cl L$
is $\max$-injective if the associated $*$-homomorphism
$D\otimes_{\max } Z \to D\otimes_{\max }  \cl L$ is injective (and hence isometric) for all $C^*$-algebras $D$.
For that to hold it suffices that it holds for $D=\C$.

  \begin{pro}\label{pch2'} Consider the situation of Proposition \ref{pch2}.
Assume $(\d_n)$ bounded. Then the associated $C^*$-algebra $Z$ has the LP and the inclusion $Z\to \ell_\infty(C)$ is $\max$-injective.
\end{pro}
\begin{proof}

To show that $Z$ has the LP we use the criterion from \cite{157}.
Let $(C_i)$ be an arbitrary family of $C^*$-algebras (we could take simply $C_i=\C$ for all $i$).
We claim that 
there is a constant $c$ such that for any $t\in Z \otimes \ell_\infty(\{C_i\}) $
the associated family $(t_i)$ with $t_i\in Z \otimes C_i $ satisfies
$$\|t\|_{Z \otimes_{\max} \ell_\infty(\{C_i\})} \le c \sup\nl_i\|t_i\|_{Z \otimes_{\max} C_i}  .$$
Actually, since here we are comparing $C^*$-norms if there is such a $c$ then $c=1$ works, and we obtain the criterion as in \cite{157}.
To verify this claim it suffices to check this
for $t\in Z_{n-1} \otimes \ell_\infty(\{C_i\}) $ with $c$ independent of $n$.


For any $C^*$-algebra $D$ we may view ${\Phi_n} \otimes Id_D$ as having range
in $[(C_0\oplus \cdots\oplus C_{n-1})\otimes D] \oplus [p_{[n,\infty]} (Z)\otimes D ]$.
By Lemma \ref{deco}
for any $t\in Z \otimes D$  we have $\|t\|_{Z \otimes_{\max} D}    = \| [\Phi_n \otimes Id_D ](t) \|_{\max}$ and hence
$$\|t\|_{Z \otimes_{\max} D}     =
\max\{ \|  [p_{[0,n-1]}  \otimes Id_D]  (t)  \|_{(C_0\oplus \cdots\oplus C_{n-1})\otimes_{\max} D} ,\| [p_{[n,\infty]}     \otimes Id]  (t) \|_{ p_{[n,\infty]} (Z)\otimes_{\max} D} \} .$$
For any $z\in Z_{n-1}$ we have
$p_{[n,\infty]} (z)=p_{[n,\infty]} \t_{n-1}  (z_{n-1})=p_{[n,\infty]} \t_{n-1}p_{n-1} (z)$.
\\ Recalling $t\in Z_{n-1} \otimes \ell_\infty(\{C_i\}) $, we have then 
\begin{equation}  \label{ju7} \| t\|_{Z \otimes_{\max} \ell_\infty(\{C_i\})}=
\max\{ \|  t' \|_{(C_0\oplus \cdots\oplus C_{n-1})\otimes_{\max} \ell_\infty(\{C_i\})} ,\| t'' \|_{ p_{[n,\infty]} (Z)\otimes_{\max} \ell_\infty(\{C_i\})} \}  . \end{equation}
where 
$$ t'_i= [p_{[0,n-1]}  \otimes Id]  (t_i)   \text{  and  } t''_i =  [p_{[n,\infty]} \t_{n-1} p_{n-1}   \otimes Id]  (t_i) .$$



We   treat the two parts separately. 
 We turn first to
$t'$ which is the  easy case.
Indeed, since $C\oplus\cdots\oplus C$ ($n$-times)
has the LP  and $p_{[0,n-1]}$ is a $*$-homomorphism from $Z$ to
$C\oplus\cdots\oplus C$, we  have
$$\|  t' \|_{(C\oplus\cdots\oplus C)\otimes_{\max} \ell_\infty(\{C_i\})} 
\le \sup\nl_i \|t_i'\| _{(C\oplus \cdots\oplus C)\otimes_{\max}   C_i  }
\le \sup\nl_i \|t_i\| _{ Z\otimes_{\max}   C_i  } \le 1.$$


Note that 
\begin{equation}  \label{ech6}
\sup\nl_k\| [p_{k }   \otimes Id]  (t_i) \|_{C \otimes_{\max} C_i} \le 1.
\end{equation}
where $p_k:\ell_\infty(C)\to C$ denotes the  coordinate of index $k$.
\\
Note  $  \|  p_{[n,\infty]} \|_{MB(Z, p_{[n,\infty]}(Z))} \le 1$ since $ p_{[n,\infty]}$ is a $*$-homomorphism. Thus by \eqref{ju6-} we have
$$\|  t'' \|_{ p_{[n,\infty]} (Z) \otimes_{\max} \ell_\infty(\{C_i\})} 
\le  (1+\d_n) \|[ p_{n-1}  \otimes Id] (t) \| _{C \otimes_{\max}\ell_\infty(\{ C_i\}) }
$$
and by the LP of $C$ and \eqref{ech6}
$$\|[ p_{n-1}  \otimes Id] (t) \| _{C \otimes_{\max}\ell_\infty(\{ C_i\}) }
\le \sup\nl_i \|[ p_{n-1}  \otimes Id] (t_i) \| _{C \otimes_{\max}   C_i  } \le 1,
$$
and it follows $\|  t''\|_{ p_{[n,\infty]} (Z) \otimes_{\max} \ell_\infty(\{C_i\})}  \le 1+\d_n$.
By \eqref{ju7} we conclude $\| t\|_{Z \otimes_{\max} \ell_\infty(\{C_i\})}\le  1+\d_n $,
and the latter is less than a constant $c$ if $\d_n$ is assumed bounded.
Actually if we assume $\d_n \to 0$ we directly obtain $c=1$ by taking $n$ as large
as we wish.

 To show that $Z\subset \ell_\infty(C)$ is $\max$-injective, let
$t\in \C \otimes Z$ be such that $\|t\|_{\C \otimes_{\max} \ell_\infty(C)}\le 1$.
Let us show that $\|t\|_{\C \otimes_{\max} Z}\le 1$.
By perturbation we may clearly assume that
$t\in \C \otimes Z_{n-1}$.
By Lemma \eqref{deco}
$$ \|   t\|_{\C \otimes_{\max} Z} 
\le  \max\{  1, \| [Id \otimes p_{[n,\infty]} \t_{n-1}p_{n-1}] (t)\|_{\C \otimes_{\max} p_{[n,\infty]}(Z)}  . $$
As in the argument for $t''$ in the first part of the proof   we obtain
$ \|   t\|_{\C \otimes_{\max} Z} \le 1+\d_n$ and we conclude as in the first part.
\end{proof}


\begin{pro} \label{pch3} Consider the situation of Proposition \ref{pch2}.
Assume $\d_n $ bounded. 
Assume in addition
that the   inductive system satisfies \eqref{ech5}, 
then the associated $C^*$-algebra $A$ has the LLP.
\end{pro}
\begin{proof} We set $\B=B(\ell_2)$. We claim that there is a constant $c$
for which the inclusion $A_n\to A$
satisfies $$\|\B \otimes_{\min} A_n \to \B \otimes_{\max} A\| \le c\ \  \text{  for all  }n  .$$ This clearly implies that the pair $(\B,A)$ is nuclear, i.e. that $A$ has the LLP. 

As in the proof of Proposition \ref{pch10} let 
$$\a_n=Q\t_n: E_n \to A_n.$$
On the one hand by
 \eqref{cho4} we have 
  \begin{equation}  \label{ju8} \|\a_n^{-1}:A_n \to E_n\|_{cb}\le 1+\eta_{n+1},\end{equation} which means
$$ \| Id \otimes \a_n^{-1} :  \B \otimes_{\min} A_n \to \B \otimes_{\min} E_n\|\le
1+\eta_{n+1}.$$ On the other hand
by \eqref{ju6}   we have
 \begin{equation}  \label{ju9}\|\a_n\|_{mb} \le 1+\d_n,\end{equation}  which implies a fortiori
$$ \| Id \otimes \a_n :  \B \otimes_{\max} E_n \to \B \otimes_{\max} A\|\le
1+\d_n.$$
Recall   that here  the norm of $\B \otimes_{\max} E_n$ is the one induced by $\B \otimes_{\max} C$. Since 
 $C$ has the LP and a fortiori the LLP we have
 $\B \otimes_{\min} E_n= \B \otimes_{\max} E_n$ isometrically and hence we conclude that the inclusion $i_{A_n} : A_n \to A$ satisfies
 $$ \| Id \otimes i_{A_n} :  \B \otimes_{\min} A_n \to \B \otimes_{\max} A\|\le
(1+\eta_{n+1})(1+\d_n).$$ 
This proves the claim.
\end{proof}

\begin{rem}
 We should emphasize  here a subtle point about \eqref{ju10} and  (iv)' that we already used:
 a priori  $\t_{n}$ is an $\vp_{n}$-morphism from $E_{n}  $ to
 $L$ but its values being inside $Z$ we may view it as 
 an $\vp_{n}$-morphism into $Z$, and  hence (iv)' 
implies
 $\| \t_{n}T_{n} \|_{MB(E_{n-1}, Z)} \le 1+\d_{n}$. Similarly
  \eqref{ju9} means 
  \begin{equation}  \label{cho3'}
    \| \a_n \|_{MB(E_{n}, A)}
  \le 1+\d_{n} . \end{equation} 
  In this light the norm in \eqref{ju10} appears much stronger than
  the mb-norm of $T$. Specifically, it dominates the  mb-norm of $T$
  even when $T$ is viewed as acting into the $C^*$-algebra generated by
  its range, which a priori may augment the mb-norm.
 \end{rem}



\begin{thm}\label{ty}
Consider the situation of Proposition \ref{pch3}. Let $D$ be a separable $C^*$-algebra.
Assume $\d_n $ bounded and \eqref{cond}.  If
  the embedding $F : C \to \cl L(C)=
                \ell_\infty(C)/c_0(C)$
  is $D$-nuclear (i.e.
$Id_D \otimes F$ is bounded from $D\otimes_{\min} C $ to $D\otimes_{\max} \cl L(C)$), the   
admissible inductive system can be constructed so that
the  associated $C^*$-algebra $A$  
(as in Proposition \ref{pch1}) is $D$-nuclear  and locally embeds in $C$.
\end{thm}
    \begin{proof}  
The underlying idea is that the inclusion
$A_{n-1} \subset A_n$ is ``similar" to the map $T_n: E_{n-1} \to E_{n}$. 
By what precedes we have a factorization of  
$A_{n-1} \subset A_n$ as :

$$A_{n-1} {\buildrel {\alpha^{-1}_{n-1}} \over \longrightarrow  } E_{n-1} {\buildrel {T_n} \over \longrightarrow  }  E_n 
{\buildrel {\a_{n} } \over \longrightarrow  } A_{n}.
 $$
We already saw in \eqref{ju8} and \eqref{ju9}
that $\|{\alpha^{-1}_{n-1}}\|_{cb} \le 1+\eta_n$ and 
 $\| \a_n \|_{mb}
  \le 1+\d_{n} .$
 %SOMETHING SEEMED WRONG HERE, FIXED?
  We now turn to the assertion about the $D$-nuclearity of $A$.
 Recall that by the projectivity of the max-tensor product we have a canonical
 contractive $*$-homomorphism
$D\otimes_{\max} \cl L(C)\to  \cl L( D \otimes_{\max} C)$, and hence
for any $x\in D \otimes C$ our assumption on $F$   implies
\begin{equation}  \label{che4}\limsup\nl_n\| [Id \otimes f_n](x) \|_ {D \otimes_{\max} C}  \le
\| [Id_D \otimes F](x) \|_ {D \otimes_{\max} {\cl L} (C)}
\le \|x\|_{D \otimes_{\min} C}.\end{equation}



Let $D_n\subset D$ be an increasing sequence of f.d. subspaces
with dense union.
We indicate how the induction step should be modified to obtain
the assertion in the theorem. 
We ensure at each step
that $T_n :E_{n-1} \to E_{n}$ is such that
\begin{equation}  \label{che4'}\| Id\otimes T_n : D_{n-1} \otimes_{\min} E_{n-1} \to D_{n-1} \otimes_{\max} E_{n} \|\le 1+\d_n.\end{equation}
Suppose we have constructed $E_{n-1},E_n,T_n$. Using a suitable  fine enough finite net 
in the (compact) unit ball of $D_{n} \otimes_{\min} E_{n}$ and using 
\eqref{che4} 
we can find
$m$ (that will be our $m(n+1)$) such that, in addition to the properties already
imposed in the proof of Proposition \ref{pch3}, we have
$$\| Id\otimes f_m : D_{n} \otimes_{\min} E_{n} \to D_{n} \otimes_{\max} C\|\le 1+\d_{n+1}$$
Then we argue as before: we let $T_{n+1}=f_m$
and $E_{n+1}=T_{n+1}(E_n)+T_{n+1}(E_n)T_{n+1}(E_n)$, and we obtain \eqref{che4'}
with $n$ replaced by $n+1$, which is
 the next step of the induction. 
We will now show how  \eqref{che4'} for all $n\ge 1$  implies that $A$ is $D$-nuclear.
Using \eqref{cho3'} and 
\eqref{che4'} we find
$$\|Id \otimes \a_nT_n : D_{n-1} \otimes_{\max} E_{n-1} \to D_{n-1} \otimes_{\max} A_n   \|\le  (1+\d_{n})^2. $$
Since
$\|{\alpha^{-1}_{n-1}}\|_{cb} \le 1+\eta_n$, the inclusion map $ i_{A_{n-1}}:  A_{n-1} \to A$, 
which is equal to $\a_nT_n a_{n-1}^{-1} $, satisfies
$\|Id \otimes i_{A_{n-1}} : D_{n-1} \otimes_{\min} A_{n-1} \to D_{n-1} \otimes_{\max} A   \|\le  (1+\eta_n)(1+\d_{n})^2,$
or equivalently
$$\|Id \otimes i_{A_{n-1}} : D_{n-1} \otimes_{\min} A_{n-1} \to D \otimes_{\max} A   \|\le  (1+\eta_n)(1+\d_{n})^2,$$
and since $(1+\eta_n)(1+\d_{n})^2$ is bounded and  $\cup [D_{n-1} \otimes  A_{n-1}]$  dense in
$D \otimes_{\min} A$    we conclude that    $A$ is $D$-nuclear.\\
By Proposition \ref{pch10}  we already know that $A$ locally embeds in $C$.
\end{proof}
\begin{rem}\label{ju14}
In the situation of Theorem \ref{ty} with $\d_n\to 0$,
 the conclusion can be  summarized 
as follows:
\\
The inclusion $A_{n-1} \to A_{n}$ can be factorized
as
$$  A_{n-1} {\buildrel {\alpha^{-1}_{n-1}} \over \longrightarrow  } E_{n-1} {\buildrel {T_n} \over \longrightarrow  }  E_n {\buildrel { \a_n} \over \longrightarrow  } A_{n} $$
where $\|{\alpha^{-1}_{n-1}}\|_{cb} \to 1$, $\|\a_n\|_{mb} \to 1$ and
$\|Id \otimes T_n : D_{n-1} \otimes_{\min} E_{n-1} \to D_{n-1} \otimes_{\max} E_n \|\to 1$ (where for the latter we use the norm induced by $D\otimes_{\max} C$).
\end{rem} 
\begin{rem} \label{ju15}
More generally given a sequence $(D(i))_{i\ge 1} $ of separable $C^*$-algebras
such that $F: C  \to \cl L (C )$  is $D(i)$-nuclear for each $i$, we claim that  
 our system can be adjusted so that $A$ is $D(i)$-nuclear for each $i$.\\
 Indeed, for each $i$,  let $\{D(i)_N\mid N\ge 1\}$ be an increasing sequence of f.d.
 subspaces with union dense  in $D(i)$. 
 Let $\{\D_n\mid n\ge 0\}$ be an enumeration of the collection $\{D(i)_N\mid i\ge 1, N\ge 1\}$ where each element is repeated countably infinitely many times.
 Fix a subspace $\D\in \{\D_n\mid n\ge 0\}$. Then $\D=\D_{n-1}$ for some $n\ge 1$ that
 we can choose as large as we wish. Clearly the inductive argument of the preceding proof can be modified
 to ensure that 
 $$\forall n\ge 1\quad \|Id \otimes i_{A_{n-1}} : \D_{n-1} \otimes_{\min} A_{n-1} \to \D_{n-1} \otimes_{\max} A   \|\le  (1+\eta_n)(1+\d_{n})^2.$$
Thus $\D=\D_{n-1}$ implies
  \begin{equation}\label{ju13} \|Id \otimes i_{A_{n-1}} : \D  \otimes_{\min} A_{n-1} \to \D  \otimes_{\max} A   \|\le  (1+\eta_n)(1+\d_{n})^2.\end{equation}
Let $c=\sup (1+\eta_n)(1+\d_{n})^2.$ Since \eqref{ju13} holds for infinitely many $n$'s
the min and max norms are $c$-equivalent on $\D \otimes[\cup A_n]$, and since the latter holds for any $\D$, for each $i$, the same $c$-equivalence holds on 
$[\cup _N D(i)_N] \otimes [\cup_{n-1} A_{n-1}]$.
Since the latter is dense in $D(i) \otimes_{\min} A$ this proves our claim.

Unfortunately we do not see how to remove the assumption that the family
$(D(i))_{i\ge 1} $  is countable.
\end{rem}

  \begin{rem} In our original approach in \cite{155} it suffices to assume that
          $C$ has the LLP. We then use for each $n\ge 1$ the existence of a c.c. lifting for
          $F_{|E_{n-1}}$ and obtain a non-nuclear WEP $C^*$-algebra $A$ that locally embeds
          in $\C$. Then the LLP of $A$ follows from the general fact that WEP $\Rightarrow$
          LLP for algebras that locally embed in $\C$. 
          A priori the non-separability of $\B$ prevents us from taking $D=\B$ to prove that
          $A$ is $\B$-nuclear i.e. has the LLP, but once we know that $A$ locally embeds
          in $\C$,  it suffices for the LLP of $A$ to know that 
          $A$ is $j$-nuclear where  $j: \C \to \B$ is any embedding and where
          by $A$ is $j$-nuclear we mean that $j\otimes Id_A$ is bounded
          from $\C \otimes_{\min} A \to \B \otimes_{\max} A$ (see the appendix for a proof). With this in mind
          the separability of $\C$ allows us to use the same argument as for   separable $D$'s to check the LLP of $A$.
          \end{rem}

\begin{rem}
As already mentioned  in \cite{155}, we can perform our construction of inductive systems
in a more general setting that we will just briefly sketch here.
We give ourselves a sequence of isometric $*$-homomorphisms
$F(N) : C_N \to \cl L (C_{N+1})$ together with c.c.s.a. liftings
$f(N): C_N \to L (C_{N+1})$ so that if $Q(N+1): L (C_{N+1}) \to  \cl L (C_{N+1})$
denotes the quotient map we have $Q(N+1)f(N)=F(N)$.
Then if we assume all the $C_N$'s have the LP and that   the coordinates of each $f(N)$
are   asymptotically 
                 locally almost completely isometric  (i.e. they satisfy the condition \eqref{cond})
then we can produce an inductive system
with $E_{n-1} \subset C_{n-1}$ and with $T_n=F(n-1)_{m(n)}$, and we obtain analogous properties.


\end{rem}

\section{Cone algebras}\label{ca}

Proposition \ref{pch1}
tells us how to associate a $C^*$-algebra $A$ to a $*$-embedding $F: C \to \cl L(C) $, equipped with 
a completely contractive lifting $f: C \to L(C)$.
By Theorem \ref{ty}  if $f$
 satisfies \eqref{cond}, if
  $C$ has the LP and if $F$ is $\C$-nuclear, the algebra $A$ has WEP and LLP. To valuably apply this result, we need to  exhibit   $F$'s with the required properties. Their existence  is not so immediate but    cone algebras
 crucially provide us with  the missing ingredient.  


Let  $C_0=C((0,1])$  and  $C_1=C([0,1])$.  For  any  $C^*$-algebra  $A$,
  we  denote  by  $C_0(A)=  C_0  \otimes_{\min}  A$  the  so-called  cone  algebra
 of $A$ and by $C(A)$ its unitization. (Warning: $C(A)\not=C_1  \otimes_{\min}  A$ !)\\
    When  dealing  with  a  bounded mapping  $u:  A  \to  B$  between  $C^*$-algebras
  (or  operator  spaces)  we  will  denote  by  $$u_0:  C_0(A)  \to  C_0(B)$$
  the  bounded map  extending    $Id_{C_0}  \otimes  u$.


   The algebra $C$ considered throughout \S \ref{am}
   will now be replaced by the cone algebra $C_0({\bf C})$ or $C({\bf C})$.
    We use the letter ${\bf C}$ for a $C^*$-algebra to avoid a notational confusion.

Let $q: {\bf C} \to B$ be a surjective $*$-homomorphism and let $\I=\ker(q)$.
We will use freely the natural identifications
$$ B\simeq  {\bf C}/\cl I \quad \text{  and  } \quad  C_0(B)\simeq C_0 ({\bf C}/\cl I) \simeq C_0({\bf C})/C_0(\cl I), \quad C(B)\simeq C ({\bf C}/\cl I) \simeq C({\bf C})/C_0(\cl I).$$
Let  $(\sigma_n)$  be  a  quasicentral  approximate  unit  in  $\I$.
Our  construction  is simpler  if   there is such a 
  $(\sigma_n)$   (and hence $(1-\sigma_n)$)  formed  of  projections.
Then  the  mappings  $x\mapsto  (1-\sigma_n ) x$  are  approximatively  multiplicative. In general this does not exist.  However,
if we replace ${\bf C},B,q$ by $C_0({\bf C}),C_0(B),q_0$  then  it does exist
and the construction of the preceding section can be applied. 


This trick of passing to cone algebras is
closely   related  to    Kirchberg's  \cite[\S  5]{Kir},
but    we  learnt it from  \cite[Lemma  13.4.4]{BO}.  A similar idea already
appears in \cite[Lemma 10]{CoH} for the suspension algebra in the context of
approximatively  multiplicative families indexed by a continuous parameter in $(0,\infty)$, but our goals seem unrelated.

 \begin{lem}\label{ll7}
            Let $q: {\bf C} \to B$ be a surjective $*$-homomorphism between $C^*$-algebras, with separable kernel $\cl I$.
            There is a pointwise  bounded sequence of   maps
             $\rho_n: C_0\otimes {\bf C} \to C_0\otimes {\bf C}$ that induces in the limit a  $*$-homomorphism
            $$\rho_\infty: C_0({\bf C}) \to \L(C_0({\bf C}) ) $$
          that  vanishes on $C_0(\cl I)$ and for which the
            associated map
            $$  \rho_{[\infty]} : C_0({\bf C})/C_0(\cl I) \to \L(C_0({\bf C}) ) $$
         (which satisfies $\rho_{[\infty]} q_0=\rho_\infty$)   is an isometric $*$-homomorphism.\\
            Moreover, we have $q_0\rho_n(x)=q_0(x)$ for all $x\in C_0\otimes {\bf C} $ and   all $n$.
              \end{lem}
           We could refer to the proof of Lemma 6.1 in \cite{155} (itself based on \cite[Lemma 13.4.4]{BO}),
           but we give the details for the reader's convenience.

           \begin{proof} Recall $\cl I=\ker(q)$.
            Let $(\sigma_n)$ be a net forming a quasicentral approximate unit of $\cl I$. 
            This means $\sigma_n\ge0$, $\|\sigma_n\| \le 1$,
            $\|\sigma_n x-x\|\to 0$ for any $x\in \cl I$ and
            $\|\sigma_n c-c\sigma_n\|\to 0$ for any $c\in {\bf C}$.
            We identify $C_0({\bf C})=C_0\otimes_{\min} {\bf C}$ with the set of ${\bf C}$ valued functions
            $f: [0,1] \to {\bf C}$ such that $f(0)=0$. 
            The set of polynomials
            $\cl P_0={\rm span}[t^m\mid m>0]$ is dense in $C_0$.
            Let $\rho_n: C_0 \otimes {\bf C} \to C_0({\bf C})$ be the map taking 
            $t\mapsto f(t) c$ ($f\in C_0,c\in {\bf C}$) to
            $t\mapsto f(t(1-\sigma_n)) c$. For instance (monomials)
            $\rho_n$ takes $t\mapsto t^m c$ to
            $t\mapsto t^m (1-\sigma_n)^m c$.
            Note $\|1-\sigma_n\|\le 1$ therefore for any $f\in C_0$ the function
            $t\mapsto f(t(1-\sigma_n))$ is in $C_0({\bf C})$
            with norm $\le \|f\|_{C_0 }$. This shows that
            $\sup_n\|\rho_n(y)\|<\infty$ for any $y\in C_0\otimes {\bf C}$, so that $(\rho_n)$ defines
            a map $\rho: C_0 \otimes {\bf C} \to \ell_\infty(C_0({\bf C}))$.\\
            We should warn the reader that  a priori we do not know
            that $\rho$ is bounded on $C_0\otimes_{\min} {\bf C}=C_0({\bf C})$, but we will show that it becomes contractive after composition with the quotient map
         $Q: \ell_\infty(C_0({\bf C})) \to \cl L(C_0({\bf C}))$.

             Since $\sigma_n\in \cl I$
             we have for all $x\in \cl P_0\otimes {\bf C}$ (and hence all $x\in \cl C_0\otimes {\bf C}$)
              \begin{equation}\label{us8}   q_0\rho_n (x) =q_0(x) . \end{equation}
              Indeed,   
            \eqref{us8} clearly holds
            in the case $x=t^m \otimes c$ and hence it holds by density
            for any $x\in C_0\otimes {\bf C}$.


            Since $\sigma_n$ is quasicentral we have
            $$\forall x,y\in C_0\otimes {\bf C}\quad 
            \limsup\nl_n\|
            \rho_n(xy)-\rho_n(x)\rho_n(y)\|=0.$$
            Indeed this reduces to the case of monomials which is obvious,
            and also $$\limsup\nl_n\|\rho_n(x)^*-\rho_n(x^*)\|=0.$$
            It follows that after composing $\rho$ by the quotient map
            $Q: \ell_\infty(C_0({\bf C})) \to \cl L(C_0({\bf C}))$ we obtain
            a  map 
            $\rho_\infty : C_0 \otimes {\bf C} \to \cl L(C_0({\bf C}))$ which
            is a $*$-homomorphism, such that $\rho_\infty=Q\rho$ on $C_0\otimes {\bf C}$.
            Since $C_0$ is nuclear, this  extends to a   $*$-homomorphism
        $\rho_\infty: C_0({\bf C}) \to \cl L(C_0({\bf C})) $  defined on the whole of 
            $C_0({\bf C})$ with $\| \rho_\infty \|\le 1$.

     We have
             \begin{equation}\label{us9}\forall f \in C_0\otimes \cl I\quad \limsup\nl_n\|
            \rho_n(f)\|=0 ,\end{equation}
            and hence  $\rho_\infty( C_0\otimes \I)=Q\rho ( C_0\otimes \I)=\{0\}$.
            Therefore,  after passing to the quotient by $C_0 (\cl I)  \subset \ker(\rho_\infty)$, we derive from $\rho_\infty$
            a  (contractive) $*$-homomorphism 
            $$\rho_{[\infty]} : C_0({\bf C})/C_0(\cl I) \to \L(C_0({\bf C}) )  .$$

          We have clearly $\rho_{[\infty]} q_0=Q\rho$ on $C_0\otimes {\bf C}$.
          To check that $\rho_{[\infty]}$ is isometric it suffices to show that
          for any $x\in C_0\otimes {\bf C}$ we have 
          $\|\rho_{[\infty]} q_0(x)\|\ge \|q_0(x)\|.$
            By \eqref{us8}
           we have
            \begin{equation}  \label{chu1}
             \forall x\in C_0\otimes {\bf C} \ \forall n\qquad  \|q_0(x)\|  \le \|\rho_n(x)\| .
            \end{equation}

             This implies
             $\|q_0(x)\|\le \limsup\|\rho_n(x)\|  = \|Q\rho(x)\|=\|\rho_{[\infty]} q_0(x)\|. $
          Thus    $\rho_{[\infty]}$ is isometric.      \end{proof}     



            \begin{rem}\label{rchi}[On unitizations] Given a map $u: A \to B$ from a $C^*$-algebra $A$ to a unital one, let
   $\hat u : \hat A \to  B$ denote its unital extension to the unitization of $A$.  
   When $u$ is a $*$-homomorphism, so is $\hat u$ and then
   if $u$ is isometric so is $\hat u$.\\
            Recall that $C({\bf C})$ (resp. $C(B)$) denotes the unitization of $C_0({\bf C})$
            (resp. $C_0(B)=C_0({\bf C}/\cl I) \simeq C_0({\bf C})/C_0(\cl I)$).
            It is easy to verify that $C(B)=C({\bf C}/\cl I)$ can be identified with  $C({\bf C})/ C_0(\cl I)$.
       We have  canonical embeddings
        $i_{ L}:   L (C_0({\bf C})) \subset   L (C({\bf C}))$
          and    $i_{\cl L}: \cl L (C_0({\bf C})) \subset \cl L (C({\bf C}))$.
       Since  $ L (C({\bf C}))$ and $\cl L (C({\bf C}))$ are unital
           we have unital $*$-homomorphisms $\tilde \rho_\infty : C({\bf C}) \to   L (C({\bf C}))$
           and $\tilde   \rho_{[\infty]} : C({\bf C}/\cl I) \to \cl L (C({\bf C}))$
           extending respectively 
           $i_{ L} \rho_\infty $ and $i_{\cl L}   \rho_{[\infty]}$.
           Clearly, $\tilde  \rho_{[\infty]}$ remains isometric.
                      Moreover,   
           denoting 
           $$V=\CC 1_{C({\bf C})} + C_0\otimes {\bf C} \subset C({\bf C})$$
       the map $\rho: C_0\otimes {\bf C} \to L(C_0({\bf C}))\subset L(C({\bf C}))$ has a unital extension
             $\tilde \rho  : V \to L(C({\bf C}))$
           and $V$     is a dense subspace of $   C({\bf C})$. 
            Let $Q': L( C  ({\bf C})) \to \cl L( C  ({\bf C}))$ denote the quotient map.
            It is then easy to check that $Q'\tilde \rho $
            is the restriction of $\tilde \rho_\infty$.


           All in all this shows that there is a version
           of Lemma \ref{ll7} valid for the unital cone algebras, as follows.       
      \end{rem}

            \begin{lem}\label{ll7u}
            Let $q: {\bf C} \to B$ be a surjective $*$-homomorphism between $C^*$-algebras ${\bf C} $ and $ B$, with separable kernel $\cl I$.
          Let $i: C_0({\bf C})/C_0(\cl I) \to  C({\bf C})/C_0(\cl I)$ be the natural inclusion. 
          Let $\tilde q_0 :  C({\bf C}) \to  C({\bf C})/C_0(\cl I) $ be the unital map
          associated to $iq_0$.
                      There is a pointwise  bounded sequence of  unital  maps
             $\tilde\rho_n: V \to V$ that induces in the limit a unital $*$-homomorphism
            $$\tilde\rho_\infty: C({\bf C}) \to \L(C({\bf C}) ) $$
          that  vanishes on $C_0(\cl I)$ and for which the
            associated map
            $$ \tilde \rho_{[\infty]} : C({\bf C})/C_0(\cl I) \to \L(C({\bf C}) ) $$
         (which satisfies $\tilde\rho_{[\infty]}\tilde q =\tilde\rho_\infty$)   is a unital isometric $*$-homomorphism.\\
            Moreover, 
            we have $\tilde q_0\tilde \rho_n(x)=\tilde q_0(x)$ for all $x\in V $ and   all $n$.
              \end{lem}

            Recapitulating, suppose
            ${\bf C}$ and $B$ are separable $C^*$-algebras for which there is
           a surjective $*$-homomorphism $q: {\bf C} \to B$.
            By Lemma \ref{ll7},   we have an embedding (i.e. an isometric $*$-homomorphism)
            $$\rho_{[\infty]} : C_0(B) \to \cl L (C_0({\bf C})).$$
            Now let $j: {\bf C} \to B$ be an embedding  so that
            $j_0: C_0({\bf C}) \to C_0(B)$ and $F= \rho_{[\infty]}  j_0$
            are clearly also  embeddings.  

            \begin{lem}\label{ju18} Let $j$   be as above and let
         $$F= \rho_{[\infty]}  j_0: C_0({\bf C}) \to \cl L (C_0({\bf C})).$$
         Let $f=(f_n)$ be a c.c. lifting for $F$.
             In the situation of either  Lemma \ref{ll7}
             or Lemma \ref{ll7u}, the condition \eqref{cond} holds.

                  \end{lem}
            \begin{proof}
            Let $V\subset \C$ be a f.d.  subspace and let
          $\D= \cl P_N \otimes V \subset C_0\otimes {\bf C}$ where 
          $\cl P_N={\rm span}[t,\cdots,t^N]$. Recall
          $jV \subset B ={\bf C}/\cl I$.
          Let $\psi:   jV \to {\bf C}$ be any linear lifting, i.e. we have
          $q\psi j(x)=j (x)$ for any $x\in V$, and hence
          $q_0\psi_0 j_0(x)=j_0(x)$ for any $x\in \D$. Let  
            $g_n=\rho_n\psi_0j_0: \D \to C_0({\bf C})$ (actually $g_n$ takes values
            in $\cl P_N \otimes {\bf C}$). We first claim that $g_n$ is asymptotic
            to ${f_n}_{|\D}$ by which we mean
            $$\forall x\in \D\qquad \|g_n(x)-f_n(x)\|\to 0 . $$
            Indeed, we have
            $Q(f(x)) =F(x)= \rho_{[\infty]} j_0 (x)$
            and also $Q(g(x))=Q\rho\psi_0j_0(x)= \rho_\infty\psi_0j_0(x) =\rho_{[\infty]} q_0 \psi_0 j_0(x)= \rho_{[\infty]} j_0(x)$.  Thus
            $Q(f(x)) = Q(g(x))$ which is equivalent to our first claim.\\
            Our second claim is that
              $$
               \forall n\qquad \|{g^{-1}_n}_{|g_n(\D)} \|_{cb}\le 1.$$
          Indeed, since (see Lemma \ref{ll7}) $q_0 \rho_n=q_0$ on $C_0\otimes {\bf C}$ we have $q_0 g_n=q_0\psi_0j_0=j_0$, from which we derive
           $\|x\|=\|j_0(x)\|\le \|g_n(x)\|$.
           Equivalently  $
                \|{g^{-1}_n}_{|g_n(\D)} \| \le 1.$
               Similarly since $q_0$ is c.c. and $j_0$  completely isometric
          we obtain our second claim.\\
          To conclude,   an elementary perturbation argument
          shows that the two claims together with the complete contractivity of the $f_n$'s imply
           \begin{equation}  \label{chy4} \limsup\|{f^{-1}_n}_{|f_n(E)} \|_{cb}\le 1.\end{equation}
           Indeed, by \cite[Lemma 2.13.2 p. 69]{P4} for any $\vp>0$  and any $E\subset C_0({\bf C})$ there are 
 ${\D} \subset {\cl P} \otimes {\bf C}$  and a complete isomorphism $h: C_0({\bf C}) \to C_0({\bf C})$ such that
 $h({\D})=E$ and $\|h- Id\|_{cb} <\vp$ and also for convenience $\|h^{-1}- Id\|_{cb}<\vp$.
 Since ${\D}$ is f.d. $\limsup \|(f_n-g_n)_{|{\D}} \|_{cb} = 0$ by the first claim. By the two claims for any $0<\vp<1$ there is
           $N=N_\vp$ such that $\sup\nl_{n\ge N}\|(f_n-g_n)_{|{\D}} \|_{cb} \le \vp$ and also
           $\|{g^{-1}_n}_{|g_n({\D})} \|_{cb}\le (1-\vp)^{-1}$.
 Fix $n\ge N$.
 Let $x\in E$ with $\|x\|=1$. 
 Let $y= h^{-1} (x)\in {\D}$. 
 Then $1-\vp\le \|y\|\le 1+\vp$.
 We have $\|g_n(y)\|\ge (1-\vp)\|y\|   $ and $\|f_n(y)-f_n(x)\| \le \|y-x\| \le \vp $.
 It follows
 $$  \|f_n(x)\| \ge \|f_n(y)\|-\vp \ge \|g_n(y)\|-\vp  \|y\|-\vp\ge (1-\vp) \|y\| -\vp  \|y\|-\vp \ge   (1-2\vp)(1-\vp) -\vp.$$
 This shows that $\|{f^{-1}_n}_{|f_n(E)} \| \le [(1-2\vp)(1-\vp) -\vp]^{-1}$.\\
 An entirely similar reasoning with
 $x$ in the unit sphere of (say) $\B \otimes_{\min}  E$ shows the same upper bound
 for $ \|{f^{-1}_n}_{|f_n(E)} \|_{cb}$. Since this holds for any $n\ge N$ and any $\vp>0$   \eqref{chy4} alias \eqref{cond} follows. 
   \end{proof}
          We can now apply the results of the preceding section to the case when $C=C_0(\C)$ or $C=C(\C)$:
          there is clearly an embedding $\C \subset \B$, and it is easy to show that there is a separable $C^*$-subalgebra  $B\subset \B$ 
          with WEP that contains $\C$. Let $j: \C \to B$ be the inclusion map.
          Since $B$ is separable we also have a surjective $*$-homomorphism $q: \C \to B$, whence $F= \rho_{[\infty]}  j_0: C_0(\C) \to \cl L (C_0(\C))$.  
        The passage to the cone algebras is harmless:
        $C_0(\C)$ has the LP and $C_0(B) $ the WEP, i.e. is $\C$-nuclear.
        A fortiori the map $F$ is $\C$-nuclear.
        We are thus in a position to apply Theorem \ref{ty}.

        \begin{thm} \label{ty'} In the situation just described
       there is an inductive system associated to the map $F : C_0(\C) \to \cl L (C_0(\C))$
        for which the associated $C^*$-algebra $A$ has the WEP and the LLP
        but is not nuclear. Moreover, $A$ locally embeds in $\C$.
        \end{thm}
          \begin{proof}

          We apply Theorem \ref{ty} 
          with $C=C_0(\C)$ to the map $F= \rho_{[\infty]}  j_0: C_0(\C) \to \cl L (C_0(\C))$
          derived above from the coexistence of $j$ and $q$ (or of $j_0$ and $q_0$) on $\C$.
          By Lemma \ref{ju18}, the condition \eqref{cond} holds. By Proposition \ref{pch10} the algebra $A$ locally embeds in $C_0(\C)$ which itself
          locally embeds in $\C$ (see Remark \ref{ju17}). By Proposition \ref{pch3}
          $A$ has the LLP.
         We use $D=\C$ in Theorem \ref{ty}. Then $A$ is $\C$-nuclear which means it has the WEP.

         Let us now show how to make sure that $A$ is {\it not} nuclear.
         For that purpose we choose for $E_0$ a suitable subspace of $C_0(\C)$,
         for instance we can select $E_0$ linearly spanned by
         $(t\otimes U_1,\cdots , t \otimes U_d)$ where $(U_1,\cdots ,  U_d)$ are a $d$-tuple
         of free unitary generators of $\F_\infty$ viewed as unitaries in $\C$ (here $t$ means abusively the function $t\mapsto t$ on $[0,1]$). 
         It is known (see \cite[Th. 21.5, p. 336]{P4}) that for any
         subspace $S$ of a nuclear $C^*$-algebra we have
         $$d_{cb} (E_0, S) \ge d/2\sqrt{d-1}.$$
         When $d\ge 3$           we have $d/2\sqrt{d-1} >1.$
         Thus by \eqref{echy5}
          to show that $A$ is not nuclear with this choice of $E_0$  it suffices to choose
           our sequence $(\vp_n)$  so that $(1+\eta_1)^2 < d/2\sqrt{d-1}$.
          See Remark \ref{rchle} below for an alternate argument. 
   \end{proof}
          \begin{rem}[Unital variant] Let $\tilde j_0: C(\C) \to C(B)$ be the unital extension of $j_0$. 
          Let $$\tilde F=   \tilde \rho_{[\infty]}    \tilde j_0 : C(\C) \to \L (C(\C) ) .$$
          Let $f=(f_n)$ be a unital c.c. (and c.p.) lifting of $\tilde F$. Then if we start
          by a unital subspace $E_0$, the construction produces unital algebras $Z$ and $A$.
           \end{rem}
           \begin{rem}[How to ensure that $\C$ locally embeds in $A$]\label{rchle} In the construction of the inductive system we may always enlarge
           $E_n$ at any step and then the next steps must of course be modified
           accordingly. Thus, if $S_n\subset C_0(\C)$ is any sequence of  f.d.s.a. subspaces
           that is dense for the $d_{cb}$ distance in the space of f.d.s.a. subspaces of $C_0(\C)$,
           we may define 
           $E_n= T_n(E_{n-1})+T_n(E_{n-1})T_n(E_{n-1}) +S_{n}$
           for each $n\ge 1$. Then
           \eqref{echy5} shows that we have a subspace $A'_n \subset A_n$
           corresponding to $S_n \subset  E_n$
           such that $d_{cb} (S_n,A'_n)\le (1+\eta_{n+1})^2.$
           If we use a sequence $(S_n)$ 
         where each of the original $S_n$'s
           is repeated infinitely many times, this shows that for the resulting system 
          $C_0(\C)$ and hence  $\C$ itself locally embeds
           in $A$.
        \end{rem}





        \section{Appendix}

        \begin{lem} Let $A$ be a $C^*$-algebra that locally embeds in $\C$.
        Then $A$ has the LLP if and only $A$ is $j$-nuclear, 
        where $j: \C \to B$ is any given $*$-homomorphism from $\C$ to a
      $C^*$-algebra $B$ with   WEP.
        \end{lem}
        \begin{proof} The only if part is obvious. To show the if part, assume that
        $A$ is $j$-nuclear.
Let $u: A \to  C/\cl I$ be a c.p.c.c. map.
Since $Id_A$ is $j$-nuclear, the map $j \otimes u$
is a contraction from $\C \otimes_{\min} A \to B \otimes_{\max}C/\cl I$.
Let $E\subset A$ be a f.d. subspace. 
        Let $t\in E^*\otimes A$
        be the tensor associated to the inclusion map $E\to A$. 
        We have $\|t\|_{\min}=1$.         Recall that $E^*$ always locally embeds in $\C$ when $E$ does (see \cite[Lem. 21.10 p. 339]{P4}).
        Therefore there is   a c.i. embedding 
        $k: E^*\to \C $. We have $[k \otimes Id_A ](t) \in  \C \otimes A$ with $\|[k \otimes Id_A] (t)\|_{\min} =1$.
After composing with $j$, we find 
        $\|[jk \otimes Id_A](t) \|_{\max} \le 1$, and since c.p.c.c. maps between $C^*$-algebras preserve the max norm,
        we have $\|[jk \otimes u](t) \|_{\max} \le 1$.
        Here $t'=[jk \otimes u](t)  \in jk(E^*) \otimes_{\max} C/\cl I \subset  B\otimes_{\max} C/\cl I$.
        By the projectivity of the max-tensor product,
      there is an element $s$ in the unit ball of $ jk(E^*) \otimes_{\max} C \subset B \otimes_{\max} C$ lifting $t'$, meaning,
   denoting by $q: C \to C/\cl I$ the quotient map,
   that $t'=[Id \otimes q](s)$. A fortiori $\|s\|_{\min} \le 1$.
   Since $jk$ is c.i. we recover from $s$ an element $\hat t$  in the unit ball of $E^* \otimes_{\min} C $, such that $[Id \otimes q] (\hat t)
=t$. Let $v: E \to C$ be the linear map associated to $\hat t$.
Then $v$ lifts the inclusion $u_{|E}$ and $\|v\|_{cb}=1$.
This yields the LLP for $A$.
 \end{proof}


