	\title{\textbf{General large deviations and functional iterated logarithm law for multivalued McKean-Vlasov stochastic differential equations}}

	\author{Lingyan Cheng$^\sharp$, Wei Liu$^\dag$, Huijie Qiao$^\ddag$ and Fengwu Zhu$^\dag$}
	\affil{$^\sharp$  School of Mathematics and Statistics, Nanjing University of Science and Technology,
