	\maketitle

	\noindent{\bf Abstract}
	\quad In this paper, we present sufficient conditions and criteria to establish general large and moderate deviation principles for multivalued McKean-Vlasov stochastic differential equations (SDEs in short) by means of the weak convergence approach, under non-Lipschit assumptions on the coefficents of the equations. Furthermore, by applying the large deviation estimates we obtain the functional iterated logarithm law for the solutions of multivalued McKean-Vlasov SDEs.
	\vskip0.3cm

	%  Keyword is required.
	\noindent {\bf Keywords}{\quad Multivalued operator, McKean-Vlasov SDE, Large deviations, Weak convergence method, Functional iterated logarithm law.}

	\noindent{{\bf Mathematics Subject Classification (2020)} 60F10 · 60H10.}
	\vskip0.3cm

	%\noindent {\bf Mathematics Subject Classification (2000)}{ 60E15; 60H15.}
