	Given $T>0$, let
	\begin{equation}\label{kd}
		\mathcal{V}=\left\{K\in C([0,T],\mathbb{R}^{d}):\, K \text{ is of finite variation and }K_{0}=0 \right\}.
	\end{equation}
	For any $K\in \mathcal{V}$ and $t\in [0,T]$, denote the variation of $K$ on $[0,t]$ by $|K|_{0}^{t}$ and  $|K|_{TV}:=|K|_{0}^{T}$. We introduce the following set of functions pair:
	\begin{align*}
		\mathcal{A}:=&\big\{(X,K):X\in C\left([0,T],\overline{D(A)}\right),K\in \mathcal{V}\;\text{and}
		\\
		\phantom{=\;\;}&\text{for all}\;(x,y)\in Gr(A),\langle X_{t}-x,dK_{t}-ydt \rangle\geq0 \big\}.
	\end{align*}

	It is known from \cite{CHM,cepa1} that for any pairs of $(X_{t},K_{t}), (\tilde{X}_{t},\tilde{K}_{t})\in \mathcal{A}$,
	\begin{equation}\label{mono}
		\langle X_{t}-\tilde{X}_{t},\mathrm{d}K_{t}-\mathrm{d}\tilde{K}_{t}\rangle\geq 0.
	\end{equation}

	We recall the following results due to C\'epa \cite{cepa1}, which will be used in the proofs in Section 4.
	\begin{proposition}\label{multi}
		Assume that Int$(D(A))\neq \emptyset$. For any $a\in$ Int$(D(A))$, there exist three positive constants $\lambda_{1}$, $\lambda_{2}\,\text{and}\, \lambda_{3}$ such that for any $(X,K)\in\mathcal{A}$ and $0\leq s<t\leq T$,
		\begin{equation}
			\int_{s}^{t}\langle X_{r}-a,\mathrm{d}K_{r}\rangle_{\mathbb{R}^{d}}\geq \lambda_{1}|K|_{t}^{s}-\lambda_{2}\int_{s}^{t}|X_{r}-a|\mathrm{d}r-\lambda_{3}(t-s),
		\end{equation}
		where $|K|_{s}^{t}$ denotes the total variation of $K$ on $[s,t]$.
	\end{proposition}


	\begin{proposition}\label{kcon}
		Let $\left\{K^n,\,n\in\mathbb{N}\right\}\in \mathcal{V}$ converge to some $K$ in $C([0,T],\mathbb{R}^d)$. If $\sup_{n\in\mathbb{N}}|K^n|_{TV}\leq \infty$, then $K\in \mathcal{V}$ and for any $X^n\in C([0,T],\mathbb{R}^d)$ converging to $X$ in $C([0,T],\mathbb{R}^d)$,
		\begin{align}
			\lim\limits_{n\to\infty}\int_{0}^{T}\langle X_s^n,\mathrm{d}K_s^n\rangle=\int_{0}^{T}\langle X_s,\mathrm{d}K_s\rangle.
		\end{align}
	\end{proposition}



	\begin{remark}
		If A is a monotone operator and $\alpha>0$, then $(I+\alpha A)^{-1}$ is a Lipschitz function on $\mathbb{R}^d$ with Lipschitz constant equal to 1. Denote $J^\alpha:=(I+\alpha A)^{-1}$ and define the Yosida approximation of the operator $A$ as
		\begin{equation}\label{yosida}
			A^\alpha(x):=\frac{1}{\alpha}\left(x-J^\alpha(x)\right), \quad x\in\mathbb{R}^d.
		\end{equation}
		Then $A^\alpha(x)$ is monotonic and Lipschitz continuous with Lipschitz constant $\frac{1}{\alpha}$. Moreover, for every $x\in\mathbb{R}^d$ we have
		\begin{align}\label{yosidap}
			A^\alpha(x)\in A(J^\alpha(x))
		\end{align}
		and for every $x\in D(A)$, as $\alpha\to 0$,
		\begin{align}\label{yosi0}
			A^\alpha(x)\to A^0(x) \,\,\,\,\text{and}\,\,\,\,|A^\alpha(x)|\to |A^0(x)|,
		\end{align}
		where $A^0(x)$ is called the minimal section of $A$ and $|A^0(x)|<\infty.$
	\end{remark}



