	\subsection{Solutions to multivalued Mckean-Vlasov SDEs}

	\begin{definition}\label{strong}
		(\textbf{Strong solution}) A pair of $\mathcal{F}_t$-adapted processes $(X,K)$ is said to be a strong solution of equation (\ref{mve}) with the initial value $x$, if $(X,K)$ is defined on a filtered probability space $(\Omega,\mathcal{F},\{\mathcal{F}_t\}_{t\geq0},P)$ such that
		\begin{enumerate} [(i)]
			\item $P(X_0=x)=1$,
			\item $X_t\in \mathcal{F}^W_t$, where $\left\{\mathcal{F}^W_t\right\}_{t\in[0,T]}$ stands for the $\sigma$-field filtration generated by $W$,
			\item $(X_.(\omega),K_.(\omega)\Big)\in\mathcal{A}$$\,\, P\text{-a.s.}$,
			\item it holds that
			\begin{align*}
				\int_{0}^{t}\left(|b(X_{s},\mathcal{L}_{X_{s}})|+\lVert\sigma(X_{s},\mathcal{L}_{X_{s}})\rVert^{2}\right)\mathrm{d}s <\infty, \quad P\text{-a.s.}
			\end{align*}
			and
			\begin{align*}
				X_{t}=x-K_{t}+\int_{0}^{t}b(X_{s},\mathcal{L}_{X_{s}})\mathrm{d}s+\int_{0}^{t}\sigma(X_{s},\mathcal{L}_{X_{s}})\mathrm{d}W_{s}, \quad \forall t\in[0,T].
			\end{align*}
		\end{enumerate}
	\end{definition}


	\begin{definition}\label{solu}
		(\textbf{Weak solution}) We say that (\ref{mve}) admits a weak solution with intial law $\mathcal{L}_{\tilde{X}_0}\in \mathcal{P}(\mathbb{R}^d)$ if there exists a stochastic basis $\tilde{\mathcal{S}}:=(\tilde{\Omega},\tilde{\mathcal{F}},\{\tilde{\mathcal{F}}_t\}_{t\geq0},\tilde{P})$, a d-dimensional standard $\tilde{\mathcal{F}}_t$-Brownian motion $(\tilde{W}_t)_{t\geq0}$ as well as a pair of continuous and $\tilde{\mathcal{F}}_t$-adapted processes $(\tilde{X},\tilde{K})$ defined on $\tilde{\mathcal{S}}$ such that
		\begin{enumerate} [(i)]
			\item $\tilde{X}_0$ has the initial law $\mathcal{L}_{\tilde{X}_0}$ and $\left(\tilde{X}_{.}(\omega),\tilde{K}_{.}(\omega)\right)\in \mathcal{A}$, $\,\,\, \tilde{P}\text{-a.s.}$,
			\item it holds that
			\begin{align*}
				\int_{0}^{t}\left(|b(\tilde{X}_{s},\mathcal{L}_{\tilde{X}_{s}})|+\lVert\sigma(\tilde{X}_{s},\mathcal{L}_{\tilde{X}_{s}})\rVert^{2}\right)\mathrm{d}s <\infty,\quad \tilde{P}\text{-a.s.},
			\end{align*}
			\item
			$$\tilde{X}_{t}=\tilde{X}_{0}-\tilde{K}_{t}+\int_{0}^{t}b(\tilde{X}_{s},\mathcal{L}_{\tilde{X}_{s}})\mathrm{d}s+\int_{0}^{t}\sigma(\tilde{X}_{s},\mathcal{L}_{\tilde{X}_{s}})\mathrm{d}\tilde{W}_{s}, \quad \forall t\in[0,T],$$
			where $\mathcal{L}_{\tilde{X}_{s}}=\tilde{P}\circ \tilde{X}_{s}^{-1}.$
		\end{enumerate}
	\end{definition}


	\begin{definition}\label{lawuni}
		(Uniqueness in Law ) Let $ (S;W,(X,K)) $ and $ (\widetilde{S};\widetilde{W},(\widetilde{X},\widetilde{K})) $ be two weak solutions with the same initial law $ \mathcal{L}_{X_{0}}=\mathcal{L}_{\widetilde{X}_{0}} $. The uniqueness in law is said to hold for (\ref{mve}) if $ (X,K) $ and $ (\widetilde{X},\widetilde{K}) $ have the same law.
	\end{definition}

	\begin{definition}\label{pathuni}
		(Pathwise Uniqueness) Let $ (S;W,(X,K)) $ and $ (S;W,(\widetilde{X},\widetilde{K})) $ be two weak solutions with $ X_{0}=\widetilde{X}_{0} $. The pathwise uniqueness is said to hold for (\ref{mve}) if for all $ t\in[0,T] $, $ (X_{t},K_{t})=(\widetilde{X}_{t},\widetilde{K}_{t}) $.
	\end{definition}



	Let $\mathcal{P}_2(\mathbb{R}^d)$ be the set of all probability measures on $(\mathbb{R}^d,\mathcal{B}(\mathbb{R}^d))$ with finite second moments. $\mathcal{P}_2(\mathbb{R}^d)$ is a Polish space equipped with $L^2$ Wasserstein distance defined by
	$$\mathbb{W}_{2}(\mu,\nu):=\inf\limits_{\xi\in \Pi(\mu,\nu)}\left(\iint_{\mathbb{R}^d\times\mathbb{R}^d}|x-y|^{2} \xi(\mathrm{d}x,\mathrm{d}y)\right)^{\frac{1}{2}},\ \ \forall \mu,\ \nu\in \mathcal{P}_2(\mathbb{R}^d)$$
	where $\Pi(\mu,\nu)$ is the set of all couplings of $\mu,\nu$, i.e. the set of all probability measures on $\mathbb{R}^d\times\mathbb{R}^d$ with marginal distributions $\mu$ and $\nu$. It is well known that $\mathbb{W}_{2}$ is a complete metric on $\mathcal{P}_2(\mathbb{R}^d)$.

	\begin{remark}\label{W2}
		From the definition above we know that for any $\mathbb{R}^{d}$-valued random variables $X$ and $Y$,
		$$\mathbb{W}_{2}\left(\mathcal{L}_{X},\mathcal{L}_{Y}\right)\leq \left[\mathbb{E}(X-Y)^{2}\right]^{\frac{1}{2}},$$ which will be used in the proofs later.
	\end{remark}

	Next we give the notations of martingale solutions. For $t\in[0,T]$, let
	\begin{align*}
		&\mathcal{W}:=C([0,T],\mathbb{R}^d)\times C([0,T],\mathbb{R}^d),\quad \mathbf{W}=\mathcal{B}(\mathcal{W}), \\
		&\mathcal{W}_t:=C([0,t],\mathbb{R}^d)\times C([0,t],\mathbb{R}^d),\quad \overline{\mathbf{W}}_t=\bigcap_{s>t}\mathcal{B}(\mathcal{W}_s).
	\end{align*}

	Denote the partial derivative operator as $\nabla:=\Big(\frac{\partial}{\partial x_1},\cdots,\frac{\partial}{\partial x_d}\Big)$ and the second partial derivate operator as $\nabla^2:=\Big(\frac{\partial^2}{\partial x_i\partial x_j}\Big)_{1\leq i,j\leq d}$. Let $C_b^2(\mathbb{R}^d)$ be the collection of all continuous functions which have bounded, continuous partial derivatives of every order up to 2.


	\begin{definition}\label{msolu}
		(\textbf{Martingale solution}) A probability measure $\mathbb{P}$ on $(\mathcal{W},\mathbf{W})$ is called a martingale solution of equation (\ref{mve}) with initial law $\mathcal{L}_{X_0}\in\mathcal{P}_2(\overline{D(A)})$ if $\mathbb{P}(\mathcal{A})=1$ and for each $f\in C_b^2(\mathbb{R}^d)$,
		\begin{align*}
			M_t^f:=&f(X_t)-f(X_0)+\int_{0}^{t}\langle\nabla f(X_s),\mathrm{d}K_s \rangle -\int_{0}^{t}\sum_{i} b_i(X_s,\mathcal{L}_{X_s})\nabla_i f(X_s)\mathrm{d}s \\
			&-\frac{1}{2}\int_0^t\sum_{i,j}( \sigma^*(X_s,\mathcal{L}_{X_s})\sigma(X_s,\mathcal{L}_{X_s}))_{ij}\nabla_{ij}^2f(X_s)\mathrm{d}s.
		\end{align*}
		is a $\overline{\mathbf{W}}_t$-adapted martingale, where $\mathcal{L}_{X_s}:=\mathbb{P}\circ X_s^{-1}$ denotes the law of $X_s$ under $\mathbb{P}$.
	\end{definition}





	\subsection{Large Deviation Principle}\label{ldp}

	We first give the definitions of the rate function and LDP. Let $\mathbb{S}$ be a Polish space and $\mathcal{B}(\mathbb{S})$ be the corresponding Borel $\sigma$-field.
	%and by $C([0,T],\mathbb{U})$ the continuous function space from $[0,T]$ to $\mathbb{U}$, and endow it with the uniform distance so that $C([0,T],\mathbb{U})$ is also a Polish space.

	\begin{definition} [Rate function]
		A function $I:\mathbb{S}\rightarrow[0,\infty]$ is called a rate function if for every $a<\infty$, the level set $\left\{g\in\mathbb{S}:I(g)\leq a\right\}$ is a closed subset of $\mathbb{S}$.  $I$ is said to be a good rate function if all the level sets defined above are compact subsets of $\mathbb{S}$.
	\end{definition}

	\begin{definition}[Large deviation principle]\label{ldpdefin} Let $I$ be a rate function on $\mathbb{S}$. Given a collection $\{\hbar(\epsilon)\}_{\epsilon>0}$ of
		positive reals, a family $\left\{X^{\epsilon}\right\}_{\epsilon>0}$ of $\mathbb{S}$-valued random variables is said to satisfy the LDP on $\mathbb{S}$ with speed $\hbar(\epsilon)$ and rate function $I$ if the following two claims hold.
		\begin{itemize}
			\item[(a)]
			(Upper bound) For each closed subset $C$ of $\mathbb{S},$
			$$
			\limsup_{\epsilon \rightarrow 0} \hbar(\epsilon) \log {P}\left(X^{\epsilon} \in C\right) \leq - \inf_{x \in C} I(x).
			$$
			\item[(b)] (Lower bound) For each open subset $O$ of $\mathbb{S},$
			$$
			\liminf_{\epsilon \rightarrow 0} \hbar(\epsilon) \log {P}\left(X^{\epsilon} \in O\right) \geq - \inf_{x \in O} I(x).
			$$
		\end{itemize}
	\end{definition}	
	%With the fundamental result about the existence and uniqueness of strong solution to multivalued stochasitic Mckean-Vlasov equation, now we are able to state precisely the goal of this paper.

	Next we recall a general criterion for laplace principle, which is equivalent to the LDP with the same rate function through the weak convergence approach (see \cite{BD2000,BDM2008,zhang}).

