	Let $\left\{\mathcal{G}^{\epsilon}\right\}_{\epsilon>0}$ be a family of measurable maps from $C([0,T],\mathbb{R}^d)$ to $\mathbb{S}$, and $X^\epsilon=\mathcal{G}^{\epsilon}(\sqrt{\epsilon}W)$. Next we introduce the following conditions which will be sufficient to establish the large and moderate deviation principles for $\left\{X^{\epsilon}\right\}_{\epsilon>0}$.

	\begin{assumption}\label{assumld}
		There exists a measurable map $\mathcal{G}^{0}:C([0,T],\mathbb{R}^d)\mapsto \mathbb{S}$ such that
		\begin{enumerate}
			\item[(\textbf{LD}$_{\bm{1}}$)] for any $m\in \mathbb{N}$ and $\left\{v_{n},n\in\mathbb{N}\right\}\subset \mathcal{S}_{m}$ satisfying that  $v_{n}$ converges to some $v\in \mathcal{S}_{m}$ as $n\rightarrow\infty$;
			$$\mathcal{G}^{0}\left(\int_{0}^{\cdot}v_{n}(s)\mathrm{d}s\right)\rightarrow\mathcal{G}^{0}\left(\int_{0}^{\cdot}v(s)\mathrm{d}s\right),$$
			\item[(\textbf{LD}$_{\bm{2}}$)] for any $m\in \mathbb{N}$ and $\left\{h_{\epsilon},\epsilon>0\right\}\subset\mathcal{D}_{m}$ satisfying that $h_{\epsilon}$  converges in distribution to some $h\in\mathcal{D}_{m}$ as $ \epsilon\rightarrow 0 $,
			$$\mathcal{G}^{\epsilon}\left(\sqrt{\epsilon}W+\int_{0}^{\cdot}h_{\epsilon}(s)\mathrm{d}s\right)\rightarrow \mathcal{G}^{0}\left(\int_{0}^{\cdot}h(s)\mathrm{d}s\right)\quad \quad \text{in distribution}.$$
		\end{enumerate}
	\end{assumption}

	For each $x\in\mathbb{S}$, define $\mathbb{V}_{x}=\left\{h\in L^{2}([0,T],\mathbb{R}^d):x=\mathcal{G}^{0}\left(\int_{0}^{\cdot}h(s)\mathrm{d}s\right)\right\}$ and
	\begin{equation}\label{rate}
		I(x):=\frac{1}{2}\inf\limits_{h\in\mathbb{V}_{x}}\int_{0}^{T}|h(s)|^{2}\mathrm{d}s,
	\end{equation}
	with the convention $\inf\{\emptyset\}=\infty$.


	We recall the following result due to \cite{BD2000} (see also \cite{BDM2008,BDM2011}).
	\begin{theorem}\label{ldlap}
		Under (\textbf{LD}$_{\bm{1}}$) and (\textbf{LD}$_{\bm{2}}$), $\left\{X^{\epsilon}\right\}_{\epsilon>0}$ satisfies the Laplace principle with  the rate function $I$. More precisely, for each real bounded continuous function $ f $ on $ \mathbb{S} $,
		\begin{equation}
			\lim\limits_{\epsilon\rightarrow 0}\epsilon\, \log\,\mathbb{E}^{\mu}\left(\exp[-f(X^{\epsilon})/\epsilon]\right)=-\inf\limits_{x\in\mathbb{S}}\left\{f(x)+I(x)\right\}.
		\end{equation}
		In particular, the family of $\left\{X^{\epsilon}\right\}_{\epsilon>0}$ satisfies the LDP in $(\mathbb{S},\mathcal{B}(\mathbb{S}))$ with speed $\epsilon$ and rate function $I$.
	\end{theorem}


