	\subsection{Large deviation principle}

	\begin{proposition}\label{Yu}Assume that (\hyperref[h0]{\textbf{H0}}), (\hyperref[h1]{\textbf{H1}}) and (\hyperref[h2]{\textbf{H2}}) hold. Then for any $ h\in \mathcal{S}_{m} $, there exists a unique process $ (Y^{h},K^h)=\left\{ (Y_{t}^{h},K_t^h), t\in\left[ 0, T \right] \right\} $ satisfying that
		\begin{enumerate}
			\item[(1)] $Y^{h}\in C\big( \left[ 0, T \right], \overline{D(A)} \big)$,
			\item[(2)] $$\int_{0}^{T} \left| b\left(Y_{s}^{h},\mathcal{L}_{X_{s}^{0}}\right) \right| \,\mathrm{d}s + \int_{0}^{T} \lvert \sigma\left(Y_{s}^{h},\mathcal{L}_{X_{s}^{0}}\right)h\left(s\right) \rvert \,\mathrm{d}s + \left| K^{h} \right|_{0}^{T} <\infty,$$
			\item[(3)]
			\begin{equation}\label{yy}
				Y_{t}^{h}=x+\int_{0}^{t}b\left( Y_{s}^{h},\mathcal{L}_{X_{s}^{0}}\right) \,\mathrm{d}s + \int_{0}^{t}\sigma\left( Y_{s}^{h},\mathcal{L}_{X_{s}^{0}}\right)h\left(s\right) \,\mathrm{d}s-K_{t}^{h},\quad t\in \left[0,T\right].
			\end{equation}
		\end{enumerate}

		Moreover, for any $m>0$,
		$$ \sup\limits_{h\in \mathcal{S}_{m}}\sup\limits_{t\in \left[0,T\right]}\left| Y_{t}^{h}\right| <\infty.$$
		%$Y^{h}$ is called the solution to the  equation (\ref{yy}) above.

	\end{proposition}
	\begin{proof} This result can be proved by using Proposition \ref{multi} presented in Section 2 and Proposition 3.7 in \cite{liuw}. We omit the tedious proofs here.\end{proof}



	Next we present our main result about the large deviation principle.
	\begin{theorem}\label{thmldp}
		Assume that (\hyperref[h0]{\textbf{H0}})-(\hyperref[h4]{\textbf{H4}}) hold, then the family of processes $ \left\{X_{t}^{\epsilon}, \epsilon >0, t\in[0,T]\right\} $ satisfies the LDP on $C\big(\left[0,T\right],\overline{D(A)}\big)$ with speed $\epsilon$ and the good rate function $I$ given by
		\begin{equation}
			I\left( g\right): = \frac{1}{2}\inf\limits_{\left\{h\in L^{2}([0,T],\mathbb{R}^d): g=Y^{h}\right\}}\int_{0}^{T}\lvert h(s)\rvert^2\,\mathrm{d}s,\quad g\in C\left(\left[0,T\right],\overline{D(A)}\right),
		\end{equation}
		where $Y^{h}$ is the solution to equation (\ref{yy}).
	\end{theorem}

	\begin{proof}
		By Proposition \ref{Yu} we can define a map $$ \mathcal{G}^{0}: \mathcal{S}_m\ni h\mapsto Y^{h} \in C\left(\left[0,T\right],\overline{D(A)}\right),$$ where $Y^{h}$ is the unique solution of eqution (\ref{yy}).

		For any $\epsilon >0$, $m\in \left(0,\infty\right)$ and $h_{\epsilon}\in \mathcal{D}_{m}$, by Lemma \ref{girs} there exists a unique solution $ \left\{Z_{t}^{\epsilon,h_{\epsilon}} ,t\in \left[0,T\right]\right\} $ to the following equation
		\begin{equation}\label{LDP}
			\mathrm{d}Z_{t}^{\epsilon,h_{\epsilon}}\in b_{\epsilon}\left(Z_{t}^{\epsilon,h_{\epsilon}},\mathcal{L}_{X_{t}^{\epsilon}}\right)\mathrm{d}t+ \sqrt{\epsilon}\sigma_{\epsilon}\left(Z_{t}^{\epsilon,h_\epsilon},\mathcal{L}_{X_{t}^{\epsilon}}\right)\mathrm{d}W_{t} + \sigma_{\epsilon}\left(Z_{t}^{\epsilon,h_\epsilon},\mathcal{L}_{X_{t}^{\epsilon}}\right)h_{\epsilon}\left(t\right)\mathrm{d}t-A_\epsilon\left(Z_{t}^{\epsilon,h_\epsilon}\right)\mathrm{d}t,
		\end{equation}
		where $Z_{0}^{\epsilon,h_{\epsilon}}=x$ is the initial value and $X^{\epsilon}$ is the solution to (\ref{per}).

		To establish the LDP by using Theorem \ref{ldlap}, it is sufficient to verify the following two conditions.


		\textbf{(LDP)$\bm{_{1}}$} For any given $m\in\left(0,\infty\right)$, if $\left\{h_{n}, n\in \mathbb{N}\right\}\subset \mathcal{S}_{m}$ weakly converges to $h\in \mathcal{S}_{m}$ as $n\to \infty$, then
		$$
		\lim\limits_{n\to \infty}\sup\limits_{t\in \left[0,T\right]}\lvert \mathcal{G}^{0}\left(h_{n}\right)\left(t\right)-\mathcal{G}^{0}\left(h\right)\left(t\right) \rvert=0;
		$$

		\textbf{(LDP)$\bm{_{2}}$} For any given $m\in\left(0,\infty\right)$, let $\left\{h_{\epsilon}, \epsilon>0\right\}\subset \mathcal{D}_{m}$, then
		$$
		\lim\limits_{\epsilon\to 0}\mathbb{E}\left(\sup\limits_{t\in \left[0,T\right]}\lvert Z^{\epsilon,h_\epsilon}_t-\mathcal{G}^{0}\left(h_{\epsilon}\right)\left(t\right)\rvert^{2}\right)=0.
		$$

		The verification of \textbf{(LDP)$\bm{_{1}}$} and \textbf{(LDP)$\bm{_{2}}$} will be given later in Section 4.2. Note that \textbf{(LDP)$\bm{_{2}}$} is stronger than (\textbf{LD}$_{\bm{2}}$) stated in Assumption \ref{assumld}.
	\end{proof}

	\subsection{Moderate deviation principle}

	Lemma \ref{girs} can also be used to establish the moderate deviation principle of $X^\epsilon$ as $\epsilon$ decreases to 0. Assume that $ \lambda(\epsilon)>0$ satisfies
	\begin{align}\label{lame}
		\lambda(\epsilon)\to 0, \quad \frac{\epsilon}{\lambda^2(\epsilon)}\to 0, \quad \text{as}\,\,\epsilon\to 0.
	\end{align}

	Define
	\begin{align*}
		M^{\epsilon}_t:=\frac{1}{\lambda(\epsilon)}(\bar{X}_t^\epsilon-X_t^0), \quad t\in[0,T],
	\end{align*}
	where $X^0_t$ solves equation (\ref{x0}), i.e.
	\begin{align*}
		\begin{cases}
			\,\,\mathrm{d}X_t^0\in\,\,b(X^0_t,\mathcal{L}_{X^0_t})\mathrm{d}t-A(X^0_t)\mathrm{d}t, \\
			\,\, X^0_0=x.
		\end{cases}
	\end{align*}
	Consider the following multivalued SDE
	\begin{align}\label{Mep}
		\begin{cases}
			\,\mathrm{d}M^{\epsilon}_t\in\,\frac{1}{\lambda(\epsilon)}\left(b_{\epsilon}(\bar{X}^\epsilon_t,\mathcal{L}_{\bar{X}_t^{\epsilon}})-b(X_t^0,\mathcal{L}_{X_t^0})\right)\mathrm{d}t+\frac{\sqrt{\epsilon}}{\lambda(\epsilon)}\sigma_{\epsilon}(\bar{X}_t^\epsilon,\mathcal{L}_{\bar{X}_t^{\epsilon}})\mathrm{d}W_t-A_\epsilon(M^{\epsilon}_t)\mathrm{d}t, \\
			\,
			M^{\epsilon}_0=0.
		\end{cases}
	\end{align}
	By Theorem \ref{strongsolu},  $(M^{\epsilon}_t,\bar{K}^\epsilon_t)$ is the unique solution to the following equation
	\begin{align}\label{mep}
		\mathrm{d}M^{\epsilon}_t=&\frac{1}{\lambda(\epsilon)}\left(b_{\epsilon}(\lambda(\epsilon)M^{\epsilon}_t+X^0_t,\mathcal{L}_{\bar{X}_t^{\epsilon}})-b(X_t^0,\mathcal{L}_{X_t^0})\right)\mathrm{d}t   \nonumber \\
		&+\frac{\sqrt{\epsilon}}{\lambda(\epsilon)}\sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon}_t+X_t^0,\mathcal{L}_{\bar{X}_t^{\epsilon}})\mathrm{d}W_t-\mathrm{d}\bar{K}^\epsilon_t.
	\end{align}

	% Assume that (\hyperref[a0]{\textbf{A0}}), (\hyperref[a1]{\textbf{A1}}) and (\hyperref[h3]{\textbf{H3}}) hold, recall the map $\mathcal{G}^\epsilon_{\mathcal{L}_{X^\epsilon}}$ defined in (\ref{zep}),

	To show the moderate deviation principle for $\bar{X}^\epsilon$, it is equivalent to prove that $M^\epsilon$ satisfies the LDP. Let $\nabla b(x,\mu)$ denote the gradient of $b(x,\mu)$ with respect to the space variable $x$.

	We make the following assumptions.

	\textbf{(B0)} There exist $L',q'\geq 0$ such that for all $x_1,x_2\in\mathbb{R}^{d}$, and $\mu_1,\mu_2\in\mathcal{P}_2(\mathbb{R}^d)$,
	\begin{align*}\label{b0}
		&\lVert\nabla b(x_1,\mu_1)-\nabla b(x_2,\mu_1)\rVert\leq L'(1+|x_1|^{q'}+|x_2|^{q'})|x_1-x_2|, \\
		&\langle x_1-x_2, b(x_1,\mu_1)-b(x_2,\mu_1) \rangle \vee \langle x_1-x_2, b_\epsilon(x_1,\mu_1)-b_\epsilon(x_2,\mu_1) \rangle\leq L'|x_1-x_2|^2, \\
		&|b(x_1,\mu_1)-b(x_1,\mu_2)|\leq L'\mathbb{W}_2(\mu_1,\mu_2), \\
		&|b(x_1,\mu_1)|\vee|b_\epsilon(x_1,\mu_1)|\leq L'(1+|x_1|+\lVert \mu_1\rVert_2).
	\end{align*}

	\textbf{(B1)} There exists $L_{\nabla b}>0$ such that
	\begin{align*}\label{b1}
		\int_{0}^{T}\lVert\nabla b(X^0_t,\mathcal{L}_{X^0_t})\rVert\mathrm{d}t<L_{\nabla b}.
	\end{align*}

	\textbf{(B2)} For $\rho_{b,\epsilon}$ given in (\hyperref[h2]{\textbf{H2}}) and $\lambda(\epsilon)$ satisfying (\ref{lame}), it holds that
	\begin{equation*}\label{b2}
		\begin{aligned}
			\lim\limits_{\epsilon\to 0}\frac{\rho_{b,\epsilon}}{\lambda(\epsilon)}=0.
		\end{aligned}
	\end{equation*}

	\textbf{(B3)}  There exists $L'>0$, such that for all $x_1,x_2\in\mathbb{R}^{d}$, and $\mu_1,\mu_2\in\mathcal{P}_2(\mathbb{R}^d)$,
	\begin{align*}\label{b3}
		& \lVert \sigma(x_1,\mu_1)-\sigma(x_2,\mu_2)\rVert^2\vee\lVert \sigma_\epsilon(x_1,\mu_1)-\sigma_\epsilon(x_2,\mu_2)\rVert^2\leq L'(|x_1-x_2|^2+\mathbb{W}^2_2(\mu_1,\mu_2)). \\
		&\lVert \sigma(x_1,\mu_1)\rVert^2 \vee \lVert \sigma_\epsilon(x_1,\mu_1)\rVert^2\leq L'(1+|x_1|^2+\lVert \mu_1\rVert_2^2).
	\end{align*}



