	\begin{proposition}\label{nu}
		Assume that (\hyperref[h1]{\textbf{H1}}), (\hyperref[h2]{\textbf{H2}}), (\hyperref[b0]{\textbf{B0}}) and (\hyperref[b1]{\textbf{B1}}) hold. Then for any fixed $m\in(0,\infty)$ and $\psi\in \mathcal{S}_m$, there is a unique solution $(\nu^\psi,\hat{K}^\psi)=\big\{\big(\nu^{\psi}_t,\hat{K}^\psi_t\big), t\in[0,T]\big\}$ to the following equation:
		\begin{equation}\label{mdp1}
			\left\{ \begin{aligned}
				&\mathrm{d}\nu^{\psi}_t=\nabla b(X^0_t,\mathcal{L}_{X^0_t})\nu^{\psi}_t\mathrm{d}t+\sigma(X_t^0,\mathcal{L}_{X_t^0})\psi(t)\mathrm{d}t-\mathrm{d}\hat{K}^\psi_t,    \\
				&\nu^{\psi}_0=0.
			\end{aligned}  \right.
		\end{equation}
		Moreover,
		\begin{align}\label{nulim}
			\sup_{\psi\in \mathcal{S}^{m}}\sup_{t\in[0,T]}|\nu^{\psi}_t|<\infty.
		\end{align}

		\begin{proof}
			Since $\big\{\hat{K}^\psi_t, t\in[0,T]\big\}$ is of finite variation with $\psi\in\mathcal{S}_m$, we have
			$|\hat{K}^\psi|_0^T<\infty.$

			By (\hyperref[h1]{\textbf{H1}}), (\hyperref[h2]{\textbf{H2}}), Remark \ref{W2} and the fact that $X^0\in C([0,T],\mathbb{R}^d)$ and $\psi\in\mathcal{S}_m$, we have
			\begin{align}\label{slim}
				\int_{0}^{T}\lVert \sigma(X_s^0,\mathcal{L}_{X_s^0})\rVert^2\mathrm{d}s<\infty.
			\end{align}
			Thus
			\begin{align}\label{si}
				\int_{0}^{T}\lvert\sigma(X_t^0,\mathcal{L}_{X_t^0})\psi(t)\rvert\mathrm{d}t  \nonumber
				\leq &\left(\int_{0}^{T}\lVert\sigma(X_t^0,\mathcal{L}_{X_t^0})\rVert^2\mathrm{d}t\right)^{\frac{1}{2}}\left(\int_{0}^{T}|\psi(t)|^2\mathrm{d}t\right)^\frac{1}{2}   \nonumber\\
				\leq &\left(\int_{0}^{T}\lVert\sigma(X_t^0,\mathcal{L}_{X_t^0})\rVert^2\mathrm{d}t\right)^{\frac{1}{2}}(2m)^{\frac{1}{2}}  \nonumber
				<\infty.
			\end{align}

			Due to (\hyperref[b1]{\textbf{B1}}) and the estimates above we can easily prove that the equation (\ref{mdp1}) has a unique solution $\big\{\big(\nu^{\psi}_t,\hat{K}^\psi_t\big), t\in[0,T]\big\}$.
			By Gronwall's inequality we have
			\begin{align}
				\nu^{\psi}_t\leq  e^{\int_{0}^{t}\nabla b(X_s^0,\mathcal{L}_{X_s^0})\mathrm{d}s}\int_{0}^{t}\sigma(X_s^0,\mathcal{L}_{X_s^0})\psi(s)\mathrm{d}s,
			\end{align}
			which implies (\ref{nulim}).

		\end{proof}

	\end{proposition}


