	\section{Proof of main results}

	\subsection{Proof of Theorem 3.4}

	First, we introduce the relationship between martingale solution and weak solution.

	\begin{proposition}\label{vv}
		The existence of martingale solutions implies the existence of weak solutions and vice versa.
	\end{proposition}

	Since the Proposition \ref{vv} above can be proved by the same way in \cite[Proposition 3.5]{Zalinescu}, we omit the detailed proofs here for brevity. To study the existence of martingale solution to equation (\ref{mve}), we first present the following lemmas. The first one is taken from \citep[Lemma 4.1]{CHM}.
	\begin{lemma}\label{kfcon}
		Let $\{\mathbb{P}_n\in\mathcal{P}(\mathcal{W})\}_{n\geq 1}$ be a sequence of probability measures converging weakly to $\mathbb{P}_0\in\mathcal{P}(\mathcal{W})$. Assume that $\mathbb{P}_n(\mathcal{A})=1$ and $\sup_{n\geq 1}\mathbb{E}^{\mathbb{P}_n}|K|^2_{TV}<\infty$, then $\mathbb{P}_0(\mathcal{A})=1$ and $\mathbb{E}^{\mathbb{P}_0}|K|^2_{TV}<\infty$. Moreover, for any bounded continuous functional $G$ on $\mathcal{W}$ and $f\in C^1_b(\mathbb{R}^d)$,
		\begin{align*}
			\lim\limits_{n\to\infty}\mathbb{E}^{\mathbb{P}_n}\left(G\int_{0}^{t}\langle\nabla f(X_s),\mathrm{d}K_s\rangle\right)=\mathbb{E}^{\mathbb{P}_0}\left(G\int_{0}^{t}\langle\nabla f(X_s),\mathrm{d}K_s\rangle\right).
		\end{align*}
	\end{lemma}

	 Denote $\tilde{\mathbb{E}}(\cdot):=\mathbb{E}^{\tilde{P}}(\cdot)$ the expectation under the probability measure $\tilde{P}$ introduced in the Definition \ref{solu}. We now state the second lemma.

	\begin{lemma}\label{l42}
		Assume that $b(x,\mu)$ and $\sigma(x,\mu)$ satisfy (\hyperref[h0]{\textbf{H0}}), (\ref{hblg}) and (\ref{hslg}). If $(\tilde{\mathcal{ S }};\tilde{W},(\tilde{X},\tilde{K}))$ is a weak solution to the equation (\ref{mve}), $\mathcal{L}_{\tilde{X}_0}\in\mathcal{P}({\overline{D(A)}})$ and $\tilde{\mathbb{E}}|\tilde{X}_0|^{2p}<\infty$ for any $p>1$, then it follows that
		\begin{align}\label{l421}
			\tilde{\mathbb{E}}(\sup_{t\in[0,T]}|\tilde{X}_t|^{2p}+(|\tilde{K}|_0^T)^{p})<\infty
		\end{align}
and
		\begin{align}\label{l422}
			\tilde{\mathbb{E}}(|\tilde{X}_t-\tilde{X}_s|^{2p}+(|\tilde{K}|_s^t)^{p})\leq C(t-s)^p,\quad 0\leq s<t\leq T,
		\end{align}
		where $C>0$ is some constant depending on $T,p,L$.
	\end{lemma}

	\begin{proof}
		By using the truncation approach to $\tilde{X}_t$ and applying Fatou's Lemma, we may assume that $\tilde{X}_t$ is bounded without loss of generality.

		For the equation (\ref{mve}), since $0\in \text{Int}D(A)$, by Proposition \ref{multi} and It\^o's fomula we have
		\begin{align*}
			|\tilde{X}_t|^{2}=&\,|\tilde{X}_0|^{2}-2\int_{0}^{t}\langle \tilde{X}_s, \mathrm{d}\tilde{K}_s\rangle + 2\int_{0}^{t}\langle \tilde{X}_s, b(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s})\rangle\mathrm{d}s \\
			&\,+ 2\int_{0}^{t}\langle \tilde{X}_s, \sigma(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s})\mathrm{d}\tilde{W}_s\rangle + \int_{0}^{t} \lVert \sigma(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s}) \rVert^2\mathrm{d}s \\
			\leq &\, |\tilde{X}_0|^{2}-2\lambda_{1}|\tilde{K}|_0^t + C\int_{0}^{t}\left(1+|\tilde{X}_s|^2+\mathbb{E}|\tilde{X}_s|^2\right)\mathrm{d}s + 2\int_{0}^{t}\langle \tilde{X}_s, \sigma(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s})\mathrm{d}\tilde{W}_s\rangle.
		\end{align*}
		By taking expectations on the both sides of the inequality above, we get
		\begin{align*}
			\tilde{\mathbb{E}}|\tilde{X}_t|^{2}\leq\, \tilde{\mathbb{E}}|\tilde{X}_0|^{2}+C\int_{0}^{t}\left(1+\tilde{\mathbb{E}}|\tilde{X}_s|^2\right)\mathrm{d}s,
		\end{align*}
		which implies $\sup_{t\in[0,T]}\tilde{\mathbb{E}}|\tilde{X}_t|^{2}<\infty$ by Gronwall's inequality.

		By BDG inequality and Young's inequality, for any $t\in[0,T]$, it holds that
		\begin{align*}
			&\tilde{\mathbb{E}}\left(\sup_{s\in[0,t]}|\tilde{X}_s|^{2p}+(|\tilde{K}|_0^t)^p\right)\\
\leq &\, C\tilde{\mathbb{E}}|\tilde{X}_0|^{2p}+C\tilde{\mathbb{E}}\left(\int_{0}^{t}\left(1+|\tilde{X}_s|^2+\tilde{\mathbb{E}}|\tilde{X}_s|^2\right)\mathrm{d}s\right)^p  +C\tilde{\mathbb{E}}\left(\int_{0}^{t}\langle \tilde{X}_s, \sigma(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s})\mathrm{d}\tilde{W}_s\rangle\right)^p \\
			\leq&\, C\tilde{\mathbb{E}}|\tilde{X}_0|^{2p}+C+Ct^{p-1}\int_{0}^{t}\tilde{\mathbb{E}}|\tilde{X}_s|^{2p}\mathrm{d}s+C\tilde{\mathbb{E}}\left(\int_{0}^{t}|\tilde{X}_s|^2\lVert\sigma(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s}) \rVert^2\mathrm{d}s\right)^{\frac{p}{2}} \\
			\leq&\, C+Ct^p+\frac{1}{2}\tilde{\mathbb{E}}\sup_{s\in[0,t]}|\tilde{X}_s|^{2p}+Ct^{p-1}\int_{0}^{t}\tilde{\mathbb{E}}|\tilde{X}_s|^{2p}\mathrm{d}s,
		\end{align*}
		where $C$ depends on $T,p,L$. This implies (\ref{l421}) by directly using Gronwall's inequality.

		%		For equation (\ref{mve}), by Jensen's inequality, H\"older's inequality and BDG inequality, for any $t\in[0,T]$, it holds that
		%		\begin{align*}
			%			&\tilde{\mathbb{E}}|\tilde{X}_t|^{2p}+\tilde{\mathbb{E}}(|\tilde{K}|_0^t)^{2p}\leq 3^{2p-1}\left(\tilde{\mathbb{E}}|\tilde{X}_0|^{2p}+\tilde{\mathbb{E}}|\int_{0}^{t}b(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s})\mathrm{d}s|^{2p}+\tilde{\mathbb{E}}|\int_{0}^{t}\sigma(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s})\mathrm{d}\tilde{W}_s|^{2p}\right) \\
			%			\leq& 3^{2p-1}\left(\tilde{\mathbb{E}}|\tilde{X}_0|^{2p}+\tilde{\mathbb{E}}|\int_{0}^{t}b(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s})\mathrm{d}s|^{2p}+\left(p(2p-1)\right)^p\tilde{\mathbb{E}}\left(\int_{0}^{t}\lVert\sigma(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s})\rVert^2\mathrm{d}s\right)^p\right) \\
			%			\leq& 3^{2p-1}\left(\tilde{\mathbb{E}}|\tilde{X}_0|^{2p}+t^{2p-1}\left(\int_{0}^{t}\tilde{\mathbb{E}}|b(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s})|^{2p}\mathrm{d}s\right)\right) \\
			%			&+3^{2p-1}\left(\left(p(2p-1)\right)^pt^{p-1}\left(\int_{0}^{t}\tilde{\mathbb{E}}\lVert\sigma(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s})\rVert^{2p}\mathrm{d}s\right)\right) \\
			%			\leq& C\left(\tilde{\mathbb{E}}|\tilde{X}_0|^{2p}+\int_{0}^{t}\tilde{\mathbb{E}}\left(|b(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s})|^{2p}+\lVert\sigma(\tilde{X}_s,\mathcal{L}_{\tilde{X}_s})\rVert^{2p}\right)\mathrm{d}s\right) \\
			%			\leq& C\left(1+\tilde{\mathbb{E}}|\tilde{X}_0|^{2p}+\int_{0}^{t}\tilde{\mathbb{E}}|\tilde{X}_s|^{2p}\mathrm{d}s\right),
