		%		where $C$ is depend on $T,p,L$. Then by Gronwall's inequality, we have (\ref{l421}).

		By the same deduction, for any $t\in[0,T]$ we get
		\begin{align*}
			&\tilde{\mathbb{E}}|\tilde{X}_t-\tilde{X}_s|^{2p}+\tilde{\mathbb{E}}(|\tilde{K}|_s^t)^{p}\\
\leq&\, C\tilde{\mathbb{E}}\left(\int_{s}^{t}\left(1+|\tilde{X}_r|^2+\mathbb{E}|\tilde{X}_r|^2\right)\mathrm{d}r\right)^p+C\tilde{\mathbb{E}}\left(\int_{s}^{t}\langle \tilde{X}_r, \sigma(\tilde{X}_r,\mathcal{L}_{\tilde{X}_r})\mathrm{d}\tilde{W}_r\rangle\right)^p \\
			\leq&\, C(t-s)^p,
		\end{align*}
		which completes the proof.

	\end{proof}

	Next we will show the existence of the martingale solution.

	\begin{proposition}\label{magl}
		Assume that the assumptions (\hyperref[h0]{\textbf{H0}}), (\ref{hblg}) and (\ref{hslg}) hold. If $\mathcal{L}_{X_0}\in\mathcal{P}({\overline{D(A)}})$ and $\mathbb{E}|X_0|^{2p}<\infty$ with $p>1$, then  there exists a martingale solution to the equation (\ref{mve}).
	\end{proposition}

	\begin{proof}
		For any fixed $n\in\mathbb{N}$, consider the following  Euler-Maruyama approximation equation:
		\begin{align*}
			\mathrm{d}X_t^n\in -A(X_t^n)+b(X^n_{t_n},\mathcal{L}_{X^n_{t_n}})\mathrm{d}t+\sigma(X^n_{t_n},\mathcal{L}_{X^n_{t_n}})\mathrm{d}W_t,\quad X^n_0=X_0,
		\end{align*}
		where $t_n=2^{-n}[2^nt]$ and $[a]$ denotes the integer part of a real number $a$. By solving a deterministic Skorohod problem, this equation can be solved step by step. That implies that there exists $(X^n,K^n)\in \mathcal{A}$ such that
		\begin{align}\label{emsolu}
			X_t^n=X_0-K_t^n+\int_{0}^{t}b(X_{s_n}^n,\mathcal{L}_{X_{s_n}^n})\mathrm{d}s+\int_{0}^{t}\sigma(X_{s_n}^n,\mathcal{L}_{X_{s_n}^n})\mathrm{d}W_s.
		\end{align}
		By Lemma \ref{l42} and the assumption $\mathbb{E}|X_0|^{2p}<\infty$, we have
		\begin{align}\label{l4b}
			&\sup_{n\in\mathbb{N}}\mathbb{E}(\sup_{t\in[0,T]}|X_t^n|^{2p})+\sup_{n\in\mathbb{N}}\mathbb{E}(|K^n|_0^T)^{p}< \infty, \\
			&\sup_{n\in\mathbb{N}}\mathbb{E}|X_t^n-X_s^n|^{2p}\leq C(t-s)^p,\quad 0\leq s<t\leq T.
		\end{align}

		By \citep[theorem 3.2]{Zalinescu} we deduce that $(X^n,K^n)_{n\in\mathbb{N}}$ is tight in $\mathcal{W}$. Let $\mathbb{P}_n:=\tilde{P}\circ(X^n,K^n)^{-1}$, then there exists a subsequence (still denoted by $\mathbb{P}_n$) and $\mathbb{P}_0\in \mathcal{P}(\mathcal{W})$ such that $\mathbb{P}_n$ weakly converges to $\mathbb{P}_0$. By Lemma \ref{kfcon}, we have
		\begin{align*}
			\mathbb{P}_0(\mathcal{A})=1.
		\end{align*}
		To complete the proof, it suffices to show that for each $f\in C_b^2(\mathbb{R}^d)$, $M_t^f$ is a continuous $\overline{\mathbf{W}}_t$-martingale under $\mathbb{P}_0$. Specifically, we only need to verify that for any $0\leq s<t\leq T$ and bounded $\overline{\mathbf{W}}_s$-measurable functional $G$ on $\mathcal{W}$,
		\begin{align*}
			\mathbb{E}^{\mathbb{P}_0}\left( (M_t^f(X,K)-M_s^f(X,K))G\right)=0.
		\end{align*}

		Let
		\begin{align*}
			M_t^{n,f}:=&f(X_t)-f(X_0)+\int_{0}^{t}\langle \nabla f(X_s),\mathrm{d}K_s\rangle-\sum_{i}\int_{0}^{t}b_i(X_{s_n},\mathcal{L}^n_{X_{s_n}})\nabla_i f(X_s)\mathrm{d}s \\
			&-\frac{1}{2}\sum_{i,j}\int_{0}^{t}(\sigma^*(X_{s_n},\mathcal{L}^n_{X_{s_n}})\sigma(X_{s_n},\mathcal{L}^n_{X_{s_n}}))_{ij}\nabla_{ij}^2(f(X_s))\mathrm{d}s,
		\end{align*}
		where $\mathcal{L}^n_{X_{s_n}}=\mathbb{P}_n\circ X_{s_n}^{-1}$.

		Since the equation (\ref{emsolu}) admits a weak solution $(X^n,K^n)$, there exists a martingale solution $\mathbb{P}_n$ on $(\mathcal{W},\mathbf{W})$ for (\ref{emsolu}) due to Proposition \ref{vv}. This implies that $M_t^{n,f}$ is a continuous $\overline{\mathbf{W}}_t$-adapted martingale under $\mathbb{P}_n$. Thus we have
		\begin{align}
			\mathbb{E}^{\mathbb{P}_n}\left( (M_t^{n,f}(X,K)-M_s^{n,f}(X,K))G\right)=0.
		\end{align}

		Since $\mathbb{P}_n$ weakly converges to $\mathbb{P}_0$ as $n\to\infty$, we obtain
		\begin{align*}
			\lim\limits_{n\to\infty}\mathbb{E}^{\mathbb{P}_n}\left((f(X_t)-f(X_s))G\right)=\mathbb{E}^{\mathbb{P}_0}\left((f(X_t)-f(X_s))G\right).
		\end{align*}
		Furthermore, by applying Lemma \ref{kfcon} we get
		\begin{align*}
			\lim\limits_{n\to\infty}\mathbb{E}^{\mathbb{P}_n}\left(G\int_{s}^{t}\left\langle \nabla f(X_r),\mathrm{d}K_r\right\rangle\right)=\mathbb{E}^{\mathbb{P}_0}\left(G\int_{s}^{t}\langle \nabla f(X_r),\mathrm{d}K_r\rangle\right).
		\end{align*}

		We now prove the following two equations: 
		\begin{align}\label{48b}
			\lim\limits_{n\to\infty}\mathbb{E}^{\mathbb{P}_n}\left(G\int_{0}^{t} b_i(X_{s_n},\mathcal{L}^n_{X_{s_n}})\nabla_if(X_s)\mathrm{d}s\right)=\mathbb{E}^{\mathbb{P}_0}\left(G\int_{0}^{t}b_i(X_{s},\mathcal{L}_{X_{s}})\nabla_if(X_s)\mathrm{d}s\right)
		\end{align}
		and
		\begin{align}\label{49s}
			&\lim\limits_{n\to\infty}\mathbb{E}^{\mathbb{P}_n}\left(G\int_{0}^{t} (\sigma^*(X_{s_n},\mathcal{L}^n_{X_{s_n}})\sigma(X_{s_n},\mathcal{L}^n_{X_{s_n}}))_{ij}\nabla_{ij}^2(f(X_s))\mathrm{d}s\right)  \nonumber\\
			=&\mathbb{E}^{\mathbb{P}_0}\left(G\int_{0}^{t}(\sigma^*(X_{s},\mathcal{L}_{X_{s}})\sigma(X_{s},\mathcal{L}_{X_{s}}))_{ij}\nabla_{ij}^2(f(X_s))\mathrm{d}s\right).
		\end{align}

		By Skorohod's representation theorem, there exists a probability space  $(\tilde{\Omega},\tilde{\mathcal{F}},\tilde{\mathbb{P}})$ and a sequence of $\mathcal{W}$-valued random variables $\left\{(\tilde{X}^n,\tilde{K}^n)\right\}_{n\in\mathbb{N}}$ and $(\tilde{X},\tilde{K})$ defined on this probability space such that
		\begin{enumerate}[(i)]
			\item the law of $(\tilde{X}^n,\tilde{K}^n)$ is $\mathbb{P}_n$ for each $n\in\mathbb{N}$ and the law of $(\tilde{X},\tilde{K})$ is $\mathbb{P}_0$,
			\item $(\tilde{X}^n,\tilde{K}^n)\to(\tilde{X},\tilde{K}),\,\, \tilde{\mathbb{P}}$-a.s. as  $n\to\infty$.
		\end{enumerate}

		Thus, it suffices to verify
		\begin{align}\label{410b}
			\lim\limits_{n\to\infty}\mathbb{E}^{\mathbb{P}_n}\left(G\int_{0}^{t} b_i(\tilde{X}^n_{s_n},\mathcal{L}^n_{\tilde{X}^n_{s_n}})\nabla_if(\tilde{X}^n_s)\mathrm{d}s\right)=\mathbb{E}^{\mathbb{P}_0}\left(G\int_{0}^{t}b_i(\tilde{X}_{s},\mathcal{L}_{\tilde{X}_{s}})\nabla_if(\tilde{X}_s)\mathrm{d}s\right)
		\end{align}
		and
		\begin{align}\label{411s}
			\lim\limits_{n\to\infty}&\mathbb{E}^{\mathbb{P}_n}\left(G\int_{0}^{t} (\sigma^*(\tilde{X}^n_{s_n},\mathcal{L}^n_{\tilde{X}^n_{s_n}})\sigma(\tilde{X}^n_{s_n},\mathcal{L}^n_{\tilde{X}^n_{s_n}}))_{ij}\nabla_{ij}^2(f(\tilde{X}^n_s))\mathrm{d}s\right)  \nonumber\\
			=&\mathbb{E}^{\mathbb{P}_0}\left(G\int_{0}^{t}(\sigma^*(\tilde{X}_{s},\mathcal{L}_{\tilde{X}_{s}})\sigma(\tilde{X}_{s},\mathcal{L}_{\tilde{X}_{s}}))_{ij}\nabla_{ij}^2(f(\tilde{X}_s))\mathrm{d}s\right).
		\end{align}

		By (\ref{l4b}), we have
		\begin{align*}
			\sup_{n\in\mathbb{N}}\mathbb{E}^{\tilde{\mathbb{P}}}\left(\sup_{t\in[0,T]}|\tilde{X}^n_t|^{2p}\right)< \infty.
		\end{align*}

Combining the estimate above with (ii), we deduce that
		\begin{align}
			\lim\limits_{n\to\infty}\mathbb{W}_2\left(\mathcal{L}_{\tilde{X}^n}^n,\mathcal{L}_{\tilde{X}}\right)= 0.
		\end{align}

		Moreover, by (\hyperref[h2]{\textbf{H2}}), (\ref{l4b}) and (i), we obtain
		\begin{align*}
			\mathbb{E}^{\tilde{\mathbb{P}}}|b(\tilde{X}^n_{s_n},\mathcal{L}^n_{\tilde{X}^n_{s_n}})|=\mathbb{E}|b(X^n_{s_n},\mathcal{L}^n_{X^n_{s_n}})|\leq \left(\mathbb{E}|b(X^n_{s_n},\mathcal{L}^n_{X^n_{s_n}})|^{2p}\right)^{\frac{1}{2p}}
			\leq C(1+\mathbb{E}|X^n_{s_n}|^{2p})^{\frac{1}{2p}}
			< \infty.
		\end{align*}

		 Thus (\ref{410b}) is verified by using dominated convergence theorem and the continuity of $b$.  The equation (\ref{411s}) follows similarly. 


	\end{proof}


	By Proposition \ref{vv} and Proposition \ref{magl}, the equation (\ref{mve}) has a weak solution. Then we only need to prove that pathwise uniqueness holds for the equation (\ref{mve}).

	\begin{proposition}
		Assume that (\hyperref[h0]{\textbf{H0}}) and (\hyperref[h2]{\textbf{H2}}) hold. Then the pathwise uniqueness holds for equation (\ref{mve}).
	\end{proposition}

	\begin{proof}
		Let $(\tilde{\mathcal{ S }};\tilde{W},(\tilde{X}^1,\tilde{K}^1))$ and $(\tilde{\mathcal{ S }};\tilde{W},(\tilde{X}^2,\tilde{K}^2))$ be two weak solutions to (\ref{mve}) with $\tilde{X}^1_0=\tilde{X}^2_0$. Let $Y_t:=\tilde{X}^1_t-\tilde{X}^2_t$. By It\^o's formula, we have
		\begin{align}\label{pro43}
			|Y_t|^2=&2\int_{0}^{t}\langle Y_s, b(\tilde{X}^1_s,\mathcal{L}_{\tilde{X}^1_s})-b(\tilde{X}^2_s,\mathcal{L}_{\tilde{X}^2_s})\rangle\mathrm{d}s+\int_{0}^{t}\lVert\sigma(\tilde{X}^1_s,\mathcal{L}_{\tilde{X}^1_s})-\sigma(\tilde{X}^2_s,\mathcal{L}_{\tilde{X}^2_s})\rVert^2\mathrm{d}s \nonumber\\
			&+2\int_{0}^{t}\langle Y_s, \sigma(\tilde{X}^1_s,\mathcal{L}_{\tilde{X}^1_s})-\sigma(\tilde{X}^2_s,\mathcal{L}_{\tilde{X}^2_s})\mathrm{d}\tilde{W}_s\rangle-2\int_{0}^{t}\langle Y_s,\mathrm{d}\tilde{K}_s^1-\mathrm{d}\tilde{K}_s^2\rangle.
		\end{align}

		Taking the expectation on both two sides of the equation (\ref{pro43}), by H\"older's inequality, (\hyperref[h3]{\textbf{H3}}), Remark \ref{W2} and (\ref{mono}), we get
		\begin{align*}
			\tilde{\mathbb{E}}|Y_t|^2\leq&2\tilde{\mathbb{E}}\int_{0}^{T}\langle Y_s,b(\tilde{X}^1_s,\mathcal{L}_{\tilde{X}^1_s})-b(\tilde{X}^2_s,\mathcal{L}_{\tilde{X}^2_s})\rangle\mathrm{d}s +\tilde{\mathbb{E}}\int_{0}^{T}\lVert\sigma(\tilde{X}^1_s,\mathcal{L}_{\tilde{X}^1_s})-\sigma(\tilde{X}^2_s,\mathcal{L}_{\tilde{X}^2_s})\rVert^2\mathrm{d}s \\
			&+2\tilde{\mathbb{E}}\int_{0}^{T}\langle Y_s, \sigma(\tilde{X}^1_s,\mathcal{L}_{\tilde{X}^1_s})-\sigma(\tilde{X}^2_s,\mathcal{L}_{\tilde{X}^2_s})\mathrm{d}\tilde{W}_s\rangle  \\
			\leq& C\tilde{\mathbb{E}}\int_{0}^{t}(\varrho(|Y_s|^2)+\varrho(\mathbb{W}^2_2(\mathcal{L}_{\tilde{X}_s^1},\mathcal{L}_{\tilde{X}_s^2})))\mathrm{d}s \\
			\leq& C\tilde{\mathbb{E}}\int_{0}^{t}[\varrho(|Y_s|^2)+\varrho(\tilde{\mathbb{E}}|Y_s|^2)]\mathrm{d}s.
		\end{align*}

		Applying Jensen's inequality, we obtain
		\begin{align*}
			\tilde{\mathbb{E}}|Y_t|^2\leq C\int_{0}^{t}\varrho(\tilde{\mathbb{E}}|Y_s|^2)\mathrm{d}s,
		\end{align*}
		where $C$ depends on $L_2$ and $T$. By Lemma \ref{bhr}, we get $\tilde{\mathbb{E}}|Y_t|^2=0$, which implies that for any $t\in[0,T]$, $Y_t=0\,\,\,$a.s.. Therefore we get the desired result.
	\end{proof}







