	\subsection{Yosida Approximations}

	Consider the following controlled  multivalued McKean-Vlasov SDE:
	\begin{equation}\label{zeue}
		\begin{cases}
			\mathrm{d}Z^{\epsilon,h_\epsilon}_t\in b_{\epsilon}(Z^{\epsilon,h_\epsilon}_t,\mathcal{L}_{X^{\epsilon}_t})\mathrm{d}t+\sigma_\epsilon(Z^{\epsilon,h_\epsilon}_t,\mathcal{L}_{X^{\epsilon}_t})h_\epsilon(t)\mathrm{d}t+\sqrt{\epsilon}\sigma_\epsilon(Z^{\epsilon,h_\epsilon}_t,\mathcal{L}_{X^{\epsilon}_t})\mathrm{d}W_t-A_\epsilon(Z^{\epsilon,h_\epsilon}_t)\mathrm{d}t , \\
			Z^{\epsilon,h_\epsilon}_0=x\in\overline{D(A)}.
		\end{cases}
	\end{equation}

	By Lemma \ref{girs} we know that the above equation has a unique solution $(Z^{\epsilon,h_\epsilon}_t,K^{\epsilon,h_\epsilon}_t)$. Next we consider the following Yosida Approximation:
	\begin{equation}
		\begin{cases}
			\mathrm{d}Z^{\epsilon,h_\epsilon,\alpha}_t= b_{\epsilon}(Z^{\epsilon,h_\epsilon,\alpha}_t,\mathcal{L}_{X^{\epsilon}_t})\mathrm{d}t+\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_t,\mathcal{L}_{X^{\epsilon}_t})h_\epsilon(t)\mathrm{d}t+\sqrt{\epsilon}\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_t,\mathcal{L}_{X^{\epsilon}_t})\mathrm{d}W_t-A_\epsilon^\alpha(Z^{\epsilon,h_\epsilon,\alpha}_t)\mathrm{d}t,  \\
			Z^{\epsilon,h_\epsilon,\alpha}_0=x\in\overline{D(A)}.
		\end{cases}
	\end{equation}

	%Then we need the following lemmas to verify our results.

	\begin{lemma}\label{yozfin}
		Assume that (\hyperref[h0]{\textbf{H0}})-(\hyperref[h4]{\textbf{H4}}) hold. For any $p\geq 1$, $h_\epsilon\in\mathcal{D}_m$ and $x\in\overline{D(A)}$, there exists some constant $C>0$ such that for any $\epsilon\in(0,1)$ and $\alpha>0$,
		\begin{equation*}
			\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t|^{2p}\leq C,
		\end{equation*}
		where C may be dependent of $p,\,T,\,m$ and $x$, but independent of $\epsilon$ and $\alpha$.

		\begin{proof}
			Since $A^\alpha_\epsilon$ is monotone, it follows that
			\begin{align*}
				-&\langle Z^{\epsilon,h_\epsilon,\alpha}_s,A^\alpha_\epsilon\left(Z^{\epsilon,h_\epsilon,\alpha}_s\right)\rangle  =-\langle Z^{\epsilon,h_\epsilon,\alpha}_s,A^\alpha_\epsilon\left(Z^{\epsilon,h_\epsilon,\alpha}_s\right)-A^\alpha_\epsilon(0)+A^\alpha_\epsilon(0)\rangle  \leq -\langle Z^{\epsilon,h_\epsilon,\alpha}_s,A^\alpha_\epsilon(0)\rangle.
			\end{align*}
			Noting that $\sup_\epsilon|A_\epsilon^\alpha(0)|\leq\sup_\epsilon|A_\epsilon^0(0)|$, we have
			\begin{align*}
				-\langle Z^{\epsilon,h_\epsilon,\alpha}_s,A^\alpha_\epsilon\left(Z^{\epsilon,h_\epsilon,\alpha}_s\right)\rangle\leq \frac{1}{2}|Z^{\epsilon,h_\epsilon,\alpha}_s|^2+C.
			\end{align*}
			By It$\hat{\text{o}}$'s formula we get
			\begin{align*}
				&|Z^{\epsilon,h_\epsilon,\alpha}_t|^{2p} \\
				=&|x|^{2p}+2p\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p-2}\langle Z^{\epsilon,h_\epsilon,\alpha}_s,b_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})\rangle\mathrm{d}s \\
				&+2p\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p-2}\langle Z^{\epsilon,h_\epsilon,\alpha}_s,\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})h_\epsilon(s)\rangle\mathrm{d}s \\
				&+2p\sqrt{\epsilon}\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p-2}\langle Z^{\epsilon,h_\epsilon,\alpha}_s,\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})\mathrm{d}W_s\rangle \\
				&+p\epsilon\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p-2}\lVert \sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X_s^\epsilon})\rVert^2\mathrm{d}s \\
				&+2p(p-1)\epsilon\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p-4}\langle Z^{\epsilon,h_\epsilon,\alpha}_s,\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})\sigma^\ast_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})Z^{\epsilon,h_\epsilon,\alpha}_s\rangle\mathrm{d}s \\
				&-2p\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p-2}\langle Z^{\epsilon,h_\epsilon,\alpha}_s,A_\epsilon^\alpha(Z^{\epsilon,h_\epsilon,\alpha}_s)\rangle\mathrm{d}s.
			\end{align*}
			Then by (\hyperref[h0]{\textbf{H0}})-(\hyperref[h2]{\textbf{H2}}) we have
			\begin{align*}
				|Z^{\epsilon,h_\epsilon,\alpha}_t|^{2p} \leq &C+C\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p}\mathrm{d}s+2p\sqrt{\epsilon}\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p-2}\langle Z^{\epsilon,h_\epsilon,\alpha}_s,\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})\mathrm{d}W_s\rangle \\
				&+2p\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p}\lvert h_\epsilon(s)\rvert\mathrm{d}s+2p\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p-1}|\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})h_\epsilon(s)|\mathrm{d}s.
			\end{align*}
			Let
			\begin{equation*}
				f(t):=\mathbb{E}\sup_{s\in[0,t]}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p}.
			\end{equation*}

			By the same deduction in Lemma \ref{l42} we get $\sup_{t\in[0,T]}\mathbb{E}|X^\epsilon_t|^{2p}<C$, where $C$ depends on $x$, $p$ and $T$. Then by BDG's inequality, H\"{o}lder's inequality, Young's inequality, \hyperref[h1]{\textbf{(H1)}} and \hyperref[h2]{\textbf{(H2)}}, we have
			\begin{align*}
				&\mathbb{E}\sup_{t_1\in[0,t]}2p\sqrt{\epsilon}\int_{0}^{t_1}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p-2}\langle Z^{\epsilon,h_\epsilon,\alpha}_s,\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})\mathrm{d}W_s\rangle  \\
				\leq& C\mathbb{E}\left[\left(\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{4p-2}\lVert\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})\rVert^2\mathrm{d}s\right)^{\frac{1}{2}}\right] \\
				\leq& \frac{1}{8}\mathbb{E}\sup_{s\in[0,t]}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p}+C\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p}\mathrm{d}s+Ct^{\frac{1}{p}}\left(\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p}\mathrm{d}s\right)^{\frac{2p-2}{2p}} \\
				\leq& \frac{1}{8}f(t)+C\int_{0}^{t}\mathbb{E}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p}\mathrm{d}s+Ct^{\frac{1}{p}}.
			\end{align*}

			By Young's inequality again we have
			\begin{align*}
				&\mathbb{E}\left[\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p}\lvert h_\epsilon(s)\rvert\mathrm{d}s\right] \\
				\leq& C\mathbb{E}\left[\left(\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{4p}\mathrm{d}s\right)^{\frac{1}{2}}\right]\left(\int_{0}^{t}|h_\epsilon(s)|^2\mathrm{d}s\right) \\
				\leq& C\mathbb{E}\left[\left(\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{4p}\mathrm{d}s\right)^{\frac{1}{2}}\right]\leq \frac{1}{4}f(t)+C\int_{0}^{t}\mathbb{E}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p}\mathrm{d}s
			\end{align*}
			and
			\begin{align*}
				&\mathbb{E}\left[\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p-1}|\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})h_\epsilon(s)|\mathrm{d}s\right]  \\
				\leq& C\mathbb{E}\left[\left(\int_{0}^{t}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{4p-2}\lVert \sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})\rVert^2\mathrm{d}s\right)^{\frac{1}{2}}\right]+C \\
				\leq& \frac{1}{8}f(t)+C\int_{0}^{t}\mathbb{E}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p}\mathrm{d}s+Ct^{\frac{1}{p}}.
			\end{align*}

			By combing the estimates above together  we get
			\begin{align*}
				f(t)\leq C\int_{0}^{t}\mathbb{E}|Z^{\epsilon,h_\epsilon,\alpha}_s|^{2p}\mathrm{d}s+Ct^{\frac{1}{p}},
			\end{align*}
			which completes the proof by Gronwall's inequality.
		\end{proof}
	\end{lemma}

	The following result can be proved in a similar way as above by Proposition \ref{multi}.

	\begin{lemma}\label{yosifin}
		Assume that (\hyperref[h0]{\textbf{H0}})-(\hyperref[h4]{\textbf{H4}}) hold. For any $p\geq 1$ and $x\in\overline{D(A)}$, there exists a constant $C>0$ such that for any $\epsilon\in(0,1)$,
		\begin{equation*}
			\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon}_t|^{2p}+\mathbb{E}|K^{\epsilon,h_{\epsilon}}|^T_0\leq C,
		\end{equation*}
		where $C$ may be dependent of $p,T,m$ and $x$, but independent of $\epsilon$.
	\end{lemma}


	\begin{lemma}\label{afin}
		Assume that (\hyperref[h0]{\textbf{H0}})-(\hyperref[h4]{\textbf{H4}}) hold. For any $x\in\overline{D(A)}$, we have
		\begin{equation*}
			\lim\limits_{\alpha\to 0}\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2=0
		\end{equation*}
		uniformly in $\epsilon>0$.

		\begin{proof}
			Firstly, let
			\begin{align*}
				N_\epsilon(t):=\int_{0}^{t}b_\epsilon(Z^{\epsilon,h_\epsilon}_s,\mathcal{L}_{X^\epsilon_s})\mathrm{d}s+\int_{0}^{t}\sigma_\epsilon(Z^{\epsilon,h_\epsilon}_s,\mathcal{L}_{X^\epsilon_s})h_\epsilon(s)\mathrm{d}s+\sqrt{\epsilon}\int_{0}^{t}\sigma_\epsilon(Z^{\epsilon,h_\epsilon}_s,\mathcal{L}_{X^\epsilon_s})\mathrm{d}W_s.
			\end{align*}

			Using BDG's inequality, (\hyperref[h1]{\textbf{H1}}), (\hyperref[h2]{\textbf{H2}}) and Lemma \ref{afin}, we have
			\begin{equation}\label{Nfin}
				\mathbb{E}\sup_{t\in[0,T]}|N_\epsilon(t)|^2<\infty.
			\end{equation}
			For any $ p\geq 2$ and $\Delta>0$, we also have
			\begin{equation}\label{Npfin}
				\mathbb{E}\sup_{0\leq|t-s|\leq\Delta}|N_\epsilon(t)-N_\epsilon(s)|^p\leq C_{p,m}\Delta^{\frac{p}{2}-1},
			\end{equation}
			where $C_{p,m}$ is independent of $\epsilon$ and $\Delta$.

			Now consider the following Yosida approximation:
			\begin{equation}\label{brez}
				\begin{cases}
					\mathrm{d}\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t=\mathrm{d}N_\epsilon(t)-A^\alpha_\epsilon(\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t)\mathrm{d}t, \\
					\breve{Z}^{\epsilon,h_\epsilon,\alpha}_0=x\in\overline{D(A)}.
				\end{cases}
			\end{equation}
			Since $A^\alpha_\epsilon$ is Lipschitz, the above equation admits a unique solution.
			%Then we will give our proof in two steps.

			First we will use the argument in \cite{rwz} to show
			\begin{equation}\label{approx}
				\lim\limits_{\alpha\to 0}\mathbb{E}\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2=0
			\end{equation}
			uniformly in $\epsilon> 0$.

			Let $N^n_\epsilon(t)$ be the $C^\infty$-approximation of $N_\epsilon(t)$ defined by
			\begin{align*}
				N^n_\epsilon(t):=n\int_{t-\frac{1}{n}}^{t+\frac{1}{n}}N_\epsilon(s-\frac{1}{n})\varphi(n(t-s))\mathrm{d}s,
			\end{align*}
			where $\varphi$ is a mollifier with $supp\,\varphi\subset(-1,1)$, $\varphi\in C^\infty$ and $\int_{-1}^{1}\varphi(s)\mathrm{d}s=1$.

			By (\ref{Nfin}) and (\ref{Npfin}) we can deduce that
			\begin{align*}
				&N_\epsilon^n(0)=0, \\
				&\lim\limits_{n\to\infty}\mathbb{E}\sup_{t\in[0,T]}|N^n_\epsilon(t)-N_\epsilon(t)|^2=0, \\
				&\sup_{t\in[0,T]}|N^n_\epsilon(t)|\leq\sup_{t\in[0,T]}|N_\epsilon(t)| \quad \text{a.s.}, \\
				&\sup_{|t-s|\leq\Delta}|N^n_\epsilon(t)-N^n_\epsilon(s)|\leq \sup_{|t-s|\leq\Delta}|N_\epsilon(t)-N_\epsilon(s)| \quad\text{a.s.,}\quad\forall \Delta>0, \\
				&\mathbb{E}\sup_{t\in[0,T]}|\dot{N}^n_\epsilon(t)|^2+\mathbb{E}\sup_{t\in[0,T]}|\ddot{N}^n_\epsilon(t)|^2\leq L_n,
			\end{align*}
			where $L_n$ is a positive constant which is independent of $\epsilon$ and $\alpha$.

			Let $(Z^{\epsilon,h_\epsilon,n}_t,K^{\epsilon,h_\epsilon,n}_t)$ be the solution of the following Multivalued McKean-Vlasov SDE
			\begin{equation}\label{zeuen}
				\begin{cases}
					\mathrm{d}Z^{\epsilon,h_\epsilon,n}_t\in \mathrm{d}N^n_\epsilon(t)-A_\epsilon(Z^{\epsilon,h_\epsilon,n}_t)\mathrm{d}t, \\
					Z^{\epsilon,h_\epsilon,n}_0=x,
				\end{cases}
			\end{equation}
			and $(\breve{Z}^{\epsilon,h_\epsilon,\alpha,n}_t,K^{\epsilon,h_\epsilon,\alpha,n}_t)$ be the solution of  the following differential equation
			\begin{equation*}
				\begin{cases}
					\mathrm{d}\breve{Z}^{\epsilon,h_\epsilon,\alpha,n}_t= \mathrm{d}N^n_\epsilon(t)-A^\alpha_\epsilon(\breve{Z}^{\epsilon,h_\epsilon,\alpha,n}_t)\mathrm{d}t, \\
					\breve{Z}^{\epsilon,h_\epsilon,\alpha,n}_0=x.
				\end{cases}
			\end{equation*}

			We divide the proof of (\ref{approx}) into three steps.

			\textbf{Step 1}: First we prove
			\begin{equation}\label{zns1}
				\lim\limits_{n\to\infty}\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon,n}_t-Z^{\epsilon,h_\epsilon}_t|=0
			\end{equation}
			uniformly in $\epsilon>0$. By \cite[Proposition 4.3]{cepa1}, we have
			\begin{align*}
				&\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon,n}_t-Z^{\epsilon,h_\epsilon}_t|^2  \\
				\leq&\sup_{t\in[0,T]}|N^n_\epsilon(t)-N_\epsilon(t)|^{\frac{1}{2}}\left(\sup_{t\in[0,T]}|N^n_\epsilon(t)-N_\epsilon(t)|+4|K^{\epsilon,h_\epsilon,n}|^0_T+4|K^{\epsilon,h_\epsilon}|^0_T\right)^\frac{1}{2}.
			\end{align*}

			By Lemma \ref{yosifin}, we have
			\begin{equation*}
				\mathbb{E}|K^{\epsilon,h_\epsilon}|^0_T\leq C,
			\end{equation*}
			where $C$ is independent of $\epsilon$. Then it is left to verify
			\begin{align*}
				\mathbb{E}|K^{\epsilon,h_\epsilon,n}|^0_T\leq C,
			\end{align*}
			where $C$ is independent of $\epsilon$ and $n$. By Proposition \ref{multi} we have for any $a\in$ Int$(D(A))$
			\begin{align*}
				&|Z^{\epsilon,h_\epsilon,n}_t-a|^2-|Z^{\epsilon,h_\epsilon,n}_s-a|^2 \\
				\leq&|N^n_\epsilon(t)+h-a|^2+|N^n_\epsilon(s)+h-a|^2-2\lambda_1|K^{\epsilon,h_\epsilon,n}|^s_t+\lambda_{2}\int_{s}^{t}|Z^{\epsilon,h_\epsilon,n}_r-a|\mathrm{d}r \\
				&+\lambda_{3}(t-s)+2\int_{s}^{t}\langle N^n_\epsilon(r)-N_\epsilon(r), \mathrm{d}K^{\epsilon,h_\epsilon,n}_r\rangle+2\langle Z^{\epsilon,h_\epsilon,n}_t-h-N^n_\epsilon(t), N^n_\epsilon(t)-N^n_\epsilon(s)\rangle \\
				\leq&C\left(1+\sup_{t\in [0,T]}|N_\epsilon(t)|^2+\sup_{t\in [0,T]}|Z^{\epsilon,h_\epsilon,n}_t-a|\right)+2\left(\sup_{|t'-s'|\leq|t-s|}|N^n_\epsilon(t')-N^n_\epsilon(s')|-\lambda_{1}\right)|K^{\epsilon,h_\epsilon,n}|^s_t,
			\end{align*}
			then we get
			\begin{align*}
				|Z^{\epsilon,h_\epsilon,n}_t-a|^2-|Z^{\epsilon,h_\epsilon,n}_s-a|^2+\lambda_{1}|K^{\epsilon,h_\epsilon,n}|^s_t
				\leq C\left(1+\sup_{t\in [0,T]}|N_\epsilon(t)|^2+\sup_{t\in [0,T]}|Z^{\epsilon,h_\epsilon,n}_t-a|\right),
			\end{align*}
			on the set
			\begin{equation*}
				\Theta_{\epsilon,n,\Delta}=\left\{\sup_{|t'-s'|\leq\Delta}|N^n_\epsilon(t')-N^n_\epsilon(s')|\leq\frac{\lambda_1}{2}\right\}.
			\end{equation*}
			By the same way in \citep[Proposition 4.9]{cepa1}, we have
			\begin{align*}
				|K^{\epsilon,h_\epsilon,n}|^0_TI_{\Theta_{\epsilon,n,\Delta}}\leq \frac{C\left(1+\sup_{t\in[0,T]}|N_\epsilon(t)|^2\right)}{\Delta}.
			\end{align*}
			Notice that for $p>6$, we can deduce that
			\begin{align*}
				\mathbb{E}|K^{\epsilon,h_\epsilon,n}|^0_T=&\sum_{k=1}^{\infty}\mathbb{E}\left[|K^{\epsilon,h_\epsilon,n}|^0_TI_{\Theta_{\epsilon,n,\frac{1}{k+1}}\backslash\Theta_{\epsilon,n,\frac{1}{k}}}\right] \\
				\leq&C\sum_{k=1}^{\infty}(k+1)P\left(\Theta_{\epsilon,n,\frac{1}{k}}^c\right)
				\leq C\sum_{k=1}^{\infty}(k+1)\mathbb{E}\sup_{|t-s|\leq\frac{1}{k}}|N_\epsilon(t)-N_\epsilon(s)|^p \\ \leq &C\sum_{k=1}^{\infty}(k+1)\left(\frac{1}{k}\right)^{\frac{p}{2}-1}<\infty.
			\end{align*}
			Hence, we obtain (\ref{zns1}).

			\textbf{Step 2}: By using the same procedure in Step $1$, we also have
			\begin{align}
				\lim\limits_{n\to\infty}\mathbb{E}\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha,n}_t-\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t|=0
			\end{align}
			uniformly in $\epsilon$ and $\alpha$.

			\textbf{Step 3}: Let $\alpha,\beta>0$. Since by Remark \ref{yosidap} we have $A^\alpha_\epsilon(x)\in A_\epsilon(J^\alpha(x))$, then for $\forall x,y\in\mathbb{R}^d$
			\begin{equation*}
				\langle A^\alpha_\epsilon(x)-A^\beta_\epsilon(y),x-y\rangle\leq-(\alpha+\beta)\langle A^\alpha_\epsilon(x),A^\beta_\epsilon(y)\rangle.
			\end{equation*}
			Hence
			\begin{align*}
				&\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha,n}_t-\breve{Z}^{\epsilon,h_\epsilon,\beta,n}_t|^2 \\
				=&\sup_{t\in[0,T]}|\int_{0}^{t}\langle A^\alpha_\epsilon(\breve{Z}^{\epsilon,h_\epsilon,\alpha,n}_s)-A^\beta_\epsilon(\breve{Z}^{\epsilon,h_\epsilon,\beta,n}_s),\breve{Z}^{\epsilon,h_\epsilon,\alpha,n}_s-\breve{Z}^{\epsilon,h_\epsilon,\beta,n}_s\rangle\mathrm{d}s| \\
				\leq&(\alpha+\beta)\int_{0}^{T}|A^\alpha_\epsilon(\breve{Z}^{\epsilon,h_\epsilon,\alpha,n}_s)||A^\beta_\epsilon(\breve{Z}^{\epsilon,h_\epsilon,\beta,n}_s)|\mathrm{d}s \\
				\leq&(\alpha+\beta)T\sup_{s\in[0,T]}|A^\alpha_\epsilon(\breve{Z}^{\epsilon,h_\epsilon,\alpha,n}_s)|\sup_{s\in[0,T]}|A^\beta_\epsilon(\breve{Z}^{\epsilon,h_\epsilon,\beta,n}_s)|.
			\end{align*}
			By the estimation in \citep[Proposition 4.7]{cepa1} and property (\ref{yosi0}), we can deduce that
			\begin{align*}
				|\frac{d}{dt}\breve{Z}^{\epsilon,h_\epsilon,\alpha,n}|\leq |A^0_\epsilon(x)|+|\dot{N}_\epsilon^n(t)|+\int_{0}^{t}|\ddot{N}^n_\epsilon(s)|\mathrm{d}s
			\end{align*}
			and thus we have
			\begin{align*}
				\sup_{t\in[0,T]}|A^\alpha_\epsilon(\breve{Z}^{\epsilon,h_\epsilon,\alpha,n}_t)|\leq|A^0_\epsilon(x)|+2\sup_{t\in[0,T]}|\dot{N}^n_\epsilon(t)|+T\sup_{t\in[0,T]}|\ddot{N}^n_\epsilon(t)|.
			\end{align*}
			Combining the above estimations we have
			\begin{equation*}
				\mathbb{E}\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha,n}_t-\breve{Z}^{\epsilon,h_\epsilon,\beta,n}_t|^2\leq\,L_n(\alpha+\beta),
			\end{equation*}
			where $L_n$ is a constant independent of $\epsilon$, $\alpha$ and $\beta$. Then by \citep[Proposition 4.7]{cepa1} we know that
			\begin{equation*}
				\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha,n}_t-Z^{\epsilon,h_\epsilon,n}_t|\to 0\,\,\,a.s.\quad \text{as }\,\alpha\to 0.
			\end{equation*}

			Thus we obtain the result of the first part
			\begin{equation}\label{yosida1}
				\lim\limits_{\alpha\to 0}\mathbb{E}\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha,n}_t-Z^{\epsilon,h_\epsilon,n}_t|^2= 0
			\end{equation}
			uniformly in $\epsilon>0$.


			Secondly, by It{\^o}'s formula and monotonicity of $A_\epsilon$, we can deduce that
			\begin{align*}
				&|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon,\alpha}_t|^2  \\
				\leq &\,\,2\int_{0}^{t}\langle \breve{Z}^{\epsilon,h_\epsilon,\alpha}_s-Z^{\epsilon,h_\epsilon}_s,\,b_\epsilon(Z^{\epsilon,h_\epsilon}_s,\mathcal{L}_{X^\epsilon_s})-b_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})\rangle\mathrm{d}s \\
				&+2\int_{0}^{t}\langle Z^{\epsilon,h_\epsilon}_s-Z^{\epsilon,h_\epsilon,\alpha}_s,\,b_\epsilon(Z^{\epsilon,h_\epsilon}_s,\mathcal{L}_{X^\epsilon_s})-b_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})\rangle\mathrm{d}s \\
				&+2\int_{0}^{t}\langle \breve{Z}^{\epsilon,h_\epsilon,\alpha}_s-Z^{\epsilon,h_\epsilon}_s,\,\sigma_\epsilon(Z^{\epsilon,h_\epsilon}_s,\mathcal{L}_{X^\epsilon_s})h_\epsilon(s)-\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})h_\epsilon(s)\rangle\mathrm{d}s \\
				&+2\int_{0}^{t}\langle Z^{\epsilon,h_\epsilon}_s-Z^{\epsilon,h_\epsilon,\alpha}_s,\,\sigma_\epsilon(Z^{\epsilon,h_\epsilon}_s,\mathcal{L}_{X^\epsilon_s})h_\epsilon(s)-\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})h_\epsilon(s)\rangle\mathrm{d}s \\
				&+2\sqrt{\epsilon}\int_{0}^{t}\langle \breve{Z}^{\epsilon,h_\epsilon,\alpha}_s-Z^{\epsilon,h_\epsilon}_s,\,\left(\sigma_\epsilon(Z^{\epsilon,h_\epsilon}_s,\mathcal{L}_{X^\epsilon_s})-\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})\right)\mathrm{d}W_s\rangle  \\
				&+2\sqrt{\epsilon}\int_{0}^{t}\langle Z^{\epsilon,h_\epsilon}_s-Z^{\epsilon,h_\epsilon,\alpha}_s,\,\left(\sigma_\epsilon(Z^{\epsilon,h_\epsilon}_s,\mathcal{L}_{X^\epsilon_s})-\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})\right)\mathrm{d}W_s\rangle  \\
				&+\frac{\epsilon}{2}\int_{0}^{t}\lVert \sigma_\epsilon(Z^{\epsilon,h_\epsilon}_s,\mathcal{L}_{X^\epsilon_s})-\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_s,\mathcal{L}_{X^\epsilon_s})\rVert^2\mathrm{d}s \\
				:=&\,\,I^{\epsilon,\alpha}_1(t)+I^{\epsilon,\alpha}_2(t)+I^{\epsilon,\alpha}_3(t)+I^{\epsilon,\alpha}_4(t)+I^{\epsilon,\alpha}_5(t)+I^{\epsilon,\alpha}_2(t)+I^{\epsilon,\alpha}_6(t)+I^{\epsilon,\alpha}_7(t).
			\end{align*}

			For $I^{\epsilon,\alpha}_1(t)$, by H{\"o}lder's inequality, Young's inequality, (\hyperref[h1]{\textbf{H1}})-(\hyperref[h4]{\textbf{H4}}), Lemma \ref{yozfin} and Lemma \ref{yosifin}, we have
			\begin{align}\label{431}
				&\mathbb{E}\sup_{t\in[0,T]}|I^{\epsilon,\alpha}_1(t)| \nonumber\\
				\leq& C\left(1+\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon}_t|+\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t|+(\sup_{t\in[0,T]}\mathbb{E}|X^\epsilon_t|^2)^{\frac{1}{2}}\right)\left(\mathbb{E}\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2\right)^\frac{1}{2} \nonumber\\
				\leq& C\left(\mathbb{E}\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2\right)^\frac{1}{2}.
			\end{align}

			By the similar way, for $I^{\epsilon,\alpha}_2(t)$, $I^{\epsilon,\alpha}_3(t)$ and $I^{\epsilon,\alpha}_4(t)$, we have
			\begin{align}\label{432}
				\mathbb{E}\sup_{t\in[0,T]}|I^{\epsilon,\alpha}_2(t)|
				\leq
				C\mathbb{E}\int_{0}^{T}\varrho\left[\sup_{s\in[0,t]}|Z^{\epsilon,h_\epsilon}_s-Z^{\epsilon,h_\epsilon,\alpha}_s|^2\right]\mathrm{d}t,
			\end{align}
			\begin{align}\label{433}
				&\mathbb{E}\sup_{t\in[0,T]}|I^{\epsilon,\alpha}_3(t)| \nonumber\\
				\leq& C\mathbb{E}\left[\left(\int_{0}^{T}|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2\lVert\sigma_\epsilon(Z^{\epsilon,h_\epsilon}_t,\mathcal{L}_{X^\epsilon_t})-\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_t,\mathcal{L}_{X^\epsilon_t})\rVert^2\mathrm{d}t\right)^\frac{1}{2}\left(\int_{0}^{T}|h_\epsilon(t)|^2\mathrm{d}t\right)^{\frac{1}{2}}\right] \nonumber\\
				\leq& C\left(1+\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon}_t|+\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t|+(\sup_{t\in[0,T]}\mathbb{E}|X^\epsilon_t|^2)^{\frac{1}{2}}\right)\left(\mathbb{E}\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2\right)^{\frac{1}{2}} \nonumber\\
				\leq&
				C\left(\mathbb{E}\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2\right)^{\frac{1}{2}}
			\end{align}
			and
			\begin{align}\label{434}
				&\mathbb{E}\sup_{t\in[0,T]}|I^{\epsilon,\alpha}_4(t)| \nonumber\\
				\leq& C\mathbb{E}\left[\left(\int_{0}^{T}|Z^{\epsilon,h_\epsilon}_t-Z^{\epsilon,h_\epsilon,\alpha}_t|^2\lVert\sigma_\epsilon(Z^{\epsilon,h_\epsilon}_t,\mathcal{L}_{X^\epsilon_t})-\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_t,\mathcal{L}_{X^\epsilon_t})\rVert^2\mathrm{d}t\right)^\frac{1}{2}\left(\int_{0}^{T}|h_\epsilon(t)|^2\mathrm{d}t\right)^{\frac{1}{2}}\right] \nonumber\\
				\leq& \frac{1}{4}\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon}_t-Z^{\epsilon,h_\epsilon,\alpha}_t|^2+C\mathbb{E}\int_{0}^{T}\varrho\left[\sup_{s\in[0,t]}|Z^{\epsilon,h_\epsilon}_s-Z^{\epsilon,h_\epsilon,\alpha}_s|^2\right]\mathrm{d}t.
			\end{align}

			By BDG's inequality, H{\"o}lder's inequality, Young's inequality, (\hyperref[h1]{\textbf{H1}}), Lemma \ref{yozfin} and Lemma \ref{yosifin}, we obtain
			\begin{align}\label{435}
				&\mathbb{E}\sup_{t\in[0,T]}|I^{\epsilon,\alpha}_5(t)| \nonumber\\
				\leq& C\mathbb{E}\left[\left(\int_{0}^{T}|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2\lVert\sigma_\epsilon(Z^{\epsilon,h_\epsilon}_t,\mathcal{L}_{X^\epsilon_t})-\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_t,\mathcal{L}_{X^\epsilon_t})\rVert^2\mathrm{d}t\right)^\frac{1}{2}\right] \nonumber\\
				\leq& C\mathbb{E}\left[\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|\sup_{t\in[0,T]}\lVert\sigma_\epsilon(Z^{\epsilon,h_\epsilon}_t,\mathcal{L}_{X^\epsilon_t})-\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_t,\mathcal{L}_{X^\epsilon_t})\rVert\right] \nonumber\\
				\leq& C\left(\mathbb{E}\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2\right)^\frac{1}{2}\left(\mathbb{E}\sup_{t\in[0,T]}\lVert\sigma_\epsilon(Z^{\epsilon,h_\epsilon}_t,\mathcal{L}_{X^\epsilon_t})-\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_t,\mathcal{L}_{X^\epsilon_t})\rVert^2\right)^\frac{1}{2} \nonumber\\
				\leq& C\left(1+\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon}_t|+\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t|+(\sup_{t\in[0,T]}\mathbb{E}|X^\epsilon_t|^2)^{\frac{1}{2}}\right)\left(\mathbb{E}\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2\right)^\frac{1}{2} \nonumber\\
				\leq& C\left(\mathbb{E}\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2\right)^\frac{1}{2}
			\end{align}
			and
			\begin{align}\label{436}
				&\mathbb{E}\sup_{t\in[0,T]}|I^{\epsilon,\alpha}_6(t)| \nonumber\\
				\leq& C\mathbb{E}\left[\left(\int_{0}^{T}|Z^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2\lVert\sigma_\epsilon(Z^{\epsilon,h_\epsilon}_t,\mathcal{L}_{X^\epsilon_t})-\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_t,\mathcal{L}_{X^\epsilon_t})\rVert^2\mathrm{d}t\right)^\frac{1}{2}\right] \nonumber\\
				\leq& C\left(\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|\right)\left(\mathbb{E}\int_{0}^{T}\lVert\sigma_\epsilon(Z^{\epsilon,h_\epsilon}_t,\mathcal{L}_{X^\epsilon_t})-\sigma_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_t,\mathcal{L}_{X^\epsilon_t})\rVert^2\mathrm{d}t\right)^\frac{1}{2} \nonumber\\
				\leq& \frac{1}{4}\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2+C\mathbb{E}\int_{0}^{T}\varrho\left[\sup_{s\in[0,t]}|Z^{\epsilon,h_\epsilon}_s-Z^{\epsilon,h_\epsilon,\alpha}_s|^2\right]\mathrm{d}t.
			\end{align}

			For the last term, we have
			\begin{align}\label{437}
				\mathbb{E}\sup_{t\in[0,T]}|I^{\epsilon,\alpha}_7(t)|\leq C\mathbb{E}\int_{0}^{T}\varrho\left[\sup_{s\in[0,t]}|Z^{\epsilon,h_\epsilon}_s-Z^{\epsilon,h_\epsilon,\alpha}_s|^2\right]\mathrm{d}t.
			\end{align}

			Denote
			\begin{equation*}
				R(t):=|Z^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2,
			\end{equation*}

			%			By the definition of $\varrho_{\upsilon}$, we can note that there exists an $\upsilon>0$ such that
			%			\begin{equation*}
				%				r^2(1\vee\log r^{-1})\leq \varrho_{\upsilon}(r^2),
				%			\end{equation*}
			then by combining (\ref{431})-(\ref{437}) together and using Jensen's inequality we have
			\begin{align}\label{rt}
				\mathbb{E}\sup_{t\in[0,T]}R(t)\leq&\,\, 2\mathbb{E}\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon,\alpha}_t|^2+2\mathbb{E}\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2\nonumber \\
				\leq&\,\, \frac{1}{2}\mathbb{E}\sup_{t\in[0,T]}R(t)+C\mathbb{E}\int_{0}^{T}\varrho(\sup_{s\in[0,t]}R(s))\mathrm{d}t+C\left(\mathbb{E}\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2\right)^{\frac{1}{2}} \nonumber\\
				&+2\mathbb{E}\sup_{t\in[0,T]}|\breve{Z}^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2 \nonumber\\
				=:&\frac{1}{2}\mathbb{E}\sup_{t\in[0,T]}R(t)+C\mathbb{E}\int_{0}^{T}\varrho(\sup_{s\in[0,t]}R(s))\mathrm{d}t+O_1(\alpha).
			\end{align}
			Since the $L$ in (\ref{rt}) is independent of $\epsilon$ and $\alpha$, by (\ref{yosida1}) we have
			\begin{align*}
				\lim\limits_{\alpha\to 0}O_1(\alpha)=0.
			\end{align*}
			Setting $f(t)=\int_{1}^{t}1/\varrho(s)\mathrm{d}s$, by Lemma \ref{bhr}, we have
			\begin{align*}\label{ad1}
				\mathbb{E}\sup_{t\in[0,T]}R(t)\leq f^{-1}\left(f(O_1(\alpha))+2LT\right).
			\end{align*}
			Since $f$ and $f^{-1}$ are strictly increasing functions and $\int_{0^+}1/\varrho(s)\mathrm{d}s=\infty$, we obtain
			\begin{align*}\label{ad2}
				\lim\limits_{\alpha\to 0}f^{-1}\left(f(O_1(\alpha))+2LT\right)= 0.
			\end{align*}
			Combining (\ref{ad1}) and (\ref{ad2}) together, we get
			\begin{equation*}
				\lim\limits_{\alpha\to 0}\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t-Z^{\epsilon,h_\epsilon}_t|^2=0
			\end{equation*}
			uniformly in $\epsilon>0$, which completes the proof.

		\end{proof}
	\end{lemma}

	Next we consider the Yosida approximation of the  equation (\ref{yy}):
	\begin{align*}
		\begin{cases}
			\mathrm{d}Y^{h,\alpha}_t=\,b(Y^{h,\alpha}_t,\mathcal{L}_{X^0_t})\mathrm{d}t+\sigma(Y^{h,\alpha}_t,\mathcal{L}_{X^0_t})h(t)\mathrm{d}t-A^\alpha(Y^{h,\alpha}_t)\mathrm{d}t, \\
			Y^{h,\alpha}_0=x\in\overline{D(A)}.
		\end{cases}
	\end{align*}

	Similar to Lemma \ref{afin}, we have the following result. For the sake of brevity, we omit the detailed proofs here.
	\begin{lemma}\label{ayfin}
		Assume that \hyperref[h0]{(\textbf{H0})}-\hyperref[h4]{\textbf{(H4)}} hold. For any $p\geq 1$ and $x\in\overline{D(A)}$, there exists $C>0$ such that for any $\alpha>0$,
		\begin{equation*}
			\sup_{t\in[0,T]}|Y^{h,\alpha}_t|^{2p}\leq C,
		\end{equation*}
		where $C$ may be dependent of $p,T,m$ and $x$, but independent of $\epsilon$ and $\alpha$.

		Moreover, for any $x\in\overline{D(A)}$, we have
		\begin{equation*}
			\lim\limits_{\alpha\to 0}\sup_{t\in[0,T]}|Y^{h,\alpha}_t-Y^h_t|^2=0.
		\end{equation*}
	\end{lemma}

