	\subsection{Proof of Theorem 3.6}
	Next we prove the main result on the LDP. We will verify the conditions \textbf{(LDP)$\bm{_{1}}$} and \textbf{(LDP)$\bm{_{2}}$} separately.
	\begin{proposition}\label{ld1}[\textbf{(LDP)$\bm{_{1}}$}]
		For any given $m\in\left(0,\infty\right)$, if $\left\{h_{n}, n\in \mathbb{N}\right\}\subset \mathcal{S}_{m}$ weakly converges to $h\in \mathcal{S}_{m}$ as $n\to \infty$, then
		$$
		\lim\limits_{n\to \infty}\sup\limits_{t\in \left[0,T\right]}\lvert \mathcal{G}^{0}\left(h_{n}\right)\left(t\right)-\mathcal{G}^{0}\left(h\right)\left(t\right) \rvert=0.
		$$
	\end{proposition}	

	\begin{proof}
		Let $Y^h$ be the solution of (\ref{yy}) and $Y^{h}_n$ be the solution of (\ref{yy}) with $h$ replaced by $h_n$. By the definition of $\mathcal{G}^0$, we have $Y^h=\mathcal{G}^0(h)$ and $Y^{h_n}=\mathcal{G}^0(h_n)$, then it is left to verify that
		\begin{align*}
			\lim\limits_{n\to\infty}\sup_{t\in[0,T]}|Y^{h_n}_t-Y^h_t|=0.
		\end{align*}

		Note that $Y^h,Y^{h_n}\in C([0,T],\overline{D(A)})$, $\forall n\in\mathbb{N}$. By Proposition \ref{Yu} we know that both $Y^h$ and $\left\{Y_{h_n}\right\}_{n\geq 1}$ are uniformly bounded, i.e. there exists some constant $C>0$ such that
		\begin{align}\label{yf}
			\max\left\{\sup_{n\geq 1}\sup_{t\in[0,T]}|Y^{h_n}_t|,\sup_{t\in[0,T]}|Y^h_t|\right\}\leq C.
		\end{align}

		Set $\varsigma_{n}(t):=Y_{t}^{h_{n}}-Y_{t}^{h}$, then
		\begin{align*}
			\varsigma_{n}(t)=&-(K_{t}^{h_{n}}-K_{t}^{h}) +\int_{0}^{t}\left[b\left(Y_{r}^{h_{n}},\mathcal{L}_{X_{r}^{0}}\right)-b\left(Y_{r}^{h},\mathcal{L}_{X_{r}^{0}}\right)\right]\,\mathrm{d}r \\
			&+\int_{0}^{t}\left[\sigma\left(Y_{r}^{h_{n}},\mathcal{L}_{X_{r}^{0}}\right)h_{n}(r)-\sigma\left(Y_{r}^{h},\mathcal{L}_{X_{r}^{0}}\right)h(r)\right]\,\mathrm{d}r.
		\end{align*}

		It follows from It$\hat{\text{o}}$'s formula that
		\begin{align*}
			|\varsigma_{n}(t)|^{2}= &2\int_{0}^{t}\left\langle\mathrm{d}K_{r}^{h}-\mathrm{d}K_{r}^{h_{n}},\varsigma_{n}(r)\right\rangle+2\int_{0}^{t}\left\langle b\left(Y_{r}^{h_{n}},\mathcal{L}_{X_{r}^{0}}\right)-b\left(Y_{r}^{h},\mathcal{L}_{X_{r}^{0}}\right),\varsigma_{n}(r)\right\rangle\mathrm{d}r \\
			&+2\int_{0}^{t}\left\langle \sigma\left(Y_{r}^{h},\mathcal{L}_{X_{r}^{0}}\right)\left[h_{n}(r)-h(r)\right],\varsigma_{n}(r)\right\rangle\mathrm{d}r \\
			&+2\int_{0}^{t}\left\langle \left[\sigma\left(Y_{r}^{h_{n}},\mathcal{L}_{X_{r}^{0}}\right)-\sigma\left(Y_{r}^{h},\mathcal{L}_{X_{r}^{0}}\right)\right]h_{n}(r),\varsigma_{n}(r)\right\rangle\mathrm{d}r \\
			=:&I_{1}^{n}(t)+I_{2}^{n}(t)+I_{3}^{n}(t)+I_{4}^{n}(t).
		\end{align*}

		By the Assumption (\hyperref[h1]{\textbf{H1}}) and Proposition \ref{multi}, there exists some constant $L>0$ such that
		\begin{align}\label{361}
			I_{1}^{n}(t)\leq0
		\end{align}
		and
		\begin{align}\label{362}
			|I_{2}^{n}(t)|\leq 2L\int_{0}^{t}\varrho(\sup_{s\in[0,r]}\lvert\varsigma_{n}(s)\rvert^{2})\mathrm{d}r.
		\end{align}			
		By Young's inequalities, the definition of $ \mathcal{S}_{m} $ and Lemma 2.1, we get
		\begin{align}\label{363}
			|I_{4}^{n}(t)|=
			&2\int_{0}^{t}\left\langle \left[\sigma\left(Y_{r}^{h_{n}},\mathcal{L}_{X_{r}^{0}}\right)-\sigma\left(Y_{r}^{h},\mathcal{L}_{X_{r}^{0}}\right)\right]h_{n}(r),\varsigma_{n}(r)\right\rangle\mathrm{d}r \nonumber\\
			&\leq 2\sqrt{L}\int_{0}^{t}\lvert h_{n}(r)\rvert \lvert\varsigma_{n}(r)\rvert\left(\varrho(|\varsigma_n(r)|^2)\right)^{\frac{1}{2}}\mathrm{d}r \nonumber\\
			&\leq 2\sqrt{L}\left(\int_{0}^{T}\lvert h_{n}(r)\rvert^{2}\mathrm{d}r\right)^{\frac{1}{2}}\left(\int_{0}^{t}\lvert \varsigma_{n}(r)\rvert^{2}\varrho(|\varsigma_n(r)|^2)\mathrm{d}r\right)^{\frac{1}{2}} \nonumber\\
			&\leq 2\sqrt{Lm}\left[\left(\sup_{r\in[0,t]}\lvert\varsigma_{n}(r)\rvert^{2}\right)\left(\int_{0}^{t}\varrho(|\varsigma_n(r)|^2)\mathrm{d}r\right)\right]^{\frac{1}{2}} \nonumber\\
			&\leq \frac{1}{2}\sup_{r\in[0,t]}\lvert\varsigma_{n}(r)\rvert^{2}+C\int_{0}^{t}\varrho(\sup_{s\in[0,r]}\lvert\varsigma_{n}(s)\rvert^{2})\mathrm{d}r.
		\end{align}

		%	Here we combine the above four parts together we have $$\sup_{r\in[0,t]}\lvert I_{4}^{n}(r)\rvert\leq \frac{1}{2}\sup_{r\in[0,t]}\lvert\varsigma_{n}(r)\rvert^{2}+C_{L,m}\int_{0}^{t}\lvert\varsigma_{n}(r)\rvert^{2}\mathrm{d}r.$$

		%	Set $$g(t):=\sup\limits_{r\in[0,t]}|\varsigma_{n}(r)|^{2}.$$


		Combining (\ref{361}), (\ref{362}) and (\ref{363}) together, we obtain
		\begin{equation*}
			\sup\limits_{r\in[0,t]}|\varsigma_{n}(r)|^{2}\leq \frac{1}{2}\sup\limits_{r\in[0,t]}|\varsigma_{n}(r)|^{2}+C\int_{0}^{t}\varrho(\sup\limits_{s\in[0,r]}|\varsigma_{n}(s)|^{2})\mathrm{d}r+\sup\limits_{r\in[0,t]}|I^n_3(r)|,
		\end{equation*}
		which implies that
		\begin{equation}\label{y11}
			\sup\limits_{r\in[0,t]}|\varsigma_{r}|^{2}\leq C\int_{0}^{t}\varrho(\sup\limits_{s\in[0,r]}|\varsigma_{n}(s)|^{2})\mathrm{d}r+\sup\limits_{r\in[0,t]}|I^n_3(r)|.
		\end{equation}

