			%        	&-\int_{0}^{t}w_{n}(s)\left[b\left(r,Y_{r}^{u_{n}},\mathcal{L}_{X_{r}^{0}}\right)-b\left(r,Y_{r}^{u},\mathcal{L}_{X_{r}^{0}}\right)\right]\,\mathrm{d}r \\
			%        	&-\int_{0}^{t}w_{n}(s)\left[\sigma\left(r,Y_{r}^{u_{n}},\mathcal{L}_{X_{r}^{0}}\right)-\sigma\left(r,Y_{r}^{u},\mathcal{L}_{X_{r}^{0}}\right)\right]u_{n}(r)\,\mathrm{d}r \\
			%        \end{align*}


		%	Due to the assumption (\hyperref[h1]{H1}), $X^{0}\in C\left(\left[0,T\right],\mathbb{R}^{d}\right)$, we can easily proved that

		%	$$\int_{0}^{T}\lVert \sigma\left(Y_{r}^{u},\mathcal{L}_{X_{r}^{0}}\right)\rVert^{2}\mathrm{d}r< \infty. $$
