		%	Since $\left\{h_{n}, n\in \mathbb{N}\right\}\subset \mathcal{S}_{m}$ converges to $h\in \mathcal{S}_{m}$ as $n\to\infty$, i.e. $u_{n}$ converges to $u$ weakly in $L^{2}\left(\left[0,T\right],\mathbb{R}^{d}\right)$,

		%	$$\int_{0}^{t}\left\langle \sigma\left(Y_{r}^{u},\mathcal{L}_{X_{r}^{0}}\right)u_{n}(r),e \right\rangle\mathrm{d}r \rightarrow \int_{0}^{t}\left\langle \sigma\left(Y_{r}^{u},\mathcal{L}_{X_{r}^{0}}\right)u(r),e \right\rangle\mathrm{d}r, \quad as\, n\rightarrow \infty.$$
