		For $I^n_3(t)$, since $h,\,h_n\in \mathcal{S}_m$, we set $$g_n(t):=\int_{0}^{t}\sigma(Y_{r}^{h},\mathcal{L}_{X_{r}^{0}})\left[h_n(r)-h(r)\right]\mathrm{d}r.$$

		Then we need to show that $g_n(t)$ tends to 0 in $C([0,T],\mathbb{R}^d)$. To begin with, we show that
		\begin{enumerate}
			\item[(i)] $\sup_{n\geq 1}\sup_{r\in[0,T]}|g_n(r)|<\infty$;
			\item[(ii)] $t\mapsto g_n(t), n\geq 1$ is equi-continuous.
		\end{enumerate}

		Firstly, for $0\leq s<t\leq T$, by \hyperref[h2]{(\textbf{H2})} we have
		\begin{align*}
			|g_n(t)-g_n(s)|\leq &\,\left\lvert\int_{s}^{t}\sigma(Y_{r}^{h},\mathcal{L}_{X_{r}^{0}})\left[h_n(r)-h(r)\right]\mathrm{d}r\right\rvert \\
			\leq &\,\int_{s}^{t}\lVert\sigma(Y_{r}^{h},\mathcal{L}_{X_{r}^{0}})\rVert\lvert h_n(r)-h(r)\rvert\mathrm{d}r \\
			\leq &\,\left(\int_{s}^{t}\lVert\sigma(Y_{r}^{h},\mathcal{L}_{X_{r}^{0}})\rVert^2\mathrm{d}r\right)^{\frac{1}{2}}\left(\int_{s}^{t}|h_n(r)-h(r)|^2\mathrm{d}r\right)^{\frac{1}{2}} \\
			\leq&\, 2\sqrt{m}\left(\int_{s}^{t}\lVert\sigma(Y_{r}^{h},\mathcal{L}_{X_{r}^{0}})\rVert^2\mathrm{d}r\right)^{\frac{1}{2}} \\
			\leq&\, 2\sqrt{Lm}\left(\int_{s}^{t}(1+|Y_{r}^{h}|^2+\lVert \mathcal{L}_{X_{r}^{0}}\rVert_2^2)\mathrm{d}r\right)^{\frac{1}{2}}.
		\end{align*}

		Let $s=0$. By (\ref{yf}) and Remark \ref{W2}, we have
