		\end{align*}
		where $C$ is independent of $n$, and then we obtain (i).
		By similar deduction we have
		\begin{align*}
			|g_n(t)-g_n(s)|\leq 2\sqrt{Lm}(C+\mathbb{E}\sup_{r\in[0,t]}|X_r^0|^2)\sqrt{t-s},
		\end{align*}
		which implies (ii).

		By (i), (ii), and Ascoli-Arzela lemma we obtain that $\left\{g_n(t),n\geq1\right\}$ is pre-compact in $C([0,T],\mathbb{R}^d)$.

		Note that
		\begin{equation*}
			\int_{0}^{t}\lVert \sigma(Y_{r}^{h},\mathcal{L}_{X_{r}^{0}})\rVert^2\mathrm{d}r<\infty
		\end{equation*}
		and $h_n(t)$ converges to $h(t)$ weakly in $L^2([0,T],\mathbb{R}^d)$ as $n\to\infty$, which implies that
		\begin{align}\label{gf}
			\lim\limits_{n\to\infty}\sup_{t\in[0,T]}|g_n(t)|=0.
		\end{align}

		By using Taylor formula for $\langle \varsigma_n(s ),g_n(s)\rangle$, we can obtain that
		\begin{align*}
			\frac{1}{2}I^n_3(t)=&\langle g_n(t),\varsigma_{n}(t)\rangle-\int_{0}^{t}\langle \mathrm{d}K^h_s-\mathrm{d}K^{h_n}_s, g_n(s)\rangle -\int_{0}^{t}\langle b(Y_{s}^{h_n},\mathcal{L}_{X_{s}^{0}})-b(Y_{s}^{h},\mathcal{L}_{X_{s}^{0}}), g_n(s)\rangle\mathrm{d}s \\
			&-\int_{0}^{t}\langle \sigma(Y_{s}^{h_n},\mathcal{L}_{X_{s}^{0}})h_n(s)-\sigma(Y_{s}^{h},\mathcal{L}_{X_{s}^{0}})h(s), g_n(s)\rangle\mathrm{d}s \\
			=:& I^n_{31}(t)+I^n_{32}(t)+I^n_{33}(t)+I^n_{34}(t).
		\end{align*}

		For $I^n_{31}(t)$, since
		\begin{align*}
			\sup_{t\in[0,T]}|I^n_{31}(t)|\leq \sup_{t\in[0,T]}|g_n(t)|\,\sup_{t\in[0,T]}|\varsigma_n(t)|,
		\end{align*}
		by (\ref{yf}) and (\ref{gf}) we have
		\begin{align}\label{3631}
			\lim\limits_{n\to\infty}\sup_{t\in[0,T]}|I^n_{31}(t)|=0.
		\end{align}
		Similarly, by (\ref{mono}) and (\ref{yf}) we obtain
		\begin{align}\label{3632}
			\lim\limits_{n\to\infty}\sup_{t\in[0,T]}|I^n_{32}(t)|=0.
		\end{align}

		For $I^n_{33}(t)$, note that
		\begin{align*}
			\sup_{t\in[0,T]}|I^n_{33}(t)|\leq T\sup_{t\in[0,T]}\left(|b(Y_{t}^{h_n},\mathcal{L}_{X_{t}^{0}})|+|b(Y_{t}^{h},\mathcal{L}_{X_{t}^{0}})| \right)\,\sup_{t\in[0,T]}|g_n(t)|,
		\end{align*}
		then by \hyperref[h1]{\textbf{(H1)}} and (\ref{gf}) we get
		\begin{align}\label{3633}
			\lim\limits_{n\to\infty}\sup_{t\in[0,T]}|I^n_{33}(t)|=0.
		\end{align}
		By \hyperref[h2]{\textbf{(H2)}} and $h_n,\,h\in \mathcal{ S }_m$, we have
		\begin{align}\label{3634}
			\lim\limits_{n\to\infty}\sup_{t\in[0,T]}|I^n_{34}(t)|=0.
		\end{align}

		Let $f(t)=\int_{1}^{t}1/\varrho(s)\mathrm{d}s$. By (\ref{3631})-(\ref{3634}) and applying Lemma \ref{bhr} to the inequality (\ref{y11}), we get
		\begin{align*}
			\sup\limits_{r\in[0,t]}|\varsigma_{r}|^{2}\leq f^{-1}\left(f(\sup\limits_{r\in[0,t]}|I^n_3(r)|)+CLT\right),
		\end{align*}
		similar to the proof of Lemma \ref{afin}, we obtain
		\begin{align*}
			\lim\limits_{n\to\infty}\sup_{t\in[0,T]}|Y^{h_n}_t-Y^h_t|=0,
		\end{align*}
		which is the desired result.
	\end{proof}



