	To verify \textbf{(LDP)$\bm{_{2}}$}, we need the following lemma.

	\begin{lemma}\label{ep0}
		Under (\hyperref[h0]{\textbf{H0}}), (\hyperref[h1]{\textbf{H1}}) and (\hyperref[h2]{\textbf{H2}}), it holds that
		$$\lim\limits_{\epsilon\to 0}\mathbb{E}\left(\sup_{t\in[0,T]}\lvert X_{t}^{\epsilon}-X_{t}^{0}\rvert^{2}\right)=0.$$
		%		where $\rho_{b,\epsilon}$ and $\rho_{\sigma,\epsilon}$ is given in \hyperref[h2]{\textbf{(H2)}}.
	\end{lemma}

	\begin{proof}
		By applying It$\hat{\text{o}}$'s formula we have
		\begin{align*}
			&\lvert X_{t}^{\epsilon}-X_{t}^{0}\rvert^{2} \\
			=&2\int_{0}^{t}\left\langle b_{\epsilon}\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right)-b\left(X_{r}^{0},\mathcal{L}_{X_{r}^{0}}\right), X_{r}^{\epsilon}-X_{r}^{0}\right\rangle\mathrm{d}r
			+2\sqrt{\epsilon}\int_{0}^{t}\left\langle\sigma_{\epsilon}\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right), X_{r}^{\epsilon}-X_{r}^{0}\right\rangle\mathrm{d}W(s) \\
			&+\epsilon\int_{0}^{t}\lVert\sigma_{\epsilon}\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right)\rVert^{2}\mathrm{d}r+\int_{0}^{t}\left\langle X_{r}^{\epsilon}-X_{r}^{0},\mathrm{d}K_{r}^{0}-\mathrm{d}K_{r}^{\epsilon}\right\rangle \\
			=:&J_{1}^{\epsilon}(t)+J_{2}^{\epsilon}(t)+J_{3}^{\epsilon}(t)+J_{4}^{\epsilon}(t).
		\end{align*}
		Next we estimate the four items above.

		For $J_{1}^{\epsilon}(t)$,
		by Jensen's inequality,  (\hyperref[h1]{\textbf{H1}}),(\hyperref[h2]{\textbf{H2}}) and Remark \ref{W2},
		\begin{align*}
			\sup_{t\in [0,T]}\lvert J_{1}^{\epsilon}(t)\rvert
			\leq& \,2\int_{0}^{T}\lvert\left\langle X_{r}^{\epsilon}-X_{r}^{0},  b_{\epsilon}\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right)-b\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right)\right\rangle\rvert\mathrm{d}r \\
			&+2\int_{0}^{T}\lvert\left\langle X_{r}^{\epsilon}-X_{r}^{0},  b\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right)-b\left(X_{r}^{0},\mathcal{L}_{X_{r}^{0}}\right)\right\rangle\rvert\mathrm{d}r \\
			\leq& \,2\rho_{b,\epsilon}\int_{0}^{T}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert\mathrm{d}r+2L\int_{0}^{T}\varrho\left[\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}+\mathbb{W}_2^{2}\left(\mathcal{L}_{X_{r}^{\epsilon}},\mathcal{L}_{X_{r}^{0}}\right)\right]\mathrm{d}r  \\
			\leq& \,\rho_{b,\epsilon}\int_{0}^{T}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\,\mathrm{d}r+2L\int_{0}^{T}\varrho(|X_r^\epsilon-X_r^0|^2)\mathrm{d}r+2L\int_{0}^{T}
			\mathbb{E}\left[\varrho(\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2})\right]\,\mathrm{d}r+T\rho_{b,\epsilon}.
			%			\leq& \,(3L+1)\int_{0}^{T}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\,\mathrm{d}r+L\int_{0}^{T}
			%			\mathbb{E}\left(\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\right)\,\mathrm{d}r+\rho_{b,\epsilon}^{2}T.\\
		\end{align*}
		%		Since $\varrho(\cdot)$ is concave and increasing, there must exist a positive number $C$ such that
		%		\begin{align*}
			%			\varrho(u)\leq C(1+u).
			%		\end{align*}

		Thus we have
		\begin{align}\label{451}
			\mathbb{E}\left(\sup_{t\in [0,T]}\lvert J_{1}^{\epsilon}(t)\rvert\right)\leq T\rho_{b,\epsilon}\mathbb{E}\left(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\right)+4L\mathbb{E}\int_{0}^{T}\varrho(\sup_{s\in [0,r]}\lvert X_{s}^{\epsilon}-X_{s}^{0}\rvert^{2})\,\mathrm{d}r+T\rho_{b,\epsilon}.
		\end{align}

		For $J_{3}^{\epsilon}(t)$,
		since $\varrho(\cdot)$ is concave and increasing, there exists a positive number $a$ such that
		\begin{align}\label{lin}
			\varrho(u)\leq a(1+u).
		\end{align}
		By (\hyperref[h1]{\textbf{H1}}), (\hyperref[h2]{\textbf{H2}}) and Remark \ref{W2} again, we get
		\begin{align}\label{453}
			\mathbb{E}\left(\sup_{t\in [0,T]}\lvert J_{3}^{\epsilon}(t)\rvert\right)
			=&\, \epsilon\,\mathbb{E}\int_{0}^{T}\lVert\sigma_{\epsilon}\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right)\rVert^{2}\,\mathrm{d}r \nonumber\\
			\leq&\, C\epsilon\,\mathbb{E}\int_{0}^{T}\lVert\sigma_{\epsilon}\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right)-\sigma\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right)\rVert^{2}\,\mathrm{d}r +C\epsilon\int_{0}^{T}\lVert\sigma\left(X_{r}^{0},\mathcal{L}_{X_{r}^{0}}\right)\rVert^{2}\,\mathrm{d}r \nonumber\\
			&+\, C\epsilon\,\mathbb{E}\int_{0}^{T}\lVert\sigma\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right)-\sigma\left(X_{r}^{0},\mathcal{L}_{X_{r}^{0}}\right)\rVert^{2}\,\mathrm{d}r \nonumber\\
			\leq&\, CT\epsilon\rho_{\sigma,\epsilon}^{2}+CL\epsilon\,\mathbb{E}\int_{0}^{T}\varrho\left[\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}+\mathbb{W}_2^{2}\left(\mathcal{L}_{X_{r}^{\epsilon}},\mathcal{L}_{X_{r}^{0}}\right)\right]\mathrm{d}r \nonumber\\
			&+\,C\epsilon\int_{0}^{T}\lVert\sigma\left(X_{r}^{0},\mathcal{L}_{X_{r}^{0}}\right)\rVert^{2}\,\mathrm{d}r \nonumber\\
			\leq&\, CT\epsilon\rho_{\sigma,\epsilon}^{2}+CL\epsilon \int_{0}^{T}\,\mathbb{E}\left[\varrho(\sup_{s\in[0,r]}\lvert X_{s}^{\epsilon}-X_{s}^{0}\rvert^{2})\right]\mathrm{~d}r +\,CLT\epsilon\nonumber\\
			\leq&\, CT\epsilon\rho_{\sigma,\epsilon}^2+\,CLT\epsilon \,\mathbb{E}\left(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\right)+\,CLT(1+a)\epsilon.
		\end{align}

		For $J_{2}^{\epsilon}(t)$,
		by BDG's inequality and Young's inequality, we have
		\begin{align}\label{452}
			\mathbb{E}\left(\sup_{t\in [0,T]}\lvert J_{2}^{\epsilon}(t)\rvert\right)
			\leq& C\sqrt{\epsilon}\,\mathbb{E}\left[\int_{0}^{T}\lVert\sigma_{\epsilon}\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right)\rVert^{2}\cdot\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\,\mathrm{d}r\right]^{\frac{1}{2}} \nonumber\\
			\leq& \frac{1}{4}\,\mathbb{E}\left(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\right)+C\epsilon\,\mathbb{E}\int_{0}^{T}\lVert\sigma_{\epsilon}\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right)\rVert^{2}\,\mathrm{d}r \nonumber\\
			\leq& \frac{1}{4}\,\mathbb{E}\left(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\right)+CL\epsilon\int_{0}^{T}\mathbb{E}\left[\varrho(\sup_{s\in[0,r]}\lvert X_{s}^{\epsilon}-X_{s}^{0}\rvert^{2})\right]\mathrm{d}r+CT\epsilon\rho_{\sigma,\epsilon}^{2} \nonumber\\
			\leq& \left(\frac{1}{4}+CLT\epsilon\right)\,\mathbb{E}\left(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\right)+CT\epsilon\rho_{\sigma,\epsilon}^{2}+\,CLT\epsilon.
		\end{align}

		For $J_{4}^{\epsilon}(t)$, by (\ref{mono}) we have
		\begin{align}\label{454}
			\sup_{t\in [0,T]} J_{4}^{\epsilon}(t)\leq 0.
		\end{align}


		Combining (\ref{451})-(\ref{454}) together, we obtain
		\begin{align*}
			&\left(\frac{3}{4}-CLT\epsilon-T\rho_{b,\epsilon}\right)\,\,\mathbb{E}\left(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\right) \\
			\leq& CL\mathbb{E}\int_{0}^{T}\varrho(\sup_{s\in[0,r]}\lvert X_{s}^{\epsilon}-X_{s}^{0}\rvert^{2})\,\mathrm{d}r+T\rho_{b,\epsilon}+CT\epsilon\rho_{\sigma,\epsilon}^{2} \\
			=:&CL\mathbb{E}\int_{0}^{T}\varrho(\sup_{s\in[0,r]}\lvert X_{s}^{\epsilon}-X_{s}^{0}\rvert^{2})\,\mathrm{d}r+O_2(\epsilon).
		\end{align*}
		By (\hyperref[h2]{\textbf{H2}}) we can deduce that
		\begin{align*}
			\lim\limits_{\epsilon\to0}O_2(\epsilon)=0.
		\end{align*}

		Since $X^{0}\in C\left([0,T],\mathbb{R}^{d}\right)$ and  by (\hyperref[h1]{\textbf{H1}}),  there exists $\epsilon_{0}>0$ small enough such that for any $\epsilon\in \left(0,\epsilon_{0}\right]$,
		$$\frac{3}{4}-CLT\epsilon-T\rho_{b,\epsilon}\geq\frac{1}{4}.$$
		By Lemma \ref{bhr}, we have
		\begin{align*}
			\mathbb{E}\left(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\right)\leq f^{-1}\left(f(O_2(\epsilon))+CLT\right),
		\end{align*}
		where $f(t)=\int_{1}^{t}1/\varrho(s)\mathrm{d}s$. Similar to the proof of Proposition \ref{ld1}, we obtain
		$$\lim\limits_{\epsilon\to 0}\mathbb{E}\left(\sup_{t\in[0,T]}\lvert X_{t}^{\epsilon}-X_{t}^{0}\rvert^{2}\right)=0,$$
		which is the desired result.
	\end{proof}



	Now we are in the position to verify  \textbf{(LDP)$\bm{_{2}}$}.

	\begin{proposition}\label{ld2}[\textbf{(LDP)$\bm{_{2}}$}]
		For any given $m\in\left(0,\infty\right)$, let $\left\{h_{\epsilon}, \epsilon>0\right\}\subset \mathcal{D}_{m}$, then
		$$
		\lim\limits_{\epsilon\to 0}\mathbb{E}\left(\sup\limits_{t\in \left[0,T\right]}\lvert Z_{t}^{\epsilon,h_{\epsilon}}-\mathcal{G}^{0}\left(h_{\epsilon}\right)\left(t\right)\rvert^{2}\right)=0.
		$$
		\begin{proof}
			Let $Y_{t}^{h_{\epsilon}}$ be the solution of (\ref{yy}) with $h$ replaced by $h_{\epsilon}$, then $\mathcal{G}^{0}(h_{\epsilon})=Y^{h_{\epsilon}}$.
			Since
			\begin{align}
				\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon}_t-Y^{h_\epsilon}_t|^2\leq &\,3\,\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon}_t-Z^{\epsilon,h_\epsilon,\alpha}_t|^2 \\
				&\,+3\,\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t-Y^{h_\epsilon,\alpha}_t|^2 \\
				&\,+3\,\mathbb{E}\sup_{t\in[0,T]}|Y^{h_\epsilon,\alpha}_t-Y^{h_\epsilon}_t|^2.
			\end{align}

			By Lemma \ref{afin} and Lemma \ref{ayfin}, for any $\delta>0$, there exists some constant $\alpha$ independent of $\epsilon$ such that
			\begin{equation}\label{fin21}
				\mathbb{E}\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon}_t-Z^{\epsilon,h_\epsilon,\alpha}|^2\leq\frac{\delta}{9}
			\end{equation}
			and
			\begin{equation}\label{fin23}
				\mathbb{E}\sup_{t\in[0,T]}|Y^{h_\epsilon,\alpha}_t-Y^{h_\epsilon}_t|^2\leq\frac{\delta}{9}.
			\end{equation}

			For this $\alpha$, we have
			\begin{align*}
				\phi_{t}^{\epsilon,h_{\epsilon},\alpha}\coloneqq&\,Z_{t}^{\epsilon,h_{\epsilon},\alpha}-Y_{t}^{h_{\epsilon},\alpha}\\
				=&\int_{0}^{t}\left[A^\alpha(Y^{h_\epsilon,\alpha}_r)-A_\epsilon^\alpha(Z_{r}^{\epsilon,h_{\epsilon},\alpha})\right]\mathrm{d}r +\int_{0}^{t}\left[b_{\epsilon}\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)-b\left(Y_{r}^{h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{0}}\right)\right]\,\mathrm{d}r \\
				&+\int_{0}^{t}\left[\sigma_{\epsilon}\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)h_{\epsilon}(r)-\sigma\left(Y_{r}^{h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{0}}\right)h_{\epsilon}(r)\right]\,\mathrm{d}r +\sqrt{\epsilon}\int_{0}^{t}\sigma_{\epsilon}\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)\,\mathrm{d}W_r.
			\end{align*}
			By It$\hat{\text{o}}$'s formula we get
			\begin{align*}
				\lvert\phi_{t}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}=&\,2\int_{0}^{t}\left\langle \phi_{r}^{\epsilon,h_{\epsilon},\alpha},A^\alpha(Y_r^{h_\epsilon,\alpha})-A^\alpha(Z_{r}^{\epsilon,h_{\epsilon},\alpha})\right\rangle\mathrm{d}r  \\
				&+2\int_{0}^{t}\left\langle \phi_{r}^{\epsilon,h_{\epsilon},\alpha},A^\alpha(Z_{r}^{\epsilon,h_{\epsilon},\alpha})-A_\epsilon^\alpha(Z_{r}^{\epsilon,h_{\epsilon},\alpha})\right\rangle\mathrm{d}r  \\ &+2\int_{0}^{t}\left\langle\phi_{r}^{\epsilon,h_{\epsilon},\alpha},b_{\epsilon}\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)-b\left(Y_{r}^{h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{0}}\right)\right\rangle\,\mathrm{d}r \\
				&+2\int_{0}^{t}\left\langle\phi_{r}^{\epsilon,h_{\epsilon},\alpha},\sigma_{\epsilon}\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)h_{\epsilon}(r)-\sigma\left(Y_{r}^{h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{0}}\right)h_{\epsilon}(r)\right\rangle\,\mathrm{d}r \\
				&+2\sqrt{\epsilon}\int_{0}^{t}\left\langle\phi_{r}^{\epsilon,h_{\epsilon},\alpha},\sigma_{\epsilon}\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)\,\mathrm{d}W_r\right\rangle +\epsilon\int_{0}^{t}\lVert \sigma_{\epsilon}\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)\rVert^{2}\mathrm{d}r \\
				=:&I_{1}^{\epsilon,\alpha}(t)+I_{2}^{\epsilon,\alpha}(t)+I_{3}^{\epsilon,\alpha}(t)+I_{4}^{\epsilon,\alpha}(t)+I_{5}^{\epsilon,\alpha}(t)+I_{6}^{\epsilon,\alpha}(t).
			\end{align*}

			Next we estimate the six items in the equality above.

			(1) $I_{1}^{\epsilon,\alpha}(t)$.
			By (\ref{mono}) and the monotonicity of $A^\alpha$ we immediately get
			\begin{align}\label{421}
				I_{1}^{\epsilon,\alpha}(t)\leq 0.
			\end{align}

			(2) $I_{2}^{\epsilon,\alpha}(t)$. For any $\tau>0$ we have
			\begin{align}\label{422}
				\sup_{t\in [0,T]}\lvert I_{2}^{\epsilon,\alpha}(t)\rvert\leq \tau\mathbb{E}\left(\sup_{t\in[0,T]}|\phi_{t}^{\epsilon,h_\epsilon,\alpha}|^2\right)+C_\tau\int_{0}^{T}\mathbb{E}|A^\alpha(Z^{\epsilon,h_\epsilon,\alpha}_t)-A^\alpha_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_t)|^2\mathrm{d}t.
			\end{align}
			Next we show that as $\epsilon\to 0$
			\begin{equation}\label{Psii}
				\Psi_\epsilon:=\int_{0}^{T}\mathbb{E}|A^\alpha(Z^{\epsilon,h_\epsilon,\alpha}_t)-A^\alpha_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_t)|^2\mathrm{d}t\to 0.
			\end{equation}
			For any $j>0$, we have
			\begin{align*}
				\Psi_\epsilon=&\int_{0}^{T}\mathbb{E}\left[|A^\alpha(Z^{\epsilon,h_\epsilon,\alpha}_t)-A^\alpha_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_t)|^2\mathbb{I}_{\left\{\sup_{t\in [0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t|\leq j\right\}}\right]\mathrm{d}t \\
				&+\int_{0}^{T}\mathbb{E}\left[|A^\alpha(Z^{\epsilon,h_\epsilon,\alpha}_t)-A^\alpha_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_t)|^2\mathbb{I}_{\left\{\sup_{t\in [0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t|> j\right\}}\right]\mathrm{d}t \\
				=:&J_1^{\epsilon,j}+J_2^{\epsilon,j}.
			\end{align*}

			By \hyperref[h4]{\textbf{(H4)}} we have $\lim\limits_{\epsilon\to 0}J_1^{\epsilon,j}=0$. For $J_2^{\epsilon,j}$,			
			by Lipschitz continuity of Yosida approximation and \hyperref[h0]{(\textbf{H0})} we have
			\begin{align*}
				|A^\alpha(Z^{\epsilon,h_\epsilon,\alpha}_t)|+|A^\alpha_\epsilon(Z^{\epsilon,h_\epsilon,\alpha}_t)|\leq C_\alpha\left(1+|Z^{\epsilon,h_\epsilon,\alpha}_t|\right),
			\end{align*}

			and hence
			\begin{align*}
				J_2^{\epsilon,j}\leq &C_\alpha\mathbb{E}\left[\left(1+\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t|^2\right)\mathbb{I}_{\left\{\sup_{t\in [0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t|> j\right\}}\right] \\
				\leq&C_\alpha\mathbb{E}\left[\left(1+\sup_{t\in[0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t|^2\right)\frac{\sup_{t\in [0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t|^2}{j^2}\right] \\
				\leq&C_\alpha\sup_{\epsilon}\frac{\mathbb{E}\left[\sup_{t\in [0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t|^2+\sup_{t\in [0,T]}|Z^{\epsilon,h_\epsilon,\alpha}_t|^4\right]}{j^2}\leq C_\alpha \cdot C/j^2,
			\end{align*}
			where the last inequality follows from Lemma \ref{yozfin} and $C$ is independent of $\epsilon$ and $\alpha$. This implies $\lim\limits_{j\to\infty}J_2^{\epsilon,j}=0$ for any $\epsilon$, and therefore (\ref{Psii}).

			(3) $I_{3}^{\epsilon,\alpha}(t)$.
			By Assumptions (\hyperref[h1]{\textbf{H1}}) and Remark \ref{W2}, we have
			\begin{align*}
				\sup_{t\in [0,T]}\lvert I_{3}^{\epsilon,\alpha}(t)\rvert
				\leq& \,2\int_{0}^{T}\lvert\left\langle \phi_{r}^{\epsilon,h_{\epsilon},\alpha},  b_{\epsilon}\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)-b\left(Y_{r}^{h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{0}}\right)\right\rangle\rvert\mathrm{d}r \\
				\leq& \,2\int_{0}^{T}\lvert\left\langle \phi_{r}^{\epsilon,h_{\epsilon},\alpha},  b_{\epsilon}\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)-b\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)\right\rangle\rvert\mathrm{d}r \\
				&+2\int_{0}^{T}\lvert\left\langle \phi_{r}^{\epsilon,h_{\epsilon},\alpha},  b\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)-b\left(Y_{r}^{h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{0}}\right)\right\rangle\rvert\mathrm{d}r \\
				\leq&\,2\rho_{b,\epsilon}\int_{0}^{T}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert\mathrm{d}r+2L\int_{0}^{T}\varrho(\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2})\mathrm{d}r+2L\int_{0}^{T}\varrho\left(\mathbb{W}^2_{2}(\mathcal{L}_{X_{r}^{\epsilon}},\mathcal{L}_{X_{r}^{0}})\right)\mathrm{d}r \\
				\leq&\,T\rho_{b,\epsilon}+\rho_{b,\epsilon}
				\int_{0}^{T}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}\mathrm{d}r+2L\int_{0}^{T}\varrho(\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2})\mathrm{d}r+2L\int_{0}^{T}\mathbb{E}\left[\varrho\left(\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\right)\right]\mathrm{d}r \\
				%				\leq&\,\rho_{b,\epsilon}^{2}T+\int_{0}^{T}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}\mathrm{d}r+2L\int_{0}^{T}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}\left(1\vee\log|\phi_{r}^{\epsilon,h_{\epsilon},\alpha}|^{-1}\right)\mathrm{d}r+L\left[\int_{0}^{T}\mathbb{E}\left(\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\right)\mathrm{d}r+\int_{0}^{T}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}\mathrm{d}r\right] \\
				\leq&T\rho_{b,\epsilon}+\,T\rho_{b,\epsilon}\sup_{r\in [0,T]}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}+2L\int_{0}^{T}\varrho(\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2})\mathrm{d}r+LT\mathbb{E}\left[\varrho(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2})\right].	
			\end{align*}
			Hence
			\begin{align}\label{423}
				\mathbb{E}\left(\sup_{r \in[0, T]}\lvert I_{3}^{\epsilon,\alpha}(t)\rvert\right)\leq& T\rho_{b,\epsilon}+\,T\rho_{b,\epsilon}\mathbb{E}\left(\sup_{r\in [0,T]}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}\right)+2L\int_{0}^{T}\mathbb{E}\left[\varrho(\sup_{s\in[0,r]}\lvert\phi_{s}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2})\right]\mathrm{d}r \nonumber\\
				&+LT\mathbb{E}\left[\varrho(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2})\right].
				%				\leq&\, 2L\int_{0}^{T}\mathbb{E}\left[\varrho(\sup_{s\in[0,r]}\lvert\phi_{s}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2})\right]\mathrm{d}r+LT\mathbb{E}\left[\varrho(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2})\right]+T\rho_{b,\epsilon}.
			\end{align}

			(4) $I_{4}^{\epsilon,\alpha}(t)$. By (\hyperref[h2]{\textbf{H2}}),  we have
			\begin{align*}
				&\mathbb{E}\left(\sup_{t\in [0,T]}\lvert I_{4}^{\epsilon,\alpha}(t)\rvert\right) \nonumber\\
				\leq& \, 2\mathbb{E}\int_{0}^{T}\lvert\left\langle \phi_{r}^{\epsilon,h_{\epsilon},\alpha}, \left[\sigma_{\epsilon}\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)-\sigma\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)\right]h_{\epsilon}(r)\right\rangle\rvert\,\mathrm{d}r \nonumber\\
				&+ 2\mathbb{E}\int_{0}^{T}\lvert\left\langle \phi_{r}^{\epsilon,h_{\epsilon},\alpha}, \left[\sigma\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)-\sigma\left(Y_{r}^{h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{0}}\right)\right]h_{\epsilon}(r)\right\rangle\rvert\,\mathrm{d}r  \nonumber\\
				\leq& \,2\rho_{\sigma,\epsilon}\mathbb{E}\int_{0}^{T}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert\lvert h_{\epsilon}(r)\rvert\,\mathrm{d}r+2\mathbb{E}\int_{0}^{T}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert\cdot\lVert\sigma\left(Z_{r}^{h_{\epsilon}},\mathcal{L}_{X_{r}^{\epsilon}}\right)-\sigma\left(Y_{r}^{h_{\epsilon}},\mathcal{L}_{X_{r}^{0}}\right)\rVert\cdot\lvert h_{\epsilon}(r)\rvert\,\mathrm{d}r \nonumber\\
				\leq& \, T\rho_{\sigma,\epsilon}\mathbb{E}\left(\sup_{r\in [0,T]}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}\right)+\rho_{\sigma,\epsilon}\int_{0}^{T}\lvert h_{\epsilon}(r)\rvert^{2}\,\mathrm{d}r \nonumber\\
				&+2\mathbb{E}\left(\sup_{r\in[0,T]}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert\int_{0}^{T}\lVert\sigma\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)-\sigma\left(Y_{r}^{h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{0}}\right)\rVert\cdot|h_\epsilon|\,\mathrm{d}r\right).
			\end{align*}
			Furthermore, for any $\tau>0$, by Young's inequality we have
			\begin{align}\label{424}
				\mathbb{E}\left(\sup_{t\in [0,T]}\lvert I_{4}^{\epsilon,\alpha}(t)\rvert\right)\leq& \, T\rho_{\sigma,\epsilon}\mathbb{E}\left(\sup_{r\in [0,T]}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}\right)+m\rho_{\sigma,\epsilon}+\tau\mathbb{E}\left(\sup_{r\in[0,T]}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}\right) \nonumber\\
				&+C\int_{0}^{T}\left(\mathbb{E}(\varrho(\sup_{s\in[0,r]}\lvert\phi_{s}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}))+\mathbb{E}\left[\varrho(\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2})\right]\right)\,\mathrm{d}r \nonumber\\
				=&(\tau+T\rho_{\sigma,\epsilon})\mathbb{E}\left(\sup_{r\in[0,T]}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}\right)+C\int_{0}^{T}\mathbb{E}\left[\varrho(\sup_{s\in[0,r]}\lvert\phi_{s}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2})\right]\mathrm{d}r \nonumber\\
				&+C\mathbb{E}\left[\varrho(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2})\right]+m\rho_{\sigma,\epsilon},
			\end{align}
			where $C$ depends on $m,T,\tau$ and $L$.

			(5) $I_{5}^{\epsilon,\alpha}(t)$ and $I_{6}^{\epsilon,\alpha}(t)$. By (\hyperref[h2]{\textbf{H2}}), Young's inequlity and (\ref{lin}) we have
			%Along with the assumptions above, due to Burkholder-Davis-Gundy's inequality, one can obtain
			\begin{align}\label{425}
				&\mathbb{E}\left(\sup_{t\in [0,T]}\lvert I_{5}^{\epsilon,\alpha}(t)\rvert\right)+\mathbb{E}\left(\sup_{t\in [0,T]}\lvert I_{6}^{\epsilon,\alpha}(t)\rvert\right) \nonumber\\
				\leq&\, C\sqrt{\epsilon}\,\mathbb{E}\left[\int_{0}^{T}\lVert\sigma_{\epsilon}\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)\rVert^{2}\cdot\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}\,\mathrm{d}r\right]^{\frac{1}{2}}+\epsilon\,\mathbb{E}\int_{0}^{T}\lVert\sigma_{\epsilon}\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)\rVert^{2}\,\mathrm{d}r \nonumber\\
				\leq& \,\tau\mathbb{E}\left(\sup_{r\in [0,T]}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}\right)+C\epsilon\,\mathbb{E}\int_{0}^{T}\lVert\sigma_{\epsilon}\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)\rVert^{2}\,\mathrm{d}r \nonumber\\
				\leq& \, \tau\mathbb{E}\left(\sup_{r\in [0,T]}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}\right)+C\epsilon\,\mathbb{E}\int_{0}^{T}\lVert\sigma_{\epsilon}\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)-\sigma\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)\rVert^{2}\,\mathrm{d}r \nonumber\\
				&+C\epsilon\,\mathbb{E}\int_{0}^{T}\lVert\sigma\left(Z_{r}^{\epsilon,h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{\epsilon}}\right)-\sigma\left(Y_{r}^{h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{0}}\right)\rVert^{2}\,\mathrm{d}r+C\epsilon\,\mathbb{E}\int_{0}^{T}\lVert\sigma\left(Y_{r}^{h_{\epsilon},\alpha},\mathcal{L}_{X_{r}^{0}}\right)\rVert^{2}\,\mathrm{d}r \nonumber\\
				\leq& \, \tau\mathbb{E}\left(\sup_{r\in [0,T]}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}\right)+C\rho_{\sigma,\epsilon}^{2}\epsilon+C\epsilon\,\int_{0}^{T}\mathbb{E}\left[\varrho(\sup_{r\in [0,s]}\lvert\phi_{s}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2})\right]\,\mathrm{d}r \nonumber\\
				&+ C\epsilon\,\int_{0}^{T}\mathbb{E}\left[\varrho(\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2})\right]\,\mathrm{d}r+C\epsilon\sup_{h_{\epsilon}\in \mathcal{S}_{m}}\left(\sup_{r\in [0,T]}\lvert Y_{r}^{h_{\epsilon}}\rvert^{2}\right)+C\epsilon\sup_{r\in [0,T]}|X_{r}^{0}|^{2}+C\epsilon \nonumber\\
				\leq&\, \left(\tau+\,Ca\epsilon\right)\mathbb{E}\left(\sup_{r\in [0,T]}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}\right)+Ca\epsilon\,\mathbb{E}\left(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\right)+C(1+a)\epsilon+C\rho_{\sigma,\epsilon}^{2}\epsilon,
			\end{align}
			where $C$  depends on $\tau,L,T,Y^{h_\epsilon},X^{0},m$.

			%			Noting that there exist an $\upsilon>0$ such that
			%			\begin{equation*}
				%				r^2(1\vee\log|r|^{-1})\leq \varrho_{\upsilon}(r^2)
				%			\end{equation*}
			Taking $\tau=\frac{1}{8}$ and combining (\ref{421})-(\ref{425}) together, we get for any $\epsilon\in \left(0,\epsilon_{0}\right]$,
			\begin{align*}
				&\left(\frac{5}{8}-Ca\epsilon-T\rho_{\sigma,\epsilon}-T\rho_{b,\epsilon}\right)\mathbb{E}\left(\sup_{r\in [0,T]}\lvert\phi_{r}^{\epsilon,h_{\epsilon},\alpha}\rvert^{2}\right)    \nonumber\\
				\leq&\, CL\int_{0}^{T}\mathbb{E}\left[\varrho(\sup_{s\in[0,r]}|\phi_{s}^{\epsilon,h_\epsilon}|^2)\right]\mathrm{d}r+CTa\epsilon\,\mathbb{E}\left(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\right)+C\mathbb{E}\left[\varrho(\sup_{r\in [0,T]}\lvert X^\epsilon_r-X^0_r\rvert^2)\right]  \nonumber\\ &+C\left(\epsilon+\rho_{b,\epsilon}+\rho_{\sigma,\epsilon}+\epsilon\rho_{\sigma,\epsilon}^{2}+\Psi_\epsilon\right) \\
				=:&CL\int_{0}^{T}\mathbb{E}\left[\varrho(\sup_{s\in[0,r]}|\phi_{s}^{\epsilon,h_\epsilon}|^2)\right]\mathrm{d}r+O_3(\epsilon).
			\end{align*}
			By Lemma \ref{ep0} and (\ref{Psii}) we get
			\begin{align*}
				\lim\limits_{\epsilon\to 0}O_3(\epsilon)=0.
			\end{align*}
			Since there exists a constant $\epsilon_1\leq \epsilon_{0}$ small enough such that for any $\epsilon\in(0,\epsilon_{1}],$
			$$ \frac{5}{8}-Ca\epsilon-T\rho_{\sigma,\epsilon}-T\rho_{b,\epsilon}\geq \frac{1}{4}. $$
			Setting $f(t)=\int_{1}^{t}1/\varrho(s)\mathrm{d}s$, then by Lemma \ref{bhr}, we obtain
			\begin{align*}
				\mathbb{E}\left(\sup_{t\in[0,T]}\lvert Z_{t}^{\epsilon,h_{\epsilon},\alpha}-Y_{t}^{h_{\epsilon},\alpha}\rvert^{2}\right)\leq f^{-1}\left(f(O_3(\epsilon)+CLT)\right).
			\end{align*}
			Since $f$ and $f^{-1}$ are strictly increasing functions and $\int_{0^+}1/\varrho(s)\mathrm{d}s=\infty$, we have
			$$\lim\limits_{\epsilon\to 0}\mathbb{E}\left(\sup_{t\in[0,T]}\lvert Z_{t}^{\epsilon,h_{\epsilon},\alpha}-Y_{t}^{h_{\epsilon},\alpha}\rvert^{2}\right)=0.$$

			Hence for fixed $\alpha$ we can choose $\epsilon$ such that
			\begin{align}\label{fin22}
				\mathbb{E}\left(\sup_{t\in[0,T]}\lvert Z_{t}^{\epsilon,h_{\epsilon},\alpha}-Y_{t}^{h_{\epsilon},\alpha}\rvert^{2}\right)\leq\frac{\delta}{9}.
			\end{align}
			By taking (\ref{fin21}) and (\ref{fin23}) into account, we get
			$$\lim\limits_{\epsilon\to 0}\mathbb{E}\left(\sup_{t\in[0,T]}\lvert Z_{t}^{\epsilon,h_{\epsilon}}-Y_{t}^{h_{\epsilon}}\rvert^{2}\right)=0,$$
			which is the desired result.

		\end{proof}
	\end{proposition}



	\subsection{An Example}
	Consider the following small perturbation of a Multivalued McKean-Vlasov SDE:
	\begin{equation}
		\begin{cases}
			\mathrm{d}X^\epsilon_t\in b_\epsilon(X^\epsilon_t,\mathcal{L}_{X^\epsilon_t})\mathrm{d}t+\sigma_\epsilon(X^\epsilon_t,\mathcal{L}_{X^\epsilon_t})\mathrm{d}W_t-\partial\Phi_\epsilon(X^\epsilon_t)\mathrm{d}t, \\
			X^\epsilon_0=h\in\overline{D(\Phi)},\quad \epsilon\in(0,1],
		\end{cases}
	\end{equation}
	where $\Phi_\epsilon$ and $\Phi$ are lower semicontinuous convex functions with common domain $D$ whose interior is non-empty. Suppose $\lim_{\epsilon\downarrow0}\Phi_\epsilon(x)=\Phi(x)$ for every $x\in D$. Define the Moreau-Yosida approximation of $\Phi$ by
	\begin{equation*}
		\Phi^\alpha(x)=\inf_{y\in{\mathbb{R}^d}}\left\{\Phi(y)+|y-x|^2/(2\alpha)\right\},
	\end{equation*}
	and that of $\Phi_\epsilon$ in the same way. Then, by \cite[Ch.\uppercase\expandafter{\romannumeral2}]{AGM}, $\Phi_\epsilon^\alpha$ and $\Phi^\alpha$ are differentiable convex functions defined on the whole space and it is not difficult to prove that
	\begin{equation*}
		\lim\limits_{\epsilon\downarrow0}\Phi_\epsilon^\alpha(x)=\Phi^\alpha(x),
	\end{equation*}
	for every $\alpha$. Let
	\begin{equation*}
		A:=\partial\Phi,\quad A_\epsilon:=\partial\Phi_\epsilon,
		A^\alpha:=\partial\Phi^\alpha,\quad A^\alpha_\epsilon:=\partial\Phi^\alpha_\epsilon,
	\end{equation*}
	then by \cite[Ch.D, Corollary 6.2.7 and Corollary 6.2.8]{JBHU}, it is easy to verify that the assumptions \hyperref[h0]{\textbf{(H0)}} and \hyperref[h4]{\textbf{(H4)}} hold in this case. Furthermore, if the assumptions \hyperref[h1]{\textbf{(H1)}}, \hyperref[h2]{\textbf{(H2)}} and \hyperref[h2]{\textbf{(H3)}} hold, then we can get the LDP by applying Theorem \ref{thmldp}.


