	\begin{proposition}\label{} [\textbf{(MDP)}$\bm{_{1}}$]
		For any given $m\in(0,\infty)$, let $\left\{\psi_n, n\in\mathbb{N}\right\}, \psi\in\mathcal{S}_m$ satisfy that $\psi_n\to\psi$ in $\mathcal{S}_m$ as $n\to\infty$, then
		$$\lim\limits_{n\to\infty}\sup_{t\in[0,T]}|\Gamma^0(\psi_n)(t)-\Gamma^0(\psi)(t)|=0.$$

		\begin{proof}
			Notice that $\nu^{\psi}=\Gamma^0(\psi)$ is the solution to (\ref{mdp1}), and $\nu^{\psi_n}=\Gamma^0(\psi_n)$ is the solution to (\ref{mdp1}) with $\psi$ replaced by $\psi_n$. It is equivalent to prove the following result
			$$\lim\limits_{n\to\infty}\sup_{t\in[0,T]}|\nu^{\psi_n}(t)-\nu^\psi(t)|=0.$$

			The proof is similar to that of Proposition \ref{ld1}.
			By Taylor formula, we have
			\begin{align*}
				|\nu^{\psi_n}(t)-\nu^{\psi}(t)|^2=&\,2\int_{0}^{t}\langle \nu^{\psi_n}_s-\nu^{\psi}_s, \nabla b(X^0_s,\mathcal{L}_{X^0_s})(\nu^{\psi_n}_s-\nu^{\psi}_s)\rangle\mathrm{d}s \\
				&+2\,\int_{0}^{t}\langle \nu^{\psi_n}_s-\nu^{\psi}_s,\sigma(X^0_s,\mathcal{L}_{X^0_s})(\psi_n(s)-\psi(s))\rangle\mathrm{d}s \\
				&-2\int_{0}^{t}\langle \nu^{\psi_n}_s-\nu^{\psi}_s, \mathrm{d}\hat{K}^{\psi_n}_s-\mathrm{d}\hat{K}^{\psi}_s\rangle \\
				:=&\,I_1(t)+I_2(t)+I_3(t).
			\end{align*}

			By property (\ref{mono}), we have $\sup_{s\in[0,t]}I_3(s)\leq 0$. For $I_1(t)$, it follows from (B1) that
			\begin{align*}
				\sup_{s\in[0,t]}I_1(s)\leq\,2L_{\nabla b}\int_{0}^{t}|\nu^{\psi_n}_s-\nu^{\psi}_s|^2\mathrm{d}s.
			\end{align*}


			Combining the estimates above, we get
			\begin{align*}
				\sup_{s\in[0,t]}|\nu^{\psi_n}_s-\nu^{\psi}_s|^2\leq\,C\int_{0}^{t}|\nu^{\psi_n}_r-\nu^{\psi}_r|^2\mathrm{d}r+\sup_{r\in[0,t]}I_2(r).
			\end{align*}
			Then by Gronwall's inequality we have
			\begin{align*}
				\sup_{s\in[0,t]}|\nu^{\psi_n}_s-\nu^{\psi}_s|^2\leq \,e^{CT}\sup_{r\in[0,t]}I_2(r).
			\end{align*}

			To estimate $I_2(t)$, we set
			\begin{align*}
				f_n(t):=\int_{0}^{t}\sigma(X_s^0,\mathcal{L}_{X_s^0})[\psi_n(s)-\psi(s)]\mathrm{d}s.
			\end{align*}

			Since $\psi_n(t)$ converges to $\psi(t)$ weakly in $L^2([0,T],\mathbb{R}^d)$ as $n\to\infty$, by the similar way in Proposition \ref{ld1},  we obtain
			\begin{align*}
				\lim_{n\to\infty}\sup_{t\in[0,T]}|f_n(t)|=0.
			\end{align*}
			By applying Taylor formula to $\langle |\nu^{\psi_n}_t-\nu^{\psi}_t|,f_n(t)\rangle$  we get
			\begin{align*}
				\lim_{n\to\infty}\sup_{t\in[0,T]}|\nu^{\psi_n}_s-\nu^{\psi}_s|=0,
			\end{align*}
			which completes the proof.







