	To verify \textbf{(MDP)}$\bm{_{2}}$, we will need the following two lemmas.

	\begin{lemma}\label{ep2}
		There exist two positive constant $\epsilon_{0}>0$ and $C_T>0$ such that
		$$\mathbb{E}\left(\sup_{t\in[0,T]}\lvert X_{t}^{\epsilon}-X_{t}^{0}\rvert^{2}\right)\leq C_T(\epsilon+\epsilon\rho_{\sigma,\epsilon}^2+\rho_{b,\epsilon}^2),\quad \forall\epsilon\in \left(0,\epsilon_{0}\right]$$
		where $\rho_{b,\epsilon}$ and $\rho_{\sigma,\epsilon}$ are the constants given in \hyperref[h2]{\textbf{(H2)}}.
	\end{lemma}

	\begin{proof}
		We follow the similar way in Lemma \ref{ep0}. By applying It$\hat{\text{o}}$'s formula we have
		\begin{align*}
			&\lvert X_{t}^{\epsilon}-X_{t}^{0}\rvert^{2} \\
			=&2\int_{0}^{t}\left\langle b_{\epsilon}\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right)-b\left(X_{r}^{0},\mathcal{L}_{X_{r}^{0}}\right), X_{r}^{\epsilon}-X_{r}^{0}\right\rangle\mathrm{d}r
			+2\sqrt{\epsilon}\int_{0}^{t}\left\langle\sigma_{\epsilon}\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right), X_{r}^{\epsilon}-X_{r}^{0}\right\rangle\mathrm{d}W_s \\
			&+\epsilon\int_{0}^{t}\lVert\sigma_{\epsilon}\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right)\rVert^{2}\mathrm{d}r+\int_{0}^{t}\left\langle X_{r}^{\epsilon}-X_{r}^{0},\mathrm{d}K_{r}^{0}-\mathrm{d}K_{r}^{\epsilon}\right\rangle \\
			=:&J_{1}^{\epsilon}(t)+J_{2}^{\epsilon}(t)+J_{3}^{\epsilon}(t)+J_{4}^{\epsilon}(t).
		\end{align*}

		For $J_{1}^{\epsilon}(t)$,
		by (\hyperref[b0]{\textbf{B0}}),(\hyperref[b1]{\textbf{B1}}) and Remark \ref{W2},
		\begin{align}\label{461}
			\mathbb{E}\left(\sup_{t\in [0,T]}\lvert J_{1}^{\epsilon}(t)\rvert\right)
			\leq (CL'+1)\mathbb{E}\int_{0}^{T}\lvert X_{s}^{\epsilon}-X_{s}^{0}\rvert^{2}\mathrm{d}s+\rho_{b,\epsilon}^2T.
		\end{align}

		For $J_{3}^{\epsilon}(t)$,
		by (\hyperref[b0]{\textbf{B0}}),(\hyperref[b3]{\textbf{B3}}) and Remark \ref{W2} again,
		\begin{align}\label{462}
			\mathbb{E}\left(\sup_{t\in [0,T]}\lvert J_{3}^{\epsilon}(t)\rvert\right)
			=&\, \epsilon\,\mathbb{E}\int_{0}^{T}\lVert\sigma_{\epsilon}\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right)\rVert^{2}\,\mathrm{d}r \nonumber\\
			\leq&\, C\epsilon\rho_{\sigma,\epsilon}^2T+\,CL'T\epsilon \,\mathbb{E}\left(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\right)+\,C\epsilon.
		\end{align}

		For $J_{2}^{\epsilon}(t)$,
		by BDG's inequality and Young's inequality, we have
		\begin{align}\label{463}
			\mathbb{E}\left(\sup_{t\in [0,T]}\lvert J_{2}^{\epsilon}(t)\rvert\right)
			\leq& C\sqrt{\epsilon}\,\mathbb{E}\left[\int_{0}^{T}\lVert\sigma_{\epsilon}\left(X_{r}^{\epsilon},\mathcal{L}_{X_{r}^{\epsilon}}\right)\rVert^{2}\cdot\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\,\mathrm{d}r\right]^{\frac{1}{2}} \nonumber\\
			\leq& \left(\frac{1}{4}+CL'T\epsilon\right)\,\mathbb{E}\left(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\right)+C\epsilon\rho_{\sigma,\epsilon}^{2}T+\,C\epsilon.
		\end{align}

		With (\ref{mono}) we get
		\begin{align}\label{464}
			\sup_{t\in [0,T]} J_{4}^{\epsilon}(t)\leq 0.
		\end{align}

		Combining (\ref{461})-(\ref{464}) together, we have
		\begin{align*}
			&\left(\frac{3}{4}-CL'T\epsilon\right)\,\,\mathbb{E}\left(\sup_{r\in[0,T]}\lvert X_{r}^{\epsilon}-X_{r}^{0}\rvert^{2}\right) \\
			\leq& CL'\mathbb{E}\int_{0}^{T}\lvert X_{s}^{\epsilon}-X_{s}^{0}\rvert^{2}\,\mathrm{d}s+\,C\epsilon+\rho_{b,\epsilon}^{2}T+C\epsilon\rho_{\sigma,\epsilon}^{2}T.
		\end{align*}

		Since there exists $\epsilon_0>0$ small enough such that for any $\epsilon\in(0,\epsilon_0],$
		$$\frac{3}{4}-C{L'}^{2}T\epsilon\geq\frac{1}{4},$$
		Finally by Gronwall's inequility, for any $\epsilon\in \left(0,\epsilon_{0}\right]$, we obtain the desired result
		$$\mathbb{E}\left(\sup_{t\in[0,T]}\lvert X_{t}^{\epsilon}-X_{t}^{0}\rvert^{2}\right)\leq C_T(\epsilon+\epsilon\rho_{\sigma,\epsilon}^2+\rho_{b,\epsilon}^2),\quad \forall\epsilon\in \left(0,\epsilon_{0}\right].$$

	\end{proof}


	\begin{lemma}\label{mdp2lemma}
		Let $M^{\epsilon,\psi_\epsilon}$ be the solution to (\ref{mdp2m}), then there exists some $\kappa_0>0$ such that for any $\psi_{\epsilon}\in\mathcal{D}_m$, then
		\begin{align}\label{minfty}
			\sup_{\epsilon\in(0,\kappa_0]}\mathbb{E}\left(\sup_{t\in[0,T]}|M^{\epsilon,\psi_{\epsilon}}_t|^2\right)<\infty.
		\end{align}
		\begin{proof}
			By applying It$\hat{\text{o}}$'s formula we have for any $t\in[0,T]$,
			\begin{align}
				&|M^{\epsilon,\psi_{\epsilon}}_t|^2  \nonumber\\
				=&\frac{2}{\lambda(\epsilon)}\int_{0}^{t}\left\langle M^{\epsilon,\psi_{\epsilon}}_s,b_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})-b(X^0_s,\mathcal{L}_{X^0_s})\right\rangle\mathrm{d}s  \nonumber\\
				&+\frac{2\sqrt{\epsilon}}{\lambda(\epsilon)}\int_{0}^{t}\left\langle M^{\epsilon,\psi_{\epsilon}}_s,\sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})\mathrm{~d}W_s\right\rangle \nonumber+\frac{\epsilon}{\lambda^{2}(\epsilon)}\int_{0}^{t}\lVert \sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})\rVert^2\mathrm{~d}s  \nonumber\\
				&+2\int_{0}^{t}\left\langle \sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})\psi_\epsilon(s),M^{\epsilon,\psi_{\epsilon}}_s\right\rangle\mathrm{d}s  \nonumber-2\int_{0}^{t}\left\langle M^{\epsilon,\psi_{\epsilon}}_s,\mathrm{d}\hat{K}^{\epsilon,\psi_\epsilon}_s\right\rangle \nonumber\\
				=:&I_{1}(t)+I_{2}(t)+I_{3}(t)+I_{4}(t)+I_{5}(t).
			\end{align}

			%Next we estimate the five terms above separately.

			By (\hyperref[b0]{\textbf{B0}})-(\hyperref[b3]{\textbf{B3}}), there exists $\epsilon_{1}>0$ such that
			\begin{align}\label{ep1}
				\frac{\epsilon}{\lambda^2(\epsilon)}\vee \lambda(\epsilon) \vee \rho_{b,\epsilon} \vee \rho_{\sigma,\epsilon} \vee \frac{\rho_{b,\epsilon}}{\lambda(\epsilon)}\in (0,\frac{1}{2}], \quad \forall\epsilon\in(0,\epsilon_{1}].
			\end{align}
			Let $\epsilon_{2}=\epsilon_{0}\wedge\epsilon_{1}\wedge\frac{1}{2}$, where $\epsilon_{0}$ is the constant given in Lemma \ref{ep0}. Denote by $C$ some generic constant which may change from line to line and is independent of $\epsilon$.

			%			Recall the definition of $M^{\epsilon,\psi_\epsilon}$,

			Since $A_\epsilon$ is monotone, by Proposition (\ref{multi}) and H\"older's inequality we have
			\begin{align}\label{mi5}
				\sup_{t\in[0,T]}I_5(t)&
				\leq \sup_{t\in[0,T]}\left(-|\hat{K}^{\epsilon,\psi_{\epsilon}}|_0^t\right)+C\int_{0}^{T}|M^{\epsilon,\psi_{\epsilon}}_s|\mathrm{d}s+C
				\leq C\int_{0}^{t}\sup_{r\in[0,s]}|M^{\epsilon,\psi_{\epsilon}}_r|^2\mathrm{d}s+C.
			\end{align}

			Due to (\hyperref[b0]{\textbf{B0}}), (\hyperref[b1]{\textbf{B1}}), Lemma \ref{ep2} and (\ref{slim}), for any $\epsilon\in(0,\epsilon_{2}]$,
			\begin{align}\label{mi1}
				I_1(t)=&\,\,\frac{2}{\lambda(\epsilon)}\int_{0}^{t}\left\langle b_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})-b(X^0_s,\mathcal{L}_{X^0_s}),M^{\epsilon,\psi_{\epsilon}}_s\right\rangle\mathrm{d}s  \nonumber\\
				=&\,\,\frac{2}{\lambda(\epsilon)}\int_{0}^{t}\left\langle b_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})-b(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s}),M^{\epsilon,\psi_{\epsilon}}_s\right\rangle\mathrm{d}s  \nonumber\\
				&+\frac{2}{\lambda(\epsilon)}\int_{0}^{t}\left\langle b(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})-b(X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s}),M^{\epsilon,\psi_{\epsilon}}_s\right\rangle\mathrm{d}s  \nonumber\\
				&+\frac{2}{\lambda(\epsilon)}\int_{0}^{t}\left\langle b(X^0_s,\mathcal{L}_{\bar{X}^{\epsilon}_s})-b(X^0_s,\mathcal{L}_{X^0_s}),M^{\epsilon,\psi_{\epsilon}}_s\right\rangle\mathrm{d}s \nonumber\\
				\leq&\,\,\frac{2\rho_{b,\epsilon}}{\lambda(\epsilon)}\int_{0}^{t}|M^{\epsilon,\psi_{\epsilon}}_s|\mathrm{d}s+2L'\int_{0}^{t}|M^{\epsilon,\psi_{\epsilon}}_s|^2\mathrm{d}s+\frac{2L'}{\lambda(\epsilon)}\int_{0}^{t}|M^{\epsilon,\psi_{\epsilon}}_s|\mathbb{W}_2(\mathcal{L}_{\bar{X}^{\epsilon}_s},\mathcal{L}_{X^0_s})\mathrm{d}s  \nonumber\\
				\leq&\,\,(2L'+\frac{2L'C\sqrt{\epsilon}}{\lambda(\epsilon)})\int_{0}^{t}|M^{\epsilon,\psi_{\epsilon}}_s|^2\mathrm{d}s+\frac{2\rho_{b,\epsilon}}{\lambda(\epsilon)}\int_{0}^{t}|M^{\epsilon,\psi_{\epsilon}}_s|\mathrm{d}s
				\leq C\int_{0}^{t}|M^{\epsilon,\psi_{\epsilon}}_s|^2\mathrm{d}s+C.
			\end{align}

			For $I_3(t)$, we have
			\begin{align}\label{mi3}
				I_3(t)=&\,\,\frac{\epsilon}{\lambda^{2}(\epsilon)}\int_{0}^{t}\lVert \sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{\bar{X}_s^\epsilon})\rVert^2\mathrm{~d}s  \nonumber\\
				\leq&\,\, \frac{\epsilon}{\lambda^{2}(\epsilon)}\int_{0}^{t}\lVert \sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{\bar{X}_s^\epsilon})-\sigma(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{\bar{X}_s^\epsilon})\rVert^2\mathrm{~d}s  \nonumber\\
				&+\frac{\epsilon}{\lambda^{2}(\epsilon)}\int_{0}^{t}\lVert \sigma(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{\bar{X}_s^\epsilon})-\sigma(X^0_s,\mathcal{L}_{\bar{X}_s^\epsilon})\rVert^2\mathrm{~d}s  \nonumber\\
				&+\frac{\epsilon}{\lambda^{2}(\epsilon)}\int_{0}^{t}\lVert \sigma(X^0_s,\mathcal{L}_{\bar{X}_s^\epsilon})-\sigma(X^0_s,\mathcal{L}_{X^0_s})\rVert^2\mathrm{~d}s+\frac{\epsilon}{\lambda^{2}(\epsilon)}\int_{0}^{t}\lVert \sigma(X^0_s,\mathcal{L}_{X^0_s})\rVert^2\mathrm{~d}s \nonumber\\
				\leq&\,\, \frac{C\epsilon\rho^2_{\sigma,\epsilon}}{\lambda^{2}(\epsilon)}+
				C\epsilon\int_{0}^{t}|M^{\epsilon,\psi_{\epsilon}}_s|^2\mathrm{d}s+\frac{\epsilon}{\lambda^{2}(\epsilon)}\int_{0}^{t}\mathbb{W}_2^2(\mathcal{L}_{\bar{X}^{\epsilon}_s},\mathcal{L}_{X^0_s})\mathrm{d}s+\frac{\epsilon}{\lambda^{2}(\epsilon)}\int_{0}^{t}\lVert \sigma(X^0_s,\mathcal{L}_{X^0_s})\rVert^2\mathrm{~d}s  \nonumber \\
				\leq&\,\, C\int_{0}^{t}|M^{\epsilon,\psi_{\epsilon}}_s|^2\mathrm{d}s+C.
			\end{align}

			For $I_4(t)$,  we have
			\begin{align}\label{mi44}
				I_4(t)=&\,2\int_{0}^{t}\left\langle \sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{X_s^0})\psi_\epsilon(s),M^{\epsilon,\psi_{\epsilon}}_s\right\rangle\mathrm{d}s  \nonumber\\
				=&\,2\int_{0}^{t}\left\langle \left[\sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{\bar{X}_s^\epsilon})-\sigma(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{\bar{X}_s^\epsilon})\right]\psi_\epsilon(s),M^{\epsilon,\psi_{\epsilon}}_s\right\rangle\mathrm{d}s  \nonumber\\
				&+2\int_{0}^{t}\left\langle \left[\sigma(\lambda(\epsilon)M^{\epsilon,\psi_{\epsilon}}_s+X^0_s,\mathcal{L}_{\bar{X}_s^\epsilon})-\sigma(X^0_s,\mathcal{L}_{X^0_s})\right]\psi_\epsilon(s),M^{\epsilon,\psi_{\epsilon}}_s\right\rangle\mathrm{d}s  \nonumber \\
				&+2\int_{0}^{t}\left\langle \sigma(X^0_s,\mathcal{L}_{X^0_s})\psi_\epsilon(s),M^{\epsilon,\psi_{\epsilon}}_s\right\rangle\mathrm{d}s  \nonumber\\
				\leq&\,\,2\rho_{\sigma,\epsilon}\int_{0}^{t}|M^{\epsilon,\psi_{\epsilon}}_s||\psi_\epsilon(s)|\mathrm{d}s+C\int_{0}^{t}(\lambda(\epsilon)|M^{\epsilon,\psi_{\epsilon}}_s|+\mathbb{W}_2(\mathcal{L}_{\bar{X}_s^\epsilon},\mathcal{L}_{X^0_s}))|M^{\epsilon,\psi_{\epsilon}}_s||\psi_\epsilon(s)|\mathrm{d}s  \nonumber\\
				&+\,C\int_{0}^{t}\lVert \sigma(X^0_s,\mathcal{L}_{X^0_s})\rVert|M^{\epsilon,\psi_{\epsilon}}_s||\psi_\epsilon(s)|\mathrm{d}s.
			\end{align}
			By H{\"o}lder's inequality and Young's inequality, we get
			\begin{align}\label{mi4}	
				I_4(t)
				\leq&\,\, \left(1+C\left(\mathbb{E}(\sup_{s\in[0,T]}|\bar{X}^\epsilon_s-X^0_s|^2
				)\right)^{\frac{1}{2}}\right)\int_{0}^{t}|M^{\epsilon,\psi_{\epsilon}}_s||\psi_\epsilon(s)|\mathrm{d}s+C\lambda(\epsilon)\int_{0}^{t}|M^{\epsilon,\psi_{\epsilon}}_s|^2|\psi_\epsilon(s)|\mathrm{d}s   \nonumber\\
				&+\, C\int_{0}^{t}\lVert \sigma(X^0_s,\mathcal{L}_{X^0_s})\rVert|M^{\epsilon,\psi_{\epsilon}}_s||\psi_\epsilon(s)|\mathrm{d}s  \nonumber\\
				\leq&\,\, C\int_{0}^{t}|M^{\epsilon,\psi_{\epsilon}}_s|^2\mathrm{d}s+C\int_{0}^{t}|\psi_\epsilon(s)|^2\mathrm{d}s+C\int_{0}^{t}|M^{\epsilon,\psi_{\epsilon}}_s|^2|\psi_\epsilon(s)|^2\mathrm{d}s+C\int_{0}^{t}\lVert \sigma(X^0_s,\mathcal{L}_{X^0_s})\rVert^2\mathrm{d}s \nonumber\\
				\leq&\,\, C\int_{0}^{t}\left(1+|\psi_\epsilon(s)|^2\right)|M^{\epsilon,\psi_{\epsilon}}_s|^2\mathrm{d}s+C.
			\end{align}

			By combining the above estimates (\ref{mi5})-(\ref{mi4}) together and  applying Gronwall's inequality, we obtain  for any $\epsilon\in(0,\epsilon_{2}]$ and $t\in[0,T]$,
			\begin{align}
				\sup_{t\in[0,T]}|M^{\epsilon,\psi_{\epsilon}}_t|^2\leq e^{C\int_{0}^{T}(4+|\psi_\epsilon(s)|^2)\mathrm{d}s}\left\{C+\sup_{t\in[0,T]}|I_2(t)|\right\}.
			\end{align}

			Since $\psi_\epsilon\in\mathcal{S}_m$ $P$-a.s., then for any $\epsilon\in(0,\epsilon_{2}]$ we have
			\begin{align}
				\frac{1}{2}\int_{0}^{T}|\psi_\epsilon(s)|^2\mathrm{d}s\leq m, \quad P\text{-a.s.}.
			\end{align}

			Therefore, there exists a constant $\zeta>0$ such that for any $\epsilon\in(0,\epsilon_{2}]$,
			\begin{align}\label{mgron}
				\mathbb{E}\left(\sup_{t\in[0,T]}|M^{\epsilon,\psi_\epsilon}_t|^2\right)\leq \zeta\left\{1+\mathbb{E}\left(\sup_{t\in[0,T]}|I_2(t)|\right)\right\}.
			\end{align}

			For $I_2(t)$, by BDG’s inequality, Young's inequality, (\hyperref[b3]{\textbf{B3}}), Lemma \ref{ep2}, (\ref{slim}) and (\ref{mi3}), we have for any $\epsilon\in(0,\epsilon_{2}]$,
			\begin{align}\label{mi2}
				\mathbb{E}\left(\sup_{t\in[0,T]}|I_2(t)|\right) \nonumber
				\leq&\,\, \frac{C\sqrt{\epsilon}}{\lambda(\epsilon)}\mathbb{E}\left(\int_{0}^{T}|M^{\epsilon,\psi_\epsilon}_s|^2\lVert\sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})\rVert^2\mathrm{d}s\right)^{\frac{1}{2}} \nonumber\\
				\leq&\,\, \frac{C\sqrt{\epsilon}}{\lambda(\epsilon)}\mathbb{E}\left(\sup_{s\in[0,T]}|M^{\epsilon,\psi_\epsilon}_s|^2\right)+\frac{C\sqrt{\epsilon}}{\lambda(\epsilon)}\mathbb{E}\int_{0}^{T}\lVert\sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})\rVert^2\mathrm{d}s  \nonumber\\
				\leq&\,\, \frac{C\sqrt{\epsilon}}{\lambda(\epsilon)}\mathbb{E}\left(\sup_{s\in[0,T]}|M^{\epsilon,\psi_\epsilon}_s|^2\right)+\frac{C\sqrt{\epsilon}}{\lambda(\epsilon)}\left(C\rho_{\sigma,\epsilon}^2+C\lambda^2(\epsilon)\mathbb{E}\int_{0}^{T}|M^{\epsilon,\psi_\epsilon}_s|^2\mathrm{d}s\right)  \nonumber\\
				&+\, \frac{C\sqrt{\epsilon}}{\lambda(\epsilon)}\left(\int_{0}^{T}\mathbb{W}_2^2(\mathcal{L}_{\bar{X}^\epsilon_s},\mathcal{L}_{X_s^0})\mathrm{d}s+\int_{0}^{T}\lVert\sigma(X^0_s,\mathcal{L}_{X^0_s})\rVert^2\mathrm{d}s\right)  \nonumber \\
				\leq&\,\, C\left(\frac{\sqrt{\epsilon}}{\lambda(\epsilon)}+\sqrt{\epsilon}\lambda(\epsilon)\right)\mathbb{E}\left(\sup_{s\in[0,T]}|M^{\epsilon,\psi_\epsilon}_s|^2\right)+C.
			\end{align}

			By substituting (\ref{mi2}) back into (\ref{mgron}), we obtain for any $\epsilon\in(0,\epsilon_{2}]$,
			\begin{align}
				\left(1-\frac{C\sqrt{\epsilon}}{\lambda(\epsilon)}-C\sqrt{\epsilon}\lambda(\epsilon)\right)\mathbb{E}\left(\sup_{s\in[0,T]}|M^{\epsilon,\psi_\epsilon}_s|^2\right)\leq C.
			\end{align}

			Then there exists a constant $0\leq\kappa_0\leq \epsilon_2$ such that for any $\epsilon\in(0,\kappa_0]$,
			\begin{align*}
				\left(1-\frac{C\sqrt{\epsilon}}{\lambda(\epsilon)}-C\sqrt{\epsilon}\lambda(\epsilon)\right)\geq \frac{1}{4}.
			\end{align*}
			Thus we have
			\begin{align*}
				\sup_{\epsilon\in(0,\kappa_0]}\mathbb{E}\left(\sup_{t\in[0,T]}|M^{\epsilon,\psi_{\epsilon}}_t|^2\right)<\infty,
			\end{align*}
			which completes the proof.
		\end{proof}

	\end{lemma}

	By adapting the same procedure in Lemma \ref{yozfin} and Lemma \ref{yosifin}, we have the following results.
