	For the sake of brevity, we omit the proofs of the lemmas above. Now we are in the position to verify \textbf{(MDP)}$\bm{_{2}}$.

	\begin{proposition}\label{}[\textbf{(MDP)}$\bm{_{2}}$]
		For any given $m\in(0,\infty)$, $\psi_\epsilon\in\mathcal{D}_m$ and $\delta>0$, we have
		\begin{align*}
			\lim\limits_{\epsilon\to 0}P\left(\sup_{t\in[0,T]}|M^{\epsilon,\psi_\epsilon}_t-\nu^{\psi_\epsilon}_t|\geq\delta\right)=0.
		\end{align*}

		\begin{proof}	
			Let $\epsilon>0$ be fixed. By triangle inequality we have
			\begin{align}\label{twoo}
				\sup_{t\in[0,T]}|M^{\epsilon,\psi_\epsilon}_t-\nu^{\psi_\epsilon}_t|\leq& \,\sup_{t\in[0,T]}|M^{\epsilon,\psi_\epsilon}_t-M^{\epsilon,\psi_\epsilon,\alpha}_t|
				+\sup_{t\in[0,T]}|M^{\epsilon,\psi_\epsilon,\alpha}_t-\nu^{\psi_\epsilon,\alpha}_t| \nonumber\\
				&+\,\sup_{t\in[0,T]}|\nu^{\psi_\epsilon,\alpha}_t-\nu^{\psi_\epsilon}_t|.
			\end{align}
			Next we deal with the above three terms separately.
			For any $\varpi>0$, by Lemma \ref{mfin} and Lemma \ref{nfin}, there exists some constant $\alpha$ independent of $\epsilon$ such that
			\begin{align}\label{441}
				P\left(\sup_{t\in[0,T]}|M^{\epsilon,\psi_\epsilon}_t-M^{\epsilon,\psi_\epsilon,\alpha}_t|\geq\frac{\delta}{3}\right)\leq \frac{9\mathbb{E}\sup_{t\in[0,T]}|M^{\epsilon,\psi_\epsilon}_t-M^{\epsilon,\psi_\epsilon,\alpha}_t|^2}{\delta^2}\leq \frac{\varpi}{3}
			\end{align}
			and
			\begin{align}\label{442}
				P\left(\sup_{t\in[0,T]}|\nu^{\psi_\epsilon}_t-\nu^{\psi_\epsilon,\alpha}_t|\geq\frac{\delta}{3}\right)\leq \frac{9\mathbb{E}\sup_{t\in[0,T]}|\nu^{\psi_\epsilon}_t-\nu^{\psi_\epsilon,\alpha}_t|^2}{\delta^2}\leq \frac{\varpi}{3}.
			\end{align}

			It is left to estimate the second term in the right hand side of \eqref{twoo}. For any $\alpha>0$ and $\psi_\epsilon\in\mathcal{D}_m$, let $Q^\epsilon(t):=M^{\epsilon,\psi_\epsilon,\alpha}(t)-\nu^{\psi_\epsilon,\alpha}(t),$ $\forall t\in[0,T]$, then
			\begin{align} \mathrm{d}Q^\epsilon_t=&\left(\frac{1}{\lambda(\epsilon)}\left(b_\epsilon(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_t+X^0_t,\mathcal{L}_{\bar{X}^\epsilon_t})-b(X^0_t,\mathcal{L}_{X^0_t})\right)-\nabla b(X^0_t,\mathcal{L}_{X^0_t})\nu^{\psi_\epsilon,\alpha}_t\right)\mathrm{d}t   \nonumber\\
				&+\left(\sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon}_t+X^0_t,\mathcal{L}_{\bar{X}^\epsilon_t})-\sigma(X^0_t,\mathcal{L}_{X^0_t})\right)\psi_\epsilon(t)\mathrm{d}t  \nonumber \\
				&+\frac{\sqrt{\epsilon}}{\lambda(\epsilon)}\sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_t+X^0_t,\mathcal{L}_{\bar{X}^\epsilon_t})\mathrm{d}W_t  \nonumber-\left(\mathrm{d}\hat{K}_t^{\epsilon,\psi_\epsilon}-\mathrm{d}\hat{K}_t^{\psi_\epsilon}\right).
			\end{align}

			For any $a\in\mathbb{N}$, define the following stopping time
			\begin{align}
				\tau_\epsilon^a=\inf\big\{t\geq 0:|M^{\epsilon,\psi_\epsilon}(t)|\geq a\big\}\wedge T.
			\end{align}
			Due to Lemma \ref{mdp2lemma} and Markov's inequality, we get
			\begin{align}\label{cheby}
				P(\tau_\epsilon^a<T)\leq\frac{\mathbb{E}(\sup_{t\in[0,T]}|M^{\epsilon,\psi_\epsilon}(t)|^2)}{a^2}\leq \frac{C}{a^2}, \quad \forall\epsilon\in(0,\kappa_0].
			\end{align}

			By It$\hat{\text{o}}$'s formula, we get
			\begin{align}\label{mdpq}
				|Q^\epsilon_{t\wedge\tau_\epsilon^a}|^2=&2\int_{0}^{t\wedge\tau_\epsilon^a}\left\langle \frac{1}{\lambda(\epsilon)}\left(b_\epsilon(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})-b(X^0_s,\mathcal{L}_{X^0_s})\right)-\nabla b(X^0_s,\mathcal{L}_{X^0_s})\nu^{\psi_\epsilon,\alpha}_s,Q^\epsilon_s\right\rangle\mathrm{d}s  \nonumber\\
				&+\frac{2\sqrt{\epsilon}}{\lambda(\epsilon)}\int_{0}^{t\wedge\tau_\epsilon^a}\left\langle Q^\epsilon_s,\sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})\mathrm{d}W_s\right\rangle  \nonumber\\
				&+\frac{\epsilon}{\lambda^2(\epsilon)}\int_{0}^{t\wedge\tau_\epsilon^a}\lVert\sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})\rVert^2\mathrm{d}s  \nonumber\\
				&+2\int_{0}^{t\wedge\tau_\epsilon^a}\left\langle \left(\sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})-\sigma(X^0_s,\mathcal{L}_{X^0_s})\right)\psi_\epsilon(s),Q^\epsilon_s\right\rangle\mathrm{d}s  \nonumber\\
				&+2\int_{0}^{t\wedge\tau_\epsilon^a}\left\langle Q^\epsilon_s,A^\alpha(\nu^{\psi_\epsilon,\alpha}_s)-A^\alpha(M^{\epsilon,\psi_\epsilon,\alpha}_s)\right\rangle\mathrm{d}s \nonumber \\
				&+2\int_{0}^{t\wedge\tau_\epsilon^a}\left\langle Q^\epsilon_s,A^\alpha(M^{\epsilon,\psi_\epsilon,\alpha}_s)-A^\alpha_\epsilon(M^{\epsilon,\psi_\epsilon,\alpha}_s)\right\rangle\mathrm{d}s  \nonumber\\
				=:&\,\,\hat{I}_1(t)+\hat{I}_2(t)+\hat{I}_3(t)+\hat{I}_4(t)+\hat{I}_5(t)+\hat{I}_6(t).
			\end{align}

			For $\hat{I}_{5}(t)$, by (\ref{mono}) we have for each $\epsilon\in(0,\epsilon_{3}]$,
			\begin{align}\label{hati5}
				\hat{I}_{5}(t)=2\int_{0}^{t\wedge\tau_\epsilon^a}\left\langle Q^\epsilon_s,A^\alpha(\nu^{\psi_\epsilon,\alpha}_s)-A^\alpha(M^{\epsilon,\psi_\epsilon,\alpha}_s)\right\rangle\mathrm{d}s\leq 0.
			\end{align}

			By (\ref{nulim}) and $\psi_\epsilon\in\mathcal{D}_m$, there exists some $\Omega^0\in\mathcal{F}$ with $P(\Omega^0)=1$ such that
			\begin{align}\label{gamma}
				\gamma\coloneqq\sup_{\epsilon\in(0,\kappa_0]}\sup_{\omega\in\Omega^0, t\in[0,T]}|\nu^{\psi_\epsilon,\alpha}_t(\omega)|<\infty.
			\end{align}

			For $\hat{I}_{6}(t)$, by the same way in Proposition \ref{ld2}, we have
			\begin{align}\label{hati6}
				\hat{I}_{6}(t)\leq C\int_{0}^{t\wedge\tau_\epsilon^a}|Q^{\epsilon,\psi_\epsilon}_s|^2\mathrm{d}s+C\int_{0}^{t\wedge\tau_\epsilon^a}|A_\epsilon^\alpha(M^{\epsilon,\psi_\epsilon,\alpha}_s)-A^\alpha(M^{\epsilon,\psi_\epsilon,\alpha}_s)|^2\mathrm{d}t\leq (a+\gamma)^2T.
			\end{align}

			For $\hat{I}_1(t)$, we have
			\begin{align}\label{hati1}
				\hat{I}_1(t)=&\frac{2}{\lambda(\epsilon)}\int_{0}^{t\wedge\tau_\epsilon^a}\left\langle b_\epsilon(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})-b(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s}),Q^{\epsilon,\psi_\epsilon}_s\right\rangle\mathrm{d}s  \nonumber\\
				&+\frac{2}{\lambda(\epsilon)}\int_{0}^{t\wedge\tau_\epsilon^a}\left\langle b(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})-b(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s+X^0_s,\mathcal{L}_{X^0_s}),Q^{\epsilon,\psi_\epsilon}_s\right\rangle\mathrm{d}s  \nonumber\\
				&+2\int_{0}^{t\wedge\tau_\epsilon^a}\left\langle \frac{1}{\lambda(\epsilon)}\left(b(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s+X^0_s,\mathcal{L}_{X^0_s})-b(X^0_s,\mathcal{L}_{X^0_s})\right)-\nabla b(X^0_s,\mathcal{L}_{X^0_s})\nu^{\psi_\epsilon,\alpha}_s,Q^{\epsilon,\psi_\epsilon}_s\right\rangle\mathrm{d}s  \nonumber\\
				=:&\,\,\hat{I}_{1,1}(t)+\hat{I}_{1,2}(t)+\hat{I}_{1,3}(t).
			\end{align}
			Due to (\hyperref[b0]{\textbf{B0}}), (\hyperref[b1]{\textbf{B1}}) and Lemma \ref{ep2}, we have
			\begin{align}\label{hati112}
				\hat{I}_{1,1}(t)+\hat{I}_{1,2}(t)\leq&\, \frac{2\rho_{b,\epsilon}}{\lambda(\epsilon)}\int_{0}^{t\wedge\tau_\epsilon^a}|Q^{\epsilon,\psi_\epsilon}_s|\mathrm{d}s+\frac{2L}{\lambda(\epsilon)}\int_{0}^{t\wedge\tau_\epsilon^a}\left(\mathbb{E}|X^\epsilon_s-X^0_s|^2\right)^{\frac{1}{2}}|Q^{\epsilon,\psi_\epsilon}_s|\mathrm{d}s  \nonumber\\
				\leq& \, \frac{2\rho_{b,\epsilon}+2L(\epsilon+\rho_{b,\epsilon}^2+\epsilon\rho_{\sigma,\epsilon}^2)^{\frac{1}{2}}}{\lambda(\epsilon)}(a+\gamma)T.
			\end{align}
			Let $\epsilon_{3}=\kappa_0\wedge\epsilon_{2}$, then for any $\epsilon\in(0,\epsilon_{3}]$, by using the mean value theorem, (\hyperref[b0]{\textbf{B0}}) and (\hyperref[b1]{\textbf{B1}}), we obtain that there exists $\theta_{\epsilon}(s)\in[0,1]$ such that
			\begin{align*}
				\hat{I}_{1,3}(t)=&\,\,2\int_{0}^{t\wedge\tau_{\epsilon}^{a}}\left\langle \frac{b(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s+X^{0}_s,\mathcal{L}_{X^{0}_s})-b(X^{0}_s,\mathcal{L}_{X^{0}_s})}{\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s}M^{\epsilon,\psi_\epsilon,\alpha}_s-\nabla b(X^{0}_s,\mathcal{L}_{X^{0}_s})\nu^{\psi_\epsilon,\alpha}_s,Q^{\epsilon,\psi_\epsilon}_s\right\rangle\mathrm{d}s \nonumber\\
				\leq&\,\,2\int_{0}^{t\wedge\tau_{\epsilon}^{a}}\left\langle \nabla b(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s\theta_{\epsilon}(s)+X^{0}_s,\mathcal{L}_{X^0_s})M^{\epsilon,\psi_\epsilon,\alpha}_s-\nabla b(X^0_s,\mathcal{L}_{X^0_s})\nu^{\psi_\epsilon,\alpha}_s,Q^{\epsilon,\psi_\epsilon}_s\right\rangle\mathrm{d}s  \nonumber\\
				=&\, 2\int_{0}^{t\wedge\tau_{\epsilon}^{a}}\left\langle \nabla b(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s\theta_{\epsilon}(s)+X^0_s,\mathcal{L}_{X^0_s})M^{\epsilon,\psi_\epsilon,\alpha}_s-\nabla b(X^0_s,\mathcal{L}_{X^0_s})M^{\epsilon,\psi_\epsilon,\alpha}_s,Q^{\epsilon,\psi_\epsilon}_s\right\rangle\mathrm{d}s  \nonumber\\
				&+\, 2\int_{0}^{t\wedge\tau_{\epsilon}^{a}}\left\langle \nabla b(X^0_s,\mathcal{L}_{X^0_s})M^{\epsilon,\psi_\epsilon,\alpha}_s-\nabla b(X^0_s,\mathcal{L}_{X^0_s})\nu^{\psi_\epsilon}_s,Q^{\epsilon,\psi_\epsilon}_s\right\rangle\mathrm{d}s  \nonumber\\
				\leq&\,\, 2\int_{0}^{t\wedge\tau_{\epsilon}^{a}}| \nabla b(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s\theta_{\epsilon}(s)+X^0_s,\mathcal{L}_{X^0_s})-\nabla b(X^0_s,\mathcal{L}_{X^0_s})||M^{\epsilon,\psi_\epsilon,\alpha}_s||Q^{\epsilon,\psi_\epsilon}_s|\mathrm{d}s   \nonumber\\
				&+\, 2\int_{0}^{t\wedge\tau_{\epsilon}^{a}}|\nabla b(X^0_s,\mathcal{L}_{X^0_s})||Q^{\epsilon,\psi_\epsilon}_s|^{2}\mathrm{d}s \nonumber\\
				\leq&\,\, L'\lambda(\epsilon)\int_{0}^{t\wedge\tau_{\epsilon}^{a}}\left(1+|X^0_s|^{q'}+|\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s+X^0_s|^{q'}\right)|M^{\epsilon,\psi_\epsilon,\alpha}_s|^{2}|Q^{\epsilon,\psi_\epsilon}_s|\mathrm{d}s  \nonumber\\
				&+\, 2\int_{0}^{t\wedge\tau_{\epsilon}^{a}}|\nabla b(X^0_s,\mathcal{L}_{X^0_s})||Q^{\epsilon,\psi_\epsilon}_s|^{2}\mathrm{d}s.
			\end{align*}

			Denote $C_a=L'\left(1+\sup_{s\in[0,T]}|X_{s}^{0}|^{q'}+|a+\sup_{s\in[0,T]}|X_{s}^{0}||^{q'}\right)a^{2}(a+\gamma)T$.  Notice that $C_a$ is independent of $\epsilon$, thus we get
			\begin{align}\label{hati132}
				\hat{I}_{1,3}(t)\leq\, C_a\lambda(\epsilon)+2\int_{0}^{t}|\nabla b(X^0_{s\wedge\tau_\epsilon^a},\mathcal{L}_{X^0_{s\wedge\tau_\epsilon^a}})||Q^{\epsilon,\psi_\epsilon}_{s\wedge\tau_\epsilon^a}|^2\mathrm{d}s.
			\end{align}

			Substituting (\ref{hati5}), (\ref{hati6}), (\ref{hati112}) and (\ref{hati132}) back into (\ref{mdpq}), and by Gronwall's inequality we have for any $\epsilon\in(0,\epsilon_{3}],\,\, t\in[0,T]$,

			\begin{align}\label{hatgron}
				\sup_{t\in[0,T]}|Q^{\epsilon,\psi_\epsilon}_{t\wedge\tau_\epsilon^a}|^2\leq e^{2\int_{0}^{T}\lVert\nabla b(X^0_s,\mathcal{L}_{X^0_s})\rVert\mathrm{d}s}\left[C_a(\frac{\rho_{b,\epsilon}+\lambda^2(\epsilon)+(\epsilon+\rho_{b,\epsilon}^2
					+\epsilon\rho_{\sigma,\epsilon})^{\frac{1}{2}}}{\lambda(\epsilon)})+\sum_{i=2}^{4}\sup_{t\in[0,T]}\hat{I}_i(t)\right].
			\end{align}
			By (\hyperref[b1]{\textbf{B1}}) we have
			\begin{align}
				\Delta:=e^{2\int_{0}^{T}\lVert\nabla b(X^0_s,\mathcal{L}_{X^0_s})\rVert\mathrm{d}s}<\infty.
			\end{align}

			For $\hat{I}_{2}(t)$ and $\hat{I}_{3}(t)$, by BDG’s inequality and (\ref{slim}), we obtain that
			\begin{align}\label{hati23}
				&\mathbb{E}\left(\sup_{t\in[0,T]}|\hat{I}_{2}(t)|\right)+\mathbb{E}\left(\sup_{t\in[0,T]}|\hat{I}_{3}(t)|\right)  \nonumber\\
				\leq&\,\frac{2\sqrt{\epsilon}}{\lambda(\epsilon)}\mathbb{E}\left(\int_{0}^{T\wedge\tau_\epsilon^a} |Q^{\epsilon,\psi_\epsilon}_s|^2\lVert\sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})\rVert^2\mathrm{d}s\right)^\frac{1}{2}  \nonumber\\
				\leq&\,\, \frac{1}{4}\mathbb{E}\left(\sup_{s\in[0,T]}|Q^{\epsilon,\psi_\epsilon}_{s\wedge\tau_\epsilon^a}|^2\right)
				+\frac{C\epsilon}{\lambda^2(\epsilon)}\mathbb{E}\int_{0}^{T\wedge\tau_\epsilon^a}\lVert\sigma_{\epsilon}(\lambda(\epsilon)M^{\epsilon,\psi_\epsilon,\alpha}_s+X^0_s,\mathcal{L}_{\bar{X}^\epsilon_s})\rVert^2\mathrm{d}s \nonumber\\
				\leq&\,\, \frac{1}{4}\mathbb{E}\left(\sup_{s\in[0,T]}|Q^{\epsilon,\psi_\epsilon}_{s\wedge\tau_\epsilon^a}|^2\right)+\frac{C\epsilon\rho_{\sigma,\epsilon}^2}{\lambda^2(\epsilon)}+\frac{C\epsilon}{\lambda^2(\epsilon)}\mathbb{E}\int_{0}^{T\wedge\tau_\epsilon^a}|M^{\epsilon,\psi_\epsilon,\alpha}_s|^2\mathrm{d}s  \nonumber\\
				&+\,\, \frac{C\epsilon}{\lambda^2(\epsilon)}\mathbb{E}\int_{0}^{T\wedge\tau_\epsilon^a}\mathbb{E}(|\bar{X}^\epsilon_s-X^0_s|^2)\mathrm{d}s+\frac{C\epsilon}{\lambda^2(\epsilon)}\int_{0}^{T}\lVert\sigma(X^0_s,\mathcal{L}_{X^0_s})\rVert^2\mathrm{d}s  \nonumber\\
				\leq&\,\, \frac{1}{4}\mathbb{E}\left(\sup_{s\in[0,T]}|Q^{\epsilon,\psi_\epsilon}_{s\wedge\tau_\epsilon^a}|^2\right)+\frac{C_a\epsilon}{\lambda^2(\epsilon)}(\rho_{\sigma,\epsilon}^2+\epsilon+\epsilon\rho_{\sigma,\epsilon}^2+\rho_{b,\epsilon}^2+T).
			\end{align}

			For $\hat{I}_{4}(t)$, by \hyperref[b3]{\textbf{(B3)}}, (\ref{gamma}), Lemma \ref{ep2} and $\psi_\epsilon\in\mathcal{D}_m$, and the similar arguments in the proof of (\ref{mi4}), we have for any $\epsilon\in(0,\epsilon_{3}]$,
			\begin{align}\label{hati4}
				\mathbb{E}\left(\sup_{t\in[0,T]}|\hat{I}_{4}(t)|\right) \leq&\, C\rho_{\sigma,\epsilon}\mathbb{E}\int_{0}^{T\wedge\tau_\epsilon^a}|Q^{\epsilon,\psi_\epsilon}_{s}||\psi_\epsilon(s)|\mathrm{d}s  \nonumber\\
				&+\,C\mathbb{E}\int_{0}^{T\wedge\tau_\epsilon^a}\left(\lambda(\epsilon)|M^{\epsilon,\psi_\epsilon,\alpha}_{s}|+\mathbb{W}_2(\mathcal{L}_{\bar{X}^\epsilon_s},\mathcal{L}_{X^0_s})+\lVert\sigma(X^0_s,\mathcal{L}_{X^0_s})\rVert\right)|\psi_\epsilon(s)||Q^{\epsilon,\psi_\epsilon}_s|\mathrm{d}s  \nonumber\\
				\leq&\,\, CT(a+\gamma)^2\left(\rho_{\sigma,\epsilon}+\lambda(\epsilon)+(\epsilon+\rho_{b,\epsilon}^2+\epsilon\rho_{\sigma,\epsilon}^2)^{\frac{1}{2}}\right)\mathbb{E}\left(\int_{0}^{T}|\psi_\epsilon|^2\mathrm{d}s\right)^{\frac{1}{2}}   \nonumber\\
				\leq&\,\, C_a\left(\rho_{\sigma,\epsilon}+\lambda(\epsilon)+(\epsilon+\rho_{b,\epsilon}^2+\epsilon\rho_{\sigma,\epsilon}^2)^{\frac{1}{2}}\right).
			\end{align}

			Inserting the above inequalities (\ref{hati23}) and (\ref{hati4}) into (\ref{hatgron}), we deduce that for any $\epsilon\in(0,\epsilon_{3}]$,
			\begin{align}
				\frac{3}{4}\mathbb{E}\left(\sup_{t\in[0,T]}|Q^{\epsilon,\psi_\epsilon}_{t\wedge\tau_\epsilon^a}|^2\right)\leq C_a\left(\rho_{\sigma,\epsilon}+\lambda(\epsilon)+\frac{\rho_{b,\epsilon}}{\lambda(\epsilon)}+\frac{\epsilon}{\lambda^2(\epsilon)}+\frac{1+\lambda(\epsilon)}{\lambda(\epsilon)}(\epsilon+\rho_{b,\epsilon}^2+\epsilon\rho_{\sigma,\epsilon}^2)^{\frac{1}{2}}\right).
			\end{align}

			Due to (\hyperref[b2]{\textbf{B2}}), we  obtain
			\begin{align}
				\lim\limits_{\epsilon\to 0}\mathbb{E}\left(\sup_{t\in[0,T]}|M^{\epsilon,\psi_\epsilon,\alpha}_{t\wedge\tau_\epsilon^a}-\nu^{\psi_\epsilon,\alpha}_{t\wedge\tau_\epsilon^a}|^2\right)=\lim\limits_{\epsilon\to 0}\mathbb{E}\left(\sup_{t\in[0,T]}|Q^{\epsilon,\psi_\epsilon}_{t\wedge\tau_\epsilon^a}|^2\right)=0.
			\end{align}

			Thus for any $\delta>0$, $\epsilon\in(0,\epsilon_{3}]$, $a\in\mathbb{N}$, we have
			\begin{align}
				&P\left(\sup_{t\in[0,T]}|M^{\epsilon,\psi_\epsilon,\alpha}_t-\nu^{\psi_\epsilon,\alpha}_t|\geq\frac{\delta}{3}\right) \nonumber\\
				\leq&\, P\left(\bigg(\sup_{t\in[0,T]}|M^{\epsilon,\psi_\epsilon,\alpha}_{t\wedge\tau_\epsilon^a}-\nu^{\psi_\epsilon,\alpha}_{t\wedge\tau_\epsilon^a}|\geq\frac{\delta}{3}\bigg)\cap(\tau_\epsilon^a\geq T)\right)+P(\tau_\epsilon^a< T) \nonumber\\
				\leq&\,\, \frac{9}{\delta^2}\mathbb{E}\left(\sup_{t\in[0,T]}|M^{\epsilon,\psi_\epsilon,\alpha}_{t\wedge\tau_\epsilon^a}-\nu^{\psi_\epsilon,\alpha}_{t\wedge\tau_\epsilon^a}|^2\right)+\frac{C}{a^2}.
			\end{align}

			For any $\alpha$ fixed, we can choose $\epsilon$ and $a\to\infty$ such that for any $\varpi>0$
			\begin{align}\label{443}
				P\left(\sup_{t\in[0,T]}|M^{\epsilon,\psi_\epsilon,\alpha}_t-\nu^{\psi_\epsilon,\alpha}_t|\geq\frac{\delta}{3}\right)\leq \frac{\varpi}{3}.
			\end{align}

			Then combining (\ref{441}), (\ref{442}) and (\ref{443}) we get the desired result
			\begin{align*}
				\lim\limits_{\epsilon\to 0}P\left(\sup_{t\in[0,T]}|M^{\epsilon,\psi_\epsilon}_t-\nu^{\psi_\epsilon}_t|\geq\delta\right)=0.
			\end{align*}
		\end{proof}

	\end{proposition}



