	\section{Functional Iterated Logarithm Law}

	%In this section, we derive a functional iterated logarithm law for MMVSDEs.

	Let $ W $ be a k-dimensional Brownian motion and $T$ be fixed. Let $H$ be an open set of $\mathbb{R}^d$ and denote the set of continuous path $\hbar:[0,T]\to H$ by $C([0,T];H)$, endowed with the norm
	$\lVert \hbar\rVert=\sup_{t\in[0,T]}|\hbar(t)|.$
	For $\hbar_1,\,\hbar_2\in C([0,T];H)$ and $B\in \mathcal{B}(C([0,T];H))$, we denote
	\begin{align*}
		d(\hbar_1,\hbar_2)=\lVert \hbar_1-\hbar_2\rVert,\quad d(\hbar_1,B)=\inf_{\hbar_2\in B}d(\hbar_1,\hbar_2).
	\end{align*}

	Let
	\begin{align*}
		\mathcal{H}:=\left\{\hbar_.=\int_{0}^{.}h(s)\mathrm{d}s\in C([0,T];\mathbb{R}^d);\hbar(0)=0,\int_{0}^{T}|h(s)|^2\mathrm{d}s<\infty\right\},
	\end{align*}

	then $\mathcal{H}$ is a Hilbert space endowed with the scalar product $\langle \hbar_1, \hbar_2\rangle:=\int_{0}^{T}\langle h_1(s),h_2(s)\rangle\mathrm{d}s $.




	\subsection{The Large Time Functional Iterated Logarithm Law}


	For $u>e$, define $$\psi(u):=\sqrt{u\log\log u}\,.$$

	Suppose that $\tilde{A}$ is a multivalued maximal monotone operator with $0\in Int(D(\tilde{A}))$,  $\tilde{b}:\overline{D(A)}\times\mathcal{P}_2\to\mathbb{R}^d$ and $\tilde{\sigma}:\overline{D(A)}\times\mathcal{P}_2\to \mathbb{R}^d\otimes\mathbb{R}^{d}$ are progressively measurable functions such that there exists a unique solution to
	\begin{align*}\label{IILS}
		\begin{cases}
			\mathrm{d}Y_t\in\tilde{b}(Y_t,\mathcal{L}_{Y_t})\mathrm{d}t+\tilde{\sigma}(Y_t,\mathcal{L}_{Y_t})\mathrm{d}W_t-\tilde{A}(Y_t)\mathrm{d}t, \\
			Y_0=x\in\overline{D(A)}.
		\end{cases}
	\end{align*}

	To show our main result, we first give the following definition introduced by Baldi in \cite{Ba1986}.

	\begin{definition}\label{gadef}
		Let $U$ be an open set of $\mathbb{R}^d$. For any $a\in\mathbb{R}^{+}$, let $\Gamma_a:U\to U$ be a $C^2$ bijective transformation having continuous derivatives up to order 2. The family $\Gamma_a=\left\{\Gamma_a\right\}_{a>0}$ is said to be a system of contractions centered at x if
		\begin{enumerate}[(a)]
			\item $\Gamma_a(x)=x$ for every $a\in\mathbb{R}^{+},$
			\item if $ a\geq\theta $ then $ |\Gamma_a(y)-\Gamma_a(z)|\leq |\Gamma_\theta(y)-\Gamma_\theta(z)| $ for every $ y,z\in U,$
			\item $ \Gamma_1 $ is identity and $ \Gamma^{-1}_a=\Gamma_{a^{-1}} $,
			\item for every compact set $\mathcal{K}$ of $U$, $f\in\mathcal{K}$ and $\epsilon>0$, there exists $\delta>0$, such that if $|a\theta-1|<\delta$ then
			$$\lvert\Gamma_a\circ\Gamma_\theta(f)-f\rvert<\epsilon,\quad \forall a,\theta\in\mathbb{R}^{+}.$$
		\end{enumerate}
	\end{definition}
	We assume $\overline{D(A)}\in U$ in the following.\\

	\textbf{Notation}. Let $u>e$, we set $\tilde{b}_u:\mathbb{R}^d\times \mathcal{P}_2\to\mathbb{R}^d$ and $\tilde{\sigma}_u:\mathbb{R}^d\times\mathcal{P}_2\to\mathbb{R}^d\otimes\mathbb{R}^d$ such that
	\begin{align*}
		&\tilde{b}_u(y,\mu):=u\tilde{L}(y,\mu)[\Gamma_{\psi(u)}](\Gamma_{\psi(u)}^{-1}(y)), \\
		&\tilde{\sigma}_u(y,\mu):=\psi(u)\nabla[\Gamma_{\psi(u)}](\Gamma_{\psi(u)}^{-1}(y))^{T}\tilde{\sigma}(\Gamma_{\psi(u)}^{-1}(y),\mu\circ\Gamma_{\psi(u)}), \\
		&\tilde{A}_u(y):=u\nabla[\Gamma_{\psi(u)}](\Gamma_{\psi(u)}^{-1}(y))^T\tilde{A}(\Gamma_{\psi(u)}^{-1}(y)),
	\end{align*}
	where for $\tilde{a}=\tilde{\sigma}^T\tilde{\sigma}$, the operator $\tilde{L}$ is given as
	\begin{align*}
		\tilde{L}(y,\mu)[f](q)|_{q=\Gamma_{\psi(u)}^{-1}(y)}=&\sum_{i=1}^{d}\frac{\partial f}{\partial y_i}(\Gamma_{\psi(u)}^{-1}(y))\tilde{b}_i(\Gamma_{\psi(u)}^{-1}(y),\mu\circ\Gamma_{\psi(u)}) \\
		&+\frac{1}{2}\sum_{i,j=1}^{d}\tilde{a}_{i,j}(\Gamma_{\psi(u)}^{-1}(y),\mu\circ\Gamma_{\psi(u)})\frac{\partial^2f}{\partial y_i\partial y_j}(\Gamma_{\psi(u)}^{-1}(y)).
	\end{align*}




	\begin{assumption}\label{Cn}
		For $\forall y\in\mathbb{R}^d$ and $\forall \mu\in\mathcal{P}_2$, we make the following assumptions.
		\begin{enumerate}
			\item[\textbf{(C0)}] There exist $\hat{b}:\mathbb{R}^d\times\mathcal{P}_2\to\mathbb{R}^d$ and $\hat{\sigma}:\mathbb{R}^d\times\mathcal{P}_2\to\mathbb{R}^d\otimes\mathbb{R}^d$ such that
			\begin{align*}
				\lim\limits_{u\to\infty}\tilde{b}_u(y,\mu)=\hat{b}(y,\mu), \quad \lim\limits_{u\to\infty}\tilde{\sigma}_u(y,\mu)=\hat{\sigma}(y,\mu),
			\end{align*}
			where $\hat{b}$ and $\hat{\sigma}$ satisfy \hyperref[h1]{\textbf{(H1)}} and \hyperref[h2]{\textbf{(H2)}} respectively. \\
			\item[\textbf{(C1)}] There exists a multivalued maximal monotone operator $\hat{A}:\mathbb{R}^d\to 2^{\mathbb{R}^d}$ such that for every $\epsilon>0$
			\begin{align*}
				\lim\limits_{u\to\infty}(1+\epsilon\tilde{A}_u)^{-1}(y)=(1+\epsilon A)^{-1}(y).
			\end{align*}
			\item[\textbf{(C2)}] $\tilde{A}_u$, $\tilde{A}$ and $\hat{A}$ are maximal monotone operators with $\overline{D(\tilde{A}_u)}=\overline{D(A)}$ and nonempty interior. Moreover, for $a\in Int(D(\tilde{A}_u))$, $\tilde{A}_u$ is locally bounded at $a$ uniformly in $u$. \\
			\item[\textbf{(C3)}] If $b_\epsilon=\tilde{b}_{1/\epsilon}$, $\sigma_\epsilon=\tilde{\sigma}_{1/\epsilon}$ and $A_\epsilon=\tilde{A}_{1/\epsilon}$, the system of small random perturbation $(b_\epsilon,\sigma_\epsilon,A_\epsilon)$ satisfies \hyperref[h1]{\textbf{(H1)}}, \hyperref[h2]{\textbf{(H2)}} and \hyperref[h4]{\textbf{(H4)}}.
		\end{enumerate}

	\end{assumption}


	For $u>e$ and $t\in\mathbb{R}^+$, define
	\begin{align*}
		Q_u(t):=\Gamma_{\psi(u)}(Y_{ut}),
	\end{align*}
	recall that $Y_0=x$ and $\Gamma_{u}(x)=x$, by definition we have $\Gamma_{u}(0)=x$. Since $\Gamma_{\psi(u)}(\cdot)$ is twice differentiable, by It$\hat{\text{o}}$'s formula we have
	\begin{align}\label{qut}
		\mathrm{d}Q_u(t)&=\mathrm{d}\Gamma_{\psi(u)}(Y_{ut}) \nonumber\\
		&=\nabla[\Gamma_{\psi(u)}](Y_{ut})^T\mathrm{d}Y_{ut}+\frac{(\mathrm{d}Y_{ut})^T}{2}Hess[\Gamma_{\psi(u)}](Y_{ut})\mathrm{d}Y_{ut}.
	\end{align}
	Rewriting $Y_{ut}=\Gamma_{\psi(u)}^{-1}(Q_u(t))$ and substituting it in (\ref{qut}), we get
	\begin{align*}
		\mathrm{d}Q_u(t)=&u\sum_{i=1}^{d}\frac{\partial\Gamma_{\psi(u)}}{\partial y_i}(\Gamma_{\psi(u)}^{-1}(Q_u(t)))\tilde{b}_i(\Gamma_{\psi(u)}^{-1}(Q_u(t)),\mathcal{L}_{Q_u(t)}\circ\Gamma_{\psi(u)})\mathrm{d}t \\
		&+\frac{u}{2}\sum_{i,j=1}^{d}\frac{\partial^2\Gamma_{\psi(u)}}{\partial y_i\partial y_j}(\Gamma_{\psi(u)}^{-1}(Q_u(t)))\sum_{k=1}^{d}\tilde{\sigma}_{k,i}\tilde{\sigma}_{j,k}(\Gamma_{\psi(u)}^{-1}(Q_u(t)),\mathcal{L}_{Q_u(t)}\circ\Gamma_{\psi(u)})\mathrm{d}t \\
		&+\sum_{i=1}^{d}\frac{\partial\Gamma_{\psi(u)}}{\partial y_i}(\Gamma_{\psi(u)}^{-1}(Q_u(t)))\sum_{k=1}^{d}\tilde{\sigma}_{i,k}(\Gamma_{\psi(u)}^{-1}(Q_u(t)),\mathcal{L}_{Q_u(t)}\circ \Gamma_{\psi(u)})\mathrm{d}W^k_{ut} \\
		&-u\sum_{i=1}^{d}\frac{\partial\Gamma_{\psi(u)}}{\partial y_i}(\Gamma_{\psi(u)}^{-1}(Q_u(t)))\tilde{A}(\Gamma_{\psi(u)}^{-1}(Q_u(t)))\mathrm{d}t.
	\end{align*}
	By time change, $\mathcal{W}^{(u)}_t=\frac{W_{ut}}{\sqrt{u}}$ is a Brownian motion. With initial condition $Q_u(0)=x$, $Q_u(t)$ is the solution to the following multivalued McKean-Vlasov SDE:
	\begin{align*}
		\mathrm{d}Q_u(t)\in \tilde{b}_u(Q_u(t),\mathcal{L}_{Q_u(t)})\mathrm{d}t+\frac{1}{\sqrt{\log\log u}}\tilde{\sigma}_u(Q_u(t),\mathcal{L}_{Q_u(t)})\mathrm{d}\mathcal{W}^{(u)}_t-\tilde{A}_u(Q_u(t))\mathrm{d}t.
	\end{align*}
	Under Assumption \ref{Cn} and by Theorem \ref{thmldp}, we have for every closed subset $C$ of $\mathcal{B}(C([0,T],\mathbb{R}^d))$,
	\begin{align}\label{ldpc}
		\limsup\limits_{u\to\infty}\frac{1}{\log\log u}\log P(Q_u\in C)\leq -\inf_{q\in C} I(q),
	\end{align}
	and for every open subset $O$ of $\mathcal{B}(C([0,T],\mathbb{R}^d))$,
	\begin{align*}\label{ldpo}
		\liminf\limits_{u\to\infty}\frac{1}{\log\log u}\log P(Q_u\in O)\geq -\inf_{q\in O} I(q).
	\end{align*}

	Then we present the main theorem of this section.
	\begin{theorem}\label{ILL}
		Under Assumption \ref{Cn}, the family $\left\{Q_u\right\}_{u>e}$ is relatively compact and the set $\Lambda:=\left\{g;I(g)\leq 1\right\}$ is the limit set of $\left\{Q_u\right\}_{u>e}$ when $u\to\infty$ $a.s.$, where
		\begin{align*}
			I(g)=\frac{1}{2}\inf_{\hbar\in\mathcal{H};g=Y^h}\int_{0}^{T}|h(s)|^2\mathrm{d}s,
		\end{align*}
		and $Y^h$ solve the following multivalued McKean-Vlasov SDE:
		\begin{align*}
			\begin{cases}
				\mathrm{d}Y^h_t\in b(Y^h_t,\mathcal{L}_{Y^h_t})\mathrm{d}t+\sigma(Y^h_t,\mathcal{L}_{Y^h_t})h(t)\mathrm{d}t-A(Y^h_t)\mathrm{d}t, \\
				Y^h_0=x.
			\end{cases}
		\end{align*}

		\begin{proof}
			The proof of relatively compactness and the limit set will be given in Proposition \ref{ILLP1} and Proposition \ref{ILLP2} respectively in section \ref{ILLMP}.
		\end{proof}

	\end{theorem}


	\subsection{The Small Time Iterated Logarithm Law}

	For $0<u<e^{-1}$, define $$\varphi(u):=\sqrt{u\log\log u^{-1}}\,.$$

	Let $\tilde{b}:\overline{D(A)}\times\mathcal{P}_2\to\mathbb{R}^d$, $\tilde{\sigma}:\overline{D(A)}\times\mathcal{P}_2\to \mathbb{R}^d\otimes\mathbb{R}^{d}$ and $\tilde{A}$ be a multivalued maximal monotone operator with $0\in Int(D(\tilde{A}))$.

	\textbf{Notation}. Let $0<u<e^{-1}$, we also set $\tilde{b}_u:\mathbb{R}^d\times \mathcal{P}_2\to\mathbb{R}^d$ and $\tilde{\sigma}_u:\mathbb{R}^d\times\mathcal{P}_2\to\mathbb{R}^d\otimes\mathbb{R}^d$ such that
	\begin{align*}
		&\tilde{b}_u(y,\mu):=u\tilde{L}(y,\mu)[\Gamma_{\varphi(u)}](\Gamma_{\varphi(u)}^{-1}(y)), \\
		&\tilde{\sigma}_u(y,\mu):=\psi(u)\nabla[\Gamma_{\varphi(u)}](\Gamma_{\varphi(u)}^{-1}(y))^{T}\tilde{\sigma}(\Gamma_{\varphi(u)}^{-1}(y),\mu\circ\Gamma_{\varphi(u)}), \\
		&\tilde{A}_u(y):=u\nabla[\Gamma_{\varphi(u)}](\Gamma_{\varphi(u)}^{-1}(y))^T\tilde{A}(\Gamma_{\varphi(u)}^{-1}(y)),
	\end{align*}
	where for $\tilde{a}=\tilde{\sigma}^T\tilde{\sigma}$, the operator $\tilde{L}$ is given as
	\begin{align*}
		\tilde{L}(y,\mu)[f](q)|_{q=\Gamma_{\varphi(u)}^{-1}(y)}=&\sum_{i=1}^{d}\frac{\partial f}{\partial y_i}(\Gamma_{\varphi(u)}^{-1}(y))\tilde{b}_i(\Gamma_{\varphi(u)}^{-1}(y),\mu\circ\Gamma_{\varphi(u)}) \\
		&+\frac{1}{2}\sum_{i,j=1}^{d}\tilde{a}_{i,j}(\Gamma_{\varphi(u)}^{-1}(y),\mu\circ\Gamma_{\varphi(u)})\frac{\partial^2f}{\partial y_i\partial y_j}(\Gamma_{\varphi(u)}^{-1}(y)).
	\end{align*}

	%Here we make the following assumption.

	\begin{assumption}\label{Cn1}
		For $\forall y\in\mathbb{R}^d$ and $\forall \mu\in\mathcal{P}_2$, we make the following assumption.
		\begin{enumerate}
			\item[\textbf{(C$'$0)}] There exists $\hat{b}:\mathbb{R}^d\times\mathcal{P}_2\to\mathbb{R}^d$ and $\hat{\sigma}:\mathbb{R}^d\times\mathcal{P}_2\to\mathbb{R}^d\otimes\mathbb{R}^d$ such that
			\begin{align*}
				\lim\limits_{u\to 0^+}\tilde{b}_u(y,\mu)=\hat{b}(y,\mu), \quad \lim\limits_{u\to 0^+}\tilde{\sigma}_u(y,\mu)=\hat{\sigma}(y,\mu),
			\end{align*}
			where $\hat{b}$ and $\hat{\sigma}$ satisfy \hyperref[h1]{\textbf{(H1)}} and \hyperref[h2]{\textbf{(H2)}} respectively. \\
			\item[\textbf{(C$'$1)}] There exists a multivalued maximal monotone operator $\hat{A}:\mathbb{R}^d\to 2^{\mathbb{R}^d}$ such that for every $\epsilon>0$
			\begin{align*}
				\lim\limits_{u\to 0^+}(1+\epsilon\tilde{A}_u)^{-1}(y)=(1+\epsilon A)^{-1}(y).
			\end{align*}
			\item[\textbf{(C$'$2)}] $\tilde{A}_u$, $\tilde{A}$ and $\hat{A}$ are maximal monotone operators with $\overline{D(\tilde{A}_u)}=\overline{D(A)}$ and nonempty interior. Moreover, for $a\in Int(D(\tilde{A}_u))$, $\tilde{A}_u$ is locally bounded at $a$ uniformly in $u$. \\
			\item[\textbf{(C$'$3)}] The system of small random perturbation $(\tilde{b}_u,\tilde{\sigma}_u,\tilde{A}_u)$ satisfies \hyperref[h1]{\textbf{(H1)}}, \hyperref[h2]{\textbf{(H2)}} and \hyperref[h4]{\textbf{(H4)}}.
		\end{enumerate}

	\end{assumption}

	Let $Y_t$ be the solution of multivalued McKean-Vlasov SDE (\ref{IILS}), and define for $0<u<e^{-1}$,
	\begin{align*}
		Q^{'}_u(t):=\Gamma_{\varphi(u)}(Y_{ut}).
	\end{align*}

	Then similarily we have the following theorem.

	\begin{theorem}
		Under Assumption \ref{Cn1}, the family $\left\{Q^{'}_u\right\}_{0<u<e^{-1}}$ is relatively compact and the set $\Lambda:=\left\{g;I(g)\leq 1\right.\}$ is the limit set of $\left\{Q^{'}_u\right\}_{0<u<e^{-1}}$ when $u\to 0^+$ $a.s.$, where
		\begin{align*}
			I(g)=\frac{1}{2}\inf_{\hbar\in\mathcal{H};g=Y^h}\int_{0}^{T}|h(s)|^2\mathrm{d}s,
		\end{align*}
		and $Y^h$ solve the following multivalued McKean-Vlasov SDE:
		\begin{align*}
			\begin{cases}
				\mathrm{d}Y^h_t\in b(Y^h_t,\mathcal{L}_{Y^h_t})\mathrm{d}t+\sigma(Y^h_t,\mathcal{L}_{Y^h_t})h(t)\mathrm{d}t-A(Y^h_t)\mathrm{d}t, \\
				Y^h_0=x.
			\end{cases}
		\end{align*}

		\begin{proof}
			The proof is analogous to that of Theorem 5.3, and is therefore omitted here.
		\end{proof}
	\end{theorem}



	\subsection{Proofs}\label{ILLMP}

	We first state the following continuous dependence result which plays an important role in the proof of Lemma \ref{ILL2}.

	\begin{lemma}\label{hcon}
		Suppose that $\tilde{A}$ is a maximal monotone multivalued operator with $0\in Int(D(\tilde{A}))$, $\tilde{b}$ and $\tilde{\sigma}$ are progressive measurable functions that satisfy \hyperref[h1]{\textbf{(H1)}} and \hyperref[h2]{\textbf{(H2)}}. Then $ B_R\ni \hbar\to Z^h $ is continuous with respect to the distance $ d $, where $ B_R:=\left\{\hbar\in\mathcal{H};\frac{1}{2}\int_{0}^{T}|h(s)|^2\mathrm{d}s\leq 2R\right\} $ and $(Z^h,K^h)$ solves the following multi-valued equation:
		\begin{align*}
			\begin{cases}
				\mathrm{d}Z^h_t\in \tilde{b}(Z^h_t,\mathcal{L}_{Z^h_t})\mathrm{d}t+\tilde{\sigma}(Z^h_t,\mathcal{L}_{Z^h_t})h(t)\mathrm{d}t-\tilde{A}(Z^h_t)\mathrm{d}t, \\
				Z^h_0=x\in\overline{D(\tilde{A})}.
			\end{cases}
		\end{align*}
		\begin{proof}
			For any fixed $\hbar_0\in B_R$, let $\hbar\in B_R$ such that $\sup_{t\in [0,T]}|\hbar(t)-\hbar_0(t)|\to 0,$ then
			\begin{align*}
				&|Z^h_t-Z^{h_0}_t|^2\\
				=&-2\,\int_{0}^{t}\langle Z^h_s-Z^{h_0}_s, \mathrm{d}K^h_s-\mathrm{d}K^{h_0}_s \rangle \mathrm{d}s+
				2\,\int_{0}^{t}\langle Z^h_s-Z^{h_0}_s, \tilde{b}(Z^h_s,\mathcal{L}_{Z^h_s})-\tilde{b}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s}) \rangle\mathrm{d}s \\
				& +2\,\int_{0}^{t}\langle Z^h_s-Z^{h_0}_s,  \tilde{\sigma}(Z^h_s,\mathcal{L}_{Z^h_s})h(s)-\tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})h_0(s) \rangle\mathrm{d}s \\
				\leq &\,2\,\int_{0}^{t} \langle Z^h_s-Z^{h_0}_s, \tilde{b}(Z^h_s,\mathcal{L}_{Z^h_s})-\tilde{b}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})  \rangle\mathrm{d}s   \\
				&+2\,\int_{0}^{t}\langle Z^h_s-Z^{h_0}_s,  \tilde{\sigma}(Z^h_s,\mathcal{L}_{Z^h_s})h(s)-\tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})h(s) \rangle\mathrm{d}s \\
				&+2\,\int_{0}^{t}\langle Z^h_s-Z^{h_0}_s,  \tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})h(s)-\tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})h_0(s) \rangle\mathrm{d}s,
			\end{align*}
			where the last inequality follows from \eqref{mono}.

			By using Young's inequality, \textbf{(H1)} and \textbf{(H2)}, we have
			\begin{align*}
				&\sup_{s\in[0,t]}|Z^h_s-Z^{h_0}_s|^2 \\
				\leq&2\int_{0}^{t}\varrho(|Z^h_s-Z^{h_0}_s|^2)\mathrm{d}s+2\,\int_{0}^{t} |Z^h_s-Z^{h_0}_s|\cdot \lVert \tilde{\sigma}(Z^h_s,\mathcal{L}_{Z^h_s})-\tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})\rVert\cdot|h(s)|\mathrm{d}s \\
				&+\sup_{t'\in[0,t]}2\int_{0}^{t'}\langle Z^h_s-Z^{h_0}_s,  \tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})(h(s)-h_0(s)) \rangle\mathrm{d}s \\
				\leq & \,2\int_{0}^{t}\varrho(|Z^h_s-Z^{h_0}_s|^2)\mathrm{d}s+4R^{1/2}\left( \int_{0}^{t}|Z^h_s-Z^{h_0}_s|^2\cdot\lVert \tilde{\sigma}(Z^h_s,\mathcal{L}_{Z^h_s})-\tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})\rVert^2 \mathrm{d}s\right)^{1/2} \\
				&+\sup_{t'\in[0,t]}2\int_{0}^{t'}\langle Z^h_s-Z^{h_0}_s,  \tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})(h(s)-h_0(s)) \rangle\mathrm{d}s,
			\end{align*}
			which implies
			\begin{align}\label{511}
				\sup_{s\in[0,t]}|Z^h_s-Z^{h_0}_s|^2\leq & \,\frac{1}{2}\sup_{s\in[0,t]}|Z^h_s-Z^{h_0}_s|^2+(8R+2)\int_{0}^{t}\varrho(\sup_{t'\in[0,s]}|Z^h_{t'}-Z^{h_0}_{t'}|^2)\mathrm{d}s \nonumber\\
				&+ \sup_{t'\in[0,t]}2\int_{0}^{t'}\langle Z^h_s-Z^{h_0}_s,  \tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})(h(s)-h_0(s)) \rangle\mathrm{d}s.
			\end{align}
			Here we denote the last term of (\ref{511}) as $J(t)$ and define
			\begin{align*}
				\nu(t):=\int_{0}^{t}\tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})(h(s)-h_0(s))\mathrm{d}s.
			\end{align*}
			Using integration by parts, we have
			\begin{align*}
				&\int_{0}^{t}\langle\, Z^h_s-Z^{h_0}_s,  \tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})(h(s)-h_0(s)) \rangle\mathrm{d}s \\
				=&\langle\, \nu(t), Z^h_t-Z^{h_0}_t\rangle-\int_{0}^{t}\langle \,\nu(s),\tilde{b}(Z^h_s,\mathcal{L}_{Z^h_s})-\tilde{b}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})\rangle\mathrm{d}s \\
				&-\int_{0}^{t}\langle \,\nu(s),\tilde{\sigma}(Z^h_s,\mathcal{L}_{Z^h_s})h(s)-\tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})h_0(s)\rangle\mathrm{d}s +\int_{0}^{t}\langle \,\nu(s),\mathrm{d}K^h_s-\mathrm{d}K^{h_0}_s\rangle.
			\end{align*}
			Following the proof of Lemma \ref{yosifin}, we have for $h,h_0\in B_R$ and $p\geq 1$
			\begin{align*}
				\sup_{t\in[0,T]}|Z^h_t|^p+|K^h|^0_T\leq C_R \text{ and }\sup_{t\in[0,T]}|Z^{h_0}_t|^p+|K^{h_0}|^0_T\leq C_R.
			\end{align*}
			By \textbf{(H1)} and \textbf{(H2)} we can deduce that
			\begin{align*}
				\sup_{t\in[0,T]} \int_{0}^{t}\langle\, Z^h_s-Z^{h_0}_s,  \tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})(h(s)-h_0(s)) \rangle\mathrm{d}s\leq C_R\sup_{t\in[0,T]}|\nu(t)|.
			\end{align*}

			Next we will prove that
			\begin{align*}
				\sup_{t\in[0,T]}|\nu(t)|\to 0\quad\textit{as } \sup_{s\in[0,T]}|\hbar(s)-\hbar_0(s)|\to 0.
			\end{align*}
			Let $\varphi$ be a mollifier with $\textit{supp}\,\varphi\subset(-1,1),\,\,\varphi\in C^{\infty}$ and $\int_{-1}^{1}\varphi(t)\mathrm{d}t=1$. Consider the following function
			\begin{align*}
				\rho_n(t)=\int_{0}^{T}\tilde{\sigma}(Z^{h_0}_{u},\mathcal{L}_{Z^{h_0}_{u}})\varphi_n(t-u)\mathrm{d}u,
			\end{align*}
			where $\varphi_n(u):=n\varphi(nu)$.
			We can easily get that $t\to\rho_n(t)$ is differentiable and
			\begin{align*}
				\int_{0}^{T}\lVert \tilde{\sigma}(Z^{h_0}_t,\mathcal{L}_{Z^{h_0}_t})-\rho_n(t)\rVert^2\mathrm{d}t\to 0\quad\textit{as} \,\,\, n\to\infty.
			\end{align*}
			Hence
			\begin{align*}
				\sup_{t\in[0,T]} |\nu(t)|=&\sup_{t\in[0,T]}\lvert \int_{0}^{t}\tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})(h(s)-h_0(s))\mathrm{d}s \rvert \\
				\leq& \sup_{t\in[0,T]}\lvert\int_{0}^{t}(\tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})-\rho_n(s))(h(s)-h_0(s))\mathrm{d}s \rvert+\sup_{t\in[0,T]}\lvert\int_{0}^{t}\rho_n(s)(h(s)-h_0(s))\mathrm{d}s \rvert \\
				=:&J_1+J_2.
			\end{align*}
			By using H\"older's inequality, for any $\delta>0$, there exists $n_0\in\mathbb{N}$ such that
			\begin{align*}
				J_1\leq&\left(\int_{0}^{T}\lVert \tilde{\sigma}(Z^{h_0}_s,\mathcal{L}_{Z^{h_0}_s})-\rho_{n_0}(s)\rVert^2\mathrm{d}s\right)^{1/2}\left( \int_{0}^{T}|h(s)-h_0(s)|^2\mathrm{d}s \right)^{1/2} \\
				\leq& \,\,4R^{1/2}\delta^{1/2}.
			\end{align*}
			For $J_2$, denote the derivative of $\rho_{n_0}(t)$ by $\rho'_{n_0}(t)$, using integration by parts, we obtain
			\begin{align*}
				J_2\leq \sup_{t\in[0,T]}|\hbar(t)-\hbar_0(t)|\left( \sup_{t\in[0,T]}\lVert \rho_{n_0}(t)\rVert+\int_{0}^{T}\lVert\rho'_{n_0}(t)\rVert\mathrm{d}t \right),
			\end{align*}
			Thus we obtain that $ J_2\to 0 $ as $\sup_{t\in[0,T]}|\hbar(t)-\hbar_0(t)|\to 0$. By Lemma \ref{bhr} we get
			\begin{align*}
				\sup_{t\in[0,T]}|Z^h_t-Z^{h_0}_t|\to 0 \quad \textit{as}\quad \sup_{t\in[0,T]}|\hbar(t)-\hbar_0(t)|\to 0.
			\end{align*}
		\end{proof}
	\end{lemma}


	The following two results will play an important role in the proof of Proposition 5.7.

	\begin{lemma}\label{ILL2}
		Assume that \hyperref[h0]{\textbf{(H0)}}-\hyperref[h4]{\textbf{(H4)}} hold. Let $a$ be a fixed positive number, then for every $\beta>0$ and $R>0$, there exist $\epsilon_{0},\eta_0>0$ such that for any $0<\epsilon<\epsilon_{0}$ and $0<\eta<\eta_0$,
		\begin{align*}
			P\left\{d(\sqrt{\epsilon} W,\hbar)<\eta,\,d(X^\epsilon,g)>\beta\right\}\leq \exp(-R/\epsilon)
		\end{align*}
		holds for every $\hbar$ with $I(g)\leq a$ and $g=Y^h$.

		\begin{proof}
			Consider the diffusion
			\begin{align*}
				Z^\epsilon_t:=
				\begin{pmatrix}
					\sqrt{\epsilon} W_t \\
					X^\epsilon_t
				\end{pmatrix} ,
			\end{align*}
			then $Z^\epsilon_t$ is the solution to the following MMVSDE:
			\begin{align*}
				\begin{cases}
					\mathrm{d}Z^\epsilon_t\in \tilde{b}_\epsilon(Z^\epsilon_t,\mathcal{L}_{Z^\epsilon_t})\mathrm{d}t+\sqrt{\epsilon}\tilde{\sigma}_\epsilon(Z^\epsilon_t,\mathcal{L}_{Z^\epsilon_t})\mathrm{d}W_t-\tilde{A}_\epsilon(Z^\epsilon_t)\mathrm{d}t, \\
					Z^\epsilon_0=\left(^0_x\right),
				\end{cases}
			\end{align*}
			where
			\begin{align*}
				&\tilde{b}_\epsilon(x',\mu')=\tilde{b}_\epsilon\left(\begin{pmatrix}y \\ x \end{pmatrix},\begin{pmatrix}\nu \\ \mu \end{pmatrix}\right)=\begin{pmatrix}0 \\ b_\epsilon(x,\mu) \end{pmatrix}:\mathbb{R}^{d+d}\times \mathcal{P}_2(\mathbb{R}^{d+d})\to \mathbb{R}^{d+d}, \\ &\tilde{\sigma}_\epsilon(x',\mu')=\tilde{\sigma}_\epsilon\left(\begin{pmatrix}y \\ x \end{pmatrix},\begin{pmatrix}\nu \\ \mu \end{pmatrix}\right)=\begin{pmatrix}I \\ \sigma_\epsilon(x,\mu) \end{pmatrix}:\mathbb{R}^{d+d}\times \mathcal{P}_2(\mathbb{R}^{d+d})\to \mathbb{R}^{d+d}\otimes \mathbb{R}^d
			\end{align*}
			and
			\begin{align*}
				\tilde{A}_\epsilon(x')=\tilde{A}_\epsilon\left(\begin{pmatrix}y \\ x \end{pmatrix}\right)=\begin{pmatrix}0 \\ A_\epsilon(x) \end{pmatrix}:\mathbb{R}^{d+d}\to 2^{\mathbb{R}^{d+d}}
			\end{align*}
			for any $x,y\in\mathbb{R}^d$ and $\mu,\nu\in\mathcal{P}_2(\mathbb{R}^d)$.

			For each $g\in C([0,T];\mathbb{R}^{d+d})$, define
			\begin{align*}
				\tilde{I}(g)\coloneqq\frac{1}{2}\inf_{\hbar\in\mathcal{H};g=Z^h}\int_{0}^{T}|h(t)|^2\mathrm{d}t,
			\end{align*}
			where $(Z^h,K^h)$ is the solution to the following equation:
			\begin{align}\label{izh}
				\begin{cases}
					\mathrm{d}Z^h_t\in \tilde{b}(Z^h_t,\mathcal{L}_{Z^h_t})\mathrm{d}t+\tilde{\sigma}(Z^h_t,\mathcal{L}_{Z^h_t})h(t)\mathrm{d}t-\tilde{A}(Z^h_t)\mathrm{d}t, \\
					Z^h_0=\left(^0_x\right).
				\end{cases}
			\end{align}
			Here $\tilde{b}, \tilde{\sigma}$ and $\tilde{A}$ are defined similarly as before.		

			It is obvious to note that $\tilde{b},\tilde{b}_\epsilon,\tilde{\sigma},\tilde{\sigma}_\epsilon,\tilde{A}$ and $\tilde{A}_\epsilon$ also satisfy \textbf{(H0)}-\textbf{(H4)}. Thus (\ref{izh}) is decomposed into two systems, i.e.
			\begin{align*}
				Z^h=\begin{pmatrix}
					\hbar \\
					Y^h
				\end{pmatrix},
			\end{align*}
			where $Y^h$ is the solution to the following equation:
			\begin{align*}
				\begin{cases}
					\mathrm{d}Y^h_t\in b(Y^h,\mathcal{L}_{Y^h_t})\mathrm{d}t+\sigma(Y^h,\mathcal{L}_{Y^h_t})h(t)\mathrm{d}t-A(Y^h_t)\mathrm{d}t, \\
					Y^h_0=x.
				\end{cases}
			\end{align*}

			Fix $\beta>0$ and $R>0$. Then
			\begin{align*}
				P\left\{d(\sqrt{\epsilon} W,\hbar)<\eta,\,d(X^\epsilon,Y^h)>\beta\right\}=P(Z^\epsilon\in \digamma_\eta),
			\end{align*}
			where
			\begin{align*}
				\digamma_\eta:=\left\{\chi=\begin{pmatrix} \chi_1 \\ \chi_2 \end{pmatrix}\in C([0,T];\mathbb{R}^{d+d});\,d(\chi_1,\hbar)<\eta,\,d(\chi_2,Y^h)>\beta\right\}.
			\end{align*}
			By Lemma \ref{hcon} we know that $\hbar\to Z^h$ is continuous with respect the distance $d$ when $\hbar\in B_R$. Thus there exists $\eta>0$ such that if $\chi_1\in B_R$ and $d(\chi_1,\hbar)\leq \eta$, then
			\begin{align*}
				d(Y^{\chi_1},Y^h)\leq \beta.
			\end{align*}
			This implies that for such $\eta$, there does not exist any trajectory $\chi\in \digamma_\eta$ such that
			\begin{align*}
				\frac{1}{2}\int_{0}^{T}|\chi_1(t)|^2\mathrm{d}t\leq 2R,\quad  \chi=\begin{pmatrix} \chi_1 \\  Y^{\chi_1} \end{pmatrix}
			\end{align*}
			which means
			\begin{align*}
				\inf_{g\in\digamma_\eta} \tilde{I}(g)\geq 2R.
			\end{align*}
			Thus by Theorem \ref{thmldp} and Definition \ref{ldpdefin}, we get the desired result.

		\end{proof}



	\end{lemma}





	\begin{lemma}\label{item1}
		For $\forall c>1$ and $\forall \epsilon>0$, there exists a positive integer $j_0(\omega)$ almost surely finite such that $\forall j>j_0$,
		\begin{align*}
			d(Q_{c^j},\Lambda)<\epsilon, \quad \text{where}\,\, d(x,B)=\inf_{y\in B}\lVert x-y\rVert.
		\end{align*}

		\begin{proof}
			Consider the set $\Lambda_\epsilon:=\left\{g;d(g,\Lambda)\geq \epsilon\right\}$. By definition and the lower semicontinuity of $I(g)$ we have that $\inf_{g\in \Lambda_\epsilon}I(g)>1$, so there exists a positive number $\eta$ such that $\inf_{g\in  \Lambda_\epsilon}I(g)>1+\eta$. Therefore, by (\ref{ldpc}) we have
			\begin{align*}
				\limsup\limits_{u\to\infty} \frac{1}{\log\log u}P(Q_u\in\Lambda_\epsilon)\leq -(1+\eta).
			\end{align*}
			Thus for $j$ large enough and for every $c>1$, there exists a constant $C>0$ such that
			\begin{align*}
				P(Q_{c^j}\in\Lambda_\epsilon)\leq \exp\left\{-(1+\eta)\log\log(c^j)\right\}=\frac{C}{j^{1+\eta}}.
			\end{align*}
			Since $\sum_{j=1}^{\infty}P(Q_{c^j}\in\Lambda_\epsilon)<\infty$, by Borel-Cantelli lemma we get $P(\limsup_j[d(Q_{c^j},\Lambda)\geq\epsilon])=0$, i.e. $\lim_{j\to\infty}d(Q_{c^j},\Lambda)=0\,$ a.s..
		\end{proof}

	\end{lemma}



	We are now able to present the proof of Theorem 5.3, which will be divided into two propositions.


	\begin{proposition}[Relatively Compactness]\label{ILLP1}
		Under Assumption \ref{Cn}, for every $\epsilon>0$ there exists almost surely a positive number $u_0$ such that for every $u>u_0$,
		\begin{align*}
			d(Q_u,\Lambda)<\epsilon.
		\end{align*}


		\begin{proof}
			Let $c> 1$. For any $u>1$, there exists some $j\in\mathbb{N}$ sufficiently large such that $c^{j-1}\leq u\leq c^j$. Then
			\begin{align*}
				d(Q_u,\Lambda)\leq&\, d(Q_{c^j},\Lambda)+d(Q_u,Q_{c^j}) \\
				\leq&\, d(Q_{c^j},\Lambda)+\lVert Q_u-\Gamma_{\psi(u)}\circ \Gamma_{\psi(c^j)}^{-1}(Q_{c^j})\rVert \\
				&+\lVert \Gamma_{\psi(u)}\circ \Gamma_{\psi(c^j)}^{-1}(Q_{c^j})-Q_{c^j}\rVert \\
				=:& J^d_1+J^d_2+J^d_3.
			\end{align*}
			For arbitrarily small $\epsilon>0$, Lemma \ref{item1} ensures that $J^d_1$ is bounded by ${\epsilon}$ and $Q_{c^j}$ is almost surely bounded with $j$ large enough. Moreover, for every $u\in[c^{j-1},c^j]$, $\forall \delta>0$
			\begin{align*}
				1\geq\frac{\psi(u)}{\psi(c^j)}\geq\frac{\psi(c^{j-1})}{\psi(c^j)}\geq \frac{1-\delta}{\sqrt{c}},
			\end{align*}
			so that if we choose $c>1$ small enough, then by using $(d)$ of Definition \ref{gadef} we get
			\begin{align*}
				J^d_3=\lVert \Gamma_{\psi(u)}\circ \Gamma_{\psi(c^j)}^{-1}(Q_{c^j})-Q_{c^j}\rVert\leq\epsilon.
			\end{align*}
			By definition of $Q_u(t)$ and $(b)$ of Definition \ref{gadef}, we have
			\begin{align*}
				J^d_2=&\sup_{t\in[0,T]}|\Gamma_{\psi(u)}(Y_{ut})-\Gamma_{\psi(u)}(Y_{c^jt})| \\
				\leq& \sup_{t\in[0,T]}|\Gamma_{\psi(c^{j-1})}(Y_{ut})-\Gamma_{\psi(c^{j-1})}(Y_{c^jt})|.
			\end{align*}
			Thus we rewrite
			\begin{align*}
				d(Q_u,\Lambda)<&\,2\epsilon+\sup_{t\in[0,T]}|\Gamma_{\psi(c^{j-1})}(Y_{ut})-\Gamma_{\psi(c^{j-1})}(Y_{c^jt})| \\
				\leq&\, 2\epsilon+\sup_{\substack{0\leq s\leq T \\ s/c\leq t\leq s}}|\Gamma_{\psi(c^{j-1})}(Y_{c^jt})-\Gamma_{\psi(c^{j-1})}(Y_{c^js})|.
			\end{align*}
			By adding and substracting the terms $Q_{c^{j}}(t)$ and $Q_{c^{j}}(s)$ and using (d) of Definition \ref{Cn}, we obtain
			\begin{align*}
				d(Q_u,\Lambda)<&\,2\epsilon+\sup_{\substack{0\leq s\leq T}}|\Gamma_{\psi(c^{j-1})}\circ\Gamma_{\psi(c^j)}^{-1}(Q_{c^j}(s))-Q_{c^j}(s)| \\
				&+\,\sup_{\substack{0\leq t\leq T}} |\Gamma_{\psi(c^{j-1})}\circ\Gamma_{\psi(c^j)}^{-1}(Q_{c^j}(t))-Q_{c^j}(t)|+\,\sup_{\substack{0\leq s\leq T \\ s/c\leq t\leq s}} |Q_{c^j}(s)-Q_{c^j}(t)| \\
				\leq &\,4\epsilon+\sup_{\substack{0\leq s\leq T \\ s/c\leq t\leq s}} |Q_{c^j}(s)-Q_{c^j}(t)|.
			\end{align*}
			Let $g\in\Lambda$ such that $\lVert Q_{c^j}-g \rVert<d(Q_{c^j},\Lambda)+\epsilon$. Then in particular, $\lVert Q_{c^j}-g\rVert <2\epsilon$ and we have
			\begin{align*}
				d(Q_u,\Lambda)\leq 8\epsilon+\sup_{g\in\Lambda}\sup_{\substack{0\leq s\leq T \\ s/c\leq t\leq s}}|g(t)-g(s)|.
			\end{align*}
			Since $\Lambda$ is compact, using Ascoli-Arzel\`a's theorem we can deduce that there exists a constant $c>1$ such that
			\begin{align*}
				\sup_{g\in\Lambda}\sup_{\substack{0\leq s\leq T \\ s/c\leq t\leq s}}|g(t)-g(s)|\leq \epsilon.
			\end{align*}
			Therefore we get the desired result
			\begin{align*}
				d(Q_u,\Lambda)<\epsilon.
			\end{align*}

		\end{proof}

	\end{proposition}




	\begin{proposition}[The set of limit points]\label{ILLP2}
		Let $g\in \Lambda$ be such that $I(g)<1$, Then for any $\epsilon>0$ there exists $c_\epsilon>1$ such that for every $c>c_\epsilon$,
		\begin{align*}
			P\left\{d(Q_{c^j},g)<\epsilon\,\,\, i.o.\right\}=1.
		\end{align*}

		\begin{proof}
			For any $g\in \Lambda$ with $I(g)<1$, let $\hbar_\cdot=\int_0^\cdot h(s)ds$ with $g=Z^h$. Recall that $\mathcal{W}^{(u)}_t=\frac{W_{ut}}{\sqrt{u}}$.  For any $\epsilon>0$ and $\eta>0$, define
			\begin{align*}
				E_j=\left\{\big\lVert \frac{\mathcal{W}^{(c^j)}}{\sqrt{\log\log c^j}}-\hbar\big\rVert< \eta\right\},\quad
				F_j=\left\{ \lVert Q_{c^j}-g \rVert<\epsilon\right\}.
			\end{align*}
			Using Lemma \ref{ILL2} we have that for $j$ large enough and $\eta$ small enough, there exists some constant $C>0$ such that
			\begin{align}\label{lp1}
				P(E_j)-P(F_j)=P(E_j\cap F_j^c)\leq \exp\left\{-2\log\log c^j\right\}=\frac{C}{j^2}.
			\end{align}
			Since $P(\limsup_{j\to\infty} E_j)=1$ by Strassen's law. Therefore, $\sum_{j}P(E_j)=\infty$. However, by (\ref{lp1}) we also have
			\begin{align*}
				\sum_j(P(E_j)-P(F_j))< \infty.
			\end{align*}
			Thus we obtain $\sum_j P(F_j)=\infty$, by Borel-Cantelli lemma we get our result
			\begin{align*}
				P\left\{\lVert Q_{c^j}-g\rVert<\epsilon\,\,\, i.o.\right\}=1.
			\end{align*}

		\end{proof}

	\end{proposition}















