            \includegraphics[width=0.5\linewidth]{figure4.pdf}%
            \caption{Mean annual power calculated directly from all measured spectra in Table~\ref{tab:waves} and used as ground truth. Dashed lines show 95\textsuperscript{th} percent confidence interval for the mean (solid line).}
              \label{fig:annual_power}
