%=== KINEMATICS =============================
\section{Kinematics}
The electroproduction of $K^+\Lambda$ on the proton can be written as an inelastic scattering process
    \begin{equation}
        e(k_i)+p(p)\to e'(k_f)+K^+(q)+\Lambda(p_\Lambda),
    \end{equation}
where the four-momentum of each particle is indicated in the parentheses. This process can also be regarded as a virtual photoproduction process
    \begin{equation}
        \gamma_\text{v}(k)+p(p)\to K^+(q)+\Lambda(p_\Lambda),
    \end{equation}
where $k\equiv k_i-k_f$ is the four-momentum of the virtual photon. The invariant amplitudes obtained from the relevant Feynman diagrams can be decomposed into six gauge- and Lorentz-invariant matrices $M_i$, 
    \begin{equation}
        \mathcal{M}=\bar{u}_\Lambda \sum_{i=1}^6A_i(s,t,u,k^2)M_iu_p,
        \label{eq:A_iM_i}
    \end{equation}
where $\bar{u}_\Lambda\equiv \bar{u}(p_\Lambda)$ and $u_p\equiv u(p)$ are the spinors of the $\Lambda$ and proton, respectively. The Mandelstam variables, $s$, $t$, and $u$ are defined by 
    \begin{equation}
        s=(k+p)^2,\ \ t=(k-q)^2,\ \ u=(k-p_\Lambda)^2
    \end{equation}
while the gauge- and Lorentz- invariant matrices $M_i$ are given by \cite{Luthfiyah:2021yqe,Clymton:2021wof,Mart:2019mtq,Mart:2015jof}
    \begin{align}
	    M_1&=\frac{1}{2}\gamma_5\brac{\slashed{\epsilon}\slashed{k}-\slashed{k}\slashed{\epsilon}},               \\
	    M_2&=\gamma_5\sqbrac{\brac{2q-k}\cdot \epsilon P\cdot k-\brac{2q-k}\cdot k P\cdot \epsilon}, \\
	    M_3&=\gamma_5\sqbrac{\brac{q\cdot k} \slashed{\epsilon}-\brac{q\cdot\epsilon}\slashed{k}},               \\
	    M_4&=i\varepsilon_{\mu\nu\rho\sigma}\gamma^\mu q^\nu\epsilon^\rho k^\sigma,               \\
	    M_5&=\gamma_5\sqbrac{\brac{q\cdot \epsilon}k^2-\brac{q\cdot k}\brac{k\cdot\epsilon}},       \\
	    M_6&=\gamma_5\sqbrac{\brac{k\cdot\epsilon}\slashed{k}-k^2\slashed{\epsilon}}, 
    \end{align}
where $P\equiv (p+p_\Lambda)/2$ and $\varepsilon_{\mu\nu\rho\sigma}$ is the four-dimensional Levi-Civita tensor. Note that in the literature, the definitions of $M_i$'s are not unique. All observables measured in experiments can be calculated analytically using $A_i$ extracted from Eq.~(\ref{eq:A_iM_i}), after accounting for all contributions from the intermediate state of the Born and resonance terms in the amplitude ${\cal M}$. 
%============================================

%=== FORM FACTORS ===========================
\section{Electromagnetic Form Factors}
As a starting point, we use the standard dipole electromagnetic form factor for baryon (i.e., nucleon and hyperon) resonances,  
\begin{equation}
    F_{\rm D}(Q^2)=\left(1+\frac{Q^2}{\Lambda^2}\right)^{-2}.
\end{equation}
Furthermore, we also use two different form factor models given by
\begin{align}
    &F^{B^*}_1(Q^2)=F_{\rm D}(Q^2)\,\exp(-a_1Q^2), \label{Eq.FF1} \\[0.25cm]
    &F^{B^*}_2(Q^2)=F_{\rm D}(Q^2)\,\text{sech}^2(a_2Q^2)\label{Eq.FF2},
\end{align}
where $Q^2\equiv -k^2$ and the free parameters $\Lambda$ and $a_i$ are determined by fitting the model to the available experimental data. 

For kaon resonances $K^*$ and $K_1$, we employ the commonly used monopole form factor
\begin{equation}
    F_{K^*}(Q^2)=\left(1+\frac{Q^2}{\Lambda_{K^*}^2}\right)^{-1} \hspace{0.5cm} \text{and} \hspace{0.5cm} F_{K_1}(Q^2)=\left(1+\frac{Q^2}{\Lambda_{K_1}^2}\right)^{-1},
\end{equation}
where the cutoff masses $\Lambda_i$ are also determined from fitting the observables to the experimental data.
%============================================

%=== Observables ==========================
\section{Observables}
The measured differential cross section for kaon electroproduction in an experiment is given by 
\begin{equation}
    \frac{d\sigma}{d\Omega_{e'}dE_{e'}d\Omega_K}= \Gamma\,\frac{d\sigma_v}{d\Omega_K},
\end{equation}
where $\Gamma$ is the flux of virtual photon field~\cite{Knochlein:1995qz}. The virtual differential cross section ${d\sigma_v}/{d\Omega_K}$ can be written in terms of the structure functions $\sigma_i\equiv{d\sigma_i}/{d\Omega_K}$, where $i=$ T, L, U, TT, LT, and LT' refer to transversely unpolarized, longitudinally polarized, unpolarized, transversely polarized, and interference terms between longitudinally and transversely polarized terms, respectively \cite{Sakinah:2019jwd}. Explicitly, it is written as \cite{Mart:2010ch}
\begin{equation}
    \frac{d\sigma_v}{d\Omega_K} = \frac{d\sigma_\mathrm{T}}{d\Omega_K} + \epsilon \frac{d\sigma_\mathrm{L}}{d\Omega_K} + \epsilon\frac{d\sigma_\mathrm{TT}}{d\Omega_K}\cos{2\Phi}+ \sqrt{\epsilon(1+\epsilon)}\frac{d\sigma_\mathrm{LT}}{d\Omega_K}\cos{\Phi}+h\sqrt{\epsilon(1-\epsilon)} \frac{d\sigma_\mathrm{LT'}}{d\Omega_K}\sin{\Phi},
\end{equation}
where $\epsilon$ measures the transverse polarization of the virtual photon and $h$ is the helicity of the electron beam \cite{Knochlein:1995qz,Mart:2010ch}. In this work, only the first three structure functions will be discussed. Additionally, we have experimental data for the averaged beam-recoil transferred polarizations $P'_{x'}$ and $P'_x$ defined as \cite{CLAS:2022yzd}
\begin{eqnarray}
  P'_{x'}(\cos\theta) 
  &=& \frac{\displaystyle 
  \int dW \int dQ^2\, K_{\rm f}
  \sqrt{1-\epsilon^2}\, 
  R_{\rm TT'}^{x'0}(Q^2,W,\cos\theta)}{\displaystyle \int 
  dW\int dQ^2\, K_{\rm f}\left\{ R_{\rm T}^{00}(Q^2,W,\cos\theta)
    +\epsilon R_{\rm L}^{00}(Q^2,W,\cos\theta)
  \right\}}\,,
  \label{eq:RF1}
\end{eqnarray}
and
\begin{eqnarray}
  P'_{x}(\cos\theta) &=& \frac{\displaystyle 
  \int dW\int dQ^2\, K_{\rm f}
  {\textstyle\frac{1}{2}}\sqrt{\epsilon(1-\epsilon)}\, \left(
  R_{\rm LT'}^{x'0}\cos\theta-R_{\rm LT'}^{y'0}+R_{\rm LT'}^{z'0}\sin\theta
  \right)}{\displaystyle \int dW \int dQ^2\, K_{\rm f}\left\{ R_{\rm T}^{00}(Q^2,W,\cos\theta)
    +\epsilon R_{\rm L}^{00}(Q^2,W,\cos\theta)
  \right\}}\,,
  \label{eq:RF2}
\end{eqnarray}
where the response functions $R_i^{\mu\nu}(Q^2,W,\cos\theta)$ and the notation for variables are given, e.g., in Ref.~\cite{Knochlein:1995qz}.


