The following corollary gives a rigorous mathematical characterization of this behaviour. The proof is straightforward and hence, omitted.

\begin{corollary}\label{cor: fee for k to 0}
    Define the matrix $ \mathbf{A} : =  ( \mathbf{A}_{i,j} )_{0 \leq i \leq j \leq 2N} $ by
    \[
    \mathbf{A}_{i,j} : =
    \begin{cases}
        \intsell e^{-1} & \text{ if } i = j - 1, \\
        \intbuy e^{-1} & \text{ if } i = j + 1, \\
        0 & \text{ otherwise,}
    \end{cases}
    \]
    and denote with $\mathbf{1}$ the unit vector of $\mathbb{R}^{2N}$. Define the function $w : [0,T] \times \{ y^{-N}, \dots, y^{N} \} \to \mathbb{R}$ by \[ w(t,y^{i}) : = (\exp( \mathbf{A}(T - t)) \mathbf{1})_{i},. \]
Let $\feeLTsells^{*}$ and $\feeLTbuys^{*}$ be the optimal fees from Theorem \ref{th: value function and optimal fees} and define the quantities
    \begin{align}
    \feeLTsells^{*}_0(t,y^i) & : =  \frac{1}{ \exratesell(y^{i}) \deltasell(y^{i})} \left( 1 +  \log \left( \frac{w(t,y^{i})}{w(t,y^{i + 1})} \right) \right) \\
    \feeLTbuys^{*}_0(t,y^i) & : = \frac{1}{ \exratebuy(y^{i}) \deltabuy(y^{i})} \left( 1 +  \log \left( \frac{w(t,y^{i})}{w(t,y^{i - 1})} \right) \right).
\end{align}
We have that 
\begin{align}
    \lim_{k \to 0} k\feeLTsells^{*}(t,y^i) = \feeLTsells^{*}_0(t,y^i) \quad \quad \text{ and } \quad \quad  \lim_{k \to 0} k\feeLTbuys^{*}(t,y^i) = \feeLTbuys^{*}_0(t,y^i),
\end{align}
for every $t \in [0,T]$ and $y^{i} \in \{ y^{-N}, \dots, y^{N} \}$.
\end{corollary}


