\section{Quadratic approximation with stochastic oracle price}\label{section: second Approximation}

For the second approximate solution we return to the original HJB equation in \eqref{eq: eq for g}. %Here, we do not pose any limitation to the inventory.\todo{Again I am not sure if this makes sense in light of the approximations} This will result in us dropping the characteristic functions $\ind_{ \{ y > \underline{y} \}}$ and $\ind_{ \{ y < \overline{y} \}}$ from the equation.
%This assumption is sensible if the depth of the pool $\depth$ is large. We work in an CPM, and we take $P(y,s) = \pencons ( Z(y) - s)^{2}.$ Finally, 
Here, we make a quadratic approximation of the exponential terms:
\small{
\begin{align*}
    e^{\expdecay (-\oracleprice \deltasell(y) + \exratesell (y) \deltasell(y) + g(t,y + \deltasell(y),s) - g(t,y,s) )} \approx 1 & + \expdecay (-\oracleprice \deltasell(y) + \exratesell (y) \deltasell(y) + g(t,y + \deltasell(y) ,s) - g(t,y,s) ) \\
    & + \frac{1}{2} [ \expdecay (-\oracleprice \deltasell(y)  + \exratesell (y) \deltasell(y) + g(t,y + \deltasell(y),s) - g(t,y,s) ) ]^{2}, \\
    e^{ \expdecay( \oracleprice \deltabuy(y) - \exratebuy (y) \deltabuy(y)   + g(t,y - \deltabuy(y) ,s) - g(t,y,s))} \approx 1 & + \expdecay( \oracleprice \deltabuy(y)  - \exratebuy (y) \deltabuy(y)  + g(t,y - \deltabuy(y),s) - g(t,y,s)) \\
    & + \frac{1}{2} [\expdecay( \oracleprice \deltabuy(y) - \exratebuy (y) \deltabuy(y) + g(t,y - \deltabuy(y),s) - g(t,y,s))]^{2}.
\end{align*}
}
The HJB in \eqref{eq: eq for g} becomes 

\begin{equation}\label{eq: approx eq for g}
\begin{aligned}
    \frac{\partial}{\partial t}  g(t,y,s) & + \frac{\sigma^{2}}{2} \frac{\partial^{2}}{\partial s^{2}} g(t,y,s) - \pencons(Z(y) -s)^{2} + \\
    & \frac{e^{-1} \intsell}{\expdecay} [ 1 - \expdecay(\oracleprice \deltasell(y) + \exratesell(y) \deltasell(y) + g(t,y + \deltasell(y),s) - g(t,y,s)) \\
    & + \frac{\expdecay^{2}}{2}(- \oracleprice \deltasell(y) + \exratesell(y) \deltasell(y) + g(t,y + \deltasell(y),s) - g(t,y,s))^{2} ] \\
    & \frac{e^{-1} \intbuy}{\expdecay} [ 1 + \expdecay(\oracleprice \deltabuy(y) - \exratebuy(y) \deltabuy(y) + g(t,y - \deltabuy(y),s) - g(t,y,s)) \\
    & + \frac{\expdecay^{2}}{2}( \oracleprice \deltabuy(y) - \exratebuy(y)\deltabuy(y)  + g(t,y - \deltabuy(y),s) - g(t,y,s))^{2} ] = 0.
\end{aligned}
\end{equation}

We assume that $\deltabuy(y)$ and $\deltasell(y)$ are constant equal to $\delta^{-}$ and $\delta^{+}$, respectively.

\begin{remark}
    The assumption that $\deltabuy(y)$ and $\deltasell(y)$ are constant is necessary if one wishes to carry out a quadratic expansion of the exponential terms. If we employ a linear approximation of the exponential terms, we could work with the case where $\deltabuy(y)$ and $\deltasell(y)$ are linear in $y$.
\end{remark}

Lastly, we use a linear approximation to the exchange rates

\begin{align*}
    Z(y) & = \frac{\depth}{y^{2}} \approx \frac{\depth}{y_0^2} - 2(y - y_0) \frac{\depth}{y_0^3}, \\
    \exratesell(y) \delta^{+}& =  \frac{\depth}{y^{2} + \delta^{+} y} \approx \frac{\depth}{y_0^2 + \delta^{+} y_0} - (y - y_0) \frac{\depth(2 y_0 + \delta^{+})}{(y_0^2 + \delta^{+}y_0)^2}, \\
    \exratebuy(y) \delta^{-} & =  \frac{\depth}{y^{2} - \delta^{-}y} \approx \frac{\depth}{y_0^2 - \delta^{-}y_0} - (y - y_0) \frac{\depth(2 y_0 - \delta^{-})}{(y_0^2 - \delta^{-}y_0)^2}.
\end{align*}

\begin{comment}
\begin{remark}
    This approximation is works only in a neighbourhood of $y_0$. However, our simulations indicate that trading activity is concentrated around $y_0$, which supports the suitability of this hypothesis.
\end{remark}    
\end{comment}



In order to find a solution for the equation \eqref{eq: approx eq for g} we assume that $g(t,y,s)$ is a quadratic polynomial in $y$ of the form \[ g(t,y,s) = y^{2} A(t) + y B(t,s) + C(t,s), \]
with $A(T) = B(T,s) = C(T,s) = 0$. Proposition \eqref{thm: solution to the PDE system} formalises the solution to the HJB equation.


\begin{theorem}\label{thm: solution to the PDE system}
    There exists constants\footnote{The full definition of the constants $\{ \psi_{i} \}_{1 \leq i \leq 26}$ is publicly available in the GitHub of the project.} $\{ \psi_{i} \}_{1 \leq i \leq 26} \subset \mathbb{R}$ that define the unique solution to the HJB equation \eqref{eq: approx eq for g} as follows. Let $A:[0,T] \to \mathbb{R}$ be the solution to the Riccati ODE
    \begin{equation*}
        \psi_0 + \psi_1 A(t) + \psi_2 A^{2}(t) + A'(t), \quad \quad A(T) = 0.
    \end{equation*}
    Let $b_0$, $b_1 : [0,T] \to \mathbb{R}$ be the unique solutions to the system
    \[
    \begin{cases}
       \psi_3 + \psi_4 A(t) + \psi_5 A^{2}(t) + \psi_6 A(t) b_0(t) + \psi_7 b_0(t) + b_0^{'}(t) = 0 \\
       \psi_8 + \psi_9 A(t) + \psi_{10}A(t)b_1(t) + \psi_{11}b_1(t) + b_1^{'}(t)= 0,
    \end{cases}
    \]
    with terminal conditions $b_0(T) = b_1(T) = 0$.
    Let $c_0$, $c_1$, $c_2: [0,T] \to \mathbb{R}$ be the unique solutions to the system
    \[
    \begin{cases}
        \psi_{12} + \psi_{13} A(t) + \psi_{14}A^{2}(t) + \psi_{15}A(t)b_0(t) + \psi_{16}b_0(t) + \psi_{17}b_0^{2}(t) + \sigma^{2} c_{2}(t) + c_0^{'}(t) = 0, \\
        \psi_{18} + \psi_{19}A(t) + \psi_{20}A(t)b_{1}(t) + \psi_{21}b_{0}(t) + \psi_{22}b_0(t)b_{1}(t) + \psi_{23}b_{1}(t) + c_{1}^{'}(t) = 0, \\
        \psi_{24} + \psi_{25} b_{1}(t) + \psi_{26}b_{1}^{2}(t) + c_{2}^{'}(t) = 0,
    \end{cases}
    \]
    with terminal conditions $c_0(T) = c_1(T) = c_2(T) = 0$.
    Define $\hat{B},\hat{C} : [0,T] \times \mathbb{R} \to \mathbb{R}$ as
    \begin{align*}
        \hat{B}(t,s) & = s b_{1}(t) + b_0(t), \\
        \hat{C}(t,s) & = s^{2} c_{2}(t) + s c_1(t) + c_0(t).
    \end{align*}
    Then, the function \[ g(t,y,s) = y^{2} \hat{A}(t) + y \hat{B}(t,s) + \hat{C}(t,s), \] is a solution to the HJB equation \eqref{eq: approx eq for g}.
\end{theorem}

With the above results, the optimal fees from \eqref{eq: maximizers} become

\begin{equation}\label{eq: maximizers second approx}
\begin{aligned}
    \feeLTsells^{*}(t,y) & := -\frac{(2y + \delta^{+})\hat{A}(t) + \hat{B}(t,s)}{ \exratesell(y) } + \frac{1}{\expdecay \exratesell(y) \delta^{+}}, \\
    \feeLTbuys^{*}(t,y) & := -\frac{(-2y + \delta^{-})\hat{A}(t) - \hat{B}(t,s)}{ \exratebuy(y)} + \frac{1}{\expdecay \exratebuy(y) \delta^{-}}.
\end{aligned}
\end{equation}

Observe that the fees depend linearly on $y$ and $s$ and they do not depend on $\sigma$.

