\title{On the Error Exponent Distribution of Code Ensembles over Classical-Quantum Channels}


\author{Giuseppe Cocco and Javier Rodríguez Fonollosa
\thanks{Giuseppe Cocco and Javier Rodríguez Fonollosa are with the Department of Signal Theory and Communications, Universitat Polit\`ecnica de Catalunya, 08034, Barcelona, Spain (Corresponding author: giuseppe.cocco@upc.edu).

